// Generated by build.js from data/*.json. Do not edit by hand.
window.DECKS=[{"name":"Common Words I","slug":"common-words-i","series":"Common Words","words":[{"w":"aberration","p":"n.","m":"A departure from what is normal or expected.","e":"Latin <i>aberrare</i>, “to wander away”: <i>ab-</i> (away) + <i>errare</i> (to wander, stray). The same <i>errare</i> gives French <i>errer</i> and English <i>err</i>, <i>error</i>.","f":"aberration","t":"Picture a knight-errant drifting off the road: ab + errer = wandering off the normal path. French already has the word with the same meaning."},{"w":"acrimony","p":"n.","m":"Bitter, sharp ill-feeling, especially in words or a dispute.","e":"Latin <i>acrimonia</i>, “sharpness, pungency”, from <i>acer</i> (sharp, sour). Same root as French <i>âcre</i>, <i>aigre</i> and <i>vinaigre</i> (vin + aigre).","f":"acrimonie, aigreur","t":"Acer → aigre → vinaigre. An acrimonious divorce is a marriage that has turned to vinegar."},{"w":"amalgam","p":"n.","m":"A mixture or blend of different elements.","e":"Medieval Latin <i>amalgama</i>, the alchemists’ word for an alloy of mercury with another metal, probably via Arabic from Greek <i>malagma</i> (a softening paste). Dentists’ silver fillings are still called amalgam.","f":"amalgame (« faire l’amalgame »)","t":"Same word as « faire l’amalgame », lumping things together. Think of the dentist’s filling: several metals fused into one."},{"w":"ambiguous","p":"adj.","m":"Open to more than one interpretation; unclear.","e":"Latin <i>ambiguus</i>, “doubtful, shifting”, from <i>ambigere</i>, “to waver”: <i>ambi-</i> (both ways, around) + <i>agere</i> (to drive, lead).","f":"ambigu","t":"Ambi = both ways, as in ambidextrous. A sentence driving in two directions at once. Identical to French ambigu."},{"w":"ambivalent","p":"adj.","m":"Having mixed or contradictory feelings about something.","e":"A modern coinage: the Swiss psychiatrist Eugen Bleuler built German <i>Ambivalenz</i> in 1910 from Latin <i>ambi-</i> (both) + <i>valentia</i> (strength, from <i>valere</i>, to be strong).","f":"ambivalent, partagé","t":"Ambi + valent = two feelings of equal strength pulling at once. Ambiguous describes a message; ambivalent describes how a person feels."},{"w":"amenable","p":"adj.","m":"Willing to cooperate or be persuaded; open to.","e":"Anglo-French <i>amenable</i>, “able to be led”, from <i>amener</i> (à + <i>mener</i>), from Late Latin <i>minare</i>, “to drive animals by shouting”. First a legal word: answerable to a court.","f":"accommodant, réceptif, disposé à","t":"French amener: an amenable person is easy to « amener » to your view. You can lead them where you want."},{"w":"amorphous","p":"adj.","m":"Without a clear shape, form or structure.","e":"Greek <i>amorphos</i>: <i>a-</i> (without) + <i>morphē</i> (shape, form). Same <i>morphē</i> as in metamorphosis and morphology.","f":"amorphe, informe","t":"A-morph = no shape, a metamorphosis that never finished. French « amorphe » often means listless; in English keep it about shape: an amorphous plan, an amorphous blob."},{"w":"anomalous","p":"adj.","m":"Deviating from what is standard or expected.","e":"Greek <i>anōmalos</i>, “uneven, irregular”: <i>an-</i> (not) + <i>homalos</i> (even, level), related to <i>homos</i> (same).","f":"anormal, anomal (une anomalie)","t":"An-homalos = not level, not the same as the rest. The anomaly is the data point that sticks out of the even line."},{"w":"artful","p":"adj.","m":"Cunning and sly (the usual GRE sense); also skilful.","e":"English <i>art</i> + <i>-ful</i>. <i>Art</i> came through Old French from Latin <i>ars, artis</i> (skill, craft), which also gave <i>artifice</i> and <i>artificial</i>. “Skilful” slid to “crafty” by the 1700s.","f":"rusé, astucieux, habile","t":"Think artifice, not art gallery. The Artful Dodger in Oliver Twist is a pickpocket full of tricks.","x":"2nd meaning"},{"w":"auspicious","p":"adj.","m":"Showing signs of future success; favourable.","e":"Latin <i>auspicium</i>, “divination from birds”: <i>avis</i> (bird) + <i>specere</i> (to look). Roman augurs read the gods’ will in the flight of birds before any big decision.","f":"favorable, de bon augure (« sous de bons auspices »)","t":"« Sous de bons auspices »: picture the Roman priest watching the birds fly the right way. Auspicious = the birds say yes."},{"w":"belie","p":"v.","m":"To give a false impression of; or to show something to be false.","e":"Old English <i>belēogan</i>, “to deceive by lying”: <i>be-</i> + <i>lēogan</i> (to lie). Purely Germanic. The surface “lies about” what is underneath.","f":"démentir, masquer, contredire","t":"Be + lie: the surface tells a lie. “Her calm smile belied her panic” = the smile lied about it."},{"w":"betray","p":"v.","m":"To reveal unintentionally (the GRE sense); also to be disloyal.","e":"Germanic prefix <i>be-</i> + Middle English <i>trayen</i>, from Old French <i>trair</i> (now <i>trahir</i>), from Latin <i>tradere</i>, “to hand over”.","f":"trahir (« sa voix trahissait sa nervosité »)","t":"Exactly like French « trahir son émotion »: your face hands over (tradere) the secret without your permission.","x":"2nd meaning"},{"w":"calumny","p":"n.","m":"A false statement made to damage someone’s reputation; slander.","e":"Latin <i>calumnia</i>, “trickery, false accusation”, from <i>calvi</i> (to deceive). Came into English through French <i>calomnie</i>.","f":"calomnie","t":"Same word as « calomnie », and the old saying: « Calomniez, calomniez, il en restera toujours quelque chose. »"},{"w":"castigate","p":"v.","m":"To criticise or reprimand severely.","e":"Latin <i>castigare</i>, “to correct, punish”, literally “to make pure”: <i>castus</i> (pure, chaste) + <i>agere</i> (to drive). The same verb became Old French <i>chastier</i>, now <i>châtier</i>, which English borrowed again as chastise.","f":"fustiger, réprimander, châtier","t":"Castigate and chastise are twins, both from castigare → châtier. « Qui aime bien châtie bien. »"},{"w":"censure","p":"n. / v.","m":"Formal, severe disapproval; to criticise officially.","e":"Latin <i>censura</i>, the office of the Roman <i>censor</i> (from <i>censere</i>, to assess). Censors ran the census and also judged citizens’ morals, publicly marking the disgraced.","f":"blâme, censure (« motion de censure »)","t":"Think « motion de censure » at the Assemblée: an official vote of disapproval. Censure = formal blame. Cutting out content is censor."},{"w":"chastise","p":"v.","m":"To scold or punish severely.","e":"Middle English <i>chastisen</i>, from <i>chasten</i>, from Old French <i>chastier</i> (modern <i>châtier</i>), from Latin <i>castigare</i>, “to make pure”.","f":"châtier, réprimander","t":"Chastise sounds like châtier because it is châtier. The twin of castigate."},{"w":"commensurate","p":"adj.","m":"In proportion to; corresponding in size or degree.","e":"Late Latin <i>commensuratus</i>: <i>com-</i> (together) + <i>mensurare</i> (to measure), from <i>mensura</i> (measure).","f":"proportionné à, à la mesure de","t":"Com + mesure = measured together. “Salary commensurate with experience” = à la mesure de votre expérience."},{"w":"demur","p":"v.","m":"To raise objections or show reluctance.","e":"Old French <i>demorer</i>, “to linger, delay” (modern <i>demeurer</i>), from Latin <i>demorari</i>, from <i>mora</i> (delay, as in moratorium). Lawyers turned “delay” into a formal objection, the demurrer.","f":"émettre des réserves, objecter, hésiter","t":"Demur = demeurer: you stay put instead of going along. Don’t confuse with demure (shy, modest).","x":"Look-alike"},{"w":"disinterested","p":"adj.","m":"Impartial, with no personal stake (not “uninterested”).","e":"<i>dis-</i> (not) + interested, from Latin <i>interesse</i>, “to be between, to matter”: <i>inter</i> + <i>esse</i>. Here “interest” means a stake, as in conflict of interest.","f":"désintéressé, impartial","t":"Same as French « désintéressé »: a referee with nothing to gain. A disinterested judge is good; an uninterested judge is asleep.","x":"2nd meaning"},{"w":"egregious","p":"adj.","m":"Outstandingly bad; shocking.","e":"Latin <i>egregius</i>, “standing out from the flock”: <i>e/ex</i> (out of) + <i>grex, gregis</i> (flock). It first meant “distinguished”; ironic use in the 1500s made the bad sense win.","f":"flagrant, énorme, grossier (« une erreur grossière »)","t":"Ex grege: the sheep that stands out of the flock, for the wrong reason. Same grex as gregarious and grégaire."},{"w":"enervate","p":"v.","m":"To weaken; drain of energy (not “to annoy” or “energise”).","e":"Latin <i>enervare</i>, “to remove the sinews”: <i>e-</i> (out) + <i>nervus</i> (sinew, tendon). Old French <i>énerver</i> meant the same before it shifted to “irritate”.","f":"affaiblir, épuiser, amollir (≠ énerver)","t":"Remember « les Énervés de Jumièges », the two princes of legend whose tendons were cut: énervés in the old sense, drained of strength. That is the English meaning.","x":"Faux ami"},{"w":"equivocal","p":"adj.","m":"Ambiguous, often deliberately; open to two readings.","e":"Late Latin <i>aequivocus</i>, “of identical sound”: <i>aequus</i> (equal) + <i>vox, vocis</i> (voice). Two meanings with an equal voice.","f":"équivoque","t":"Same as « équivoque »: two meanings speak equally loud, so you can’t tell which is meant. To equivocate = to dodge with double-meaning words."},{"w":"extant","p":"adj.","m":"Still in existence; surviving.","e":"Latin <i>exstantem</i>, from <i>exstare</i>, “to stand out, be visible”: <i>ex</i> + <i>stare</i> (to stand).","f":"existant, qui subsiste, encore conservé","t":"Ex-stare = still standing. “The oldest extant manuscript” is the one still standing after the others were lost. Opposite: extinct."},{"w":"frugal","p":"adj.","m":"Sparing and economical with money or food.","e":"Latin <i>frugalis</i>, from <i>frugi</i> (useful, thrifty), from <i>frux, frugis</i> (fruit, produce). A frugal man made good use of his harvest.","f":"frugal, économe (« un repas frugal »)","t":"Identical to « un repas frugal ». Frux = fruit: living on what your own trees give you."},{"w":"galvanize","p":"v.","m":"To shock or excite someone into action.","e":"Named after Luigi Galvani (1737–1798), the Bologna physician whose dissected frog legs twitched when touched with metals: “animal electricity”. The zinc-coating sense came later, from galvanic cells.","f":"galvaniser","t":"Picture Galvani’s frog leg jumping when the current hits it. To galvanize a team = jolt it into motion. Same in French."},{"w":"gregarious","p":"adj.","m":"Fond of company; sociable.","e":"Latin <i>gregarius</i>, “of the flock”, from <i>grex, gregis</i> (flock, herd).","f":"sociable, liant (« grégaire » is more pejorative)","t":"Grex = the flock: a gregarious person loves being in the herd. In English it’s a compliment, unlike « l’instinct grégaire »."},{"w":"harangue","p":"n. / v.","m":"A long, aggressive or pompous speech; to lecture forcefully.","e":"Middle French <i>harangue</i>, from Old Italian <i>aringa</i> (public speech), from <i>aringo</i> (public square), from a Germanic word for a ring of people at an assembly (compare English <i>ring</i>).","f":"harangue, haranguer","t":"Same as « haranguer la foule ». Picture a Germanic chief in the middle of a ring of warriors, shouting at them."},{"w":"iconoclast","p":"n.","m":"A person who attacks cherished beliefs or institutions.","e":"Greek <i>eikōn</i> (image) + <i>klastēs</i> (breaker), from <i>klan</i> (to break). First the Byzantine iconoclasts of the 8th–9th centuries, who smashed religious images.","f":"iconoclaste","t":"Icon-breaker: a monk smashing holy images. Today it’s someone smashing sacred ideas, like the founder who breaks every rule of an industry."},{"w":"impertinent","p":"adj.","m":"Rude, disrespectful; also (older sense) not relevant.","e":"Latin <i>impertinentem</i>, “not belonging”: <i>in-</i> (not) + <i>pertinere</i> (to relate to). First “irrelevant”, then “meddling in what doesn’t concern you”, hence “rude”.","f":"impertinent, insolent; (ou) non pertinent","t":"Both meanings come from “not pertinent”: either irrelevant, or poking into things that are none of your business.","x":"2nd meaning"},{"w":"ingenuous","p":"adj.","m":"Innocent, naive, candid (not “ingenious”).","e":"Latin <i>ingenuus</i>, “native, freeborn”, hence “noble, frank”: <i>in-</i> + <i>gignere</i> (to beget). A freeborn person had nothing to hide.","f":"ingénu, candide, naïf","t":"Ingenuous = ingénu, like Voltaire’s L’Ingénu. Ingenious (with an i) is clever; disingenuous is fake-innocent.","x":"Look-alike"},{"w":"innocuous","p":"adj.","m":"Harmless; inoffensive.","e":"Latin <i>innocuus</i>: <i>in-</i> (not) + <i>nocuus</i> (harmful), from <i>nocere</i> (to harm). Same family as French <i>nuire</i>, <i>nocif</i> and <i>innocent</i>.","f":"inoffensif, anodin","t":"In + nocif = not nocif. An innocuous remark does no harm at all."},{"w":"intimate","p":"v.","m":"To hint or suggest indirectly (the GRE verb sense).","e":"Late Latin <i>intimare</i>, “to make known, announce”, from <i>intimus</i> (inmost): putting an idea into someone’s innermost thoughts.","f":"laisser entendre, insinuer, suggérer (≠ intimer)","t":"The verb, said “inti-MATE”, slips an idea into someone’s mind without saying it. Not French « intimer un ordre », which is the opposite of subtle.","x":"2nd meaning"},{"w":"involved","p":"adj.","m":"Complicated, intricate (the GRE sense).","e":"Latin <i>involvere</i>, “to roll into, wrap up”: <i>in-</i> + <i>volvere</i> (to roll). Something rolled in many layers is hard to unwrap.","f":"compliqué, alambiqué, complexe","t":"Picture a scroll rolled up on itself: an involved argument has to be unrolled layer by layer. Think « alambiqué ».","x":"2nd meaning"},{"w":"laconic","p":"adj.","m":"Using very few words; terse.","e":"Greek <i>Lakōnikos</i>, “of Laconia”, the region around Sparta. Spartans were famous for blunt brevity.","f":"laconique","t":"Philip II of Macedon warned Sparta: “If I invade Laconia, I will destroy you.” The Spartans replied with one word: “If.”"},{"w":"maintain","p":"v.","m":"To assert, claim firmly (the GRE sense).","e":"Old French <i>maintenir</i>, from Latin <i>manu tenere</i>, “to hold in the hand”.","f":"maintenir, affirmer, soutenir (« je maintiens que… »)","t":"Exactly French « je maintiens que c’est faux »: you hold your position in your hand and won’t let go.","x":"2nd meaning"},{"w":"mercurial","p":"adj.","m":"Subject to sudden, unpredictable changes of mood.","e":"Latin <i>mercurialis</i>, “of Mercury”: the swift messenger god, the fast planet, and quicksilver, the liquid metal that never sits still. Astrologers said people born under Mercury were volatile.","f":"versatile, lunatique, d’humeur changeante","t":"Picture a drop of mercury (vif-argent) skittering across a table, impossible to pin down. A mercurial boss changes mood that fast."},{"w":"parochial","p":"adj.","m":"Narrow in outlook; limited to local concerns.","e":"Late Latin <i>parochialis</i>, from <i>parochia</i> (parish), from Greek <i>paroikia</i>: <i>para</i> (beside) + <i>oikos</i> (house). Thinking that stops at the parish boundary.","f":"borné, provincial (« esprit de clocher »)","t":"Parochial = paroissial. « L’esprit de clocher »: someone who can’t see past their own village church tower."},{"w":"parsimonious","p":"adj.","m":"Extremely unwilling to spend money; stingy.","e":"Latin <i>parsimonia</i> (thrift), from <i>parcere</i>, “to spare, save”.","f":"parcimonieux, pingre, radin","t":"« Avec parcimonie »: coins handed out one by one. Stronger than frugal: frugal is a virtue, parsimonious is stingy."},{"w":"prevaricate","p":"v.","m":"To speak evasively; to dodge the truth.","e":"Latin <i>praevaricari</i>, “to walk crookedly, straddle”: <i>prae</i> + <i>varicare</i> (to straddle), from <i>varus</i> (bow-legged). In Roman law, a prosecutor secretly colluding with the defence.","f":"tergiverser, user de faux-fuyants (≠ prévariquer)","t":"Picture someone bow-legged, zig-zagging so they never walk straight to the truth. Tergiverser.","x":"Faux ami"},{"w":"prodigal","p":"adj. / n.","m":"Wastefully extravagant; someone who squanders.","e":"Latin <i>prodigus</i> (wasteful), from <i>prodigere</i>, “to drive away, squander”: <i>pro-</i> (forth) + <i>agere</i> (to drive).","f":"prodigue (« l’enfant prodigue »)","t":"The prodigal son of the parable, « l’enfant prodigue », who blew his inheritance. Not to be confused with prodigy (a genius).","x":"Look-alike"},{"w":"profligate","p":"adj.","m":"Recklessly wasteful; also dissolute, immoral.","e":"Latin <i>profligatus</i>, “ruined, dissolute”, from <i>profligare</i>, “to strike down”: <i>pro-</i> + <i>fligere</i> (to strike), as in inflict and conflict.","f":"dépensier, dissipateur, débauché","t":"Profligate = prodigal who also parties. Pro + fligere: knocking down your own fortune and morals blow by blow."},{"w":"qualify","p":"v.","m":"To limit or modify a statement; add reservations (GRE sense).","e":"Medieval Latin <i>qualificare</i>, “to give a quality to”: <i>qualis</i> (of what kind) + <i>facere</i> (to make).","f":"nuancer, apporter une réserve, tempérer","t":"Think « nuancer son propos ». A qualified endorsement is a yes with an asterisk.","x":"2nd meaning"},{"w":"restive","p":"adj.","m":"Restless, impatient, resisting control.","e":"Old French <i>restif</i> (now <i>rétif</i>), “stationary, balky”, from <i>rester</i>, Latin <i>restare</i> (to stay). Used first of horses that refused to go forward; their stamping and fidgeting took over the meaning.","f":"agité, nerveux, rétif","t":"Picture « un cheval rétif », refusing to move while stamping and pulling at the reins. A restive crowd is losing patience."},{"w":"undermine","p":"v.","m":"To weaken gradually or secretly.","e":"Middle English <i>under</i> + <i>mine</i> (from Old French <i>miner</i>). Besiegers dug tunnels under castle walls, propped them with timber, then burned the props so the wall fell.","f":"saper, miner, ébranler","t":"Same image as French « saper le moral »: digging under the wall until it collapses."},{"w":"upbraid","p":"v.","m":"To scold or reproach severely.","e":"Old English <i>upbregdan</i>, “to throw up against”: <i>up</i> + <i>bregdan</i> (to move quickly, weave; the source of braid). You throw someone’s faults back at them.","f":"réprimander, sermonner, faire des reproches","t":"Up + braid: you hurl the reproach up into their face. It sounds harsh because it is."},{"w":"venality","p":"n.","m":"Openness to bribery; corruption.","e":"Latin <i>venalis</i>, “for sale”, from <i>venum</i> (sale), which also gave <i>vendere</i>, to sell (<i>venum dare</i>).","f":"vénalité, corruption","t":"Think « la vénalité des offices » under the Ancien Régime, when judges bought their posts. Venal = for sale. Venial is a small, forgivable sin.","x":"Look-alike"},{"w":"venerate","p":"v.","m":"To regard with deep respect; revere.","e":"Latin <i>venerari</i>, “to worship, revere”, related to <i>Venus</i> (love, desire).","f":"vénérer","t":"Identical to « vénérer ». Picture bowing before a statue of Venus."},{"w":"veracious","p":"adj.","m":"Truthful; accurate.","e":"Latin <i>verax, veracis</i> (truthful), from <i>verus</i> (true).","f":"véridique (« la véracité »)","t":"Véracité = truthfulness. Don’t confuse with voracious (hungry): veracious = vrai.","x":"Look-alike"},{"w":"vindicate","p":"v.","m":"To clear of blame; to prove right.","e":"Latin <i>vindicare</i>, “to claim, avenge, set free”, from <i>vindex</i> (claimant, avenger). The same verb gave French <i>venger</i> and <i>revendiquer</i>.","f":"disculper, justifier, donner raison à","t":"Vindicate = venger: being proved right is your revenge. When the data vindicated her, she was avenged."},{"w":"wanting","p":"adj.","m":"Lacking; not good enough.","e":"Old Norse <i>vanta</i>, “to lack”, brought by Viking settlers. “Want” meant “lack” long before it meant “desire”.","f":"insuffisant, déficient, qui fait défaut","t":"From the Book of Daniel: “weighed in the balances, and found wanting” (« pesé dans la balance et trouvé léger »).","x":"2nd meaning"}]},{"name":"Common Words II","slug":"common-words-ii","series":"Common Words","words":[{"w":"aesthete","p":"n.","m":"A person with a refined appreciation of art and beauty (sometimes excessive).","e":"Coined in 19th-century English from Greek <i>aisthētēs</i>, “one who perceives”, from <i>aisthanesthai</i> (to perceive, feel). Tied to Oscar Wilde’s Aesthetic movement and “art for art’s sake”.","f":"esthète","t":"Picture Oscar Wilde with a lily and a velvet jacket. Aesthete = the person; aesthetic = the quality."},{"w":"aesthetic","p":"adj. / n.","m":"Concerned with beauty or artistic taste.","e":"Greek <i>aisthētikos</i>, “of sense perception”, from <i>aisthanesthai</i> (to perceive). The German philosopher Baumgarten gave it the meaning “theory of taste” in the 1700s.","f":"esthétique","t":"Anesthetic = no feeling. Aesthetic = what your senses feel, especially beauty."},{"w":"apathetic","p":"adj.","m":"Showing no interest, enthusiasm or concern.","e":"Greek <i>apatheia</i>: <i>a-</i> (without) + <i>pathos</i> (feeling, suffering). For the Stoics apatheia was an ideal; in English it became indifference.","f":"apathique, indifférent","t":"A-pathos = no feeling, the opposite of sympathy and passion. Same as French apathique."},{"w":"audacious","p":"adj.","m":"Bold and daring; sometimes shamelessly so.","e":"Latin <i>audax, audacis</i> (bold), from <i>audere</i> (to dare).","f":"audacieux","t":"Danton in 1792: « De l’audace, encore de l’audace, toujours de l’audace ! » Audacious can praise or condemn."},{"w":"banal","p":"adj.","m":"Lacking originality; trite.","e":"French <i>banal</i>, from the feudal <i>ban</i> (the lord’s jurisdiction; a Frankish word). The <i>four banal</i> and <i>moulin banal</i> were the lord’s oven and mill every villager had to use: “common to all” became “commonplace”.","f":"banal","t":"Picture the village four banal: everyone bakes in the same oven, so every loaf looks the same."},{"w":"bucolic","p":"adj.","m":"Relating to the pleasant side of country life; pastoral.","e":"Greek <i>boukolikos</i>, “of herdsmen”, from <i>boukolos</i> (cowherd): <i>bous</i> (ox) + <i>-kolos</i> (tending). Virgil’s <i>Bucolics</i> made it a literary genre.","f":"bucolique, champêtre","t":"Bous = ox. A cowherd lounging in a meadow, Virgil-style. Same as French bucolique."},{"w":"chortle","p":"v. / n.","m":"To laugh in a gleeful, breathy way.","e":"Coined by Lewis Carroll in <i>Through the Looking-Glass</i> (1871) as a blend of chuckle + snort.","f":"glousser, rire de contentement","t":"Chuckle + snort = chortle. The satisfied, slightly smug laugh after winning an argument."},{"w":"concede","p":"v.","m":"To admit something is true, often reluctantly; to yield.","e":"Latin <i>concedere</i>, “to give way”: <i>com-</i> + <i>cedere</i> (to go, yield).","f":"concéder, admettre, céder","t":"Concéder: same word. You concede a point in an argument, or concede defeat in an election."},{"w":"conspicuous","p":"adj.","m":"Clearly visible; attracting attention.","e":"Latin <i>conspicuus</i> (visible), from <i>conspicere</i>, “to look at closely”: <i>com-</i> + <i>specere</i> (to look), the root of spectacle and perspicace.","f":"voyant, manifeste, ostensible","t":"Veblen’s “conspicuous consumption” (1899): the logo-covered handbag bought to be seen. Conspicuous = made to be looked at."},{"w":"cryptic","p":"adj.","m":"Mysterious; obscure in meaning.","e":"Late Latin <i>crypticus</i>, from Greek <i>kryptikos</i>, from <i>kryptos</i> (hidden). Same root as crypt and cryptography.","f":"énigmatique, sibyllin","t":"Kryptos = hidden, like a crypt under a church. A cryptic message keeps its meaning underground."},{"w":"culminate","p":"v.","m":"To reach the highest point or climax.","e":"Late Latin <i>culminare</i> (to crown), from <i>culmen</i> (summit). Astronomers used it for a star reaching its highest point in the sky.","f":"culminer, aboutir","t":"« Le point culminant » = the summit. A career that culminates in the CEO role reaches its peak there."},{"w":"culpability","p":"n.","m":"Responsibility for a fault or wrong; blameworthiness.","e":"Latin <i>culpabilis</i> (blameworthy), from <i>culpa</i> (fault, blame).","f":"culpabilité","t":"Mea culpa = my fault. Culpability = culpabilité."},{"w":"decorous","p":"adj.","m":"In keeping with good taste and propriety; polite.","e":"Latin <i>decorus</i> (becoming, proper), from <i>decor</i> (seemliness), from <i>decere</i> (to be fitting). Same root as decorum and décent.","f":"bienséant, convenable, digne","t":"Think « le décorum »: decorous behaviour respects decorum. Nothing to do with decorations."},{"w":"deferential","p":"adj.","m":"Showing respect and humble submission.","e":"From deference, French <i>déférence</i>, from <i>déférer</i> (to yield to), Latin <i>deferre</i>: <i>de-</i> + <i>ferre</i> (to carry).","f":"déférent, respectueux","t":"Same as « par déférence ». A deferential junior defers to the partner’s judgment."},{"w":"dictatorial","p":"adj.","m":"Domineering; imposing one’s will on others.","e":"Latin <i>dictator</i>, from <i>dictare</i> (to say repeatedly, prescribe). In Rome a dictator was a magistrate given absolute power for six months in an emergency.","f":"dictatorial, autoritaire, tyrannique","t":"The one who dictates. A dictatorial manager dictates and nobody else gets to speak."},{"w":"didactic","p":"adj.","m":"Intended to teach, often in a preachy or moralising way.","e":"Greek <i>didaktikos</i>, “apt at teaching”, from <i>didaskein</i> (to teach).","f":"didactique; moralisateur","t":"Same as « didactique ». On the GRE it often stings a little: a didactic novel lectures you."},{"w":"diffident","p":"adj.","m":"Shy; lacking self-confidence.","e":"Latin <i>diffidentem</i>, from <i>diffidere</i>, “to mistrust”: <i>dis-</i> (not) + <i>fidere</i> (to trust), as in fidèle and confiance. First it meant distrusting others; now, distrusting yourself.","f":"timide, qui manque d’assurance","t":"Dis + fidere = no trust. Défiance is mistrust of others; diffidence is mistrust of yourself. Opposite: confident (con + fidere)."},{"w":"dogmatic","p":"adj.","m":"Asserting opinions as undeniably true; inflexible.","e":"Greek <i>dogmatikos</i>, from <i>dogma</i> (opinion, decree), from <i>dokein</i> (to seem, think).","f":"dogmatique","t":"Dogma = a decree that can’t be questioned. Same as French dogmatique."},{"w":"engender","p":"v.","m":"To cause or give rise to.","e":"Old French <i>engendrer</i>, from Latin <i>ingenerare</i>: <i>in-</i> + <i>generare</i> (to beget), from <i>genus</i> (birth, kind).","f":"engendrer","t":"Same as « engendrer ». A policy engenders resentment the way parents engender children."},{"w":"entrenched","p":"adj.","m":"Firmly established and hard to change.","e":"<i>en-</i> + trench, from Old French <i>trenche</i> (a cut, a ditch), from <i>trenchier</i> (now <i>trancher</i>), probably from Latin <i>truncare</i> (to cut off).","f":"ancré, enraciné, retranché","t":"Picture WWI soldiers dug into their tranchées for years. An entrenched belief is dug in and won’t move."},{"w":"eschew","p":"v.","m":"To deliberately avoid; abstain from.","e":"Old French <i>eschiver</i> (later <i>esquiver</i>), from Frankish <i>skiuhan</i> (to fear, shun). A cousin of English shy and German <i>scheuen</i>.","f":"éviter, esquiver, s’abstenir de","t":"Eschew = esquiver. Say it “es-CHOO” and picture dodging a sneeze. To eschew meat = to avoid it on principle."},{"w":"exacerbate","p":"v.","m":"To make a problem worse.","e":"Latin <i>exacerbare</i> (to irritate, make harsh): <i>ex-</i> + <i>acerbus</i> (harsh, bitter).","f":"exacerber, aggraver","t":"Acerbus = acerbe. Pouring something bitter on a wound: same as « exacerber »."},{"w":"fortuitous","p":"adj.","m":"Happening by chance (not necessarily lucky).","e":"Latin <i>fortuitus</i> (happening by chance), from <i>fors</i> (chance), the root of Fortuna.","f":"fortuit (« une rencontre fortuite »)","t":"« Une rencontre fortuite » = a chance meeting. On the GRE, fortuitous means accidental, not fortunate.","x":"Look-alike"},{"w":"frivolous","p":"adj.","m":"Not serious; silly, trivial.","e":"Latin <i>frivolus</i> (silly, empty, worthless), possibly from <i>friare</i> (to crumble).","f":"frivole","t":"Identical to frivole. Things that crumble into nothing: a frivolous lawsuit has no substance."},{"w":"gainsay","p":"v.","m":"To deny or contradict.","e":"Middle English: <i>gain-</i>, “against” (Old English <i>gegn</i>, as in again and against) + say. Purely Germanic.","f":"contredire, nier","t":"Gain = against: to say against. “No one can gainsay her results” = no one can contradict them."},{"w":"gall","p":"n.","m":"Bold, impudent behaviour; nerve. (Also bitterness, bile.)","e":"Old English <i>gealla</i> (bile), from an Indo-European root for yellow-green; related to Greek <i>cholē</i> (bile, as in cholera and mélancolie). Bitterness became audacity in 19th-century American slang.","f":"culot, toupet; fiel (la bile)","t":"The gall bladder holds bitter bile. Having the gall to ask = avoir le culot. To gall someone = to irritate them."},{"w":"germane","p":"adj.","m":"Relevant to the subject at hand.","e":"A variant of <i>german</i>, “of the same parents”, from Latin <i>germanus</i> (full brother or sister). Closely related, hence relevant.","f":"pertinent, en rapport avec","t":"Cousin germain! A germane point is closely related to the topic, like a first cousin."},{"w":"glut","p":"n. / v.","m":"An excessive supply; to oversupply.","e":"Middle English <i>glotten</i> (to swallow greedily), from Old French <i>gloutir</i>, from Latin <i>gluttire</i> (to swallow). Same root as glouton and engloutir.","f":"surabondance, excédent, saturation","t":"Glouton + engloutir: a market so stuffed it can’t swallow any more. A glut of oil = prices collapse."},{"w":"gossamer","p":"n. / adj.","m":"Extremely light, thin and delicate; fine spider silk.","e":"Middle English <i>gossomer</i>, probably “goose summer”: the warm spell in late autumn (St Martin’s summer) when geese were eaten and fine cobwebs floated over the fields.","f":"fils de la Vierge; arachnéen, vaporeux","t":"« Les fils de la Vierge »: threads of spider silk drifting over a field in an Indian summer. Gossamer = that light."},{"w":"impudent","p":"adj.","m":"Not showing due respect; shamelessly bold.","e":"Latin <i>impudentem</i> (shameless): <i>in-</i> (not) + <i>pudens</i> (modest), from <i>pudere</i> (to feel shame).","f":"impudent, effronté, insolent","t":"In + pudeur = no shame. Same as French impudent, and close to gall and impertinent."},{"w":"incisive","p":"adj.","m":"Sharp and clear-thinking; going straight to the point.","e":"Medieval Latin <i>incisivus</i>, from <i>incidere</i>, “to cut into”: <i>in-</i> + <i>caedere</i> (to cut).","f":"incisif, tranchant, pénétrant","t":"Your incisives are the cutting teeth. An incisive question cuts straight to the core of the problem."},{"w":"inexorable","p":"adj.","m":"Impossible to stop or prevent; relentless.","e":"Latin <i>inexorabilis</i>: <i>in-</i> (not) + <i>exorabilis</i> (moved by pleading), from <i>exorare</i>: <i>ex-</i> + <i>orare</i> (to pray, plead; cf. oraison).","f":"inexorable, implacable","t":"In-ex-orare = can’t be moved by prayer. Like death or the tide: beg all you want."},{"w":"lambast","p":"v.","m":"To criticise harshly.","e":"1630s, probably <i>lam</i> (to beat, from Old Norse <i>lemja</i>) + <i>baste</i> (to thrash). Both halves mean hitting.","f":"éreinter, fustiger, descendre en flammes","t":"Lam + baste = beat + beat. A critic who lambasts a film gives it a double thrashing: « se faire éreinter par la critique »."},{"w":"mawkish","p":"adj.","m":"Excessively, sickly sentimental.","e":"From <i>mawk</i> (maggot), Old Norse <i>maðkr</i>. In the 1660s it meant “sickly, nauseated”; by the 1700s, “sickly-sweet sentimental”.","f":"mièvre, à l’eau de rose, gnangnan","t":"Sentimentality so sweet it turns your stomach like maggots. A mawkish Christmas ad = mièvre."},{"w":"meticulous","p":"adj.","m":"Showing great attention to detail; very careful.","e":"Latin <i>meticulosus</i> (fearful, timid), from <i>metus</i> (fear). In 19th-century French, <i>méticuleux</i> shifted to “afraid of making mistakes”, hence careful.","f":"méticuleux, minutieux","t":"Same as méticuleux. Metus = fear: a meticulous person is scared of making a single mistake."},{"w":"mitigate","p":"v.","m":"To make less severe or painful.","e":"Latin <i>mitigare</i> (to soften): <i>mitis</i> (mild, gentle) + <i>agere</i> (to make).","f":"atténuer, adoucir, mitiger","t":"Mitigating circumstances = « circonstances atténuantes ». Mitis = soft: you soften the blow."},{"w":"obscure","p":"adj. / v.","m":"Not well known, or unclear; to conceal.","e":"Latin <i>obscurus</i> (dark, dim, hidden).","f":"obscur; obscurcir","t":"Identical to obscur. Something in the dark is either unknown or hard to see clearly."},{"w":"perfidy","p":"n.","m":"Deceitfulness; treachery.","e":"Latin <i>perfidia</i> (faithlessness): <i>per-</i> (away, to ruin) + <i>fides</i> (faith).","f":"perfidie","t":"« La perfide Albion »: the classic French jab at England’s supposed treachery. Per + fides = breaking faith."},{"w":"platitude","p":"n.","m":"A remark used too often to be interesting; a cliché.","e":"French <i>platitude</i> (17th century), “flatness”, from <i>plat</i> (flat), from Vulgar Latin <i>plattus</i>, from Greek <i>platys</i> (broad, flat).","f":"platitude, banalité, lieu commun","t":"Same as « platitude »: a flat, dull remark. “Let’s think outside the box” is a corporate platitude."},{"w":"preclude","p":"v.","m":"To prevent from happening; make impossible.","e":"Latin <i>praecludere</i> (to shut off in advance): <i>prae-</i> (before) + <i>claudere</i> (to close).","f":"empêcher, exclure, écarter","t":"Pre + close = closing the door in advance. Same root as exclude and clore."},{"w":"predilection","p":"n.","m":"A preference or special liking.","e":"French <i>prédilection</i>, from Medieval Latin <i>praedilectio</i>: <i>prae-</i> (before) + <i>diligere</i> (to love, choose).","f":"prédilection","t":"Identical: « un sujet de prédilection ». A predilection for good coffee is a favourite habit."},{"w":"prescience","p":"n.","m":"Knowledge of events before they happen; foresight.","e":"Latin <i>praescientia</i>: <i>prae-</i> (before) + <i>scire</i> (to know).","f":"prescience, clairvoyance","t":"Pre + science = knowing before. A prescient investor saw the crash coming."},{"w":"querulous","p":"adj.","m":"Complaining in a whining, petulant way.","e":"Latin <i>querulus</i>, from <i>queri</i> (to complain). Same root as querelle and quarrel.","f":"plaintif, geignard, ronchon","t":"Queri → querelle. A querulous person picks small complaints all day long."},{"w":"recondite","p":"adj.","m":"Little known; obscure; hard to understand.","e":"Latin <i>reconditus</i> (hidden, put away), from <i>recondere</i>: <i>re-</i> + <i>condere</i> (to put, store). Its cousin <i>abscondere</i> (to hide away) gave French <i>abscons</i>.","f":"abscons, ésotérique, obscur","t":"Recondite ≈ abscons: knowledge stored away where few can find it, like a footnote in a dusty archive."},{"w":"reticent","p":"adj.","m":"Not revealing one’s thoughts readily; reserved.","e":"Latin <i>reticentem</i>, from <i>reticere</i> (to keep silent): <i>re-</i> + <i>tacere</i> (to be silent), as in taciturne.","f":"réservé, discret, taciturne (≠ réticent)","t":"Tacere = se taire: a reticent person holds back their words. Modern French réticent means reluctant; for the GRE, think taciturn.","x":"Faux ami"},{"w":"rustic","p":"adj.","m":"Of the countryside; simple, unsophisticated.","e":"Latin <i>rusticus</i>, from <i>rus</i> (countryside), as in rural.","f":"rustique, campagnard","t":"Same as rustique. Rus = countryside: a rustic table is rough wood from the farm."},{"w":"superfluous","p":"adj.","m":"Unnecessary; more than enough.","e":"Latin <i>superfluus</i> (overflowing): <i>super</i> (over) + <i>fluere</i> (to flow).","f":"superflu","t":"Superflu: water overflowing the glass. The extra words on a slide are superfluous."},{"w":"torpor","p":"n.","m":"Physical or mental inactivity; lethargy.","e":"Latin <i>torpor</i> (numbness), from <i>torpere</i> (to be numb). The Latin <i>torpedo</i> was the electric ray, the fish that numbs its prey.","f":"torpeur, léthargie","t":"« La torpeur de l’après-midi ». Picture being zapped by a torpille fish: numb and sluggish."},{"w":"vociferous","p":"adj.","m":"Loud and forceful in expressing opinions.","e":"Latin <i>vociferari</i> (to shout): <i>vox, vocis</i> (voice) + <i>ferre</i> (to carry).","f":"véhément, bruyant, vociférant","t":"« Vociférer » = to yell. A vociferous critic carries their voice far and loud."},{"w":"volubility","p":"n.","m":"Fluent, ready, continuous speech; talkativeness.","e":"Latin <i>volubilis</i> (that turns, rolls easily), from <i>volvere</i> (to roll).","f":"volubilité, loquacité","t":"Words that keep rolling out (volvere). Same as « volubilité ». Opposite of laconic and reticent."}]},{"name":"Common Words III","slug":"common-words-iii","series":"Common Words","words":[{"w":"abstain","p":"v.","m":"To deliberately refrain from doing or consuming something.","e":"Latin <i>abstinere</i>, “to hold oneself back”: <i>abs-</i> (away) + <i>tenere</i> (to hold). Came through Old French <i>abstenir</i>.","f":"s’abstenir","t":"Same as « s’abstenir » (and l’abstention in a vote). You hold yourself away from the thing."},{"w":"ameliorate","p":"v.","m":"To make something bad better; improve.","e":"From French <i>améliorer</i>, from Latin <i>ad-</i> + <i>melior</i> (better). The 18th-century English form added Latin-looking <i>-ate</i>.","f":"améliorer","t":"Ameliorate = améliorer, word for word. Melior = meilleur."},{"w":"apathy","p":"n.","m":"Lack of interest, enthusiasm or concern.","e":"Greek <i>apatheia</i>: <i>a-</i> (without) + <i>pathos</i> (feeling, suffering). The Stoics prized it as freedom from passion.","f":"apathie, indifférence","t":"A-pathos = no feeling, the opposite of sympathy. Same as « apathie »."},{"w":"ascetic","p":"adj. / n.","m":"Practising strict self-denial; a person who does so.","e":"Greek <i>askētikos</i>, from <i>askētēs</i> (monk, hermit), from <i>askein</i> (to exercise, train). First used of athletes in training, then of hermits training the soul.","f":"ascétique, ascète","t":"Picture a desert hermit training like an athlete, but for the soul: no food, no comfort. « Une vie ascétique »."},{"w":"avaricious","p":"adj.","m":"Extremely greedy for wealth.","e":"Latin <i>avaritia</i> (greed), from <i>avarus</i> (greedy), from <i>avere</i> (to crave).","f":"avare, cupide","t":"Molière’s « L’Avare », Harpagon clutching his cash box. Avaricious = avare, and greedy for more."},{"w":"belligerent","p":"adj.","m":"Hostile and aggressive; eager to fight.","e":"Latin <i>belligerare</i>, “to wage war”: <i>bellum</i> (war) + <i>gerere</i> (to carry on).","f":"belliqueux, agressif (belligérant = at war)","t":"Bellum = war, as in « belliqueux ». A belligerent client is looking for a fight."},{"w":"circumvent","p":"v.","m":"To find a way around an obstacle or rule.","e":"Latin <i>circumvenire</i>, “to come around, surround”: <i>circum</i> (around) + <i>venire</i> (to come).","f":"contourner","t":"Circum + venir = to come around it. « Contourner la règle »."},{"w":"contrive","p":"v.","m":"To plan or bring about cleverly, often artificially.","e":"Old French <i>controver</i> (to invent, find), from Late Latin <i>contropare</i> (to compare). A contrived plot feels artificial.","f":"inventer, combiner, manigancer; contrived = artificiel","t":"Old French controuver = to invent. A contrived ending is invented too obviously: « forcé, artificiel »."},{"w":"delineate","p":"v.","m":"To describe or outline precisely.","e":"Latin <i>delineare</i>, “to sketch out”: <i>de-</i> + <i>linea</i> (line).","f":"décrire, délimiter, tracer","t":"De + linea = drawing the lines of something. A good brief delineates the scope."},{"w":"denote","p":"v.","m":"To indicate; to be the literal meaning of.","e":"Latin <i>denotare</i>, “to mark out”: <i>de-</i> + <i>notare</i> (to mark), from <i>nota</i> (a mark).","f":"dénoter, désigner, signifier","t":"Same as « dénoter ». Denote = the dictionary meaning; connote = the feeling around it."},{"w":"derivative","p":"adj. / n.","m":"Imitative of another’s work; unoriginal. (Also something derived.)","e":"Late Latin <i>derivativus</i>, from <i>derivare</i>, “to draw off a stream”: <i>de-</i> + <i>rivus</i> (stream).","f":"dérivé; peu original","t":"Water drawn off someone else’s stream. On the GRE, a derivative novel copies others."},{"w":"derive","p":"v.","m":"To obtain or trace from a source.","e":"Old French <i>deriver</i>, from Latin <i>derivare</i>: <i>de-</i> (from) + <i>rivus</i> (stream). Channelling water off a river.","f":"tirer de, dériver de","t":"Picture a channel drawing water from a river: you derive pleasure from a source."},{"w":"disaffected","p":"adj.","m":"Dissatisfied and no longer loyal, especially to authority.","e":"<i>dis-</i> (reverse) + <i>affect</i> (to love, from Latin <i>affectare</i>). Literally having lost one’s affection.","f":"désabusé, mécontent, en rupture","t":"Dis + affection: loyalty and love gone. Disaffected voters have given up on the party."},{"w":"eclectic","p":"adj.","m":"Drawing on a wide variety of sources or styles.","e":"Greek <i>eklektikos</i>, “selective”, from <i>eklegein</i>: <i>ek</i> (out) + <i>legein</i> (to pick). Ancient philosophers who picked the best from every school.","f":"éclectique","t":"Ek + legein = picking out the best bits. « Des goûts éclectiques »."},{"w":"elucidate","p":"v.","m":"To make clear; explain.","e":"Late Latin <i>elucidare</i>: <i>e-</i> (out) + <i>lucidus</i> (bright), from <i>lux</i> (light).","f":"élucider, éclaircir","t":"Same as « élucider ». Lux = light: you shine light on the mystery."},{"w":"eminent","p":"adj.","m":"Famous and respected; outstanding.","e":"Latin <i>eminentem</i>, from <i>eminere</i>, “to stand out”: <i>e-</i> + <i>minere</i> (to project). Related to Latin <i>mons</i> (mountain).","f":"éminent","t":"Une éminence = a hill that sticks out. An eminent scientist stands above the crowd. Not imminent (about to happen)."},{"w":"ephemeral","p":"adj.","m":"Lasting a very short time.","e":"Greek <i>ephēmeros</i>, “lasting a day”: <i>epi</i> (on) + <i>hēmera</i> (day). The mayfly (<i>éphémère</i>) lives one day.","f":"éphémère","t":"Same as « éphémère »: the mayfly that lives a single day. Ephemeral fame, ephemeral trends."},{"w":"fallacious","p":"adj.","m":"Based on a mistaken belief; misleading.","e":"Latin <i>fallaciosus</i>, from <i>fallacia</i> (deceit), from <i>fallere</i> (to deceive). Same root as false and fail.","f":"fallacieux","t":"Identical to « fallacieux ». A fallacy is a trick of reasoning."},{"w":"forlorn","p":"adj.","m":"Pitifully sad and abandoned.","e":"Old English <i>forloren</i>, past participle of <i>forlēosan</i> (to lose completely): <i>for-</i> + <i>lēosan</i> (to lose). Germanic, cousin of German <i>verloren</i>.","f":"abandonné, triste, délaissé","t":"For-lorn = for-lost, verloren. A forlorn puppy left at the roadside."},{"w":"frustrate","p":"v.","m":"To prevent a plan from succeeding; to annoy.","e":"Latin <i>frustrari</i> (to disappoint, deceive), from <i>frustra</i> (in vain).","f":"contrecarrer, déjouer; frustrer","t":"Frustra = in vain. On the GRE, “frustrate a plan” = déjouer: make it come to nothing."},{"w":"guileless","p":"adj.","m":"Innocent and without deception.","e":"<i>guile</i> (Old French <i>guile</i>, deceit, probably from Frankish, related to wile) + <i>-less</i>.","f":"candide, sans malice","t":"Guile = ruse. Guileless = sans ruse. A guileless child tells the truth without thinking."},{"w":"haughty","p":"adj.","m":"Arrogantly superior and disdainful.","e":"From <i>haught</i>, Old French <i>haut</i> (high), from Latin <i>altus</i>. The <i>gh</i> was added by analogy with high.","f":"hautain","t":"Haughty = hautain, from haut. Someone looking down on you from high up."},{"w":"heretic","p":"n.","m":"Someone who holds views contrary to accepted belief.","e":"Greek <i>hairetikos</i> (able to choose), from <i>hairesis</i> (a choosing, a sect).","f":"hérétique","t":"Hairesis = a choice. The heretic chose a different belief from the Church. Same as « hérétique »."},{"w":"immutable","p":"adj.","m":"Unchanging; unable to be changed.","e":"Latin <i>immutabilis</i>: <i>in-</i> (not) + <i>mutare</i> (to change), as in mutation.","f":"immuable","t":"No mutation possible. « Les lois immuables de la physique »."},{"w":"incongruous","p":"adj.","m":"Out of place; not in harmony with the surroundings.","e":"Latin <i>incongruus</i>: <i>in-</i> (not) + <i>congruus</i> (agreeing), from <i>congruere</i> (to come together).","f":"incongru, déplacé","t":"Same as « incongru ». Flip-flops at a board meeting."},{"w":"insidious","p":"adj.","m":"Spreading gradually and harmfully, often unnoticed.","e":"Latin <i>insidiosus</i> (cunning), from <i>insidiae</i> (ambush), from <i>insidere</i> (to sit in, lie in wait).","f":"insidieux, sournois","t":"Insidiae = an ambush. An insidious disease lies in wait. Same as « insidieux »."},{"w":"itinerant","p":"adj.","m":"Travelling from place to place.","e":"Late Latin <i>itinerantem</i>, from <i>itinerari</i> (to travel), from <i>iter, itineris</i> (journey).","f":"itinérant, ambulant","t":"Iter = journey, as in itinéraire. Itinerant workers follow the harvest."},{"w":"jingoism","p":"n.","m":"Extreme, aggressive patriotism.","e":"From a British music-hall song of 1878 supporting war against Russia, with the oath “by Jingo” (a euphemism for Jesus). Supporters were mocked as jingoes.","f":"chauvinisme, nationalisme belliqueux","t":"Picture Victorian Londoners singing for war in a music hall. Same idea as French « chauvinisme »."},{"w":"jubilant","p":"adj.","m":"Feeling or expressing great joy.","e":"Latin <i>iubilare</i> (to shout with joy), originally a shepherd’s call; later linked to the Hebrew <i>yobel</i> (jubilee).","f":"jubilant, exultant","t":"« Jubiler » = to rejoice. A jubilant crowd after a final whistle."},{"w":"juxtapose","p":"v.","m":"To place side by side for contrast.","e":"French <i>juxtaposer</i>, from Latin <i>iuxta</i> (beside) + French <i>poser</i> (to place).","f":"juxtaposer","t":"Identical to « juxtaposer ». A before/after slide juxtaposes two images."},{"w":"languid","p":"adj.","m":"Slow and relaxed; lacking energy.","e":"Latin <i>languidus</i> (faint, weak), from <i>languere</i> (to be weak). Same root as languish.","f":"langoureux, alangui, nonchalant","t":"Think « languir » and « langueur »: a languid afternoon in the heat."},{"w":"magnanimous","p":"adj.","m":"Generous and forgiving, especially to a rival.","e":"Latin <i>magnanimus</i>: <i>magnus</i> (great) + <i>animus</i> (soul, spirit).","f":"magnanime","t":"Magna + anima = a great soul. Same as « magnanime ». The winner who praises the loser."},{"w":"mollify","p":"v.","m":"To calm someone’s anger or anxiety.","e":"Latin <i>mollificare</i>: <i>mollis</i> (soft) + <i>facere</i> (to make).","f":"apaiser, amadouer","t":"Mollis = mou. To mollify an angry client = to soften them."},{"w":"negligible","p":"adj.","m":"So small or unimportant it can be ignored.","e":"From French <i>négligeable</i>, from Latin <i>neglegere</i> (to disregard): <i>nec</i> (not) + <i>legere</i> (to pick up).","f":"négligeable","t":"Identical to « négligeable ». Something you can neglect."},{"w":"panache","p":"n.","m":"Flamboyant confidence of style.","e":"French <i>panache</i>, the plume of feathers on a helmet, from Italian <i>pennacchio</i>, from Latin <i>penna</i> (feather).","f":"panache","t":"Cyrano de Bergerac’s last word: « mon panache »! The helmet plume worn with style."},{"w":"precocious","p":"adj.","m":"Having developed abilities unusually early.","e":"Latin <i>praecox</i>, “ripened early”: <i>prae</i> (before) + <i>coquere</i> (to cook, ripen).","f":"précoce","t":"Same as « précoce »: cooked before its time. A precocious child reads at three."},{"w":"quotidian","p":"adj.","m":"Ordinary, everyday.","e":"Latin <i>quotidianus</i>, from <i>quotidie</i> (daily): <i>quot</i> (how many) + <i>dies</i> (day).","f":"quotidien","t":"Quotidian = « quotidien ». Le Quotidien, your daily paper: totally ordinary."},{"w":"refractory","p":"adj.","m":"Stubborn and unmanageable.","e":"Latin <i>refractarius</i> (obstinate), from <i>refringere</i> (to break back): <i>re-</i> + <i>frangere</i> (to break).","f":"réfractaire, rebelle","t":"Les « réfractaires » refused to submit (e.g. to the STO in WWII). Refractory = resists control."},{"w":"rudimentary","p":"adj.","m":"Basic, elementary; undeveloped.","e":"Latin <i>rudimentum</i> (first attempt), from <i>rudis</i> (rough, untrained).","f":"rudimentaire","t":"Identical to « rudimentaire ». Rudis = raw, rough."},{"w":"spurious","p":"adj.","m":"False; not genuine or valid.","e":"Late Latin <i>spurius</i> (illegitimate, of unknown father).","f":"faux, fallacieux, apocryphe","t":"Spurius = illegitimate child: a spurious argument doesn’t come from a real source."},{"w":"staunch","p":"adj.","m":"Very loyal and committed.","e":"Old French <i>estanche</i> (watertight), from <i>estanchier</i> (to stop a flow). Watertight → reliable → loyal.","f":"loyal, fervent, inébranlable","t":"Étanche = watertight! A staunch ally never leaks."},{"w":"subsume","p":"v.","m":"To include within a larger group.","e":"Modern Latin <i>subsumere</i>: <i>sub</i> (under) + <i>sumere</i> (to take).","f":"englober, subsumer","t":"Take under: the smaller category is taken under the bigger one."},{"w":"supplant","p":"v.","m":"To replace, often by force or scheming.","e":"Latin <i>supplantare</i>, “to trip up”: <i>sub</i> (under) + <i>planta</i> (sole of the foot).","f":"supplanter, évincer","t":"Same as « supplanter »: you trip someone up and take their place."},{"w":"tantamount","p":"adj.","m":"Equivalent in seriousness to.","e":"Anglo-French <i>tant amunter</i>, “to amount to as much”: <i>tant</i> (so much) + <i>amonter</i> (to go up, amount).","f":"équivalent à, qui revient à","t":"Tant + monter = amounts to as much. Silence is tantamount to consent."},{"w":"tenacious","p":"adj.","m":"Holding firmly; persistent.","e":"Latin <i>tenax, tenacis</i>, from <i>tenere</i> (to hold).","f":"tenace","t":"Same as « tenace »: a grip that won’t let go."},{"w":"travesty","p":"n.","m":"A false, absurd or distorted version of something.","e":"French <i>travesti</i> (disguised), from Italian <i>travestire</i>: <i>tra-</i> (across) + <i>vestire</i> (to dress).","f":"parodie, simulacre","t":"« Travesti » = dressed up as something else. A travesty of justice is justice in disguise."},{"w":"treacherous","p":"adj.","m":"Guilty of betrayal; also hazardous.","e":"Old French <i>trecherous</i>, from <i>trechier</i> (to cheat, trick).","f":"traître, perfide; dangereux","t":"Think « tricher »: a treacherous friend cheats you; a treacherous road tricks your tyres."},{"w":"unequivocal","p":"adj.","m":"Leaving no doubt; unambiguous.","e":"<i>un-</i> + equivocal, from Late Latin <i>aequivocus</i>: <i>aequus</i> (equal) + <i>vox</i> (voice).","f":"sans équivoque, catégorique","t":"Exactly « sans équivoque »: only one voice speaking."},{"w":"vehement","p":"adj.","m":"Showing strong, forceful feeling.","e":"Latin <i>vehementem</i> (impetuous, violent), possibly from <i>vehere</i> (to carry) + <i>mens</i> (mind): carried away.","f":"véhément","t":"Same as « véhément »: a mind carried away by passion."},{"w":"vilify","p":"v.","m":"To speak or write about in an abusive, disparaging way.","e":"Late Latin <i>vilificare</i>: <i>vilis</i> (cheap, base) + <i>facere</i> (to make).","f":"diffamer, dénigrer, vilipender","t":"Make vile = « vilipender ». The tabloids vilified her."}]},{"name":"Common Words IV","slug":"common-words-iv","series":"Common Words","words":[{"w":"aberrant","p":"adj.","m":"Departing from what is normal or accepted.","e":"Latin <i>aberrantem</i>, from <i>aberrare</i>: <i>ab-</i> (away) + <i>errare</i> (to wander).","f":"aberrant","t":"Same root as aberration: wandering (errer) off the path. Identical to « aberrant »."},{"w":"abstruse","p":"adj.","m":"Difficult to understand; obscure.","e":"Latin <i>abstrusus</i> (hidden), from <i>abstrudere</i>: <i>abs-</i> (away) + <i>trudere</i> (to push). Pushed away out of sight.","f":"abstrus, abscons","t":"Same as « abstrus »: an idea pushed so far away you can’t reach it."},{"w":"acerbic","p":"adj.","m":"Sharp and forthright, especially in criticism.","e":"Latin <i>acerbus</i> (harsh, bitter, sour), related to <i>acer</i> (sharp).","f":"acerbe, caustique","t":"« Un ton acerbe ». Same acer as aigre and vinaigre."},{"w":"adamant","p":"adj.","m":"Refusing to change one’s mind; unshakable.","e":"Greek <i>adamas</i>, “unconquerable”: <i>a-</i> (not) + <i>daman</i> (to tame). A legendary unbreakable stone, later diamond.","f":"inflexible, intransigent","t":"Adamas = the unbreakable stone that gave « diamant ». An adamant person is diamond-hard."},{"w":"admonitory","p":"adj.","m":"Giving or conveying a warning or reprimand.","e":"Latin <i>admonere</i>, “to remind, warn”: <i>ad-</i> + <i>monere</i> (to warn), as in monitor.","f":"d’avertissement, réprobateur","t":"Ad + monere: a monitor warning you. Une admonestation = a reprimand."},{"w":"apocryphal","p":"adj.","m":"Of doubtful authenticity, though widely repeated.","e":"Greek <i>apokryphos</i> (hidden): <i>apo</i> + <i>kryptein</i> (to hide). The Apocrypha were biblical books excluded as of uncertain origin.","f":"apocryphe","t":"Same as « apocryphe ». Like the famous quote nobody actually said."},{"w":"blatant","p":"adj.","m":"Done openly and unashamedly; very obvious.","e":"Coined by Edmund Spenser in <i>The Faerie Queene</i> (1596) for the “Blatant Beast”, a noisy monster of slander; perhaps from Latin <i>blatire</i> (to babble).","f":"flagrant, criant","t":"Spenser’s loud Blatant Beast: blatant things shout at you. « Un mensonge flagrant »."},{"w":"bumbling","p":"adj.","m":"Acting in a confused or clumsy way.","e":"From <i>bumble</i>, an imitative English word (like the buzz of a bumblebee), meaning to blunder or ramble.","f":"maladroit, empoté","t":"A bumblebee bumping into windows. Inspector Clouseau is a bumbling detective."},{"w":"burgeon","p":"v.","m":"To grow or increase rapidly; flourish.","e":"Old French <i>borjoner</i> (to bud), from <i>borjon</i> (bud), modern <i>bourgeon</i>.","f":"bourgeonner, croître rapidement","t":"Burgeon = « bourgeonner »: buds bursting out in spring. A burgeoning start-up scene."},{"w":"confound","p":"v.","m":"To confuse; or to prove wrong.","e":"Old French <i>confondre</i>, from Latin <i>confundere</i>, “to pour together”: <i>com-</i> + <i>fundere</i> (to pour).","f":"confondre, déconcerter","t":"Same as « confondre »: everything poured together. Results that confound the experts prove them wrong."},{"w":"construe","p":"v.","m":"To interpret a meaning.","e":"Latin <i>construere</i>, “to pile together, build”: <i>com-</i> + <i>struere</i> (to build). In grammar, to build up a sentence’s meaning.","f":"interpréter","t":"You construct a meaning. Misconstrue = to build the wrong one."},{"w":"contingent","p":"adj. / n.","m":"Dependent on something uncertain. (n.: a group within a larger one.)","e":"Latin <i>contingentem</i>, from <i>contingere</i>, “to touch, befall”: <i>com-</i> + <i>tangere</i> (to touch).","f":"subordonné à, éventuel; contingent","t":"The offer is contingent on due diligence: it touches on it and depends on it. « Les contingences »."},{"w":"copious","p":"adj.","m":"Abundant, plentiful.","e":"Latin <i>copiosus</i>, from <i>copia</i> (abundance), as in cornucopia.","f":"copieux, abondant","t":"« Un repas copieux ». Copia = abundance."},{"w":"decorum","p":"n.","m":"Behaviour in keeping with good taste and propriety.","e":"Latin <i>decorum</i> (that which is proper), from <i>decere</i> (to be fitting).","f":"décorum, bienséance","t":"Identical to « le décorum ». Same family as decorous."},{"w":"denigrate","p":"v.","m":"To criticise unfairly; belittle.","e":"Latin <i>denigrare</i>, “to blacken”: <i>de-</i> + <i>nigrare</i>, from <i>niger</i> (black).","f":"dénigrer","t":"Same as « dénigrer »: blackening someone’s name."},{"w":"discrete","p":"adj.","m":"Separate and distinct.","e":"Latin <i>discretus</i> (separated), from <i>discernere</i>: <i>dis-</i> (apart) + <i>cernere</i> (to sift). Same origin as discreet, split in spelling later.","f":"distinct, séparé; discret (maths)","t":"Discrete = distinct units, like discrete maths. Discreet (ee) = « discret », tactful."},{"w":"eradicate","p":"v.","m":"To destroy completely; wipe out.","e":"Latin <i>eradicare</i>, “to pull up by the roots”: <i>e-</i> (out) + <i>radix</i> (root).","f":"éradiquer","t":"Radix = racine: pulling the weed out by its root. Same as « éradiquer »."},{"w":"espouse","p":"v.","m":"To adopt or support a cause or belief.","e":"Old French <i>espouser</i> (to marry), from Latin <i>sponsare</i>, from <i>spondere</i> (to promise).","f":"épouser (une cause), embrasser","t":"Exactly « épouser une cause »: you marry the idea."},{"w":"exacting","p":"adj.","m":"Making great demands; strict.","e":"From <i>exact</i> (to demand), Latin <i>exigere</i>, “to drive out, demand”: <i>ex-</i> + <i>agere</i>.","f":"exigeant","t":"Exacting = « exigeant », from the same exigere. An exacting partner."},{"w":"exalt","p":"v.","m":"To praise highly; raise in rank.","e":"Latin <i>exaltare</i>: <i>ex-</i> + <i>altus</i> (high).","f":"exalter, glorifier","t":"Ex + altus = lift up high. « Exalter »."},{"w":"exonerate","p":"v.","m":"To clear from blame.","e":"Latin <i>exonerare</i>, “to unload”: <i>ex-</i> + <i>onus, oneris</i> (burden).","f":"disculper, exonérer","t":"Onus = burden: lifting the burden of guilt off someone. « Exonérer » in French is mostly about taxes, but same image."},{"w":"expound","p":"v.","m":"To explain in detail.","e":"Old French <i>espondre</i>, from Latin <i>exponere</i>, “to put forth”: <i>ex-</i> + <i>ponere</i> (to place).","f":"exposer, expliquer en détail","t":"Expound = « exposer » (same exponere). Expounding a theory at length."},{"w":"forthcoming","p":"adj.","m":"Willing to share information; also about to happen.","e":"English <i>forth</i> (forward) + <i>coming</i>. Germanic.","f":"ouvert, communicatif; à venir","t":"Coming forth with information. An unforthcoming witness says nothing."},{"w":"hackneyed","p":"adj.","m":"Overused, unoriginal; trite.","e":"From <i>hackney</i>, a horse for hire (perhaps from Hackney, the London village). A horse used by everyone became anything worn out.","f":"rebattu, éculé, banal","t":"Picture a tired hired horse ridden by everyone. A hackneyed phrase has been ridden to death."},{"w":"iconoclastic","p":"adj.","m":"Attacking cherished beliefs or institutions.","e":"Greek <i>eikōn</i> (image) + <i>klastēs</i> (breaker). From the Byzantine image-smashers.","f":"iconoclaste","t":"The adjective of iconoclast: smashing sacred images, or sacred ideas."},{"w":"idiosyncrasy","p":"n.","m":"A peculiar habit or way of behaving.","e":"Greek <i>idiosynkrasia</i>: <i>idios</i> (one’s own) + <i>synkrasis</i> (mixture of temperaments).","f":"particularité, manie, idiosyncrasie","t":"Idios = one’s own (as in idiom): your own personal mix of quirks."},{"w":"ignoble","p":"adj.","m":"Dishonourable; base.","e":"Latin <i>ignobilis</i>: <i>in-</i> (not) + <i>nobilis</i> (noble, well known).","f":"ignoble, vil","t":"Not noble. Same as « ignoble »."},{"w":"implacable","p":"adj.","m":"Unable to be appeased; relentless.","e":"Latin <i>implacabilis</i>: <i>in-</i> (not) + <i>placare</i> (to calm, appease).","f":"implacable","t":"Same as « implacable »: impossible to placate."},{"w":"implausible","p":"adj.","m":"Not seeming reasonable or likely.","e":"<i>in-</i> + Latin <i>plausibilis</i> (deserving applause), from <i>plaudere</i> (to clap).","f":"invraisemblable, peu plausible","t":"An excuse nobody would applaud. « Pas plausible »."},{"w":"incorrigible","p":"adj.","m":"Not able to be corrected or reformed.","e":"Latin <i>incorrigibilis</i>: <i>in-</i> + <i>corrigere</i> (to correct).","f":"incorrigible","t":"Identical to « incorrigible »: beyond correction."},{"w":"indifference","p":"n.","m":"Lack of interest or concern. (Also mediocrity.)","e":"Latin <i>indifferentia</i>: <i>in-</i> + <i>differre</i> (to differ). It makes no difference to you.","f":"indifférence","t":"Same as « indifférence ». Careful: indifferent can also mean mediocre on the GRE."},{"w":"ingratiate","p":"v.","m":"To bring oneself into favour, often by flattery.","e":"Italian <i>ingratiare</i>, from Latin <i>in gratiam</i> (into favour), <i>gratia</i> (grace).","f":"s’attirer les bonnes grâces de, s’insinuer","t":"Getting into someone’s good graces (gratia). « S’attirer les bonnes grâces »."},{"w":"intransigent","p":"adj.","m":"Unwilling to compromise.","e":"Spanish <i>intransigente</i>, from Latin <i>in-</i> + <i>transigere</i> (to come to an agreement).","f":"intransigeant","t":"Same as « intransigeant »: no transaction possible."},{"w":"largess","p":"n.","m":"Generosity in giving gifts or money.","e":"Old French <i>largesse</i>, from <i>large</i> (generous), Latin <i>largus</i> (abundant).","f":"largesse, générosité","t":"Identical to « largesse ». A lord throwing coins from his carriage."},{"w":"laudable","p":"adj.","m":"Deserving praise.","e":"Latin <i>laudabilis</i>, from <i>laudare</i> (to praise), <i>laus</i> (praise).","f":"louable","t":"Laud = louer (to praise). Laudable = louable."},{"w":"myopic","p":"adj.","m":"Short-sighted; lacking foresight.","e":"Greek <i>myōps</i>, “short-sighted”: <i>myein</i> (to shut) + <i>ōps</i> (eye). Squinting with half-closed eyes.","f":"myope; à courte vue","t":"Same as « myope ». A myopic strategy only sees this quarter."},{"w":"opaque","p":"adj.","m":"Not transparent; hard to understand.","e":"Latin <i>opacus</i> (shaded, dark).","f":"opaque, obscur","t":"Same as « opaque »: light can’t get through, and neither can meaning."},{"w":"ostentatious","p":"adj.","m":"Designed to impress; showy.","e":"Latin <i>ostentatio</i> (display), from <i>ostendere</i> (to show): <i>ob-</i> + <i>tendere</i> (to stretch).","f":"ostentatoire, tape-à-l’œil","t":"« Ostentatoire »: stretching it out for everyone to see."},{"w":"pedantic","p":"adj.","m":"Overly concerned with minor details and rules.","e":"Italian <i>pedante</i> (schoolmaster), probably related to Greek <i>paideuein</i> (to teach).","f":"pédant, pointilleux","t":"Same as « pédant »: the schoolmaster correcting your commas."},{"w":"petulant","p":"adj.","m":"Childishly sulky or bad-tempered.","e":"Latin <i>petulantem</i> (forward, insolent), from <i>petere</i> (to attack, seek).","f":"irritable, boudeur (≠ pétulant)","x":"Faux ami","t":"Careful: French « pétulant » means lively. English petulant = a sulking toddler."},{"w":"pragmatic","p":"adj.","m":"Dealing with things practically, not theoretically.","e":"Greek <i>pragmatikos</i> (businesslike), from <i>pragma</i> (deed, affair), from <i>prassein</i> (to do).","f":"pragmatique","t":"Pragma = action. Same as « pragmatique »."},{"w":"provincial","p":"adj.","m":"Unsophisticated, narrow-minded.","e":"Latin <i>provincialis</i>, from <i>provincia</i> (a territory outside Rome).","f":"provincial, borné","t":"Like parochial: thinking from far away from the capital. « Un esprit provincial »."},{"w":"pundit","p":"n.","m":"An expert who gives opinions publicly.","e":"Hindi <i>paṇḍit</i>, from Sanskrit <i>paṇḍita</i> (learned man).","f":"expert, commentateur","t":"A pandit was a learned Hindu scholar. Today’s pundits are TV experts."},{"w":"reconcile","p":"v.","m":"To restore friendly relations; make compatible.","e":"Latin <i>reconciliare</i>: <i>re-</i> + <i>conciliare</i> (to bring together).","f":"réconcilier, concilier","t":"Same as « réconcilier ». You also reconcile two sets of numbers in a model."},{"w":"refute","p":"v.","m":"To prove wrong.","e":"Latin <i>refutare</i> (to drive back, disprove).","f":"réfuter","t":"Same as « réfuter ». Not just deny: prove false."},{"w":"soporific","p":"adj.","m":"Causing sleep; very boring.","e":"Latin <i>sopor</i> (deep sleep) + <i>-ficus</i> (making).","f":"soporifique","t":"Identical to « soporifique ». A soporific lecture."},{"w":"temperance","p":"n.","m":"Moderation, self-restraint (especially with alcohol).","e":"Latin <i>temperantia</i> (moderation), from <i>temperare</i> (to mix in due proportion).","f":"tempérance, modération","t":"One of the four cardinal virtues: « la tempérance ». Tempered = mixed in the right dose."},{"w":"tortuous","p":"adj.","m":"Full of twists and turns; overly complex.","e":"Latin <i>tortuosus</i>, from <i>tortus</i> (twisted), from <i>torquere</i> (to twist).","f":"tortueux","t":"Same as « tortueux ». Not torturous (painful) — tortuous twists."},{"w":"underscore","p":"v.","m":"To emphasise.","e":"English <i>under</i> + <i>score</i> (a line, from Old Norse <i>skor</i>, notch). Literally to underline.","f":"souligner","t":"Underline = « souligner ». The data underscores the risk."},{"w":"unscrupulous","p":"adj.","m":"Having no moral principles; not honest.","e":"<i>un-</i> + scrupulous, from Latin <i>scrupulus</i> (a small sharp stone): the pebble in your sandal that bothers your conscience.","f":"sans scrupules","t":"Scrupulus = a little stone in your shoe. The unscrupulous feel no pebble at all. « Sans scrupules »."}]},{"name":"Common Words V","slug":"common-words-v","series":"Common Words","words":[{"w":"accolade","p":"n.","m":"An award or expression of praise.","e":"French <i>accolade</i>, an embrace, from Latin <i>ad</i> + <i>collum</i> (neck). The knight’s ceremony included an embrace or a tap on the neck with the sword.","f":"distinction, éloge (accolade = hug)","t":"The king dubbing a knight with an embrace around the neck (collum). Today: an honour, a prize."},{"w":"admonish","p":"v.","m":"To warn or reprimand firmly.","e":"Old French <i>amonester</i>, from Latin <i>admonere</i>: <i>ad-</i> + <i>monere</i> (to warn).","f":"admonester, réprimander","t":"Same as « admonester ». Monere = warn, like a monitor."},{"w":"antithetical","p":"adj.","m":"Directly opposed.","e":"Greek <i>antithesis</i>: <i>anti</i> (against) + <i>tithenai</i> (to place). Placed against.","f":"antithétique, opposé","t":"Thesis vs antithesis: placed against each other. « Aux antipodes »."},{"w":"arbitrary","p":"adj.","m":"Based on random choice or personal whim, not reason.","e":"Latin <i>arbitrarius</i>, from <i>arbiter</i> (judge). Left to the judge’s discretion.","f":"arbitraire","t":"Same as « arbitraire »: whatever the arbitre decides on a whim."},{"w":"arcane","p":"adj.","m":"Understood by few; mysterious.","e":"Latin <i>arcanus</i> (secret), from <i>arca</i> (chest, box). Locked in a box.","f":"obscur, ésotérique; les arcanes","t":"« Les arcanes du pouvoir »: secrets locked in a chest (arca)."},{"w":"audacity","p":"n.","m":"Willingness to take bold risks; rude boldness.","e":"Latin <i>audacia</i>, from <i>audax</i> (bold), <i>audere</i> (to dare).","f":"audace; culot","t":"« L’audace ». Can be praise (bold) or blame (the audacity to ask!)."},{"w":"austere","p":"adj.","m":"Severe or strict; plain, without comfort.","e":"Greek <i>austēros</i> (harsh, bitter, making the tongue dry), via Latin <i>austerus</i>.","f":"austère","t":"Same as « austère ». A monk’s cell: bare walls, no comfort."},{"w":"brazen","p":"adj.","m":"Bold and shameless.","e":"Old English <i>bræsen</i> (made of brass). Brass = hard and loud, hence shameless.","f":"effronté, éhonté","t":"A face made of brass: no blush possible. A brazen lie."},{"w":"circumscribe","p":"v.","m":"To restrict within limits.","e":"Latin <i>circumscribere</i>: <i>circum</i> (around) + <i>scribere</i> (to write, draw). Drawing a line around.","f":"circonscrire, limiter","t":"Same as « circonscrire »: drawing a circle around something (une circonscription)."},{"w":"constituent","p":"n. / adj.","m":"A component part; a voter in a district.","e":"Latin <i>constituentem</i>, from <i>constituere</i> (to set up): <i>com-</i> + <i>statuere</i> (to set).","f":"composant, constituant; électeur","t":"The parts that constitute something, or the voters who constitute a constituency."},{"w":"dilettante","p":"n.","m":"A person with superficial interest in an art or subject.","e":"Italian <i>dilettante</i> (lover of the arts), from <i>dilettare</i> (to delight), Latin <i>delectare</i>.","f":"dilettante, amateur","t":"Same as « dilettante »: dabbling for delight, never mastering."},{"w":"foment","p":"v.","m":"To stir up trouble or rebellion.","e":"Latin <i>fomentare</i>, from <i>fomentum</i> (a warm poultice), from <i>fovere</i> (to warm).","f":"fomenter","t":"Same as « fomenter un complot »: keeping a revolt warm until it hatches."},{"w":"garrulous","p":"adj.","m":"Excessively talkative about trivial things.","e":"Latin <i>garrulus</i> (chattering), from <i>garrire</i> (to chatter).","f":"bavard, loquace","t":"Garrire = to chatter like a bird. A garrulous seatmate on a long flight."},{"w":"gauche","p":"adj.","m":"Socially awkward; tactless.","e":"French <i>gauche</i> (left; clumsy), probably from Frankish <i>welkan</i> (to wilt).","f":"gauche, maladroit","t":"Exactly French « gauche »: clumsy, like doing everything with the left hand."},{"w":"haphazard","p":"adj.","m":"Lacking order or plan; random.","e":"English <i>hap</i> (luck, from Old Norse <i>happ</i>) + <i>hazard</i> (chance, via French <i>hasard</i> from Arabic <i>az-zahr</i>, the die).","f":"au hasard, désordonné","t":"Hap + hasard = luck + luck. Nothing planned."},{"w":"hegemony","p":"n.","m":"Dominance of one group or state over others.","e":"Greek <i>hēgemonia</i> (leadership), from <i>hēgemōn</i> (leader), <i>hēgeisthai</i> (to lead).","f":"hégémonie","t":"Same as « hégémonie »: Athens leading the other Greek cities."},{"w":"inimical","p":"adj.","m":"Hostile; harmful.","e":"Late Latin <i>inimicalis</i>, from <i>inimicus</i> (enemy): <i>in-</i> + <i>amicus</i> (friend).","f":"hostile, nuisible","t":"In-amicus = not a friend → « ennemi ». Conditions inimical to growth."},{"w":"inscrutable","p":"adj.","m":"Impossible to understand or interpret.","e":"Late Latin <i>inscrutabilis</i>: <i>in-</i> + <i>scrutari</i> (to search, examine).","f":"impénétrable, insondable","t":"Can’t be scrutinised. An inscrutable poker face."},{"w":"insolent","p":"adj.","m":"Rude and disrespectful.","e":"Latin <i>insolentem</i> (unusual, arrogant): <i>in-</i> + <i>solere</i> (to be accustomed).","f":"insolent","t":"Same as « insolent »."},{"w":"intrepid","p":"adj.","m":"Fearless; adventurous.","e":"Latin <i>intrepidus</i>: <i>in-</i> (not) + <i>trepidus</i> (alarmed).","f":"intrépide","t":"Same as « intrépide »: no trépidation."},{"w":"inveterate","p":"adj.","m":"Having a long-established habit unlikely to change.","e":"Latin <i>inveteratus</i> (grown old), from <i>vetus</i> (old), as in veteran.","f":"invétéré","t":"Same as « un fumeur invétéré ». A veteran habit."},{"w":"irrevocable","p":"adj.","m":"Not able to be changed or reversed.","e":"Latin <i>irrevocabilis</i>: <i>in-</i> + <i>revocare</i> (to call back).","f":"irrévocable","t":"Same as « irrévocable »: can’t be called back."},{"w":"lionize","p":"v.","m":"To treat someone as a celebrity.","e":"From lion, in the 18th-century sense “a celebrity”: from the custom of taking visitors to see the lions at the Tower of London.","f":"porter aux nues, aduler","t":"Treat someone like the star attraction: the lion everyone queues to see."},{"w":"munificent","p":"adj.","m":"Very generous.","e":"Latin <i>munificus</i>: <i>munus</i> (gift, duty) + <i>facere</i> (to make).","f":"munificent, généreux","t":"A maker of gifts. Same as « munificent » (rare in French)."},{"w":"myriad","p":"n. / adj.","m":"Countless; a great number.","e":"Greek <i>myrias</i> (ten thousand), from <i>myrioi</i> (countless).","f":"myriade","t":"« Une myriade d’étoiles ». Literally 10,000."},{"w":"obsequious","p":"adj.","m":"Excessively eager to please or obey.","e":"Latin <i>obsequiosus</i>, from <i>obsequi</i> (to comply): <i>ob-</i> + <i>sequi</i> (to follow).","f":"obséquieux","t":"Same as « obséquieux »: following someone everywhere to please them."},{"w":"ostracize","p":"v.","m":"To exclude from a group.","e":"Greek <i>ostrakizein</i>, from <i>ostrakon</i> (pottery shard). Athenians voted to exile someone by writing his name on shards.","f":"ostraciser, exclure","t":"Picture Athenians scratching a name on a broken pot to banish him."},{"w":"pedestrian","p":"adj.","m":"Dull, unimaginative.","e":"Latin <i>pedester</i> (on foot; prosaic), from <i>pes, pedis</i> (foot). Prose was “on foot”, poetry had wings.","f":"terne, prosaïque, banal","x":"2nd meaning","t":"Not the person crossing the road: a style that plods on foot instead of flying."},{"w":"pernicious","p":"adj.","m":"Having a harmful effect, especially gradually.","e":"Latin <i>perniciosus</i>, from <i>pernicies</i> (destruction): <i>per-</i> + <i>nex, necis</i> (death).","f":"pernicieux","t":"Same as « pernicieux ». Nex = death, slowly."},{"w":"poignant","p":"adj.","m":"Evoking a keen sense of sadness.","e":"Old French <i>poignant</i> (pricking), from <i>poindre</i>, Latin <i>pungere</i> (to prick).","f":"poignant, émouvant","t":"Same as « poignant »: it pricks your heart (pungere, as in punctuation)."},{"w":"precipitous","p":"adj.","m":"Dangerously steep; also sudden.","e":"Latin <i>praeceps</i> (headlong): <i>prae</i> (before) + <i>caput</i> (head).","f":"abrupt, escarpé; précipité","t":"Head first over the précipice. A precipitous drop in sales."},{"w":"prodigious","p":"adj.","m":"Remarkably great in size or degree.","e":"Latin <i>prodigiosus</i>, from <i>prodigium</i> (omen, marvel).","f":"prodigieux","t":"Same as « prodigieux »: like an omen, it amazes."},{"w":"prolific","p":"adj.","m":"Producing much; productive.","e":"French <i>prolifique</i>, from Latin <i>proles</i> (offspring) + <i>facere</i>.","f":"prolifique","t":"Same as « prolifique »: lots of offspring."},{"w":"propitious","p":"adj.","m":"Favourable; indicating a good chance of success.","e":"Latin <i>propitius</i> (favourable, gracious), perhaps from <i>pro</i> + <i>petere</i> (to seek).","f":"propice","t":"Propitious = « propice »: « un moment propice »."},{"w":"ravenous","p":"adj.","m":"Extremely hungry.","e":"Old French <i>ravineus</i> (violent, rapacious), from <i>raviner</i> (to ravage), Latin <i>rapina</i> (plunder).","f":"affamé, vorace","t":"Hungry enough to plunder (rapina, as in « rapine »). Not from the bird raven."},{"w":"repudiate","p":"v.","m":"To refuse to accept; reject.","e":"Latin <i>repudiare</i> (to divorce, reject), from <i>repudium</i> (divorce).","f":"répudier, rejeter","t":"« Répudier sa femme »: in Rome, a formal divorce. Repudiate a claim = cast it off."},{"w":"rescind","p":"v.","m":"To revoke or cancel.","e":"Latin <i>rescindere</i> (to cut off): <i>re-</i> + <i>scindere</i> (to split).","f":"annuler, révoquer, rescinder","t":"Scindere = scinder, to cut: rescinding a contract cuts it off."},{"w":"resurgent","p":"adj.","m":"Increasing or reviving after a period of decline.","e":"Latin <i>resurgere</i> (to rise again): <i>re-</i> + <i>surgere</i> (to rise).","f":"renaissant, en plein renouveau","t":"Rising again, like resurrection. « Une résurgence »."},{"w":"reverent","p":"adj.","m":"Feeling or showing deep respect.","e":"Latin <i>reverentem</i>, from <i>revereri</i> (to stand in awe of).","f":"révérencieux, respectueux","t":"« Faire la révérence »: a deep, respectful bow."},{"w":"sanction","p":"n. / v.","m":"Official approval OR a penalty (contranym).","e":"Latin <i>sanctio</i> (decree, penalty), from <i>sancire</i> (to make sacred, decree).","f":"approbation; sanction","x":"2nd meaning","t":"A decree can approve or punish. On the GRE it often means approve: « entériner »."},{"w":"scrupulous","p":"adj.","m":"Very careful, honest and thorough.","e":"Latin <i>scrupulosus</i>, from <i>scrupulus</i> (small sharp stone; a pang of conscience).","f":"scrupuleux","t":"Same as « scrupuleux »: feeling every tiny pebble in your shoe."},{"w":"sporadic","p":"adj.","m":"Occurring at irregular intervals.","e":"Greek <i>sporadikos</i> (scattered), from <i>speirein</i> (to sow).","f":"sporadique","t":"Seeds scattered when sowing (as in spore). « Sporadique »."},{"w":"subversive","p":"adj.","m":"Seeking to undermine an established system.","e":"Latin <i>subvertere</i>: <i>sub</i> (under) + <i>vertere</i> (to turn). Turning upside down from below.","f":"subversif","t":"Same as « subversif »: turning the system over from underneath."},{"w":"sycophant","p":"n.","m":"A servile flatterer.","e":"Greek <i>sykophantēs</i> (informer), literally “fig-shower”: <i>sykon</i> (fig) + <i>phainein</i> (to show). Origin of the image debated.","f":"flagorneur, lèche-bottes","t":"The fig-shower: picture a courtier offering figs to the king, nodding at every word."},{"w":"taciturn","p":"adj.","m":"Saying little; reserved.","e":"Latin <i>taciturnus</i>, from <i>tacitus</i> (silent), <i>tacere</i> (to be silent).","f":"taciturne","t":"Same as « taciturne ». Tacere = se taire."},{"w":"tempered","p":"adj.","m":"Moderated or toned down.","e":"Latin <i>temperare</i> (to mix in proper proportion).","f":"tempéré, nuancé, modéré","t":"Like tempered steel or a « climat tempéré »: optimism tempered by realism."},{"w":"tractable","p":"adj.","m":"Easy to control or deal with.","e":"Latin <i>tractabilis</i>, from <i>tractare</i> (to handle), frequentative of <i>trahere</i> (to pull).","f":"docile, maniable","t":"Easy to pull, like a tractor pulling a docile cart. Opposite: intractable."},{"w":"trite","p":"adj.","m":"Overused and unoriginal.","e":"Latin <i>tritus</i> (worn out), from <i>terere</i> (to rub).","f":"banal, rebattu","t":"Rubbed so much it’s worn out. A trite cliché."},{"w":"vacillate","p":"v.","m":"To waver between opinions.","e":"Latin <i>vacillare</i> (to sway, totter).","f":"vaciller, hésiter","t":"Same as « vaciller »: a candle flame swaying back and forth."},{"w":"winsome","p":"adj.","m":"Charming, engaging.","e":"Old English <i>wynsum</i>: <i>wynn</i> (joy) + <i>-sum</i> (-some). Germanic.","f":"charmant, avenant","t":"Win + some: a smile that wins you over. Old English wynn = joy."}]},{"name":"Common Words VI","slug":"common-words-vi","series":"Common Words","words":[{"w":"anomaly","p":"n.","m":"Something that deviates from what is expected.","e":"Greek <i>anōmalia</i>: <i>an-</i> (not) + <i>homalos</i> (even).","f":"anomalie","t":"Same as « anomalie »: the point off the even line."},{"w":"antipathy","p":"n.","m":"A deep-seated dislike.","e":"Greek <i>antipatheia</i>: <i>anti</i> (against) + <i>pathos</i> (feeling).","f":"antipathie","t":"Feeling against: the opposite of sympathy. « Antipathie »."},{"w":"appease","p":"v.","m":"To pacify by giving in to demands.","e":"Old French <i>apaisier</i>: <i>a</i> + <i>pais</i> (peace), Latin <i>pax</i>.","f":"apaiser","t":"Appease = « apaiser »: bringing peace. Munich 1938 = appeasement."},{"w":"arduous","p":"adj.","m":"Involving great effort; difficult.","e":"Latin <i>arduus</i> (steep, difficult).","f":"ardu, pénible","t":"Same as « ardu »: a steep climb."},{"w":"askance","p":"adv.","m":"With suspicion or disapproval (to look askance).","e":"Origin uncertain, 1500s; perhaps from Italian <i>a scancio</i> (sideways).","f":"de travers, avec méfiance","t":"Looking at someone sideways: « regarder de travers »."},{"w":"banality","p":"n.","m":"The quality of being trite or unoriginal.","e":"French <i>banalité</i>, from <i>banal</i>, from the feudal <i>ban</i> (Frankish): the lord’s oven used by all.","f":"banalité","t":"Same as « banalité ». The village four banal again."},{"w":"bolster","p":"v.","m":"To support or strengthen.","e":"Old English <i>bolster</i> (a long pillow). Germanic. To prop up with a cushion.","f":"renforcer, étayer, soutenir","t":"A bolster is a long pillow propping you up. Data that bolsters your case."},{"w":"capricious","p":"adj.","m":"Given to sudden, unpredictable changes.","e":"French <i>capricieux</i>, from Italian <i>capriccio</i> (a sudden start, whim), perhaps from <i>capra</i> (goat) for its leaps.","f":"capricieux","t":"A goat leaping unpredictably: « capricieux »."},{"w":"contrition","p":"n.","m":"Sincere remorse.","e":"Latin <i>contritio</i> (grinding), from <i>conterere</i> (to grind, crush). A heart crushed by guilt.","f":"contrition, repentir","t":"Same as « contrition » in confession: a heart ground down by guilt."},{"w":"craven","p":"adj.","m":"Contemptibly cowardly.","e":"Middle English <i>cravant</i> (defeated), probably from Old French <i>cravanté</i> (crushed).","f":"lâche, couard","t":"Defeated and crushed: a craven surrender."},{"w":"deleterious","p":"adj.","m":"Causing harm.","e":"Greek <i>dēlētērios</i> (noxious), from <i>dēleisthai</i> (to hurt).","f":"délétère, nuisible","t":"Same as « délétère »: « une ambiance délétère »."},{"w":"dilatory","p":"adj.","m":"Slow; tending to delay.","e":"Latin <i>dilatorius</i>, from <i>differre</i> (to delay), supine <i>dilatum</i>.","f":"dilatoire, lent","t":"« Des manœuvres dilatoires »: stalling tactics."},{"w":"dispassionate","p":"adj.","m":"Not influenced by strong emotion; impartial.","e":"<i>dis-</i> + passionate, from Latin <i>passio</i> (suffering).","f":"impartial, objectif, posé","t":"Without passion: a dispassionate analysis."},{"w":"disseminate","p":"v.","m":"To spread widely.","e":"Latin <i>disseminare</i>: <i>dis-</i> (apart) + <i>seminare</i> (to sow), from <i>semen</i> (seed).","f":"disséminer, diffuser","t":"Sowing seeds everywhere: « disséminer »."},{"w":"duress","p":"n.","m":"Threats or pressure used to force someone.","e":"Old French <i>duresse</i> (hardness, harshness), from Latin <i>durus</i> (hard).","f":"contrainte","t":"From dur: signed under duress = sous la contrainte."},{"w":"economical","p":"adj.","m":"Using no more than necessary; thrifty (also: economical with the truth).","e":"Greek <i>oikonomia</i>: <i>oikos</i> (house) + <i>nomos</i> (management).","f":"économe, sobre","t":"House management. On the GRE: economical prose = no wasted words."},{"w":"edifying","p":"adj.","m":"Morally or intellectually instructive.","e":"Latin <i>aedificare</i> (to build): <i>aedes</i> (building) + <i>facere</i>. Building up the soul.","f":"édifiant","t":"Same as « édifiant »: building (édifice) your character."},{"w":"efficacious","p":"adj.","m":"Effective, producing the desired result.","e":"Latin <i>efficax</i>, from <i>efficere</i> (to accomplish).","f":"efficace","t":"Efficacious = « efficace ». Used of remedies."},{"w":"elicit","p":"v.","m":"To draw out a response or fact.","e":"Latin <i>elicere</i>: <i>e-</i> (out) + <i>lacere</i> (to lure).","f":"susciter, obtenir","t":"Lure out a reaction. Not illicit (illegal)."},{"w":"erudite","p":"adj.","m":"Very learned.","e":"Latin <i>eruditus</i>, from <i>erudire</i> (to instruct): <i>e-</i> + <i>rudis</i> (rough). Taking the roughness out.","f":"érudit","t":"Same as « érudit »: no longer rude/rough."},{"w":"esoteric","p":"adj.","m":"Understood by only a small group.","e":"Greek <i>esōterikos</i> (inner), from <i>esō</i> (within). Teachings for inner disciples only.","f":"ésotérique","t":"Same as « ésotérique »: for the inner circle."},{"w":"fastidious","p":"adj.","m":"Very attentive to detail; hard to please.","e":"Latin <i>fastidiosus</i> (disdainful), from <i>fastidium</i> (loathing).","f":"méticuleux, pointilleux (≠ fastidieux)","x":"Faux ami","t":"Careful: « fastidieux » = tedious. Fastidious = maniaque, fussy."},{"w":"flux","p":"n.","m":"Continuous change.","e":"Latin <i>fluxus</i> (flow), from <i>fluere</i> (to flow).","f":"flux, mouvance","t":"Heraclitus: everything flows. A market in flux."},{"w":"furtive","p":"adj.","m":"Secretive; trying not to be noticed.","e":"Latin <i>furtivus</i>, from <i>furtum</i> (theft), <i>fur</i> (thief).","f":"furtif","t":"Same as « furtif »: moving like a thief."},{"w":"harried","p":"adj.","m":"Harassed, stressed by demands.","e":"Old English <i>hergian</i> (to ravage, raid), related to <i>here</i> (army). Germanic.","f":"harcelé, débordé","t":"Raided by an army of emails. A harried consultant on a Sunday."},{"w":"ignominious","p":"adj.","m":"Deserving or causing public disgrace.","e":"Latin <i>ignominia</i>: <i>in-</i> (not) + <i>nomen</i> (name). Loss of one’s good name.","f":"ignominieux, honteux","t":"Same as « ignominieux »: losing your name."},{"w":"impartial","p":"adj.","m":"Treating all equally; fair.","e":"<i>in-</i> + partial, from Latin <i>pars</i> (part). Not taking a part.","f":"impartial","t":"Same as « impartial »."},{"w":"imprudent","p":"adj.","m":"Not showing care for the consequences.","e":"Latin <i>imprudens</i>: <i>in-</i> + <i>prudens</i> (foreseeing), contraction of <i>providens</i>.","f":"imprudent","t":"Same as « imprudent »: not foreseeing."},{"w":"indecorous","p":"adj.","m":"Improper; in bad taste.","e":"Latin <i>indecorus</i>: <i>in-</i> + <i>decorus</i> (fitting).","f":"inconvenant","t":"Breaking « le décorum »."},{"w":"jovial","p":"adj.","m":"Cheerful and friendly.","e":"Latin <i>Iovialis</i> (of Jupiter). Astrologers held those born under Jupiter to be happy.","f":"jovial","t":"Same as « jovial »: born under jolly Jupiter (Jove)."},{"w":"maladroit","p":"adj.","m":"Clumsy, inept.","e":"French <i>maladroit</i>: <i>mal</i> (badly) + <i>adroit</i> (skilful, à droit).","f":"maladroit","t":"Straight from French « maladroit »."},{"w":"maverick","p":"n.","m":"An independent-minded nonconformist.","e":"From Samuel Maverick (1803–1870), a Texas rancher who refused to brand his cattle; unbranded calves were called mavericks.","f":"franc-tireur, non-conformiste","t":"The unbranded calf wandering free from the herd. Also Top Gun’s pilot."},{"w":"mendacity","p":"n.","m":"Untruthfulness, lying.","e":"Latin <i>mendax</i> (lying), from <i>mendum</i> (fault).","f":"mensonge, fausseté","t":"Mendacity sounds like « mensonge », and that’s exactly what it is: a habit of lying."},{"w":"misconstrue","p":"v.","m":"To interpret wrongly.","e":"<i>mis-</i> + construe, Latin <i>construere</i> (to build).","f":"mal interpréter","t":"Building the wrong meaning. Contrast with construe."},{"w":"mundane","p":"adj.","m":"Ordinary, dull; earthly.","e":"Latin <i>mundanus</i>, from <i>mundus</i> (world).","f":"banal, terre-à-terre (≠ mondain)","x":"Faux ami","t":"Careful: « mondain » = society/high life. Mundane = ordinary everyday stuff."},{"w":"nonplussed","p":"adj.","m":"So surprised one doesn’t know how to react.","e":"Latin <i>non plus</i> (no more): a state where nothing more can be said.","f":"perplexe, décontenancé","t":"« Non plus »: you have nothing more to say. Means baffled, not calm."},{"w":"nuance","p":"n.","m":"A subtle difference in meaning or expression.","e":"French <i>nuance</i> (shade), from <i>nuer</i> (to shade), from <i>nue</i> (cloud).","f":"nuance","t":"Straight from French: shades like those of a cloud (nue)."},{"w":"opulence","p":"n.","m":"Great wealth or luxury.","e":"Latin <i>opulentia</i>, from <i>opes</i> (wealth).","f":"opulence","t":"Same as « opulence ». Versailles’ Hall of Mirrors."},{"w":"pejorative","p":"adj.","m":"Expressing contempt or disapproval.","e":"Latin <i>peiorare</i> (to make worse), from <i>peior</i> (worse).","f":"péjoratif","t":"Same as « péjoratif »: making it sound worse."},{"w":"placate","p":"v.","m":"To calm or soothe someone angry.","e":"Latin <i>placare</i> (to calm).","f":"apaiser, calmer","t":"Placare: same root as implacable and plaire. Placate an angry client."},{"w":"polemic","p":"n.","m":"A strong verbal or written attack.","e":"Greek <i>polemikos</i> (warlike), from <i>polemos</i> (war).","f":"polémique","t":"Same as « polémique »: war (polemos) by words."},{"w":"posit","p":"v.","m":"To put forward as fact or a basis for argument.","e":"Latin <i>positus</i>, from <i>ponere</i> (to place).","f":"postuler, poser comme principe","t":"To posit = « poser » a hypothesis on the table."},{"w":"rebuke","p":"v. / n.","m":"To express sharp disapproval.","e":"Anglo-French <i>rebuker</i> (to beat back), from Old French <i>bukier</i> (to strike).","f":"réprimander, reproche","t":"Beat back verbally: a sharp rebuke from the partner."},{"w":"reproach","p":"v. / n.","m":"To express disappointment or disapproval.","e":"Old French <i>reprochier</i>, from Vulgar Latin <i>repropiare</i> (to bring back near).","f":"reprocher, reproche","t":"Same as « reprocher ». Beyond reproach = irréprochable."},{"w":"specious","p":"adj.","m":"Superficially plausible but actually wrong.","e":"Latin <i>speciosus</i> (good-looking), from <i>species</i> (appearance).","f":"spécieux","t":"Same as « spécieux »: pretty on the surface, false inside."},{"w":"stringent","p":"adj.","m":"Strict, precise and exacting.","e":"Latin <i>stringentem</i>, from <i>stringere</i> (to draw tight).","f":"rigoureux, strict","t":"Pulled tight (stringere, as in stricte). Stringent regulations."},{"w":"sullen","p":"adj.","m":"Bad-tempered and sulky.","e":"Anglo-French <i>solein</i> (solitary), from Latin <i>solus</i> (alone).","f":"maussade, renfrogné","t":"Solus = alone: the sulky teen alone in his room."},{"w":"timorous","p":"adj.","m":"Showing fear; timid.","e":"Medieval Latin <i>timorosus</i>, from <i>timor</i> (fear).","f":"craintif, timoré","t":"Same as « timoré ». Timor = fear."},{"w":"transient","p":"adj.","m":"Lasting only a short time.","e":"Latin <i>transire</i> (to go across): <i>trans</i> + <i>ire</i> (to go).","f":"transitoire, passager","t":"Passing through: « transitoire »."},{"w":"truncate","p":"v.","m":"To shorten by cutting off.","e":"Latin <i>truncare</i> (to cut off), from <i>truncus</i> (trunk, maimed).","f":"tronquer","t":"Same as « tronquer »: cut down to the trunk."}]},{"name":"Common Words VII","slug":"common-words-vii","series":"Common Words","words":[{"w":"abate","p":"v.","m":"To become less intense; diminish.","e":"Old French <i>abatre</i> (to beat down), from Latin <i>ad</i> + <i>battuere</i> (to beat).","f":"diminuer, s’apaiser (abattre)","t":"« Abattre »: the storm is beaten down. The storm abated."},{"w":"acumen","p":"n.","m":"Keen insight; sharp judgment.","e":"Latin <i>acumen</i> (point, sharpness), from <i>acuere</i> (to sharpen).","f":"perspicacité, flair","t":"Acus = needle: a mind sharp as a point. Business acumen = le sens des affaires."},{"w":"adulterate","p":"v.","m":"To make impure by adding inferior substances.","e":"Latin <i>adulterare</i> (to corrupt), from <i>ad</i> + <i>alter</i> (other).","f":"frelater, altérer","t":"Adding something other (alter): watered-down wine is adulterated, « frelaté »."},{"w":"alleviate","p":"v.","m":"To make suffering less severe.","e":"Late Latin <i>alleviare</i>: <i>ad</i> + <i>levis</i> (light).","f":"soulager, alléger","t":"Levis = léger: alleviate = « alléger » the pain."},{"w":"approbation","p":"n.","m":"Approval or praise.","e":"Latin <i>approbatio</i>, from <i>approbare</i> (to approve): <i>ad</i> + <i>probare</i> (to test, find good).","f":"approbation","t":"Same as « approbation ». Opposite: opprobrium."},{"w":"articulate","p":"adj. / v.","m":"Expressing oneself clearly; to express clearly.","e":"Latin <i>articulatus</i> (jointed), from <i>articulus</i> (small joint). Speech divided into distinct parts.","f":"qui s’exprime bien; articuler, formuler","t":"Joints (articulations) make movement clear; articulate speech is clearly jointed."},{"w":"aver","p":"v.","m":"To state or assert to be true.","e":"Old French <i>averer</i>, from Latin <i>ad</i> + <i>verus</i> (true).","f":"affirmer, avérer","t":"Aver = declare it « avéré », true (verus)."},{"w":"bombastic","p":"adj.","m":"High-sounding but with little meaning; pompous.","e":"From <i>bombast</i>, cotton padding for clothes, from Medieval Latin <i>bombax</i> (cotton). Padded speech.","f":"grandiloquent, pompeux","t":"Bombast = cotton stuffing: speech padded with fluff."},{"w":"chicanery","p":"n.","m":"Trickery to achieve a goal.","e":"French <i>chicanerie</i>, from <i>chicaner</i> (to quibble).","f":"chicane, manœuvres","t":"French « chicane »: legal tricks and quibbles."},{"w":"circumspect","p":"adj.","m":"Cautious; unwilling to take risks.","e":"Latin <i>circumspectus</i>: <i>circum</i> (around) + <i>specere</i> (to look).","f":"circonspect, prudent","t":"Same as « circonspect »: looking all around before acting."},{"w":"clamor","p":"n. / v.","m":"A loud, insistent demand or noise.","e":"Latin <i>clamor</i> (shout), from <i>clamare</i> (to cry out).","f":"clameur, réclamer à grands cris","t":"« Une clameur »: the crowd shouting for something."},{"w":"compliant","p":"adj.","m":"Inclined to obey; meeting rules.","e":"From comply, Italian <i>complire</i>, from Latin <i>complere</i> (to fill up, complete).","f":"docile, conforme","t":"Compliant with the rules = « conforme ». Compliance team."},{"w":"connoisseur","p":"n.","m":"An expert judge in matters of taste.","e":"Old French <i>connoisseur</i> (modern <i>connaisseur</i>), from Latin <i>cognoscere</i> (to know).","f":"connaisseur","t":"Straight from French « connaisseur »."},{"w":"covert","p":"adj.","m":"Not openly acknowledged; secret.","e":"Old French <i>covert</i> (covered), past participle of <i>covrir</i> (to cover).","f":"secret, caché, clandestin","t":"Covered = « couvert ». Covert ops. Opposite: overt (ouvert)."},{"w":"desiccate","p":"v.","m":"To dry out completely.","e":"Latin <i>desiccare</i>: <i>de-</i> + <i>siccare</i> (to dry), from <i>siccus</i> (dry).","f":"dessécher","t":"Siccus = sec: « dessécher »."},{"w":"deterrent","p":"n.","m":"Something that discourages an action.","e":"Latin <i>deterrere</i>: <i>de-</i> (away) + <i>terrere</i> (to frighten).","f":"moyen de dissuasion","t":"Frighten away (terrere, as in terreur). Nuclear deterrent = « force de dissuasion »."},{"w":"dissent","p":"n. / v.","m":"Disagreement with official opinion.","e":"Latin <i>dissentire</i>: <i>dis-</i> + <i>sentire</i> (to feel).","f":"dissidence, désaccord","t":"Feeling apart: a dissenting opinion. « Dissension »."},{"w":"divest","p":"v.","m":"To deprive or rid oneself of something.","e":"Medieval Latin <i>divestire</i>: <i>dis-</i> + <i>vestire</i> (to clothe). To undress.","f":"se défaire de, céder","t":"Un-dress: divesting a business unit = taking off a piece of clothing (vêtement)."},{"w":"efficacy","p":"n.","m":"The ability to produce the intended result.","e":"Latin <i>efficacia</i>, from <i>efficere</i> (to accomplish).","f":"efficacité","t":"« Efficacité » of a drug in a clinical trial."},{"w":"eloquent","p":"adj.","m":"Fluent and persuasive in speech.","e":"Latin <i>eloquentem</i>, from <i>eloqui</i>: <i>e-</i> (out) + <i>loqui</i> (to speak).","f":"éloquent","t":"Same as « éloquent »: speaking out."},{"w":"epitome","p":"n.","m":"A perfect example of a type.","e":"Greek <i>epitomē</i> (abridgement), from <i>epitemnein</i> (to cut short).","f":"incarnation, quintessence","t":"Once a summary; now the essence condensed. Not « épitomé » (summary) in modern use."},{"w":"eulogy","p":"n.","m":"A speech praising someone, especially at a funeral.","e":"Greek <i>eulogia</i> (praise): <i>eu</i> (well) + <i>logos</i> (speaking).","f":"éloge funèbre","t":"Eu-logos = speaking well of someone. « Éloge »."},{"w":"explicit","p":"adj.","m":"Stated clearly; leaving nothing implied.","e":"Latin <i>explicitus</i> (unfolded), from <i>explicare</i>: <i>ex-</i> + <i>plicare</i> (to fold).","f":"explicite","t":"Unfolded fully. Opposite: implicit (folded in)."},{"w":"facilitate","p":"v.","m":"To make easier.","e":"French <i>faciliter</i>, from Latin <i>facilis</i> (easy).","f":"faciliter","t":"Same as « faciliter »."},{"w":"fervid","p":"adj.","m":"Intensely enthusiastic; passionate.","e":"Latin <i>fervidus</i>, from <i>fervere</i> (to boil).","f":"fervent, ardent","t":"Boiling: same root as « ferveur »."},{"w":"guile","p":"n.","m":"Sly or cunning intelligence.","e":"Old French <i>guile</i> (deceit), probably Frankish; related to English <i>wile</i>.","f":"ruse, astuce","t":"Guile = wiles = ruse. Guileless = without it."},{"w":"gullible","p":"adj.","m":"Easily persuaded to believe something.","e":"From <i>gull</i> (to dupe), perhaps from the seagull, a bird that swallows anything.","f":"crédule, naïf","t":"A seagull swallows whatever is thrown. « Crédule »."},{"w":"homogeneous","p":"adj.","m":"Of the same kind; uniform.","e":"Greek <i>homogenēs</i>: <i>homos</i> (same) + <i>genos</i> (kind).","f":"homogène","t":"Same as « homogène »."},{"w":"implicit","p":"adj.","m":"Implied though not stated; absolute (implicit trust).","e":"Latin <i>implicitus</i> (entwined), from <i>implicare</i>: <i>in-</i> + <i>plicare</i> (to fold).","f":"implicite; absolu","t":"Folded inside. Opposite: explicit."},{"w":"inconsequential","p":"adj.","m":"Not important or significant.","e":"<i>in-</i> + Latin <i>consequentia</i>, from <i>consequi</i> (to follow).","f":"insignifiant, sans importance","t":"Nothing follows from it: no consequences."},{"w":"indeterminate","p":"adj.","m":"Not exactly known or established.","e":"Latin <i>indeterminatus</i>: <i>in-</i> + <i>determinare</i> (to limit), from <i>terminus</i> (boundary).","f":"indéterminé","t":"No boundary drawn: « indéterminé »."},{"w":"intractable","p":"adj.","m":"Hard to control or solve.","e":"Latin <i>intractabilis</i>: <i>in-</i> + <i>tractare</i> (to handle).","f":"insoluble, réfractaire","t":"Can’t be handled or pulled (tractor). An intractable problem."},{"w":"lavish","p":"adj. / v.","m":"Sumptuous; to give generously.","e":"Old French <i>lavasse</i> (downpour), from <i>laver</i> (to wash). A flood of something.","f":"somptueux, prodiguer","t":"A downpour (« lavasse ») of gifts. Lavish praise."},{"w":"loquacious","p":"adj.","m":"Talkative.","e":"Latin <i>loquax</i>, from <i>loqui</i> (to speak).","f":"loquace","t":"Same as « loquace »."},{"w":"nascent","p":"adj.","m":"Just beginning to develop.","e":"Latin <i>nascentem</i>, from <i>nasci</i> (to be born).","f":"naissant","t":"« Naissant »: just born. A nascent industry."},{"w":"onerous","p":"adj.","m":"Burdensome; involving heavy effort.","e":"Latin <i>onerosus</i>, from <i>onus</i> (burden).","f":"lourd, pesant (onéreux = costly)","x":"Faux ami","t":"Onus = burden. French « onéreux » means expensive; English onerous means heavy work."},{"w":"opprobrium","p":"n.","m":"Harsh public criticism; disgrace.","e":"Latin <i>opprobrium</i> (reproach): <i>ob</i> (against) + <i>probrum</i> (shameful act).","f":"opprobre","t":"Same as « jeter l’opprobre sur ». Opposite of approbation."},{"w":"overt","p":"adj.","m":"Done openly; not hidden.","e":"Old French <i>overt</i> (open), past participle of <i>ovrir</i> (to open), now <i>ouvrir</i>.","f":"manifeste, ouvert","t":"Overt = « ouvert ». Covert = « couvert »."},{"w":"paradox","p":"n.","m":"A seemingly self-contradictory statement that may be true.","e":"Greek <i>paradoxos</i>: <i>para</i> (contrary to) + <i>doxa</i> (opinion).","f":"paradoxe","t":"Against common opinion (doxa). Same as « paradoxe »."},{"w":"partisan","p":"adj. / n.","m":"Strongly biased towards a party or cause.","e":"French <i>partisan</i>, from Italian <i>partigiano</i>, from <i>parte</i> (part, faction).","f":"partisan","t":"Same as « partisan »: taking one party’s side."},{"w":"plethora","p":"n.","m":"An excess; a large amount.","e":"Greek <i>plēthōrē</i> (fullness), from <i>plēthein</i> (to be full).","f":"pléthore","t":"« Pléthore de candidats »: an overflow."},{"w":"propriety","p":"n.","m":"Conformity to accepted standards of behaviour.","e":"Old French <i>propriete</i>, from Latin <i>proprietas</i> (appropriateness), from <i>proprius</i> (one’s own, proper).","f":"bienséance, convenance (≠ propriété)","x":"Faux ami","t":"Not property! Propriety = « les convenances », what is proper."},{"w":"tacit","p":"adj.","m":"Understood without being stated.","e":"Latin <i>tacitus</i> (silent), from <i>tacere</i>.","f":"tacite","t":"Same as « tacite »: « reconduction tacite »."},{"w":"tangential","p":"adj.","m":"Only slightly relevant; diverging.","e":"Latin <i>tangentem</i>, from <i>tangere</i> (to touch). A tangent only touches the circle at one point.","f":"accessoire, secondaire","t":"Going off on a tangent: barely touching the topic. « Partir dans une digression »."},{"w":"tenuous","p":"adj.","m":"Very weak or slight.","e":"Latin <i>tenuis</i> (thin).","f":"ténu, fragile","t":"Same as « ténu »: a thin thread of logic."},{"w":"veracity","p":"n.","m":"Truthfulness; accuracy.","e":"Medieval Latin <i>veracitas</i>, from <i>verax</i> (truthful), <i>verus</i> (true).","f":"véracité","t":"Same as « véracité ». Vrai."},{"w":"verbose","p":"adj.","m":"Using more words than needed.","e":"Latin <i>verbosus</i>, from <i>verbum</i> (word).","f":"verbeux","t":"Same as « verbeux »: too many verbs/words."},{"w":"volatile","p":"adj.","m":"Liable to change rapidly and unpredictably.","e":"Latin <i>volatilis</i> (flying), from <i>volare</i> (to fly).","f":"volatile, instable, explosif","t":"Flying away (voler): volatile markets, a volatile temper."},{"w":"wary","p":"adj.","m":"Cautious about possible dangers.","e":"Old English <i>wær</i> (watchful). Germanic, related to aware and beware.","f":"méfiant, prudent","t":"Beware → wary. Méfiant."},{"w":"zealous","p":"adj.","m":"Having great energy for a cause.","e":"Greek <i>zēlos</i> (ardour, jealousy), via Latin <i>zelus</i>.","f":"zélé","t":"Same as « zélé ». Zealots were fervent rebels in Judea."}]},{"name":"Basic I","slug":"basic-i","series":"Basic","words":[{"w":"acme","p":"n.","m":"The highest point of achievement or excellence.","e":"Greek <i>akmē</i> (point, peak, prime).","f":"apogée, summum","t":"Akmē = the peak. (Yes, the Acme company in the Road Runner cartoons claims to be the best.)"},{"w":"affable","p":"adj.","m":"Friendly, easy to talk to.","e":"Latin <i>affabilis</i> (easy to speak to): <i>ad</i> + <i>fari</i> (to speak).","f":"affable","t":"Same as « affable »: easy to speak to."},{"w":"affluent","p":"adj.","m":"Wealthy.","e":"Latin <i>affluentem</i>, from <i>affluere</i> (to flow towards): <i>ad</i> + <i>fluere</i>.","f":"aisé, riche (≠ affluent = tributary)","t":"Money flowing towards you. In French « un affluent » is a tributary river; same flow image."},{"w":"amiable","p":"adj.","m":"Friendly and pleasant.","e":"Old French <i>amiable</i>, from Late Latin <i>amicabilis</i> (friendly), from <i>amicus</i>.","f":"aimable, amical","t":"Ami → amiable. « À l’amiable » = settled in a friendly way."},{"w":"bleak","p":"adj.","m":"Bare, cold, without hope.","e":"Old Norse <i>bleikr</i> (pale, shining), related to Old English <i>blāc</i> (pale). Germanic.","f":"morne, sombre, désolé","t":"Pale and colourless, like a bleak winter landscape or a bleak outlook."},{"w":"candid","p":"adj.","m":"Truthful and straightforward; frank.","e":"Latin <i>candidus</i> (white, pure). Roman office-seekers wore white togas, hence candidate.","f":"franc, sincère (≠ candide = naive)","x":"Faux ami","t":"Pure white: nothing hidden. French « candide » means naive; English candid means frank."},{"w":"censor","p":"v. / n.","m":"To suppress unacceptable parts of a text or film.","e":"Latin <i>censor</i>, the Roman magistrate who took the census and policed morals, from <i>censere</i> (to assess).","f":"censurer; censeur","t":"Censor = cuts content. Censure (Common I) = formal blame."},{"w":"demean","p":"v.","m":"To lower the dignity of.","e":"<i>de-</i> + mean (low, inferior; Old English <i>gemǣne</i>, common). Germanic + Latin prefix.","f":"rabaisser, avilir","t":"Make someone mean (low). A demeaning task."},{"w":"demure","p":"adj.","m":"Reserved, modest and shy.","e":"Probably Anglo-French <i>demuré</i>, from <i>demorer</i> (to stay, be calm), Latin <i>demorari</i>.","f":"réservé, sage, pudique","t":"Demure = « sage comme une image ». Not demur (to object)."},{"w":"diabolical","p":"adj.","m":"Characteristic of the devil; very bad.","e":"Greek <i>diabolos</i> (slanderer, devil), from <i>diaballein</i> (to throw across, slander).","f":"diabolique","t":"Same as « diabolique »: the devil (diable)."},{"w":"dog","p":"v.","m":"To follow closely and persistently; to plague.","e":"Old English <i>docga</i>, a word of unknown origin. The verb (to track like a hound) dates from the 1500s.","f":"poursuivre, harceler, hanter","x":"2nd meaning","t":"A dog on your heels: dogged by scandal = « poursuivi par »."},{"w":"dupe","p":"v. / n.","m":"To deceive; a person easily tricked.","e":"French <i>dupe</i>, perhaps from <i>huppe</i> (hoopoe), a bird reputed to be stupid.","f":"duper; dupe","t":"Same as French « duper »."},{"w":"embroiled","p":"adj.","m":"Deeply involved in a conflict or difficult situation.","e":"French <i>embrouiller</i> (to confuse, tangle): <i>en</i> + <i>brouiller</i>.","f":"empêtré, mêlé à","t":"« Embrouillé »: tangled up in a scandal."},{"w":"err","p":"v.","m":"To be mistaken.","e":"Latin <i>errare</i> (to wander, stray).","f":"se tromper, errer","t":"To err is human: « l’erreur est humaine »."},{"w":"erratic","p":"adj.","m":"Not even or regular; unpredictable.","e":"Latin <i>erraticus</i> (wandering), from <i>errare</i>.","f":"erratique, irrégulier","t":"Wandering all over: « erratique »."},{"w":"hound","p":"v.","m":"To harass or pursue relentlessly.","e":"Old English <i>hund</i> (dog), Germanic (German <i>Hund</i>).","f":"traquer, harceler","x":"2nd meaning","t":"Hunted by hounds: the press hounded the minister."},{"w":"indict","p":"v.","m":"To formally accuse of a crime.","e":"Anglo-French <i>enditer</i>, from Latin <i>indicere</i> (to proclaim): <i>in</i> + <i>dicere</i> (to say). Pronounced “in-DITE”.","f":"inculper, mettre en accusation","t":"Indicere = to declare against. Silent c: in-DITE."},{"w":"indigenous","p":"adj.","m":"Native to a particular place.","e":"Late Latin <i>indigenus</i>, from <i>indigena</i> (native): <i>indu</i> (within) + <i>gignere</i> (to beget).","f":"indigène, autochtone","t":"Born within: « autochtone »."},{"w":"indignant","p":"adj.","m":"Angry at perceived unfairness.","e":"Latin <i>indignari</i> (to consider unworthy): <i>in-</i> + <i>dignus</i> (worthy).","f":"indigné","t":"Same as « indigné »: « Indignez-vous ! »"},{"w":"inflammatory","p":"adj.","m":"Arousing angry or violent feelings.","e":"Latin <i>inflammare</i> (to set on fire), from <i>flamma</i>.","f":"incendiaire, provocateur","t":"Words that set the room on fire: « des propos incendiaires »."},{"w":"insolvent","p":"adj.","m":"Unable to pay debts.","e":"<i>in-</i> + Latin <i>solvere</i> (to loosen, pay).","f":"insolvable","t":"Not solvable: « insolvable »."},{"w":"inundate","p":"v.","m":"To overwhelm, flood.","e":"Latin <i>inundare</i>: <i>in</i> + <i>unda</i> (wave).","f":"inonder, submerger","t":"Unda = onde: « inonder ». Inundated with emails."},{"w":"macabre","p":"adj.","m":"Disturbing because concerned with death.","e":"French <i>macabre</i>, from <i>Danse Macabre</i> (Dance of Death, 15th c.), perhaps after the Maccabees.","f":"macabre","t":"La Danse macabre: skeletons dancing. Same as French."},{"w":"mesmerize","p":"v.","m":"To hold someone’s attention completely.","e":"From Franz Anton Mesmer (1734–1815), a German doctor whose “animal magnetism” sessions were the rage in Paris.","f":"hypnotiser, fasciner","t":"Picture Mesmer’s Parisian salons, patients entranced around his tub."},{"w":"miser","p":"n.","m":"A person who hoards wealth and spends little.","e":"Latin <i>miser</i> (wretched, unhappy).","f":"avare, grippe-sou","t":"Latin miser = « misérable »: the wretched hoarder (Harpagon, Scrooge)."},{"w":"peruse","p":"v.","m":"To read carefully (often misused as “skim”).","e":"Probably <i>per-</i> (thoroughly) + <i>use</i>: to use up completely.","f":"lire attentivement, examiner","t":"Per + use = use thoroughly. On the GRE: careful reading."},{"w":"pine","p":"v.","m":"To long for; to waste away from grief.","e":"Old English <i>pīnian</i> (to torment), from Latin <i>poena</i> (punishment).","f":"languir, se languir de","x":"2nd meaning","t":"Poena = peine: pining for a lost love."},{"w":"pinnacle","p":"n.","m":"The highest point.","e":"Old French <i>pinacle</i>, from Late Latin <i>pinnaculum</i> (peak, turret), from <i>pinna</i> (feather, point).","f":"pinacle, sommet","t":"« Porter au pinacle »: the turret at the very top."},{"w":"profuse","p":"adj.","m":"Plentiful, abundant.","e":"Latin <i>profusus</i>, from <i>profundere</i> (to pour out).","f":"abondant, profus","t":"Pouring forth: profuse apologies."},{"w":"remiss","p":"adj.","m":"Negligent in one’s duty.","e":"Latin <i>remissus</i> (slack), from <i>remittere</i> (to send back, relax).","f":"négligent","t":"Slackened off: it would be remiss of me not to thank…"},{"w":"reprobate","p":"n.","m":"An unprincipled person.","e":"Late Latin <i>reprobatus</i> (rejected), from <i>reprobare</i> (to disapprove).","f":"dépravé, vaurien, réprouvé","t":"« Les réprouvés »: those rejected by God."},{"w":"retiring","p":"adj.","m":"Shy, tending to avoid company.","e":"From retire, French <i>retirer</i> (to withdraw).","f":"réservé, effacé","x":"2nd meaning","t":"Someone who withdraws (« se retire ») from the crowd."},{"w":"screed","p":"n.","m":"A long, tedious, usually angry piece of writing.","e":"Old English <i>scrēade</i> (a shred, strip). A long strip of parchment.","f":"diatribe, long pamphlet","t":"A long shred of paper full of ranting."},{"w":"serendipity","p":"n.","m":"Finding good things by chance.","e":"Coined by Horace Walpole in 1754 from the Persian tale <i>The Three Princes of Serendip</i> (Sri Lanka), who kept making lucky discoveries.","f":"sérendipité, heureux hasard","t":"The princes of Serendip finding treasures by accident. Fleming’s penicillin."},{"w":"slapdash","p":"adj.","m":"Done hurriedly and carelessly.","e":"English <i>slap</i> + <i>dash</i>, both suggesting quick, careless action.","f":"bâclé","t":"Slap it on, dash off: « travail bâclé »."},{"w":"spendthrift","p":"n.","m":"A person who spends money wastefully.","e":"<i>spend</i> + <i>thrift</i> (savings, prosperity, from Old Norse <i>þrift</i>). Someone who spends the savings.","f":"dépensier, panier percé","t":"Spends the thrift (the savings)."},{"w":"stipend","p":"n.","m":"A fixed regular allowance or salary.","e":"Latin <i>stipendium</i> (soldier’s pay): <i>stips</i> (coin) + <i>pendere</i> (to weigh out).","f":"allocation, traitement","t":"Coins weighed out for a soldier. PhD stipend."},{"w":"summit","p":"n.","m":"The highest point; a meeting of leaders.","e":"Old French <i>somete</i>, diminutive of <i>som</i>, from Latin <i>summum</i> (highest).","f":"sommet","t":"« Sommet » and « sommet du G7 »."},{"w":"telling","p":"adj.","m":"Revealing; having a striking effect.","e":"From <i>tell</i>, Old English <i>tellan</i> (to count, relate). Germanic.","f":"révélateur, significatif","x":"2nd meaning","t":"It tells you something. A telling silence."},{"w":"telltale","p":"adj.","m":"Revealing something hidden.","e":"<i>tell</i> + <i>tale</i>: originally a tattletale who tells tales.","f":"révélateur, qui trahit","t":"Telltale signs = « signes révélateurs »."},{"w":"tender","p":"v. / n.","m":"To offer formally (tender a resignation); money offered.","e":"Old French <i>tendre</i> (to offer, stretch out), from Latin <i>tendere</i>.","f":"offrir, présenter; soumission","x":"2nd meaning","t":"« Tendre la main »: you stretch out an offer. Legal tender, a public tender (appel d’offres)."},{"w":"thoroughgoing","p":"adj.","m":"Complete, thorough.","e":"<i>thorough</i> (Old English <i>þuruh</i>, through) + <i>going</i>. Going all the way through.","f":"complet, total, minutieux","t":"Going thoroughly through everything."},{"w":"thrifty","p":"adj.","m":"Careful with money.","e":"From <i>thrift</i>, Old Norse <i>þrift</i> (prosperity), from <i>thrive</i>.","f":"économe","t":"Thrifty people thrive. A thrift shop sells cheap second-hand goods."},{"w":"tirade","p":"n.","m":"A long angry speech of criticism.","e":"French <i>tirade</i>, from Italian <i>tirata</i> (a pull, volley), from <i>tirare</i> (to pull).","f":"tirade, diatribe","t":"Same as « tirade » (Cyrano’s famous nose tirade)."},{"w":"underwrite","p":"v.","m":"To guarantee financially; to support.","e":"<i>under</i> + <i>write</i>: insurers wrote their names under the risk on Lloyd’s policies.","f":"garantir, souscrire, financer","t":"Signing your name under a policy to cover it. Banks underwrite an IPO."},{"w":"unnerve","p":"v.","m":"To make someone lose courage or confidence.","e":"<i>un-</i> + nerve (strength, courage), from Latin <i>nervus</i> (sinew).","f":"déstabiliser, démonter","t":"Remove the nerve (courage): his stare unnerved me."},{"w":"variance","p":"n.","m":"Disagreement; the amount of difference.","e":"Latin <i>variantia</i>, from <i>variare</i> (to change).","f":"désaccord, écart","t":"At variance with = « en désaccord avec ». Also statistical variance."},{"w":"vindictive","p":"adj.","m":"Having a strong desire for revenge.","e":"From Latin <i>vindicta</i> (vengeance), from <i>vindicare</i>.","f":"vindicatif, rancunier","t":"Same as « vindicatif »."},{"w":"voracious","p":"adj.","m":"Wanting great quantities; insatiable.","e":"Latin <i>vorax</i>, from <i>vorare</i> (to devour).","f":"vorace","t":"« Dévorer »: a voracious reader."},{"w":"zenith","p":"n.","m":"The highest point; peak.","e":"Arabic <i>samt ar-ra’s</i> (path over the head), misread by medieval scribes as <i>cenit</i>.","f":"zénith, apogée","t":"Same as « zénith »: the sun right over your head."}]},{"name":"Basic II","slug":"basic-ii","series":"Basic","words":[{"w":"aboveboard","p":"adj.","m":"Legitimate, honest, open.","e":"Card players’ term: keeping your hands above the board (table) so you can’t cheat.","f":"régulier, honnête, transparent","t":"Hands above the card table: no cheating underneath."},{"w":"amok","p":"adv.","m":"Behaving uncontrollably and disruptively (run amok).","e":"Malay <i>amuk</i> (attacking in a frenzy).","f":"en folie, de manière incontrôlée","t":"« Être pris d’amok »: a frenzied, uncontrolled rampage."},{"w":"animosity","p":"n.","m":"Strong hostility.","e":"Latin <i>animositas</i> (boldness, spirit), from <i>animus</i> (spirit, passion).","f":"animosité","t":"Same as « animosité »."},{"w":"apex","p":"n.","m":"The top or highest point.","e":"Latin <i>apex</i> (summit, tip).","f":"sommet, apogée","t":"Apex predator = top of the food chain."},{"w":"avarice","p":"n.","m":"Extreme greed for wealth.","e":"Latin <i>avaritia</i>, from <i>avarus</i> (greedy).","f":"avarice, cupidité","t":"Same as « avarice »: L’Avare."},{"w":"badger","p":"v.","m":"To pester repeatedly.","e":"From the animal; badger-baiting set dogs to harass a badger in its burrow.","f":"harceler, importuner","x":"2nd meaning","t":"Dogs pestering a badger in its hole: badgering your manager for an answer."},{"w":"beatific","p":"adj.","m":"Blissfully happy.","e":"Latin <i>beatificus</i>: <i>beatus</i> (blessed) + <i>facere</i>.","f":"béat, radieux","t":"« Un sourire béat »: blessed (béatitude)."},{"w":"becoming","p":"adj.","m":"Attractive or suitable; fitting.","e":"From <i>become</i> in the sense “to suit” (Old English <i>becuman</i>).","f":"seyant, convenable","x":"2nd meaning","t":"A dress that becomes you = « qui te va bien »."},{"w":"bellicose","p":"adj.","m":"Eager to fight; warlike.","e":"Latin <i>bellicosus</i>, from <i>bellum</i> (war).","f":"belliqueux","t":"Bellum = war: « belliqueux »."},{"w":"cadaverous","p":"adj.","m":"Very pale, thin or bony, like a corpse.","e":"Latin <i>cadaver</i> (corpse), from <i>cadere</i> (to fall).","f":"cadavérique","t":"Same as « cadavérique »."},{"w":"cardinal","p":"adj.","m":"Of the greatest importance; fundamental.","e":"Latin <i>cardinalis</i>, from <i>cardo</i> (hinge). The point on which everything turns.","f":"cardinal, capital","t":"The hinge everything turns on: cardinal sins, cardinal points."},{"w":"catalyst","p":"n.","m":"Something that causes or speeds up a change.","e":"Greek <i>katalysis</i> (dissolution): <i>kata</i> (down) + <i>lyein</i> (to loosen).","f":"catalyseur","t":"Same as « catalyseur »."},{"w":"chauvinist","p":"n.","m":"A person with excessive or prejudiced loyalty to their group.","e":"French <i>chauvin</i>, after Nicolas Chauvin, a probably legendary, fanatically loyal Napoleonic soldier.","f":"chauvin","t":"Nicolas Chauvin and his blind patriotism. Male chauvinist = « macho »."},{"w":"check","p":"v. / n.","m":"To restrain or stop; a restraint.","e":"Old French <i>eschec</i> (check in chess), from Persian <i>shāh</i> (king). The king is stopped.","f":"freiner, enrayer","x":"2nd meaning","t":"Échec au roi! Checks and balances = « contre-pouvoirs »."},{"w":"checkered","p":"adj.","m":"Marked by changes of fortune, often including bad episodes.","e":"From the chessboard pattern (Old French <i>eschequier</i>, chessboard).","f":"mouvementé, en dents de scie","t":"A chessboard of black and white squares: a checkered past."},{"w":"cogent","p":"adj.","m":"Clear, logical and convincing.","e":"Latin <i>cogentem</i>, from <i>cogere</i> (to compel, drive together).","f":"convaincant, irréfutable","t":"An argument that compels you (cogere). Une raison cogente is rare in French."},{"w":"contrite","p":"adj.","m":"Feeling remorse.","e":"Latin <i>contritus</i> (crushed), from <i>conterere</i> (to grind).","f":"contrit, repentant","t":"Same as « contrit »."},{"w":"corroborate","p":"v.","m":"To confirm or give support to.","e":"Latin <i>corroborare</i> (to strengthen): <i>com-</i> + <i>robur</i> (strength, oak).","f":"corroborer","t":"Same as « corroborer »: strong as oak."},{"w":"desecrate","p":"v.","m":"To violate something sacred.","e":"<i>de-</i> + (con)secrate, Latin <i>sacrare</i> (to make holy).","f":"profaner","t":"Un-sacred: « profaner une tombe »."},{"w":"disparate","p":"adj.","m":"Essentially different; not comparable.","e":"Latin <i>disparatus</i> (separated): <i>dis-</i> + <i>parare</i> (to prepare).","f":"disparate","t":"Same as « disparate »."},{"w":"errant","p":"adj.","m":"Straying from the proper course; wandering.","e":"Old French <i>errant</i> (travelling), from <i>errer</i>; also Latin <i>errare</i>.","f":"errant, égaré","t":"A knight-errant wanders; an errant child strays."},{"w":"exhort","p":"v.","m":"To strongly urge or encourage.","e":"Latin <i>exhortari</i>: <i>ex-</i> + <i>hortari</i> (to encourage).","f":"exhorter","t":"Same as « exhorter »."},{"w":"extenuating","p":"adj.","m":"Making a fault seem less serious.","e":"Latin <i>extenuare</i> (to make thin): <i>ex-</i> + <i>tenuis</i> (thin).","f":"atténuant","t":"Circonstances atténuantes = extenuating circumstances: thinning the guilt."},{"w":"ferret","p":"v.","m":"To search persistently (ferret out).","e":"From the animal, Old French <i>furet</i>, used to hunt rabbits out of burrows.","f":"dénicher, fureter","t":"« Fureter » like un furet: ferreting out the truth."},{"w":"fleece","p":"v.","m":"To swindle or overcharge.","e":"Old English <i>flēos</i> (sheep’s wool). To shear someone of their money.","f":"escroquer, plumer","x":"2nd meaning","t":"Shearing a sheep: « se faire plumer / tondre »."},{"w":"flush","p":"adj.","m":"Having plenty of money; also level with.","e":"Of uncertain origin; “flush with money” from the idea of being full to overflowing.","f":"en fonds; à fleur de, de niveau","x":"2nd meaning","t":"A river in flood is flush: flush with cash."},{"w":"heyday","p":"n.","m":"The period of greatest success.","e":"From an old exclamation of joy, <i>hey-day!</i> (16th c.).","f":"âge d’or, apogée","t":"Shouting « hey! » in your best years."},{"w":"hodgepodge","p":"n.","m":"A confused mixture.","e":"From <i>hotchpotch</i>, French <i>hochepot</i>, a stew of mixed ingredients.","f":"méli-mélo, fourre-tout","t":"Hochepot, a Flemish stew: everything thrown in."},{"w":"immaterial","p":"adj.","m":"Unimportant, irrelevant.","e":"Late Latin <i>immaterialis</i>: <i>in-</i> + <i>materia</i> (matter).","f":"sans importance, négligeable","x":"2nd meaning","t":"It doesn’t matter: that’s immaterial."},{"w":"imponderable","p":"n. / adj.","m":"A factor difficult or impossible to assess.","e":"<i>in-</i> + Latin <i>ponderare</i> (to weigh), from <i>pondus</i> (weight).","f":"impondérable","t":"« Les impondérables »: what can’t be weighed."},{"w":"junta","p":"n.","m":"A military group ruling after seizing power.","e":"Spanish <i>junta</i> (council), from Latin <i>iuncta</i> (joined).","f":"junte","t":"« La junte militaire »."},{"w":"lassitude","p":"n.","m":"Physical or mental weariness.","e":"Latin <i>lassitudo</i>, from <i>lassus</i> (weary).","f":"lassitude","t":"Same as « lassitude »: las."},{"w":"melee","p":"n.","m":"A confused fight or crowd.","e":"French <i>mêlée</i> (mixed fight), from <i>mêler</i> (to mix).","f":"mêlée","t":"Straight from « mêlée », even in rugby."},{"w":"misanthrope","p":"n.","m":"A person who dislikes humankind.","e":"Greek <i>misanthrōpos</i>: <i>misein</i> (to hate) + <i>anthrōpos</i> (man).","f":"misanthrope","t":"Molière’s « Le Misanthrope », Alceste."},{"w":"moment","p":"n.","m":"Importance (of great moment).","e":"Latin <i>momentum</i> (movement, weight), from <i>movere</i>. A weight that tips the scale.","f":"importance","x":"2nd meaning","t":"Momentum tips the balance: a decision of great moment."},{"w":"paucity","p":"n.","m":"Scarcity; small quantity.","e":"Latin <i>paucitas</i>, from <i>paucus</i> (few).","f":"rareté, pénurie","t":"Paucus = few (peu)."},{"w":"pittance","p":"n.","m":"A very small or inadequate amount of money.","e":"Old French <i>pitance</i> (a monk’s ration given out of piety), from <i>pitié</i>.","f":"pitance, misère","t":"« Une maigre pitance »."},{"w":"preemptive","p":"adj.","m":"Taken to prevent an anticipated event.","e":"Latin <i>prae</i> (before) + <i>emere</i> (to buy). First “buying before others”.","f":"préventif","t":"A preemptive strike: acting before the other side does."},{"w":"pugnacious","p":"adj.","m":"Eager to argue or fight.","e":"Latin <i>pugnax</i>, from <i>pugnare</i> (to fight), <i>pugnus</i> (fist).","f":"pugnace, agressif","t":"Pugnus = poing: « pugnace »."},{"w":"raft","p":"n.","m":"A large number or amount.","e":"Probably from <i>raff</i> (heap, rubbish), influenced by raft (a floating mass of logs).","f":"tas, flopée","x":"2nd meaning","t":"A raft of logs floating together: a raft of new rules."},{"w":"replete","p":"adj.","m":"Filled or well supplied.","e":"Latin <i>repletus</i>, from <i>replere</i> (to fill again).","f":"rempli, repu","t":"« Repu » after a feast: replete with."},{"w":"sanctimonious","p":"adj.","m":"Making a show of moral superiority.","e":"Latin <i>sanctimonia</i> (holiness), from <i>sanctus</i>.","f":"moralisateur, bigot","t":"Fake saintliness: « des airs de sainte nitouche »."},{"w":"sanguine","p":"adj.","m":"Optimistic, especially in a difficult situation.","e":"Latin <i>sanguineus</i> (bloody). In humour theory, blood made people cheerful.","f":"optimiste (≠ sanguinaire)","x":"Faux ami","t":"Ruddy-cheeked and cheerful: a sanguine temperament. Not bloodthirsty."},{"w":"scintillating","p":"adj.","m":"Brilliantly clever or lively.","e":"Latin <i>scintillare</i> (to sparkle), from <i>scintilla</i> (spark).","f":"brillant, pétillant","t":"« Scintillant »: sparkling conversation."},{"w":"start","p":"v.","m":"To jump in surprise.","e":"Old English <i>styrtan</i> (to leap up). The jump came before the begin sense.","f":"sursauter","x":"2nd meaning","t":"To wake with a start = « se réveiller en sursaut »."},{"w":"stem","p":"v.","m":"To stop or restrict a flow.","e":"Old Norse <i>stemma</i> (to stop, dam).","f":"endiguer, enrayer","x":"2nd meaning","t":"Stem the bleeding, stem the tide: « endiguer »."},{"w":"unconscionable","p":"adj.","m":"Not right or reasonable; shockingly unfair.","e":"<i>un-</i> + conscionable, from conscience.","f":"inadmissible, déraisonnable","t":"Something no conscience could accept."},{"w":"vicarious","p":"adj.","m":"Experienced through another person.","e":"Latin <i>vicarius</i> (substitute), from <i>vicis</i> (change, turn), as in vicar and vice-president.","f":"par procuration","t":"Living through your kids = « vivre par procuration »."},{"w":"virago","p":"n.","m":"A domineering, violent or bad-tempered woman.","e":"Latin <i>virago</i> (man-like woman, heroine), from <i>vir</i> (man).","f":"virago, mégère","t":"Same as « virago »."},{"w":"wax","p":"v.","m":"To grow larger (wax and wane); to speak in a certain way.","e":"Old English <i>weaxan</i> (to grow), Germanic (German <i>wachsen</i>).","f":"croître; devenir","x":"2nd meaning","t":"The moon waxes and wanes: grows and shrinks. Wax lyrical = devenir lyrique."}]},{"name":"Basic III","slug":"basic-iii","series":"Basic","words":[{"w":"advocate","p":"v. / n.","m":"To publicly support; a supporter.","e":"Latin <i>advocatus</i> (one called to help), from <i>ad</i> + <i>vocare</i> (to call).","f":"préconiser, défendre; avocat, partisan","t":"Called (vocare) to defend: like « un avocat ». To advocate = prôner."},{"w":"appreciable","p":"adj.","m":"Large enough to be noticed.","e":"French <i>appréciable</i>, from Late Latin <i>appretiare</i> (to set a price on), <i>pretium</i> (price).","f":"appréciable, notable","t":"Same as « appréciable »: big enough to put a price on."},{"w":"apprehension","p":"n.","m":"Anxiety about the future; also understanding or arrest.","e":"Latin <i>apprehendere</i> (to seize): <i>ad</i> + <i>prehendere</i> (to grasp).","f":"appréhension","t":"Same as « appréhension »: fear seizes you."},{"w":"archaic","p":"adj.","m":"Very old or old-fashioned.","e":"Greek <i>arkhaikos</i>, from <i>arkhaios</i> (ancient), <i>arkhē</i> (beginning).","f":"archaïque","t":"Same as « archaïque »: archaeology."},{"w":"ascendancy","p":"n.","m":"Occupation of a position of dominant power.","e":"From ascendant, Latin <i>ascendere</i> (to climb up): <i>ad</i> + <i>scandere</i>.","f":"ascendant, suprématie","t":"« Avoir de l’ascendant sur »: having climbed above."},{"w":"autonomously","p":"adv.","m":"Independently; self-governing.","e":"Greek <i>autonomos</i>: <i>autos</i> (self) + <i>nomos</i> (law).","f":"de façon autonome","t":"Auto + nomos = making your own law."},{"w":"avid","p":"adj.","m":"Very eager, enthusiastic.","e":"Latin <i>avidus</i> (longing, greedy), from <i>avere</i> (to crave).","f":"avide, passionné","t":"« Avide »: an avid reader devours books."},{"w":"boon","p":"n.","m":"A blessing; something helpful.","e":"Old Norse <i>bón</i> (prayer, request). A favour granted in answer to a prayer.","f":"aubaine, bienfait","t":"A prayer answered: remote work was a boon for her."},{"w":"consummate","p":"adj. / v.","m":"Showing great skill; to complete perfectly.","e":"Latin <i>consummare</i> (to sum up, complete), from <i>summa</i> (total).","f":"accompli, parfait; consommer","t":"Summed up to perfection: a consummate professional."},{"w":"dearth","p":"n.","m":"A scarcity or lack.","e":"Middle English <i>derthe</i>, from <i>dear</i> (costly): when things are scarce, they are dear.","f":"pénurie, manque","t":"Dear + th: scarce things become dear."},{"w":"degrade","p":"v.","m":"To treat with disrespect; to break down.","e":"Late Latin <i>degradare</i> (to lower in rank): <i>de</i> + <i>gradus</i> (step).","f":"dégrader, avilir","t":"Same as « dégrader »: step down."},{"w":"deter","p":"v.","m":"To discourage from acting.","e":"Latin <i>deterrere</i>: <i>de</i> (away) + <i>terrere</i> (to frighten).","f":"dissuader","t":"Frighten away: terror."},{"w":"discriminate","p":"v.","m":"To distinguish; also to treat unfairly.","e":"Latin <i>discriminare</i> (to divide), from <i>discernere</i> (to separate).","f":"discriminer, distinguer","t":"On the GRE, discriminating often = discerning taste."},{"w":"disenfranchise","p":"v.","m":"To deprive of a right, especially voting.","e":"<i>dis-</i> + enfranchise, from Old French <i>franc</i> (free).","f":"priver du droit de vote, marginaliser","t":"Franc = free: taking away a citizen’s franchise."},{"w":"disheartened","p":"adj.","m":"Having lost determination or confidence.","e":"<i>dis-</i> + <i>hearten</i>, from Old English <i>heorte</i> (heart).","f":"découragé","t":"The heart taken out: « découragé » (cœur)."},{"w":"elusive","p":"adj.","m":"Difficult to find, catch or remember.","e":"Latin <i>eludere</i> (to escape, mock): <i>e-</i> + <i>ludere</i> (to play).","f":"insaisissable","t":"It plays (ludere) its way out of your grasp: « éluder »."},{"w":"endemic","p":"adj.","m":"Regularly found in a particular area.","e":"Greek <i>endēmos</i> (native): <i>en</i> (in) + <i>dēmos</i> (people).","f":"endémique","t":"Same as « endémique »: corruption endemic to the system."},{"w":"entice","p":"v.","m":"To attract by offering advantage.","e":"Old French <i>enticier</i> (to set on fire, provoke), Vulgar Latin <i>intitiare</i>, from <i>titio</i> (firebrand).","f":"attirer, séduire","t":"Like « attiser »: stoking a fire to lure someone in."},{"w":"fete","p":"v. / n.","m":"To honour lavishly; a celebration.","e":"French <i>fête</i>, Latin <i>festa</i>.","f":"fêter, fête","t":"Straight from « fêter »."},{"w":"fledgling","p":"adj. / n.","m":"New and inexperienced; a young bird.","e":"From <i>fledge</i> (to grow feathers), Old English <i>flycge</i> (able to fly).","f":"naissant, débutant; oisillon","t":"A baby bird just getting feathers: a fledgling start-up."},{"w":"flounder","p":"v.","m":"To struggle clumsily; to be in confusion.","e":"Perhaps a blend of founder and blunder (16th c.).","f":"patauger, s’empêtrer","t":"Thrashing about in mud: « patauger »."},{"w":"guffaw","p":"n. / v.","m":"A loud, boisterous laugh.","e":"Scottish, imitative of the sound (18th c.).","f":"gros rire, s’esclaffer","t":"Say it out loud: guff-AW! « S’esclaffer »."},{"w":"impede","p":"v.","m":"To delay or obstruct.","e":"Latin <i>impedire</i> (to shackle the feet): <i>in</i> + <i>pes, pedis</i> (foot).","f":"entraver, empêcher","t":"Feet tied: « empêcher » comes from the same word."},{"w":"impermeable","p":"adj.","m":"Not allowing fluid (or influence) to pass through.","e":"Late Latin <i>impermeabilis</i>: <i>in-</i> + <i>permeare</i> (to pass through).","f":"imperméable","t":"Same as « imperméable », your raincoat."},{"w":"incessant","p":"adj.","m":"Continuing without pause.","e":"Late Latin <i>incessantem</i>: <i>in-</i> + <i>cessare</i> (to stop).","f":"incessant","t":"Never ceasing: « incessant »."},{"w":"inclement","p":"adj.","m":"Unpleasantly cold or wet (weather).","e":"Latin <i>inclemens</i>: <i>in-</i> + <i>clemens</i> (mild).","f":"rigoureux, peu clément","t":"Not clement: « un temps peu clément »."},{"w":"ingenuity","p":"n.","m":"Cleverness, inventiveness.","e":"Latin <i>ingenuitas</i> (originally frankness, confused with <i>ingenium</i>, talent).","f":"ingéniosité","t":"« Ingéniosité ». Funny twist: it comes from ingenuous (naive)."},{"w":"jocular","p":"adj.","m":"Fond of joking; humorous.","e":"Latin <i>iocularis</i>, from <i>iocus</i> (joke), which gave French <i>jeu</i>.","f":"enjoué, facétieux","t":"Iocus = jeu, joke: jovial and jokey."},{"w":"malady","p":"n.","m":"A disease or ailment.","e":"Old French <i>maladie</i>, from <i>malade</i>, Latin <i>male habitus</i> (in bad condition).","f":"maladie, mal","t":"Straight from « maladie »."},{"w":"malleable","p":"adj.","m":"Easily shaped or influenced.","e":"Medieval Latin <i>malleabilis</i>, from <i>malleus</i> (hammer).","f":"malléable","t":"Metal you can shape with a hammer (malleus, maillet)."},{"w":"meander","p":"v.","m":"To wander aimlessly; follow a winding course.","e":"Greek <i>Maiandros</i>, a famously winding river in Asia Minor.","f":"serpenter, méandre","t":"« Les méandres » of the river Maeander."},{"w":"moot","p":"adj.","m":"Debatable; or of no practical relevance.","e":"Old English <i>mōt</i> (assembly, meeting) where matters were debated.","f":"discutable; sans intérêt pratique","t":"A question debated at the moot (assembly). “A moot point” = « sans objet »."},{"w":"morose","p":"adj.","m":"Sullen and gloomy.","e":"Latin <i>morosus</i> (peevish), from <i>mos, moris</i> (custom, mood).","f":"morose","t":"Same as « morose »."},{"w":"muted","p":"adj.","m":"Quiet, subdued, not intense.","e":"Latin <i>mutus</i> (silent).","f":"atténué, discret, feutré","t":"« Muet »: a muted response, muted colours."},{"w":"obdurate","p":"adj.","m":"Stubbornly refusing to change.","e":"Latin <i>obduratus</i> (hardened): <i>ob</i> + <i>durare</i> (to harden), <i>durus</i>.","f":"obstiné, inflexible","t":"Hardened (dur) against persuasion."},{"w":"ornate","p":"adj.","m":"Elaborately decorated.","e":"Latin <i>ornatus</i>, from <i>ornare</i> (to adorn).","f":"orné, chargé","t":"« Orné »: ornate Baroque churches."},{"w":"patronize","p":"v.","m":"To treat condescendingly; also to be a customer of.","e":"From patron, Latin <i>patronus</i> (protector), from <i>pater</i> (father).","f":"traiter avec condescendance; fréquenter","t":"Acting like a father to an adult: condescending."},{"w":"pithy","p":"adj.","m":"Concise and full of meaning.","e":"From <i>pith</i>, Old English <i>pitha</i> (the essential core of a plant).","f":"concis, lapidaire","t":"All core, no fluff: a pithy remark."},{"w":"plodding","p":"adj.","m":"Slow and laborious; dull.","e":"Probably imitative of heavy footsteps (16th c.).","f":"laborieux, lent","t":"The sound of heavy boots: plod, plod."},{"w":"proponent","p":"n.","m":"A person who advocates a theory.","e":"Latin <i>proponentem</i>, from <i>proponere</i> (to put forward).","f":"partisan, défenseur","t":"Someone who proposes."},{"w":"quandary","p":"n.","m":"A state of uncertainty over what to do.","e":"Origin uncertain (16th c.); perhaps from Latin <i>quando</i> (when?).","f":"dilemme, embarras","t":"« Quand? » — not knowing what or when to do."},{"w":"raffish","p":"adj.","m":"Unconventional and slightly disreputable, but attractive.","e":"From <i>raff</i> (rubbish, riff-raff).","f":"canaille, un peu voyou","t":"Riff-raff with charm: « un air canaille »."},{"w":"renege","p":"v.","m":"To go back on a promise.","e":"Medieval Latin <i>renegare</i> (to deny): <i>re-</i> + <i>negare</i>.","f":"revenir sur sa parole","t":"Like « renier »: you deny your own promise."},{"w":"resolve","p":"n.","m":"Firm determination.","e":"Latin <i>resolvere</i> (to loosen, settle).","f":"détermination, résolution","x":"2nd meaning","t":"Making a resolution = showing resolve."},{"w":"respite","p":"n.","m":"A short period of rest or relief.","e":"Old French <i>respit</i>, from Latin <i>respectus</i> (regard, delay).","f":"répit","t":"Same as « répit »."},{"w":"robust","p":"adj.","m":"Strong and healthy; sturdy.","e":"Latin <i>robustus</i> (oaken, strong), from <i>robur</i> (oak).","f":"robuste","t":"Strong as an oak: « robuste »."},{"w":"snide","p":"adj.","m":"Mocking in an indirect, unkind way.","e":"19th-century slang, originally “counterfeit”; origin unknown.","f":"sarcastique, narquois","t":"A snide remark: a fake compliment with a sneer."},{"w":"stolid","p":"adj.","m":"Calm, dependable, showing little emotion.","e":"Latin <i>stolidus</i> (dull, stupid).","f":"impassible, flegmatique","t":"Not solid, but close: stolid = unmoving, impassive."},{"w":"thwart","p":"v.","m":"To prevent someone from accomplishing something.","e":"Old Norse <i>þvert</i> (across). To put something across someone’s path.","f":"contrecarrer, déjouer","t":"Laying a log across the path: thwarted plans."},{"w":"transitory","p":"adj.","m":"Not permanent.","e":"Latin <i>transitorius</i>, from <i>transire</i> (to pass over).","f":"transitoire, passager","t":"Same as « transitoire »."}]},{"name":"Basic IV","slug":"basic-iv","series":"Basic","words":[{"w":"altruism","p":"n.","m":"Selfless concern for others.","e":"French <i>altruisme</i>, coined by Auguste Comte (1830s) from Italian <i>altrui</i> (of others), Latin <i>alter</i>.","f":"altruisme","t":"Coined by a Frenchman, Comte: « autrui » = others."},{"w":"assail","p":"v.","m":"To attack violently, physically or verbally.","e":"Old French <i>asaillir</i>, from Latin <i>ad</i> + <i>salire</i> (to leap).","f":"assaillir","t":"Same as « assaillir »: leaping at someone."},{"w":"assuage","p":"v.","m":"To make an unpleasant feeling less intense.","e":"Old French <i>assouagier</i>, from Latin <i>ad</i> + <i>suavis</i> (sweet).","f":"apaiser, soulager","t":"Sweeten (suave) the pain: assuage guilt."},{"w":"augment","p":"v.","m":"To make greater; increase.","e":"Latin <i>augmentare</i>, from <i>augere</i> (to increase).","f":"augmenter","t":"Same as « augmenter »."},{"w":"banish","p":"v.","m":"To send away; exile.","e":"Old French <i>banir</i>, from Frankish <i>bannjan</i> (to proclaim). Germanic.","f":"bannir","t":"Same as « bannir »: proclaimed out."},{"w":"benign","p":"adj.","m":"Gentle and kind; not harmful.","e":"Latin <i>benignus</i> (kind): <i>bene</i> (well) + <i>gignere</i> (to be born).","f":"bénin, bienveillant","t":"« Une tumeur bénigne »: born well."},{"w":"buck","p":"v.","m":"To resist or oppose (buck the trend).","e":"From the male deer or horse that kicks and resists its rider.","f":"résister à, aller à contre-courant","x":"2nd meaning","t":"A bucking horse throwing off its rider: bucking the trend."},{"w":"commendable","p":"adj.","m":"Deserving praise.","e":"Latin <i>commendare</i> (to entrust, recommend).","f":"louable","t":"Worth a recommendation."},{"w":"conducive","p":"adj.","m":"Making a certain outcome likely.","e":"Latin <i>conducere</i> (to lead together).","f":"propice à, favorable à","t":"Leading (conduire) towards a result: conducive to learning."},{"w":"contemptuous","p":"adj.","m":"Showing contempt; scornful.","e":"Latin <i>contemptus</i>, from <i>contemnere</i> (to despise).","f":"méprisant","t":"« Contempteur »: looking down on someone."},{"w":"cornucopia","p":"n.","m":"An abundant supply.","e":"Latin <i>cornu copiae</i>, horn of plenty: the goat’s horn that fed baby Zeus.","f":"corne d’abondance, profusion","t":"The horn of plenty spilling fruit."},{"w":"credence","p":"n.","m":"Belief or acceptance as true.","e":"Medieval Latin <i>credentia</i>, from <i>credere</i> (to believe).","f":"crédit, foi","t":"Give credence = « accorder du crédit »."},{"w":"debase","p":"v.","m":"To reduce in quality or value.","e":"<i>de-</i> + base (low), from Late Latin <i>bassus</i>.","f":"avilir, dévaluer","t":"Bring down low (bas): debasing a currency."},{"w":"derisive","p":"adj.","m":"Expressing contempt or ridicule.","e":"Latin <i>deridere</i> (to laugh at), <i>ridere</i>.","f":"moqueur, dérisoire","t":"« Dérision »: mocking laughter."},{"w":"detrimental","p":"adj.","m":"Tending to cause harm.","e":"Latin <i>detrimentum</i> (loss), from <i>deterere</i> (to rub away).","f":"préjudiciable, nuisible","t":"« Au détriment de »: rubbing away your interests."},{"w":"egotist","p":"n.","m":"A self-centred, conceited person.","e":"Latin <i>ego</i> (I).","f":"égotiste, égocentrique","t":"Ego + -ist: every conversation comes back to “I”. « Égotiste »."},{"w":"elaborate","p":"v. / adj.","m":"To add detail; intricate.","e":"Latin <i>elaborare</i> (to work out): <i>e-</i> + <i>labor</i> (work).","f":"développer, préciser; élaboré","t":"« Élaborer »: work it out further."},{"w":"empathetic","p":"adj.","m":"Showing understanding of others’ feelings.","e":"Greek <i>empatheia</i>: <i>en</i> (in) + <i>pathos</i> (feeling).","f":"empathique","t":"Feeling in someone else’s shoes."},{"w":"euphoria","p":"n.","m":"Intense excitement and happiness.","e":"Greek <i>euphoria</i>: <i>eu</i> (well) + <i>pherein</i> (to bear).","f":"euphorie","t":"Same as « euphorie »."},{"w":"facetious","p":"adj.","m":"Treating serious issues with inappropriate humour.","e":"French <i>facétieux</i>, from Latin <i>facetia</i> (jest).","f":"facétieux","t":"Same as « facétieux », but in English often a criticism."},{"w":"fickle","p":"adj.","m":"Changing frequently, especially in loyalty.","e":"Old English <i>ficol</i> (deceitful). Germanic.","f":"inconstant, volage","t":"Fickle fans switch teams every season."},{"w":"genial","p":"adj.","m":"Friendly and cheerful.","e":"Latin <i>genialis</i> (festive, pleasant), from <i>genius</i> (guardian spirit).","f":"cordial, aimable (≠ génial)","x":"Faux ami","t":"Not « génial »! A genial host is warm and friendly."},{"w":"genteel","p":"adj.","m":"Polite, refined, respectable (sometimes affectedly so).","e":"French <i>gentil</i> (noble, well-born), Latin <i>gentilis</i> (of the same clan).","f":"distingué, raffiné","t":"Old French « gentil » = noble (gentilhomme)."},{"w":"glib","p":"adj.","m":"Fluent but insincere and shallow.","e":"Perhaps Low German <i>glibberig</i> (slippery).","f":"désinvolte, facile, superficiel","t":"Slippery words: a glib answer slides off without thought."},{"w":"grovel","p":"v.","m":"To act obsequiously to win favour.","e":"From Old Norse <i>á grúfu</i> (face down).","f":"ramper, s’aplatir","t":"Face down on the floor: « ramper »."},{"w":"hamstrung","p":"adj.","m":"Severely restricted; crippled.","e":"From <i>hamstring</i>: cutting the tendon behind the knee to disable.","f":"paralysé, entravé","t":"Tendons cut, like les Énervés de Jumièges: unable to act."},{"w":"illicit","p":"adj.","m":"Forbidden by law or custom.","e":"Latin <i>illicitus</i>: <i>in-</i> + <i>licitus</i> (allowed).","f":"illicite","t":"Same as « illicite ». Not elicit."},{"w":"impeccable","p":"adj.","m":"Flawless.","e":"Latin <i>impeccabilis</i>: <i>in-</i> + <i>peccare</i> (to sin).","f":"impeccable","t":"Without sin (péché)."},{"w":"inadvertent","p":"adj.","m":"Not intentional.","e":"<i>in-</i> + Latin <i>advertere</i> (to turn towards).","f":"involontaire, par inadvertance","t":"« Par inadvertance »."},{"w":"irresolute","p":"adj.","m":"Uncertain; hesitant.","e":"<i>in-</i> + Latin <i>resolutus</i> (resolved).","f":"irrésolu, indécis","t":"Same as « irrésolu »."},{"w":"jargon","p":"n.","m":"Specialist words hard for others to understand.","e":"Old French <i>jargon</i> (twittering of birds).","f":"jargon","t":"Birds chirping: consulting jargon like “synergies”."},{"w":"lucid","p":"adj.","m":"Clear, easy to understand.","e":"Latin <i>lucidus</i>, from <i>lux</i> (light).","f":"lucide, limpide","t":"Full of light: a lucid explanation."},{"w":"martial","p":"adj.","m":"Relating to war.","e":"Latin <i>martialis</i>, of Mars, god of war.","f":"martial","t":"Mars: martial arts, martial law."},{"w":"perennial","p":"adj.","m":"Lasting a long time; recurring.","e":"Latin <i>perennis</i>: <i>per</i> + <i>annus</i> (year).","f":"pérenne, éternel; vivace","t":"Through the years: « pérenne »."},{"w":"perpetuate","p":"v.","m":"To make something continue indefinitely.","e":"Latin <i>perpetuare</i>, from <i>perpetuus</i> (continuous).","f":"perpétuer","t":"Same as « perpétuer »."},{"w":"pertinent","p":"adj.","m":"Relevant.","e":"Latin <i>pertinentem</i>, from <i>pertinere</i> (to relate to).","f":"pertinent","t":"Same as « pertinent »."},{"w":"precedent","p":"n.","m":"An earlier event used as a guide.","e":"Latin <i>praecedere</i> (to go before).","f":"précédent","t":"« Créer un précédent »."},{"w":"pristine","p":"adj.","m":"In original, perfect condition.","e":"Latin <i>pristinus</i> (former, original).","f":"immaculé, intact","t":"Like new, original state: pristine beaches."},{"w":"rankle","p":"v.","m":"To cause lasting irritation.","e":"Old French <i>draoncler</i> (to fester), from <i>draoncle</i> (ulcer), Latin <i>dracunculus</i> (little dragon).","f":"rester en travers de la gorge","t":"A little dragon festering inside you: the comment still rankles."},{"w":"sentimental","p":"adj.","m":"Driven by tender emotion, often excessively.","e":"From sentiment, Latin <i>sentire</i> (to feel).","f":"sentimental","t":"Same as « sentimental »."},{"w":"smattering","p":"n.","m":"A slight knowledge; a small amount.","e":"From <i>smatter</i> (to talk ignorantly), perhaps Scandinavian.","f":"vague notion, quelques rudiments","t":"A smattering of Spanish: « quelques notions »."},{"w":"spurn","p":"v.","m":"To reject with disdain.","e":"Old English <i>spurnan</i> (to kick). Germanic, related to spur.","f":"repousser, dédaigner","t":"Kicking away an offer."},{"w":"surly","p":"adj.","m":"Bad-tempered and unfriendly.","e":"Earlier <i>sirly</i> (lordly, arrogant), from <i>sir</i>.","f":"bourru, revêche","t":"Acting like a haughty sir: a surly waiter."},{"w":"tawdry","p":"adj.","m":"Showy but cheap and of poor quality.","e":"From <i>St Audrey’s lace</i>: cheap lace sold at St Audrey’s fair in Ely.","f":"clinquant, de pacotille","t":"Cheap fair-ground lace: tawdry decor."},{"w":"tumult","p":"n.","m":"Loud confused noise; uproar.","e":"Latin <i>tumultus</i>, from <i>tumere</i> (to swell).","f":"tumulte","t":"Same as « tumulte »."},{"w":"uncompromising","p":"adj.","m":"Unwilling to make concessions.","e":"<i>un-</i> + compromise, Latin <i>compromittere</i> (to promise mutually).","f":"intransigeant","t":"No compromise at all: « intransigeant », like an uncompromising negotiator."},{"w":"unruly","p":"adj.","m":"Disorderly; hard to control.","e":"<i>un-</i> + <i>ruly</i> (orderly, from rule).","f":"indiscipliné, turbulent","t":"Not following the rules: an unruly class."},{"w":"urbane","p":"adj.","m":"Suave, courteous and refined.","e":"Latin <i>urbanus</i> (of the city), from <i>urbs</i>.","f":"courtois, raffiné","t":"City-polished manners (« urbanité »), as opposed to rustic."},{"w":"vacuous","p":"adj.","m":"Showing lack of thought; empty.","e":"Latin <i>vacuus</i> (empty).","f":"vide, creux, niais","t":"Vacuum: a vacuous stare."},{"w":"whimsical","p":"adj.","m":"Playfully quaint or fanciful.","e":"From <i>whim</i>, short for <i>whim-wham</i> (a trifle).","f":"fantasque, capricieux","t":"Following every whim: a whimsical illustration."}]},{"name":"Basic V","slug":"basic-v","series":"Basic","words":[{"w":"aphoristic","p":"adj.","m":"Expressed in short, wise sayings.","e":"Greek <i>aphorismos</i> (definition), from <i>aphorizein</i> (to mark off boundaries).","f":"aphoristique, sentencieux","t":"La Rochefoucauld’s maxims are aphoristic."},{"w":"brusquely","p":"adv.","m":"In an abrupt, rude way.","e":"French <i>brusque</i>, from Italian <i>brusco</i> (sour, harsh).","f":"brusquement, sèchement","t":"Same as « brusquement »."},{"w":"candidness","p":"n.","m":"Frankness, openness.","e":"Latin <i>candidus</i> (white, pure).","f":"franchise","x":"Faux ami","t":"Candour = franchise, not French candeur (naivety)."},{"w":"collusion","p":"n.","m":"Secret cooperation to cheat or deceive.","e":"Latin <i>colludere</i> (to play together): <i>com-</i> + <i>ludere</i>.","f":"collusion, connivence","t":"Playing together secretly: « collusion »."},{"w":"complacent","p":"adj.","m":"Smugly self-satisfied, unaware of danger.","e":"Latin <i>complacere</i> (to please greatly).","f":"suffisant, trop sûr de soi (≠ complaisant)","x":"Faux ami","t":"French « complaisant » = obliging. Complacent = resting on your laurels."},{"w":"connive","p":"v.","m":"To secretly allow wrongdoing; to conspire.","e":"Latin <i>connivere</i> (to wink, shut the eyes).","f":"être de connivence, fermer les yeux","t":"Winking at a crime: « connivence »."},{"w":"convoluted","p":"adj.","m":"Extremely complex and hard to follow.","e":"Latin <i>convolutus</i> (rolled together): <i>com-</i> + <i>volvere</i>.","f":"alambiqué, compliqué","t":"Rolled up on itself, like involved."},{"w":"credulity","p":"n.","m":"Tendency to believe too readily.","e":"Latin <i>credulitas</i>, from <i>credere</i> (to believe).","f":"crédulité","t":"Same as « crédulité »."},{"w":"derogative","p":"adj.","m":"Showing a critical or disrespectful attitude.","e":"Latin <i>derogare</i> (to detract from): <i>de-</i> + <i>rogare</i> (to ask).","f":"péjoratif, désobligeant","t":"« Déroger »: taking away from someone’s worth."},{"w":"destitute","p":"adj.","m":"Extremely poor, lacking basic necessities.","e":"Latin <i>destitutus</i> (abandoned), from <i>destituere</i> (to forsake).","f":"démuni, dans le dénuement","t":"Abandoned with nothing: « dans le dénuement »."},{"w":"devolve","p":"v.","m":"To transfer power to a lower level.","e":"Latin <i>devolvere</i> (to roll down).","f":"déléguer, transférer","t":"Rolling power down: devolved Scottish government."},{"w":"diligent","p":"adj.","m":"Showing care and effort.","e":"Latin <i>diligentem</i> (attentive), from <i>diligere</i> (to value).","f":"diligent, assidu","t":"Same as « diligent »: due diligence."},{"w":"discord","p":"n.","m":"Disagreement; lack of harmony.","e":"Latin <i>discordia</i>: <i>dis-</i> + <i>cor, cordis</i> (heart). Hearts apart.","f":"discorde","t":"« La pomme de discorde »."},{"w":"eke","p":"v.","m":"To make something last by careful use (eke out).","e":"Old English <i>īecan</i> (to increase). Germanic.","f":"faire durer; gagner péniblement","t":"Eke out a living = scraping by."},{"w":"elude","p":"v.","m":"To evade or escape skilfully.","e":"Latin <i>eludere</i> (to escape by trickery).","f":"échapper à, éluder","t":"« Éluder une question »."},{"w":"embellish","p":"v.","m":"To make more attractive; to exaggerate a story.","e":"Old French <i>embellir</i>, from <i>bel</i> (beautiful).","f":"embellir, enjoliver","t":"Same as « embellir »."},{"w":"enmity","p":"n.","m":"Hostility.","e":"Old French <i>enemistié</i>, from Latin <i>inimicus</i> (enemy).","f":"inimitié, hostilité","t":"Enemy → enmity."},{"w":"exasperate","p":"v.","m":"To irritate intensely.","e":"Latin <i>exasperare</i> (to roughen): <i>ex-</i> + <i>asper</i> (rough).","f":"exaspérer","t":"Same as « exaspérer »."},{"w":"exemplify","p":"v.","m":"To be a typical example of.","e":"Medieval Latin <i>exemplificare</i>, from <i>exemplum</i>.","f":"illustrer, incarner","t":"Exemplify = be the exemplum, « illustrer »: she exemplifies the Bain work ethic."},{"w":"foible","p":"n.","m":"A minor weakness in character.","e":"French <i>foible</i>, old form of <i>faible</i> (weak); in fencing, the weak part of the blade.","f":"faiblesse, petit travers","t":"« Faible »: everyone has their little foibles."},{"w":"goad","p":"v.","m":"To provoke or urge into action.","e":"Old English <i>gād</i> (a pointed stick for driving cattle).","f":"aiguillonner, pousser","t":"A pointed stick prodding oxen: goaded into a fight."},{"w":"impending","p":"adj.","m":"About to happen (usually something bad).","e":"Latin <i>impendere</i> (to hang over).","f":"imminent","t":"Hanging over your head: impending doom."},{"w":"impregnable","p":"adj.","m":"Unable to be captured or broken into.","e":"Old French <i>imprenable</i>: <i>in-</i> + <i>prendre</i> (to take).","f":"imprenable","t":"Same as « imprenable » (a fortress)."},{"w":"irk","p":"v.","m":"To irritate, annoy.","e":"Middle English <i>irken</i> (to grow weary), perhaps Old Norse.","f":"agacer","t":"Irk = « agacer »: small and sharp, like the sound of the word itself."},{"w":"leery","p":"adj.","m":"Cautious or suspicious.","e":"From <i>leer</i> (a sideways look), Old English <i>hlēor</i> (cheek).","f":"méfiant","t":"Looking at it sideways: leery of strangers."},{"w":"malevolent","p":"adj.","m":"Wishing evil on others.","e":"Latin <i>malevolentem</i>: <i>male</i> (badly) + <i>velle</i> (to wish).","f":"malveillant","t":"Wishing ill: « malveillant »."},{"w":"maxim","p":"n.","m":"A short statement of a general truth or rule.","e":"Latin <i>maxima</i> (propositio), the greatest premise.","f":"maxime","t":"Same as « maxime »."},{"w":"obstinate","p":"adj.","m":"Stubbornly refusing to change.","e":"Latin <i>obstinatus</i>, from <i>obstinare</i> (to persist).","f":"obstiné","t":"Same as « obstiné »."},{"w":"pastoral","p":"adj.","m":"Relating to idealised country life.","e":"Latin <i>pastoralis</i>, from <i>pastor</i> (shepherd).","f":"pastoral, champêtre","t":"Shepherds (pasteurs) in green fields."},{"w":"peevish","p":"adj.","m":"Easily irritated, especially by trifles.","e":"Middle English <i>pevish</i> (perverse), origin unknown.","f":"grincheux, irritable","t":"Peeved over nothing."},{"w":"perturb","p":"v.","m":"To make anxious or unsettled.","e":"Latin <i>perturbare</i>: <i>per-</i> + <i>turbare</i> (to disturb).","f":"perturber, troubler","t":"Same as « perturber »."},{"w":"placid","p":"adj.","m":"Calm; not easily upset.","e":"Latin <i>placidus</i>, from <i>placere</i> (to please).","f":"placide","t":"Same as « placide »."},{"w":"ploy","p":"n.","m":"A cunning tactic.","e":"Perhaps from employ (17th c. Scottish).","f":"stratagème, manœuvre","t":"A marketing ploy."},{"w":"presumption","p":"n.","m":"Arrogant overstepping of bounds; also an assumption.","e":"Latin <i>praesumere</i> (to take beforehand).","f":"présomption, arrogance","t":"Taking for granted: « présomptueux »."},{"w":"quip","p":"n.","m":"A witty remark.","e":"Perhaps from Latin <i>quippe</i> (indeed, forsooth, used ironically).","f":"bon mot, trait d’esprit","t":"A quick quip = « un bon mot »."},{"w":"rash","p":"adj.","m":"Acting without careful thought.","e":"Middle English <i>rasch</i> (quick), Germanic.","f":"irréfléchi, téméraire","t":"Rushing into it: a rash decision."},{"w":"reservation","p":"n.","m":"A doubt or qualification.","e":"Latin <i>reservare</i> (to keep back).","f":"réserve, réticence","x":"2nd meaning","t":"« Émettre des réserves »: holding something back."},{"w":"retract","p":"v.","m":"To withdraw a statement.","e":"Latin <i>retrahere</i> (to draw back).","f":"rétracter, revenir sur","t":"« Se rétracter »."},{"w":"savvy","p":"adj. / n.","m":"Shrewd and knowledgeable; practical know-how.","e":"Pidgin from Spanish/Portuguese <i>sabe</i> (he knows), Latin <i>sapere</i>.","f":"avisé, futé; savoir-faire","t":"« Savoir »: tech-savvy."},{"w":"serene","p":"adj.","m":"Calm, peaceful.","e":"Latin <i>serenus</i> (clear, untroubled).","f":"serein","t":"Same as « serein »."},{"w":"smug","p":"adj.","m":"Excessively pleased with oneself.","e":"Perhaps Low German <i>smuk</i> (neat, trim).","f":"suffisant, content de soi","t":"The smug grin of someone who told you so."},{"w":"squander","p":"v.","m":"To waste.","e":"Origin unknown (16th c.).","f":"gaspiller, dilapider","t":"Squander an opportunity: « gâcher »."},{"w":"steadfast","p":"adj.","m":"Resolutely firm and unwavering.","e":"Old English <i>stedefæst</i>: <i>stede</i> (place) + <i>fæst</i> (firm). Fixed in place.","f":"inébranlable, constant","t":"Stuck fast to its place."},{"w":"tact","p":"n.","m":"Sensitivity in dealing with others.","e":"French <i>tact</i>, Latin <i>tactus</i> (touch).","f":"tact","t":"Same as « tact »: the right touch."},{"w":"tarnish","p":"v.","m":"To damage a reputation; to dull a metal.","e":"French <i>ternir</i>, from <i>terne</i> (dull).","f":"ternir","t":"Tarnish = « ternir »."},{"w":"taxing","p":"adj.","m":"Physically or mentally demanding.","e":"Latin <i>taxare</i> (to assess, censure).","f":"éprouvant, épuisant","x":"2nd meaning","t":"It takes a tax on your energy."},{"w":"tout","p":"v.","m":"To promote insistently.","e":"Middle English <i>tuten</i> (to peep, look out). A tout looked out for customers.","f":"vanter, racoler","t":"Touted as the next big thing: « vanté »."},{"w":"travail","p":"n.","m":"Painful or laborious effort.","e":"Old French <i>travail</i> (suffering), from Latin <i>tripalium</i>, a three-pronged torture device.","f":"labeur, peine","t":"French « travail », in its old sense: hard toil. (Also labour pains.)"},{"w":"unprecedented","p":"adj.","m":"Never done or known before.","e":"<i>un-</i> + precedent, Latin <i>praecedere</i>.","f":"sans précédent","t":"« Sans précédent »."},{"w":"unseemly","p":"adj.","m":"Not proper or appropriate.","e":"<i>un-</i> + seemly (fitting), Old Norse <i>sœmr</i>.","f":"inconvenant, malséant","t":"Not seemly: unseemly behaviour."}]},{"name":"Basic VI","slug":"basic-vi","series":"Basic","words":[{"w":"analogous","p":"adj.","m":"Comparable in certain respects.","e":"Greek <i>analogos</i> (proportionate): <i>ana</i> + <i>logos</i> (ratio).","f":"analogue","t":"Same as « analogue »."},{"w":"antedate","p":"v.","m":"To come before in time.","e":"Latin <i>ante</i> (before) + date.","f":"précéder, antidater","t":"Ante = before (antérieur)."},{"w":"ascribe","p":"v.","m":"To attribute to a cause or source.","e":"Latin <i>ascribere</i>: <i>ad</i> + <i>scribere</i> (to write).","f":"attribuer, imputer","t":"Writing a name next to it: ascribe success to luck."},{"w":"avert","p":"v.","m":"To prevent; to turn away (eyes).","e":"Latin <i>avertere</i>: <i>ab</i> + <i>vertere</i> (to turn).","f":"éviter, détourner","t":"Turn away disaster."},{"w":"begrudge","p":"v.","m":"To resent someone having something; give reluctantly.","e":"<i>be-</i> + grudge, Old French <i>grouchier</i> (to grumble).","f":"envier, donner à contrecœur","t":"Grumbling (grouchy) about someone’s bonus."},{"w":"behoove","p":"v.","m":"To be necessary or proper for.","e":"Old English <i>behōfian</i> (to need). Germanic.","f":"incomber à, convenir à","t":"It behooves you to = « il vous incombe de »."},{"w":"belittle","p":"v.","m":"To make seem unimportant.","e":"<i>be-</i> + little. Coined in America (Jefferson, 1780s).","f":"rabaisser, minimiser","t":"Be + little = make someone feel little: « rabaisser »."},{"w":"besmirch","p":"v.","m":"To damage someone’s reputation.","e":"<i>be-</i> + <i>smirch</i> (to soil), perhaps from Old French <i>esmorcher</i> (to torment with heat).","f":"salir, ternir","t":"Smearing dirt on a name."},{"w":"buttress","p":"v. / n.","m":"To support or strengthen; a support.","e":"Old French <i>bouterez</i> (thrusting), from <i>bouter</i> (to push). A flying buttress pushes against a wall.","f":"étayer, renforcer; contrefort","t":"The flying buttresses (arcs-boutants) of Notre-Dame holding up the walls."},{"w":"cavalier","p":"adj.","m":"Showing arrogant disregard.","e":"French <i>cavalier</i> (horseman), Latin <i>caballus</i> (horse).","f":"désinvolte, cavalier","t":"« Une attitude cavalière »: the haughty horseman."},{"w":"cerebral","p":"adj.","m":"Intellectual rather than emotional.","e":"Latin <i>cerebrum</i> (brain).","f":"cérébral","t":"Same as « cérébral »."},{"w":"clemency","p":"n.","m":"Mercy, leniency.","e":"Latin <i>clementia</i>, from <i>clemens</i> (mild).","f":"clémence","t":"Same as « clémence »."},{"w":"coalesce","p":"v.","m":"To come together to form one whole.","e":"Latin <i>coalescere</i>: <i>com-</i> + <i>alescere</i> (to grow).","f":"fusionner, s’unir","t":"Growing together into one (coalition)."},{"w":"cohesive","p":"adj.","m":"Forming a united whole.","e":"Latin <i>cohaerere</i> (to stick together).","f":"cohésif, uni","t":"Sticking together: « cohésion »."},{"w":"consecrate","p":"v.","m":"To make sacred.","e":"Latin <i>consecrare</i>, from <i>sacer</i> (sacred).","f":"consacrer","t":"« Consacrer »."},{"w":"conundrum","p":"n.","m":"A difficult problem or puzzle.","e":"16th-century Oxford mock-Latin, origin unknown.","f":"énigme, casse-tête","t":"A conundrum = « un casse-tête »."},{"w":"delegate","p":"v. / n.","m":"To entrust a task to another.","e":"Latin <i>delegare</i>: <i>de</i> + <i>legare</i> (to send).","f":"déléguer; délégué","t":"Same as « déléguer »."},{"w":"deride","p":"v.","m":"To mock, ridicule.","e":"Latin <i>deridere</i> (to laugh at).","f":"tourner en dérision","t":"« Dérision »."},{"w":"docile","p":"adj.","m":"Ready to accept control; submissive.","e":"Latin <i>docilis</i> (teachable), from <i>docere</i> (to teach).","f":"docile","t":"Same as « docile »."},{"w":"eccentric","p":"adj.","m":"Unconventional, slightly strange.","e":"Greek <i>ekkentros</i>: <i>ek</i> (out of) + <i>kentron</i> (centre).","f":"excentrique","t":"Ex + kentron = off-centre: the eccentric aunt orbiting outside normal behaviour."},{"w":"emulate","p":"v.","m":"To imitate in order to equal or surpass.","e":"Latin <i>aemulari</i> (to rival).","f":"imiter, rivaliser avec","t":"« Émulation »: rivalry that pushes you."},{"w":"evenhanded","p":"adj.","m":"Fair and impartial.","e":"English <i>even</i> + <i>handed</i>.","f":"impartial, équitable","t":"Holding both hands level, like the scales of justice."},{"w":"fawn","p":"v.","m":"To flatter excessively.","e":"Old English <i>fagnian</i> (to rejoice, wag the tail).","f":"flagorner, faire des courbettes","t":"A dog wagging its tail to please: fawning on the boss."},{"w":"finagle","p":"v.","m":"To obtain by trickery.","e":"American slang (1920s), perhaps from dialect <i>fainaigue</i> (to cheat).","f":"manigancer, obtenir par la ruse","t":"Finagling a deal = « magouiller »."},{"w":"foolhardy","p":"adj.","m":"Recklessly bold.","e":"Old French <i>fol hardi</i> (foolishly bold).","f":"téméraire, imprudent","t":"Fol + hardi: foolishly daring."},{"w":"forthright","p":"adj.","m":"Direct and outspoken.","e":"Old English <i>forthriht</i> (straight forward).","f":"franc, direct","t":"Straight forward."},{"w":"glean","p":"v.","m":"To gather information gradually.","e":"Old French <i>glener</i> (to gather leftover grain), Late Latin <i>glennare</i>.","f":"glaner","t":"« Glaner », like Millet’s Gleaners."},{"w":"humdrum","p":"adj.","m":"Lacking excitement; monotonous.","e":"Reduplication of <i>hum</i> (16th c.).","f":"monotone, ennuyeux","t":"Humming the same drum beat every day."},{"w":"implicate","p":"v.","m":"To show to be involved in a crime.","e":"Latin <i>implicare</i> (to entwine).","f":"impliquer, mettre en cause","t":"Folded into the case."},{"w":"incense","p":"v.","m":"To make very angry.","e":"Latin <i>incendere</i> (to set on fire).","f":"exaspérer, mettre en colère","x":"2nd meaning","t":"Set on fire (incendie): incensed by the decision. Stress on the second syllable."},{"w":"incumbent","p":"adj. / n.","m":"Necessary as a duty; the current holder of an office.","e":"Latin <i>incumbere</i> (to lie upon).","f":"qui incombe; titulaire, sortant","t":"« Il vous incombe »: lying upon you. The incumbent president."},{"w":"industrious","p":"adj.","m":"Diligent and hard-working.","e":"Latin <i>industria</i> (diligence).","f":"travailleur, assidu","t":"Not industrial: hard-working like a bee."},{"w":"insipid","p":"adj.","m":"Lacking flavour or interest.","e":"Latin <i>insipidus</i>: <i>in-</i> + <i>sapidus</i> (tasty).","f":"insipide, fade","t":"Same as « insipide »."},{"w":"intermittent","p":"adj.","m":"Occurring at irregular intervals.","e":"Latin <i>intermittere</i> (to leave off for a while).","f":"intermittent","t":"« Les intermittents du spectacle »."},{"w":"irascible","p":"adj.","m":"Easily made angry.","e":"Latin <i>irascibilis</i>, from <i>ira</i> (anger).","f":"irascible, colérique","t":"Same as « irascible »."},{"w":"lethargic","p":"adj.","m":"Sluggish and apathetic.","e":"Greek <i>lēthargos</i> (forgetful), from <i>lēthē</i> (forgetfulness).","f":"léthargique","t":"The river Lethe of forgetfulness."},{"w":"melancholy","p":"n. / adj.","m":"Deep, lasting sadness.","e":"Greek <i>melankholia</i>: <i>melas</i> (black) + <i>kholē</i> (bile).","f":"mélancolie, mélancolique","t":"Black bile: same as « mélancolie »."},{"w":"piquant","p":"adj.","m":"Pleasantly sharp; stimulating.","e":"French <i>piquant</i> (stinging), from <i>piquer</i>.","f":"piquant","t":"Straight from « piquant »."},{"w":"precarious","p":"adj.","m":"Dangerously unstable.","e":"Latin <i>precarius</i> (obtained by prayer, dependent on others), from <i>prex</i> (prayer).","f":"précaire","t":"Same as « précaire »: dependent on someone’s goodwill."},{"w":"preempt","p":"v.","m":"To act in advance to prevent something.","e":"Back-formation from pre-emption, Latin <i>prae</i> + <i>emere</i> (to buy).","f":"devancer, anticiper","t":"Pre-empt = buy before others (prae + emere): acting first so the rival can’t."},{"w":"presumptuous","p":"adj.","m":"Overstepping limits; overconfident.","e":"Latin <i>praesumptuosus</i>, from <i>praesumere</i>.","f":"présomptueux","t":"Same as « présomptueux »."},{"w":"prevail","p":"v.","m":"To prove more powerful; to be widespread.","e":"Latin <i>praevalere</i>: <i>prae</i> + <i>valere</i> (to be strong).","f":"prévaloir, l’emporter","t":"« Prévaloir »."},{"w":"profusion","p":"n.","m":"An abundance.","e":"Latin <i>profusio</i> (pouring out).","f":"profusion","t":"« À profusion »."},{"w":"rakish","p":"adj.","m":"Dashing, jaunty; slightly disreputable.","e":"From <i>rake</i> (a dissolute man), short for <i>rakehell</i>.","f":"désinvolte, canaille","t":"A hat at a rakish angle: the charming rake."},{"w":"redress","p":"v. / n.","m":"To remedy a wrong; remedy.","e":"Old French <i>redrecier</i> (to set straight again).","f":"réparer, redresser","t":"« Redresser un tort »."},{"w":"rile","p":"v.","m":"To annoy or irritate.","e":"Variant of <i>roil</i> (to stir up mud), perhaps French <i>rouiller</i>.","f":"agacer, énerver","t":"Stirring up muddy water: don’t rile him."},{"w":"tribulation","p":"n.","m":"A cause of great trouble or suffering.","e":"Latin <i>tribulare</i> (to press, oppress), from <i>tribulum</i> (threshing sledge).","f":"tribulation, épreuve","t":"Same as « tribulations »: crushed like grain."},{"w":"uncanny","p":"adj.","m":"Strange or mysterious in an unsettling way.","e":"Scots <i>un-</i> + <i>canny</i> (knowing, safe), from <i>can</i> (to know).","f":"troublant, étrange","t":"Beyond what can be known: an uncanny resemblance."},{"w":"veneer","p":"n.","m":"A superficial appearance covering reality.","e":"German <i>furnieren</i>, from French <i>fournir</i> (to furnish). A thin layer of fine wood.","f":"vernis, façade","t":"A thin layer of fine wood on cheap furniture: a veneer of respectability."},{"w":"wanton","p":"adj.","m":"Deliberate and unprovoked; also immoral.","e":"Middle English <i>wantowen</i>: <i>wan-</i> (lacking) + <i>togen</i> (trained, disciplined).","f":"gratuit, délibéré; dévergondé","t":"Lacking discipline: wanton destruction."}]},{"name":"Basic VII","slug":"basic-vii","series":"Basic","words":[{"w":"abysmal","p":"adj.","m":"Extremely bad; also very deep.","e":"Old French <i>abisme</i> (abyss), from Greek <i>abyssos</i> (bottomless).","f":"exécrable, abyssal","t":"Bottomless: « abîme »."},{"w":"amply","p":"adv.","m":"Sufficiently or more than enough.","e":"Latin <i>amplus</i> (large).","f":"amplement","t":"« Amplement »."},{"w":"antiquated","p":"adj.","m":"Old-fashioned, outdated.","e":"Latin <i>antiquare</i>, from <i>antiquus</i> (old).","f":"désuet, vieillot","t":"Antique and out of date."},{"w":"aphorism","p":"n.","m":"A concise statement of a general truth.","e":"Greek <i>aphorismos</i> (definition).","f":"aphorisme, maxime","t":"Same as « aphorisme »."},{"w":"balk","p":"v.","m":"To hesitate or refuse to proceed.","e":"Old English <i>balca</i> (ridge between furrows); a horse balks at a ridge.","f":"rechigner, renâcler","t":"A horse refusing a jump: « renâcler »."},{"w":"besiege","p":"v.","m":"To surround with armed forces; to overwhelm.","e":"<i>be-</i> + siege, Old French <i>sege</i> (seat).","f":"assiéger, assaillir","t":"« Assiéger »: besieged by journalists."},{"w":"boorish","p":"adj.","m":"Rough and bad-mannered.","e":"From <i>boor</i>, Dutch <i>boer</i> (farmer, peasant).","f":"rustre, grossier","t":"Boer = peasant: « rustre »."},{"w":"carping","p":"adj.","m":"Constantly finding fault.","e":"Old Norse <i>karpa</i> (to boast), influenced by Latin <i>carpere</i> (to pluck, slander).","f":"chicanier, critique","t":"Carping critics pluck at every detail."},{"w":"champion","p":"v.","m":"To support or defend a cause.","e":"Old French <i>champion</i> (combatant), Late Latin <i>campio</i>, from <i>campus</i> (field of battle).","f":"défendre, se faire le champion de","x":"2nd meaning","t":"« Se faire le champion de »: fighting for a cause."},{"w":"chivalrous","p":"adj.","m":"Courteous and gallant, especially towards women.","e":"Old French <i>chevalerie</i>, from <i>cheval</i>.","f":"chevaleresque","t":"The horseman’s code: « chevaleresque »."},{"w":"colossal","p":"adj.","m":"Extremely large.","e":"Greek <i>kolossos</i>, the giant statue (Colossus of Rhodes).","f":"colossal","t":"The Colossus of Rhodes."},{"w":"complementary","p":"adj.","m":"Combining to complete each other.","e":"Latin <i>complementum</i> (that which fills up), from <i>complere</i>.","f":"complémentaire","t":"Not complimentary (praise): pieces that complete each other."},{"w":"compound","p":"v.","m":"To make worse; to combine.","e":"Old French <i>compondre</i>, Latin <i>componere</i> (to put together).","f":"aggraver; composer","x":"2nd meaning","t":"Compound interest grows on itself: compound a problem = aggravate it."},{"w":"constraint","p":"n.","m":"A limitation or restriction.","e":"Old French <i>constreinte</i>, from Latin <i>constringere</i> (to bind tightly).","f":"contrainte","t":"Same as « contrainte »."},{"w":"convivial","p":"adj.","m":"Friendly, lively and enjoyable.","e":"Latin <i>convivium</i> (feast): <i>com-</i> + <i>vivere</i> (to live).","f":"convivial","t":"Same as « convivial »."},{"w":"cosmopolitan","p":"adj.","m":"Familiar with many cultures; including people from many countries.","e":"Greek <i>kosmopolitēs</i> (citizen of the world): <i>kosmos</i> + <i>politēs</i>.","f":"cosmopolite","t":"Citizen of the world."},{"w":"creditable","p":"adj.","m":"Deserving praise, though not outstanding.","e":"From credit, Latin <i>credere</i> (to believe).","f":"honorable, estimable","t":"It does you credit."},{"w":"cumbersome","p":"adj.","m":"Large, heavy and awkward.","e":"From <i>cumber</i> (to hinder), Old French <i>encombrer</i>.","f":"encombrant, lourd","t":"« Encombrant »."},{"w":"debunk","p":"v.","m":"To expose a myth as false.","e":"<i>de-</i> + bunk (nonsense, from <i>bunkum</i>, Buncombe County, whose congressman made a pointless speech in 1820).","f":"démystifier, démentir","t":"Removing the bunk (nonsense)."},{"w":"decimation","p":"n.","m":"Killing or destruction of a large part.","e":"Latin <i>decimare</i>: Roman punishment killing one soldier in ten (<i>decimus</i>).","f":"décimation, destruction","t":"One in ten killed: « décimer »."},{"w":"deliberate","p":"v. / adj.","m":"To think carefully; intentional.","e":"Latin <i>deliberare</i> (to weigh well), from <i>libra</i> (scales).","f":"délibérer; délibéré","t":"Weighing on scales (libra)."},{"w":"differentiate","p":"v.","m":"To recognise or show the difference.","e":"Medieval Latin <i>differentiare</i>.","f":"différencier","t":"Same as « différencier »."},{"w":"dilapidated","p":"adj.","m":"In a state of disrepair.","e":"Latin <i>dilapidare</i> (to scatter stones), from <i>lapis</i> (stone).","f":"délabré","t":"Stones falling apart (lapis)."},{"w":"discreet","p":"adj.","m":"Careful to avoid causing offence or revealing secrets.","e":"Old French <i>discret</i>, Latin <i>discretus</i> (separated, discerning).","f":"discret","t":"Discreet = « discret ». Discrete = separate."},{"w":"dispatch","p":"v. / n.","m":"To send off; to deal with quickly; speed.","e":"Italian <i>dispacciare</i> or Spanish <i>despachar</i> (to expedite).","f":"expédier; célérité","x":"2nd meaning","t":"« Dépêcher »: with dispatch = promptly."},{"w":"enumerate","p":"v.","m":"To list one by one.","e":"Latin <i>enumerare</i>, from <i>numerus</i>.","f":"énumérer","t":"Same as « énumérer »."},{"w":"evasive","p":"adj.","m":"Tending to avoid commitment or answers.","e":"Latin <i>evadere</i> (to escape).","f":"évasif","t":"Same as « évasif »."},{"w":"excruciating","p":"adj.","m":"Intensely painful.","e":"Latin <i>excruciare</i>, from <i>crux</i> (cross): tormented as on a cross.","f":"atroce, insoutenable","t":"Crux = croix: crucifying pain."},{"w":"futile","p":"adj.","m":"Pointless, ineffective.","e":"Latin <i>futilis</i> (leaky, worthless).","f":"vain, inutile (futile = frivolous)","t":"A leaky vessel: futile efforts. French « futile » leans to frivolous."},{"w":"hamper","p":"v.","m":"To hinder.","e":"Middle English <i>hamperen</i>, perhaps related to German <i>hemmen</i> (to restrain).","f":"entraver, gêner","t":"Hamper progress = « entraver »."},{"w":"inarticulate","p":"adj.","m":"Unable to express ideas clearly.","e":"<i>in-</i> + Latin <i>articulatus</i>.","f":"incapable de s’exprimer, inarticulé","t":"Speech without joints."},{"w":"inkling","p":"n.","m":"A slight suspicion or hint.","e":"Middle English <i>inclen</i> (to hint), origin uncertain.","f":"soupçon, vague idée","t":"Not the faintest inkling = « pas la moindre idée »."},{"w":"laborious","p":"adj.","m":"Requiring much effort.","e":"Latin <i>laboriosus</i>, from <i>labor</i>.","f":"laborieux","t":"Same as « laborieux »."},{"w":"malodorous","p":"adj.","m":"Smelling very unpleasant.","e":"Latin <i>male</i> (badly) + <i>odor</i>.","f":"malodorant","t":"Same as « malodorant »."},{"w":"miscreant","p":"n.","m":"A wrongdoer.","e":"Old French <i>mescreant</i> (unbeliever): <i>mes-</i> + <i>croire</i>.","f":"scélérat, malfaiteur","t":"« Mécréant » = unbeliever → villain."},{"w":"misogynist","p":"n.","m":"A person who dislikes women.","e":"Greek <i>misogynēs</i>: <i>misein</i> (to hate) + <i>gynē</i> (woman).","f":"misogyne","t":"Same as « misogyne »."},{"w":"morph","p":"v.","m":"To change gradually into something else.","e":"Short for metamorphose, Greek <i>morphē</i> (shape).","f":"se transformer","t":"Metamorphosis shortened."},{"w":"obliging","p":"adj.","m":"Willing to help.","e":"Latin <i>obligare</i> (to bind).","f":"serviable, obligeant","t":"« Obligeant »."},{"w":"paradoxical","p":"adj.","m":"Seemingly absurd or contradictory.","e":"Greek <i>paradoxos</i>.","f":"paradoxal","t":"Same as « paradoxal »."},{"w":"perquisite","p":"n.","m":"A benefit in addition to salary (a perk).","e":"Medieval Latin <i>perquisitum</i> (thing acquired), from <i>perquirere</i> (to seek diligently).","f":"avantage, à-côté","t":"Perk is short for perquisite."},{"w":"provisional","p":"adj.","m":"Arranged for the present, likely to change.","e":"Latin <i>provisio</i> (foresight).","f":"provisoire","t":"« Provisoire »."},{"w":"qualm","p":"n.","m":"An uneasy feeling of doubt or guilt.","e":"Origin uncertain; Old English <i>cwealm</i> (death, pain) or Dutch <i>kwalm</i> (nausea).","f":"scrupule, remords","t":"No qualms = « aucun scrupule »."},{"w":"relegate","p":"v.","m":"To assign to a lower rank.","e":"Latin <i>relegare</i> (to send away, banish).","f":"reléguer","t":"Same as « reléguer »."},{"w":"resignation","p":"n.","m":"Acceptance of something undesirable but inevitable.","e":"Latin <i>resignare</i> (to unseal, give up).","f":"résignation","x":"2nd meaning","t":"« Résignation »."},{"w":"snub","p":"v. / n.","m":"To rebuff or ignore disdainfully.","e":"Old Norse <i>snubba</i> (to rebuke).","f":"snober, rabrouer","t":"Snub = to ignore someone pointedly: the colleague who looks right through you at the coffee machine."},{"w":"sordid","p":"adj.","m":"Morally vile; dirty.","e":"Latin <i>sordidus</i> (dirty), from <i>sordes</i> (dirt).","f":"sordide","t":"Same as « sordide »."},{"w":"staid","p":"adj.","m":"Sedate, respectable and unadventurous.","e":"Old past participle of <i>stay</i>: settled, steady.","f":"guindé, rangé","t":"Stayed in place: a staid banker."},{"w":"stymie","p":"v.","m":"To prevent or hinder progress.","e":"Golf term: a ball blocking another’s path to the hole.","f":"entraver, bloquer","t":"A golf ball in your way."},{"w":"vanquish","p":"v.","m":"To defeat thoroughly.","e":"Old French <i>vencus</i>, from Latin <i>vincere</i> (to conquer).","f":"vaincre","t":"Vincere = « vaincre »."},{"w":"vie","p":"v.","m":"To compete eagerly.","e":"Short for <i>envy</i> in the old sense “to challenge”, from Old French <i>envier</i> (to invite, challenge).","f":"rivaliser","t":"Vying for the top spot = « rivaliser »."}]},{"name":"Basic VIII","slug":"basic-viii","series":"Basic","words":[{"w":"cacophony","p":"n.","m":"A harsh, discordant mixture of sounds.","e":"Greek <i>kakophōnia</i>: <i>kakos</i> (bad) + <i>phōnē</i> (sound).","f":"cacophonie","t":"Same as « cacophonie »."},{"w":"cathartic","p":"adj.","m":"Providing emotional release.","e":"Greek <i>katharsis</i> (purging), from <i>katharos</i> (pure).","f":"cathartique, libérateur","t":"Aristotle’s catharsis: tragedy purging emotions."},{"w":"caustic","p":"adj.","m":"Sarcastic in a scathing way; corrosive.","e":"Greek <i>kaustikos</i> (burning), from <i>kaiein</i> (to burn).","f":"caustique, mordant","t":"Burning like acid: caustic humour."},{"w":"cloying","p":"adj.","m":"Sickeningly sweet or sentimental.","e":"From <i>cloy</i>, Old French <i>encloer</i> (to nail, block up).","f":"écœurant, mièvre","t":"So sweet it clogs you up: cloying."},{"w":"debacle","p":"n.","m":"A sudden and ignominious failure.","e":"French <i>débâcle</i> (breaking up of ice on a river), from <i>débâcler</i> (to unbar).","f":"débâcle, fiasco","t":"Same as « débâcle »."},{"w":"discern","p":"v.","m":"To perceive or recognise.","e":"Latin <i>discernere</i> (to separate, distinguish).","f":"discerner","t":"Same as « discerner »."},{"w":"discordant","p":"adj.","m":"Disagreeing; harsh-sounding.","e":"Latin <i>discordare</i> (to disagree), <i>cor</i> (heart).","f":"discordant","t":"Same as « discordant »."},{"w":"discredit","p":"v.","m":"To harm the reputation of; to cause to be doubted.","e":"<i>dis-</i> + credit, Latin <i>credere</i>.","f":"discréditer","t":"Same as « discréditer »."},{"w":"discrepancy","p":"n.","m":"A lack of compatibility between facts.","e":"Latin <i>discrepare</i> (to sound differently): <i>dis-</i> + <i>crepare</i> (to rattle).","f":"divergence, écart","t":"Two numbers that don’t sound the same in a model."},{"w":"disparage","p":"v.","m":"To belittle.","e":"Old French <i>desparagier</i> (to marry beneath one’s rank), from <i>parage</i> (rank).","f":"dénigrer, déprécier","t":"Lowering someone’s rank (« parage »)."},{"w":"divulge","p":"v.","m":"To reveal (secret information).","e":"Latin <i>divulgare</i> (to publish), from <i>vulgus</i> (common people).","f":"divulguer","t":"Same as « divulguer »."},{"w":"dubious","p":"adj.","m":"Doubtful; suspect.","e":"Latin <i>dubiosus</i>, from <i>dubium</i> (doubt).","f":"douteux","t":"Doubt: « douteux »."},{"w":"euphemism","p":"n.","m":"A mild word substituted for a harsh one.","e":"Greek <i>euphēmismos</i>: <i>eu</i> (well) + <i>phēmē</i> (speaking).","f":"euphémisme","t":"Same as « euphémisme »."},{"w":"florid","p":"adj.","m":"Overly elaborate; also red-faced.","e":"Latin <i>floridus</i> (flowery), from <i>flos</i> (flower).","f":"fleuri, ampoulé; rougeaud","t":"Flos = fleur: florid prose is over-flowered; a florid face is flushed red."},{"w":"flout","p":"v.","m":"To openly disregard a rule.","e":"Perhaps from Middle Dutch <i>fluyten</i> (to play the flute, to jeer).","f":"bafouer, braver","t":"Not flaunt (show off). Flout the rules."},{"w":"heterogeneous","p":"adj.","m":"Diverse in character.","e":"Greek <i>heterogenēs</i>: <i>heteros</i> (other) + <i>genos</i>.","f":"hétérogène","t":"Same as « hétérogène »."},{"w":"hierarchy","p":"n.","m":"A system of ranked levels.","e":"Greek <i>hierarkhia</i> (rule of a high priest): <i>hieros</i> (sacred) + <i>arkhein</i> (to rule).","f":"hiérarchie","t":"Same as « hiérarchie »."},{"w":"hyperbole","p":"n.","m":"Deliberate exaggeration.","e":"Greek <i>hyperbolē</i> (excess): <i>hyper</i> (beyond) + <i>ballein</i> (to throw).","f":"hyperbole, exagération","t":"Throwing beyond: « hyperbole »."},{"w":"incorporate","p":"v.","m":"To include as part of a whole.","e":"Latin <i>incorporare</i>, from <i>corpus</i> (body).","f":"incorporer, intégrer","t":"In + corpus = into the body: incorporating feedback into the final deck."},{"w":"indelible","p":"adj.","m":"Impossible to remove or forget.","e":"Latin <i>indelebilis</i>: <i>in-</i> + <i>delere</i> (to erase).","f":"indélébile","t":"Same as « indélébile »."},{"w":"indifferent","p":"adj.","m":"Uninterested; also mediocre.","e":"Latin <i>indifferens</i> (not differing).","f":"indifférent; médiocre","x":"2nd meaning","t":"GRE trap: an indifferent cook = a mediocre one."},{"w":"indolent","p":"adj.","m":"Lazy.","e":"Late Latin <i>indolentem</i> (insensitive to pain): <i>in-</i> + <i>dolere</i> (to suffer).","f":"indolent, paresseux","t":"« Indolent »: too comfortable to move."},{"w":"lament","p":"v. / n.","m":"To mourn; express regret.","e":"Latin <i>lamentari</i>.","f":"se lamenter, déplorer","t":"Same as « lamentation »."},{"w":"laud","p":"v.","m":"To praise highly.","e":"Latin <i>laudare</i>.","f":"louer, encenser","t":"Laud = « louer »."},{"w":"negate","p":"v.","m":"To nullify; to deny.","e":"Latin <i>negare</i> (to deny).","f":"annuler, nier","t":"Negate = « nier », cancel out: one bad quarter can negate a year of growth."},{"w":"neophyte","p":"n.","m":"A beginner.","e":"Greek <i>neophytos</i> (newly planted): <i>neos</i> + <i>phyein</i>.","f":"néophyte, novice","t":"Same as « néophyte »."},{"w":"orthodox","p":"adj.","m":"Conforming to established beliefs.","e":"Greek <i>orthodoxos</i>: <i>orthos</i> (right) + <i>doxa</i> (opinion).","f":"orthodoxe","t":"Ortho (right, as in orthographe) + doxa (opinion): the correct, approved opinion."},{"w":"permeate","p":"v.","m":"To spread throughout.","e":"Latin <i>permeare</i> (to pass through).","f":"imprégner, pénétrer","t":"Permeable: seeping through everything."},{"w":"pervasive","p":"adj.","m":"Spreading widely throughout.","e":"Latin <i>pervadere</i> (to go through).","f":"omniprésent, envahissant","t":"Pervading everything."},{"w":"precursor","p":"n.","m":"Something that comes before and leads to another.","e":"Latin <i>praecursor</i> (forerunner): <i>prae</i> + <i>currere</i> (to run).","f":"précurseur","t":"Same as « précurseur »."},{"w":"proliferate","p":"v.","m":"To increase rapidly.","e":"French <i>prolifère</i>, Latin <i>proles</i> (offspring).","f":"proliférer","t":"Same as « proliférer »."},{"w":"propensity","p":"n.","m":"A natural tendency.","e":"Latin <i>propensus</i> (inclined), from <i>propendere</i> (to hang forward).","f":"propension","t":"Same as « propension »."},{"w":"rarefy","p":"v.","m":"To make thinner or more refined.","e":"Latin <i>rarefacere</i>: <i>rarus</i> (thin) + <i>facere</i>.","f":"raréfier","t":"« L’air raréfié » at altitude."},{"w":"recant","p":"v.","m":"To formally withdraw a belief.","e":"Latin <i>recantare</i> (to sing back, revoke).","f":"se rétracter, abjurer","t":"Galileo forced to recant."},{"w":"satirize","p":"v.","m":"To mock with humour or irony.","e":"Latin <i>satira</i> (a mixed dish, medley).","f":"satiriser, tourner en dérision","t":"« Satire »."},{"w":"scant","p":"adj.","m":"Barely sufficient.","e":"Old Norse <i>skamt</i> (short).","f":"insuffisant, maigre","t":"Scant evidence = « peu de preuves »."},{"w":"stigma","p":"n.","m":"A mark of disgrace.","e":"Greek <i>stigma</i> (mark made by a pointed tool, brand).","f":"stigmate, opprobre","t":"Branded: « stigmatiser »."},{"w":"subjugate","p":"v.","m":"To bring under domination.","e":"Latin <i>subiugare</i> (to put under the yoke, <i>iugum</i>).","f":"subjuguer, asservir","t":"Under the yoke (joug)."},{"w":"sublime","p":"adj.","m":"Of great beauty or excellence.","e":"Latin <i>sublimis</i> (lofty).","f":"sublime","t":"Same as « sublime »."},{"w":"subside","p":"v.","m":"To become less intense.","e":"Latin <i>subsidere</i> (to settle down).","f":"s’apaiser, se calmer","t":"The storm subsides, settles down."},{"w":"succinct","p":"adj.","m":"Brief and clearly expressed.","e":"Latin <i>succinctus</i> (girded up, tucked in).","f":"succinct","t":"Same as « succinct »."},{"w":"supersede","p":"v.","m":"To replace something older.","e":"Latin <i>supersedere</i> (to sit above).","f":"remplacer, supplanter","t":"Sitting above the old one."},{"w":"surmise","p":"v.","m":"To suppose without evidence.","e":"Old French <i>surmettre</i> (to accuse).","f":"conjecturer, supposer","t":"A guess put on top."},{"w":"table","p":"v.","m":"To postpone consideration (US); to propose (UK).","e":"Latin <i>tabula</i> (board).","f":"ajourner; mettre sur la table","x":"2nd meaning","t":"US: tabling = putting aside. UK: putting on the table."},{"w":"utilitarian","p":"adj.","m":"Designed to be useful rather than attractive.","e":"From utility, Latin <i>utilis</i>.","f":"utilitaire, fonctionnel","t":"« Utilitaire »."},{"w":"virtuoso","p":"n.","m":"A highly skilled person, especially in music.","e":"Italian <i>virtuoso</i> (skilled), Latin <i>virtus</i>.","f":"virtuose","t":"Same as « virtuose »."},{"w":"virulent","p":"adj.","m":"Extremely severe or hostile.","e":"Latin <i>virulentus</i>, from <i>virus</i> (poison).","f":"virulent","t":"Same as « virulent »."},{"w":"viscous","p":"adj.","m":"Thick and sticky.","e":"Latin <i>viscosus</i>, from <i>viscum</i> (birdlime, mistletoe).","f":"visqueux","t":"Same as « visqueux »."},{"w":"watershed","p":"n.","m":"A turning point.","e":"German <i>Wasserscheide</i> (water-parting): the ridge dividing river basins.","f":"tournant, moment décisif","t":"The ridge where water flows one way or the other."},{"w":"winnow","p":"v.","m":"To reduce a group by removing the least desirable.","e":"Old English <i>windwian</i> (to fan), from <i>wind</i>: blowing chaff from grain.","f":"trier, faire le tri","t":"Wind blowing chaff away: winnowing the shortlist."}]},{"name":"Basic IX","slug":"basic-ix","series":"Basic","words":[{"w":"abhor","p":"v.","m":"To regard with disgust.","e":"Latin <i>abhorrere</i> (to shrink back in horror): <i>ab</i> + <i>horrere</i> (to bristle).","f":"abhorrer, avoir en horreur","t":"« Avoir en horreur »: your hair bristles."},{"w":"abscond","p":"v.","m":"To leave secretly, often with stolen goods.","e":"Latin <i>abscondere</i> (to hide away).","f":"s’enfuir, décamper","t":"Same root as « abscons »: hiding away with the money."},{"w":"adhere","p":"v.","m":"To stick to; to follow a rule.","e":"Latin <i>adhaerere</i> (to stick to).","f":"adhérer, respecter","t":"Same as « adhérer »."},{"w":"aggregate","p":"n. / adj.","m":"A whole formed by combining elements; total.","e":"Latin <i>aggregare</i> (to add to a flock): <i>ad</i> + <i>grex</i>.","f":"ensemble, total, agrégat","t":"Adding to the flock (grex)."},{"w":"autonomous","p":"adj.","m":"Self-governing; independent.","e":"Greek <i>autonomos</i>.","f":"autonome","t":"Same as « autonome »."},{"w":"bastion","p":"n.","m":"A stronghold of a belief or quality.","e":"French <i>bastion</i>, Italian <i>bastione</i>, from <i>bastire</i> (to build).","f":"bastion","t":"Same as « bastion »."},{"w":"conciliatory","p":"adj.","m":"Intended to placate.","e":"Latin <i>conciliare</i> (to bring together).","f":"conciliant","t":"« Conciliant »."},{"w":"contention","p":"n.","m":"Heated disagreement; an assertion.","e":"Latin <i>contentio</i> (strife), from <i>contendere</i>.","f":"différend; affirmation","t":"Bone of contention = « pomme de discorde »."},{"w":"credulous","p":"adj.","m":"Too ready to believe.","e":"Latin <i>credulus</i>.","f":"crédule","t":"Same as « crédule »."},{"w":"deference","p":"n.","m":"Humble respect.","e":"French <i>déférence</i>.","f":"déférence","t":"Same as « déférence »."},{"w":"discretion","p":"n.","m":"Freedom to decide; also tact.","e":"Latin <i>discretio</i> (separation, discernment).","f":"discrétion; libre appréciation","t":"« À votre discrétion »."},{"w":"diverge","p":"v.","m":"To separate and go in different directions.","e":"Medieval Latin <i>divergere</i> (to incline apart).","f":"diverger","t":"Same as « diverger »."},{"w":"dogma","p":"n.","m":"Principles laid down as undeniably true.","e":"Greek <i>dogma</i> (opinion, decree).","f":"dogme","t":"Same as « dogme »."},{"w":"dour","p":"adj.","m":"Stern and gloomy.","e":"Scots, probably from Latin <i>durus</i> (hard).","f":"austère, sévère, renfrogné","t":"Hard (dur) and gloomy."},{"w":"egalitarian","p":"adj.","m":"Believing in equality.","e":"French <i>égalitaire</i>, from <i>égal</i>.","f":"égalitaire","t":"Liberté, égalité…"},{"w":"enigma","p":"n.","m":"A mysterious person or thing.","e":"Greek <i>ainigma</i> (riddle).","f":"énigme","t":"Same as « énigme »."},{"w":"facade","p":"n.","m":"A deceptive outward appearance.","e":"French <i>façade</i>, from Italian <i>facciata</i>, <i>faccia</i> (face).","f":"façade","t":"Same as « façade »."},{"w":"implore","p":"v.","m":"To beg urgently.","e":"Latin <i>implorare</i>: <i>in</i> + <i>plorare</i> (to weep).","f":"implorer","t":"Weeping (pleurer) while begging."},{"w":"inert","p":"adj.","m":"Lacking ability or will to move.","e":"Latin <i>iners</i> (unskilled, idle): <i>in-</i> + <i>ars</i>.","f":"inerte","t":"Same as « inerte »."},{"w":"inherent","p":"adj.","m":"Existing as a permanent, essential attribute.","e":"Latin <i>inhaerere</i> (to stick in).","f":"inhérent","t":"Same as « inhérent »."},{"w":"insular","p":"adj.","m":"Narrow-minded; isolated.","e":"Latin <i>insula</i> (island).","f":"insulaire, fermé","t":"Island mentality."},{"w":"judicious","p":"adj.","m":"Having good judgment.","e":"French <i>judicieux</i>, Latin <i>iudicium</i>.","f":"judicieux","t":"Same as « judicieux »."},{"w":"levity","p":"n.","m":"Humour or lack of seriousness.","e":"Latin <i>levitas</i> (lightness), <i>levis</i>.","f":"légèreté","t":"Lightness: « légèreté »."},{"w":"luminous","p":"adj.","m":"Full of light; very clear.","e":"Latin <i>luminosus</i>, from <i>lumen</i>.","f":"lumineux","t":"Same as « lumineux »."},{"w":"naive","p":"adj.","m":"Lacking experience or judgment.","e":"French <i>naïve</i>, Latin <i>nativus</i> (native, natural).","f":"naïf","t":"Same as « naïf »."},{"w":"notoriety","p":"n.","m":"Fame for something bad.","e":"Medieval Latin <i>notorietas</i>, from <i>notus</i> (known).","f":"mauvaise réputation","x":"Faux ami","t":"French « notoriété » is neutral; English notoriety is bad fame."},{"w":"opine","p":"v.","m":"To state an opinion.","e":"Latin <i>opinari</i>.","f":"opiner, déclarer","t":"« Opiner »."},{"w":"oscillate","p":"v.","m":"To swing back and forth; to waver.","e":"Latin <i>oscillare</i> (to swing).","f":"osciller","t":"Same as « osciller »."},{"w":"painstaking","p":"adj.","m":"Done with great care.","e":"English <i>pains</i> + <i>taking</i>: taking pains.","f":"minutieux","t":"Taking pains over every detail."},{"w":"penchant","p":"n.","m":"A strong liking.","e":"French <i>penchant</i>, from <i>pencher</i> (to lean).","f":"penchant","t":"Same as « penchant »."},{"w":"pious","p":"adj.","m":"Devoutly religious; sometimes hypocritically virtuous.","e":"Latin <i>pius</i> (dutiful).","f":"pieux","t":"« Pieux »."},{"w":"plastic","p":"adj.","m":"Easily shaped; adaptable.","e":"Greek <i>plastikos</i> (fit for moulding), from <i>plassein</i>.","f":"malléable, plastique","x":"2nd meaning","t":"Neuroplasticity: the brain reshaping."},{"w":"plummet","p":"v.","m":"To fall straight down rapidly.","e":"Old French <i>plommet</i> (plumb line weight), from <i>plomb</i> (lead).","f":"chuter, s’effondrer","t":"Falling like lead (plomb)."},{"w":"prudent","p":"adj.","m":"Acting with care for the future.","e":"Latin <i>prudens</i> (foreseeing).","f":"prudent","t":"Same as « prudent »."},{"w":"rhetoric","p":"n.","m":"Persuasive language, often insincere.","e":"Greek <i>rhētorikē</i>, art of the orator (<i>rhētōr</i>).","f":"rhétorique","t":"Same as « rhétorique »."},{"w":"savor","p":"v.","m":"To enjoy fully.","e":"Old French <i>savourer</i>, Latin <i>sapor</i> (taste).","f":"savourer","t":"Same as « savourer »."},{"w":"secrete","p":"v.","m":"To produce and discharge; also to hide.","e":"Latin <i>secernere</i> (to separate).","f":"sécréter; cacher","x":"2nd meaning","t":"Hide like a secret."},{"w":"sentient","p":"adj.","m":"Able to perceive or feel.","e":"Latin <i>sentiens</i>, from <i>sentire</i>.","f":"sensible, doué de sensibilité","t":"Feeling (sentir)."},{"w":"shard","p":"n.","m":"A broken piece of pottery or glass.","e":"Old English <i>sceard</i> (cleft). Germanic.","f":"éclat, tesson","t":"A shard is a sharp broken piece, « un tesson » of glass or pottery."},{"w":"skeptic","p":"n.","m":"A person inclined to doubt.","e":"Greek <i>skeptikos</i> (inquiring).","f":"sceptique","t":"Same as « sceptique »."},{"w":"slight","p":"v. / n.","m":"To insult by ignoring; an insult.","e":"Old Norse <i>sléttr</i> (smooth, level).","f":"offenser, snober; affront","x":"2nd meaning","t":"To treat as slight (unimportant)."},{"w":"stint","p":"n. / v.","m":"A period of work; to be sparing.","e":"Old English <i>styntan</i> (to blunt, dull).","f":"période, passage; lésiner","t":"A stint at Bain; don’t stint on effort."},{"w":"striated","p":"adj.","m":"Marked with lines or grooves.","e":"Latin <i>striatus</i>, from <i>stria</i> (furrow).","f":"strié","t":"Same as « strié »."},{"w":"substantiate","p":"v.","m":"To provide evidence for.","e":"Latin <i>substantia</i> (substance).","f":"étayer, prouver","t":"Give substance to a claim: « étayer » it with evidence."},{"w":"terse","p":"adj.","m":"Brief to the point of rudeness.","e":"Latin <i>tersus</i> (wiped clean, neat).","f":"laconique, sec","t":"Wiped clean of extra words."},{"w":"ubiquitous","p":"adj.","m":"Present everywhere.","e":"Latin <i>ubique</i> (everywhere).","f":"omniprésent, ubiquitaire","t":"« Ubiquité »."},{"w":"unfettered","p":"adj.","m":"Free, unrestricted.","e":"<i>un-</i> + fetter (chain), Old English <i>feter</i>.","f":"sans entraves","t":"Fetters = chains on the feet. Unfettered = chains off: unfettered capitalism."},{"w":"viable","p":"adj.","m":"Capable of working successfully.","e":"French <i>viable</i>, from <i>vie</i>.","f":"viable","t":"Same as « viable »."},{"w":"yoke","p":"n. / v.","m":"A bond or burden; to join together.","e":"Old English <i>geoc</i>, cousin of Latin <i>iugum</i>.","f":"joug","t":"« Le joug »."},{"w":"zeal","p":"n.","m":"Great energy for a cause.","e":"Greek <i>zēlos</i>.","f":"zèle","t":"Same as « zèle »."}]},{"name":"Advanced I","slug":"advanced-i","series":"Advanced","words":[{"w":"alacrity","p":"n.","m":"Brisk and cheerful readiness.","e":"Latin <i>alacritas</i>, from <i>alacer</i> (lively, eager), which gave French <i>allègre</i>.","f":"empressement, entrain","t":"Alacer → « allègre »: accepting with alacrity = « avec empressement »."},{"w":"anathema","p":"n.","m":"Something or someone vehemently disliked.","e":"Greek <i>anathema</i> (thing devoted to evil, accursed). The Church’s formal curse and excommunication.","f":"anathème, bête noire","t":"« Jeter l’anathème »: cursed by the Church. Lying is anathema to her."},{"w":"apogee","p":"n.","m":"The highest point; climax.","e":"Greek <i>apogaion</i> (away from the earth): <i>apo</i> + <i>gē</i>. A moon’s farthest point from Earth.","f":"apogée","t":"Same as « apogée »."},{"w":"apostate","p":"n.","m":"A person who renounces a belief or party.","e":"Greek <i>apostatēs</i> (deserter): <i>apo</i> (away) + <i>histanai</i> (to stand).","f":"apostat, renégat","t":"Standing away from the faith: « apostat »."},{"w":"arrant","p":"adj.","m":"Complete, utter (arrant nonsense).","e":"Variant of <i>errant</i> (wandering): an “arrant thief” was a roving outlaw; then just “notorious, utter”.","f":"fieffé, pur, total","t":"Arrant nonsense = « une pure absurdité ». « Un fieffé menteur »."},{"w":"artless","p":"adj.","m":"Without guile; natural and simple.","e":"<i>art</i> (skill, artifice) + <i>-less</i>.","f":"naturel, ingénu","t":"No artifice: opposite of artful (Common I)."},{"w":"attenuate","p":"v.","m":"To reduce the force or effect of.","e":"Latin <i>attenuare</i> (to make thin): <i>ad</i> + <i>tenuis</i>.","f":"atténuer","t":"Same as « atténuer »."},{"w":"base","p":"adj.","m":"Without moral principles; ignoble.","e":"Late Latin <i>bassus</i> (low).","f":"bas, vil, ignoble","x":"2nd meaning","t":"Low (« bas »): base motives. Base metals vs noble ones."},{"w":"beg","p":"v.","m":"To evade (beg the question = assume what is to be proved).","e":"Middle English <i>beggen</i>; “beg the question” translates Latin <i>petitio principii</i>.","f":"éluder; pétition de principe","x":"2nd meaning","t":"Begging the question = « une pétition de principe »: circular logic."},{"w":"byzantine","p":"adj.","m":"Excessively complicated; devious.","e":"From Byzantium, whose imperial court was famous for complex intrigue and bureaucracy.","f":"byzantin, alambiqué","t":"« Des querelles byzantines »: the labyrinthine Byzantine court."},{"w":"catholic","p":"adj.","m":"Wide-ranging; universal (lower-case c).","e":"Greek <i>katholikos</i> (universal): <i>kata</i> + <i>holos</i> (whole).","f":"éclectique, universel","x":"2nd meaning","t":"Catholic tastes = eclectic, covering the whole (holos)."},{"w":"chary","p":"adj.","m":"Cautiously reluctant.","e":"Old English <i>cearig</i> (sorrowful, careful), from <i>caru</i> (care).","f":"méfiant, réticent, prudent","t":"Chary = full of care, cautious: chary of giving out his number."},{"w":"choleric","p":"adj.","m":"Bad-tempered, irritable.","e":"Greek <i>kholērikos</i>, from <i>kholē</i> (yellow bile), the humour of anger.","f":"colérique","t":"Yellow bile → « colère »."},{"w":"churlish","p":"adj.","m":"Rude and mean-spirited.","e":"Old English <i>ceorl</i> (peasant, low-born man).","f":"grossier, mal élevé","t":"Behaving like a churl (lowly peasant): churlish to refuse."},{"w":"conciliate","p":"v.","m":"To placate; to win over.","e":"Latin <i>conciliare</i> (to bring together).","f":"concilier, apaiser","t":"Same as « concilier »."},{"w":"contentious","p":"adj.","m":"Causing or likely to cause argument.","e":"Latin <i>contentiosus</i>, from <i>contentio</i> (strife).","f":"controversé, litigieux","t":"« Contentieux »: a dispute."},{"w":"cow","p":"v.","m":"To intimidate into submission.","e":"Probably Old Norse <i>kúga</i> (to oppress).","f":"intimider, terroriser","x":"2nd meaning","t":"Cowed into silence: made meek as a cow."},{"w":"defray","p":"v.","m":"To pay costs.","e":"French <i>défrayer</i>: <i>de</i> + <i>frai</i> (expense).","f":"défrayer","t":"Same as « défrayer »: travel costs defrayed."},{"w":"diatribe","p":"n.","m":"A bitter verbal attack.","e":"Greek <i>diatribē</i> (pastime, discourse), from <i>diatribein</i> (to wear away).","f":"diatribe","t":"Same as « diatribe »."},{"w":"equivocate","p":"v.","m":"To use ambiguous language to conceal the truth.","e":"Late Latin <i>aequivocare</i> (to call by the same name).","f":"tergiverser, user d’équivoques","t":"Speaking with two equal voices."},{"w":"exegesis","p":"n.","m":"Critical explanation of a text.","e":"Greek <i>exēgēsis</i> (explanation): <i>ex</i> + <i>hēgeisthai</i> (to lead).","f":"exégèse","t":"Same as « exégèse »."},{"w":"expansive","p":"adj.","m":"Open and communicative; extensive.","e":"Latin <i>expandere</i> (to spread out).","f":"expansif, communicatif","t":"Same as « expansif »."},{"w":"expunge","p":"v.","m":"To erase completely.","e":"Latin <i>expungere</i> (to prick out). Scribes marked deletions with dots.","f":"effacer, supprimer","t":"Dots pricked under deleted words."},{"w":"factious","p":"adj.","m":"Inclined to dissension.","e":"Latin <i>factiosus</i>, from <i>factio</i> (party, faction).","f":"factieux","t":"Same as « factieux ». Not factitious (artificial)."},{"w":"feckless","p":"adj.","m":"Lacking initiative; irresponsible.","e":"Scots <i>feck</i> (effect, value), short for effect + <i>-less</i>.","f":"incapable, irresponsable","t":"Feck = effect. Feckless = without effect: the feckless flatmate who never pays his share."},{"w":"fractious","p":"adj.","m":"Irritable and quarrelsome; hard to control.","e":"From fraction in the old sense “discord”, Latin <i>frangere</i> (to break).","f":"rétif, querelleur","t":"Breaking into factions: a fractious coalition."},{"w":"hector","p":"v.","m":"To bully, talk to in an intimidating way.","e":"From Hector of Troy; in 17th-c. London, “Hectors” were swaggering street bullies.","f":"rudoyer, malmener","t":"Hector of Troy: in 17th-century London, “hectors” were swaggering street bullies."},{"w":"imbibe","p":"v.","m":"To drink; to absorb ideas.","e":"Latin <i>imbibere</i>: <i>in</i> + <i>bibere</i> (to drink).","f":"boire; s’imprégner de","t":"« Imbiber », « biberon »."},{"w":"indigent","p":"adj.","m":"Poor, needy.","e":"Latin <i>indigentem</i> (in need).","f":"indigent","t":"Same as « indigent »."},{"w":"insufferable","p":"adj.","m":"Too extreme to bear.","e":"<i>in-</i> + Latin <i>sufferre</i> (to endure).","f":"insupportable","t":"In + suffer: someone you cannot suffer (endure): « insupportable »."},{"w":"jingoist","p":"n.","m":"An aggressive nationalist.","e":"From the 1878 music-hall song “by Jingo”.","f":"chauvin, nationaliste belliqueux","t":"The Victorian music-hall crowd singing for war."},{"w":"kowtow","p":"v.","m":"To act in an excessively subservient way.","e":"Chinese <i>kòutóu</i> (knock head): touching the forehead to the ground before the emperor.","f":"se prosterner, courber l’échine","t":"Forehead on the floor before the emperor."},{"w":"lascivious","p":"adj.","m":"Feeling or showing overt sexual desire.","e":"Latin <i>lascivia</i> (playfulness, wantonness).","f":"lascif","t":"Same as « lascif »."},{"w":"malfeasance","p":"n.","m":"Wrongdoing, especially by a public official.","e":"Anglo-French <i>malfaisance</i>: <i>mal</i> + <i>faire</i>.","f":"malversation, prévarication","t":"« Malfaisance »: doing evil."},{"w":"nadir","p":"n.","m":"The lowest point.","e":"Arabic <i>naẓīr</i> (opposite), i.e. the point opposite the zenith.","f":"nadir, point le plus bas","t":"Nadir = the point right under your feet, opposite the zenith above your head."},{"w":"overweening","p":"adj.","m":"Showing excessive confidence or pride.","e":"<i>over</i> + <i>ween</i> (to think, Old English <i>wēnan</i>). Thinking too much of oneself.","f":"outrecuidant, démesuré","t":"Over-thinking of yourself: overweening ambition."},{"w":"pariah","p":"n.","m":"An outcast.","e":"Tamil <i>paraiyar</i>, drummers at festivals, a caste treated as outcasts in colonial India.","f":"paria","t":"Same as « paria »."},{"w":"penurious","p":"adj.","m":"Extremely poor; also stingy.","e":"Latin <i>penuria</i> (want, scarcity).","f":"misérable; avare","t":"« Pénurie »."},{"w":"perfunctory","p":"adj.","m":"Done with minimum effort.","e":"Late Latin <i>perfunctorius</i> (careless), from <i>perfungi</i> (to get through, discharge).","f":"de pure forme, superficiel","t":"Just getting it done: a perfunctory nod."},{"w":"ponderous","p":"adj.","m":"Slow and clumsy because heavy; dull.","e":"Latin <i>ponderosus</i>, from <i>pondus</i> (weight).","f":"lourd, pesant","t":"Weighty (pondéré): ponderous prose."},{"w":"precipitate","p":"v. / adj.","m":"To cause to happen suddenly; hasty.","e":"Latin <i>praecipitare</i> (to throw headlong).","f":"précipiter; précipité","t":"Same as « précipiter »."},{"w":"prosaic","p":"adj.","m":"Lacking imagination; ordinary.","e":"Late Latin <i>prosaicus</i>, from <i>prosa</i> (prose).","f":"prosaïque","t":"Same as « prosaïque »."},{"w":"saturnine","p":"adj.","m":"Gloomy, slow and serious.","e":"From Saturn, the planet said by astrologers to make people gloomy.","f":"sombre, taciturne","t":"Opposite of jovial (Jupiter)."},{"w":"sedulous","p":"adj.","m":"Showing dedication and diligence.","e":"Latin <i>sedulus</i> (zealous), perhaps <i>se dolo</i> (without guile).","f":"assidu, appliqué","t":"Sedulous ≈ assiduous: steady, careful, persevering work."},{"w":"supercilious","p":"adj.","m":"Behaving as if superior; haughty.","e":"Latin <i>supercilium</i> (eyebrow): raising the eyebrow in disdain.","f":"hautain, dédaigneux","t":"Raised eyebrows (sourcils)."},{"w":"truculent","p":"adj.","m":"Eager to argue or fight.","e":"Latin <i>truculentus</i> (fierce), from <i>trux</i> (savage).","f":"agressif, belliqueux (≠ truculent)","x":"Faux ami","t":"French « truculent » = colourful. English = aggressive."},{"w":"turpitude","p":"n.","m":"Depravity, wickedness.","e":"Latin <i>turpitudo</i>, from <i>turpis</i> (base, shameful).","f":"turpitude","t":"Same as « turpitude »."},{"w":"untoward","p":"adj.","m":"Unexpected and inappropriate.","e":"<i>un-</i> + toward (promising, docile).","f":"fâcheux, malencontreux","t":"Nothing untoward = « rien d’anormal »."},{"w":"vicissitude","p":"n.","m":"A change of circumstances, usually unwelcome.","e":"Latin <i>vicissitudo</i>, from <i>vicis</i> (change).","f":"vicissitude","t":"« Les vicissitudes de la vie »."},{"w":"zeitgeist","p":"n.","m":"The spirit of the time.","e":"German <i>Zeitgeist</i>: <i>Zeit</i> (time) + <i>Geist</i> (spirit).","f":"air du temps","t":"« L’air du temps »."}]},{"name":"Advanced II","slug":"advanced-ii","series":"Advanced","words":[{"w":"apotheosis","p":"n.","m":"The highest point; perfect example; deification.","e":"Greek <i>apotheōsis</i>: <i>apo</i> + <i>theos</i> (god). Making someone a god.","f":"apothéose","t":"Same as « apothéose »."},{"w":"arch","p":"adj.","m":"Deliberately playful or teasing; also chief.","e":"Greek <i>arkhi-</i> (chief), from <i>arkhein</i> (to rule). From “arch-rogue” it came to mean mischievous.","f":"malicieux, espiègle; principal","x":"2nd meaning","t":"An arch smile = « un sourire malicieux »."},{"w":"arriviste","p":"n.","m":"An ambitious, self-seeking newcomer.","e":"French <i>arriviste</i>, from <i>arriver</i>.","f":"arriviste","t":"Straight from French."},{"w":"benighted","p":"adj.","m":"Ignorant, unenlightened.","e":"<i>be-</i> + night: overtaken by darkness.","f":"ignorant, obscurantiste","t":"Be + night: overtaken by the night of ignorance. « Obscurantiste »."},{"w":"bilious","p":"adj.","m":"Bad-tempered; nauseous.","e":"Latin <i>biliosus</i>, from <i>bilis</i> (bile).","f":"bilieux, irritable","t":"« Se faire de la bile »."},{"w":"blinkered","p":"adj.","m":"Having a narrow outlook.","e":"From blinkers, eye shields on a horse’s bridle.","f":"borné, qui a des œillères","t":"« Avoir des œillères »."},{"w":"cupidity","p":"n.","m":"Greed for money.","e":"Latin <i>cupiditas</i> (desire), from <i>cupere</i>; Cupid.","f":"cupidité","t":"Same as « cupidité »."},{"w":"curmudgeon","p":"n.","m":"A bad-tempered, surly person.","e":"Origin unknown (16th c.).","f":"grincheux, vieux ronchon","t":"Sounds grumpy: the curmudgeonly neighbour."},{"w":"disabuse","p":"v.","m":"To free someone from a mistaken idea.","e":"<i>dis-</i> + abuse (deceive), after French <i>désabuser</i>.","f":"détromper","t":"« Désabuser »."},{"w":"excoriate","p":"v.","m":"To criticise severely.","e":"Latin <i>excoriare</i> (to strip the skin): <i>ex</i> + <i>corium</i> (hide).","f":"fustiger, éreinter","t":"Stripping the skin off: « écorcher »."},{"w":"execrate","p":"v.","m":"To feel or express great loathing.","e":"Latin <i>exsecrari</i> (to curse): <i>ex</i> + <i>sacer</i>.","f":"exécrer","t":"Same as « exécrer »."},{"w":"expurgate","p":"v.","m":"To remove objectionable parts of a text.","e":"Latin <i>expurgare</i> (to purge).","f":"expurger","t":"Same as « expurger »."},{"w":"factitious","p":"adj.","m":"Artificial, contrived.","e":"Latin <i>facticius</i> (made by art), from <i>facere</i>.","f":"factice","t":"« Factice ». Not factious."},{"w":"fell","p":"adj. / v.","m":"Fierce, deadly; to cut down.","e":"Old French <i>fel</i> (wicked), from which French <i>félon</i>.","f":"cruel, funeste; abattre","x":"2nd meaning","t":"In one fell swoop: « d’un seul coup funeste »."},{"w":"gerrymander","p":"v.","m":"To manipulate electoral boundaries.","e":"Governor Elbridge Gerry + salamander: an 1812 Massachusetts district shaped like a salamander.","f":"charcutage électoral","t":"Gerry + salamander: a voting district drawn in a ridiculous shape to win."},{"w":"hedge","p":"v.","m":"To avoid committing oneself; to limit risk.","e":"Old English <i>hecg</i> (fence).","f":"rester évasif; se couvrir","x":"2nd meaning","t":"Fence yourself in: hedge your bets."},{"w":"histrionic","p":"adj.","m":"Overly theatrical or melodramatic.","e":"Latin <i>histrio</i> (actor).","f":"théâtral, cabotin","t":"Histrio = actor: « histrionique »."},{"w":"imbroglio","p":"n.","m":"A complicated, embarrassing situation.","e":"Italian <i>imbroglio</i>, from <i>imbrogliare</i> (to tangle).","f":"imbroglio","t":"Same as « imbroglio »."},{"w":"impecunious","p":"adj.","m":"Having little or no money.","e":"<i>in-</i> + Latin <i>pecunia</i> (money), from <i>pecus</i> (cattle).","f":"impécunieux, sans le sou","t":"In + pecunia (pécuniaire): no money at all."},{"w":"invective","p":"n.","m":"Insulting, abusive language.","e":"Latin <i>invehi</i> (to attack with words).","f":"invective","t":"Same as « invectives »."},{"w":"jaundiced","p":"adj.","m":"Bitter or resentful; cynical.","e":"Old French <i>jaunisse</i>, from <i>jaune</i>: yellow-skinned illness thought to make you see everything yellow.","f":"aigri, désabusé","t":"Seeing everything yellow (jaune)."},{"w":"jejune","p":"adj.","m":"Naive and simplistic; dull.","e":"Latin <i>ieiunus</i> (fasting, barren), which gave French <i>jeûne</i>.","f":"naïf, puéril; insipide","t":"Fasting (jeûne): empty, unnourishing ideas. Not « jeune », but you may think childish."},{"w":"juggernaut","p":"n.","m":"A huge, unstoppable force.","e":"Hindi <i>Jagannāth</i> (lord of the world), whose huge temple chariot was said to crush devotees.","f":"rouleau compresseur","t":"Jagannath’s giant temple chariot that nothing could stop."},{"w":"limpid","p":"adj.","m":"Clear, transparent.","e":"Latin <i>limpidus</i>.","f":"limpide","t":"Same as « limpide »."},{"w":"malapropism","p":"n.","m":"The mistaken use of a similar-sounding word.","e":"From Mrs Malaprop in Sheridan’s <i>The Rivals</i> (1775), from French <i>mal à propos</i>.","f":"lapsus, impropriété","t":"« Mal à propos »."},{"w":"martinet","p":"n.","m":"A strict disciplinarian.","e":"From Jean Martinet, a 17th-century French drillmaster under Louis XIV.","f":"tyran, adjudant","t":"Colonel Martinet drilling soldiers (and the whip, « martinet »)."},{"w":"maudlin","p":"adj.","m":"Self-pityingly or tearfully sentimental.","e":"From Mary Magdalene (Maudlin), painted weeping.","f":"larmoyant, sentimental","t":"Maudlin comes from Mary Magdalene, always painted weeping: tearful and self-pitying."},{"w":"mellifluous","p":"adj.","m":"Sweet and smooth-sounding.","e":"Latin <i>mel</i> (honey) + <i>fluere</i> (to flow).","f":"mélodieux, suave","t":"Mel (miel) + fluere: words flowing like honey."},{"w":"mettlesome","p":"adj.","m":"Spirited, courageous.","e":"From <i>mettle</i>, variant of metal.","f":"fougueux, courageux","t":"Mettle (metal): showing what you’re made of. Spirited, brave."},{"w":"mulct","p":"v.","m":"To extract money by fine or deception.","e":"Latin <i>mulcta</i> (a fine).","f":"escroquer, mettre à l’amende","t":"« Une amende »: mulcted of savings."},{"w":"palimpsest","p":"n.","m":"Something reused but with traces of its earlier form.","e":"Greek <i>palimpsēstos</i> (scraped again): manuscripts scraped and rewritten.","f":"palimpseste","t":"Same as « palimpseste »."},{"w":"parvenu","p":"n.","m":"A newly rich person seen as lacking refinement.","e":"French <i>parvenu</i> (arrived).","f":"parvenu","t":"Straight from French."},{"w":"peremptory","p":"adj.","m":"Insisting on immediate obedience; brusque.","e":"Latin <i>peremptorius</i> (decisive, destructive), from <i>perimere</i> (to destroy).","f":"péremptoire","t":"Same as « péremptoire »."},{"w":"phantasmagorical","p":"adj.","m":"Dreamlike; bizarrely changing.","e":"French <i>fantasmagorie</i> (1802), a magic-lantern ghost show; Greek <i>phantasma</i>.","f":"fantasmagorique","t":"The magic-lantern ghost shows in Paris."},{"w":"picayune","p":"adj.","m":"Petty; of little value.","e":"Louisiana French <i>picaillon</i> (small coin).","f":"insignifiant, mesquin","t":"A picayune was a tiny Louisiana coin: picayune details are worth almost nothing."},{"w":"Pollyannaish","p":"adj.","m":"Unreasonably or illogically optimistic.","e":"From Pollyanna, heroine of Eleanor H. Porter’s 1913 novel who always finds something to be glad about.","f":"d’un optimisme béat","t":"Pollyanna’s “glad game”: always looking on the bright side."},{"w":"propitiate","p":"v.","m":"To win the favour of; appease.","e":"Latin <i>propitiare</i>, from <i>propitius</i> (favourable).","f":"apaiser, se concilier","t":"Making the gods « propices »."},{"w":"protean","p":"adj.","m":"Able to change frequently; versatile.","e":"From Proteus, the Greek sea god who could change shape.","f":"protéiforme","t":"Proteus, the sea god who changed shape to escape capture: endlessly versatile."},{"w":"pyrrhic","p":"adj.","m":"(Of a victory) won at too great a cost.","e":"After King Pyrrhus of Epirus, who beat Rome in 279 BC but lost most of his army.","f":"à la Pyrrhus","t":"« Une victoire à la Pyrrhus »."},{"w":"quisling","p":"n.","m":"A traitor who collaborates with an occupier.","e":"Vidkun Quisling, who led Norway’s Nazi-collaborating government.","f":"collabo, traître","t":"Vidkun Quisling, who governed Norway for the Nazis: the archetype of the traitor."},{"w":"quixotic","p":"adj.","m":"Idealistic and impractical.","e":"From Don Quixote, Cervantes’ knight tilting at windmills.","f":"chimérique, donquichottesque","t":"Don Quixote attacking windmills: noble but hopelessly impractical."},{"w":"remonstrate","p":"v.","m":"To protest.","e":"Medieval Latin <i>remonstrare</i> (to demonstrate).","f":"protester, faire des remontrances","t":"« Faire des remontrances »."},{"w":"sangfroid","p":"n.","m":"Composure under pressure.","e":"French <i>sang-froid</i> (cold blood).","f":"sang-froid","t":"Straight from French."},{"w":"sartorial","p":"adj.","m":"Relating to clothing or tailoring.","e":"Latin <i>sartor</i> (tailor), from <i>sarcire</i> (to patch).","f":"vestimentaire","t":"Sartor = tailor: sartorial elegance = how well you dress."},{"w":"schadenfreude","p":"n.","m":"Pleasure at another’s misfortune.","e":"German <i>Schaden</i> (harm) + <i>Freude</i> (joy).","f":"joie malsaine","t":"Schaden (harm) + Freude (joy): the private smile when a rival’s deal falls through."},{"w":"sententious","p":"adj.","m":"Given to pompous moralising.","e":"Latin <i>sententiosus</i> (full of meaning), from <i>sententia</i> (opinion, maxim).","f":"sentencieux","t":"Same as « sentencieux »."},{"w":"sybarite","p":"n.","m":"A person devoted to luxury.","e":"From Sybaris, a Greek city in southern Italy famous for luxury.","f":"sybarite","t":"Same as « sybarite »."},{"w":"tendentious","p":"adj.","m":"Promoting a particular cause; biased.","e":"German <i>tendenziös</i>, from Latin <i>tendere</i>.","f":"tendancieux","t":"Same as « tendancieux »."},{"w":"venial","p":"adj.","m":"(Of a sin) forgivable.","e":"Latin <i>venialis</i>, from <i>venia</i> (forgiveness).","f":"véniel","t":"« Péché véniel »."},{"w":"vituperate","p":"v.","m":"To blame or insult abusively.","e":"Latin <i>vituperare</i> (to censure).","f":"vitupérer","t":"Same as « vitupérer »."}]},{"name":"Advanced III","slug":"advanced-iii","series":"Advanced","words":[{"w":"anemic","p":"adj.","m":"Lacking energy or vigour; weak.","e":"Greek <i>anaimia</i>: <i>an-</i> + <i>haima</i> (blood).","f":"anémique, faible","t":"An + haima = no blood: anemic growth is pale and weak."},{"w":"anodyne","p":"adj.","m":"Inoffensive, bland; (n.) a painkiller.","e":"Greek <i>anōdynos</i> (painless): <i>an-</i> + <i>odynē</i> (pain).","f":"anodin, fade","t":"Same as « anodin »: harmless and bland."},{"w":"approbatory","p":"adj.","m":"Expressing approval.","e":"Latin <i>approbare</i> (to approve).","f":"approbateur","t":"« Approbation »."},{"w":"artlessness","p":"n.","m":"Simplicity; lack of guile.","e":"<i>art</i> (artifice) + <i>-less</i> + <i>-ness</i>.","f":"naturel, ingénuité","t":"No artifice at all: childlike, natural simplicity."},{"w":"bowdlerize","p":"v.","m":"To remove indecent parts from a text.","e":"From Thomas Bowdler, who published a censored “Family Shakespeare” in 1818.","f":"expurger","t":"Bowdler’s prudish Shakespeare."},{"w":"cede","p":"v.","m":"To give up power or territory.","e":"Latin <i>cedere</i> (to yield).","f":"céder","t":"Same as « céder »."},{"w":"charlatan","p":"n.","m":"A person falsely claiming expertise.","e":"Italian <i>ciarlatano</i> (quack), from <i>ciarlare</i> (to chatter).","f":"charlatan","t":"Same as « charlatan »."},{"w":"derelict","p":"adj.","m":"Abandoned and dilapidated; negligent.","e":"Latin <i>derelictus</i> (abandoned).","f":"à l’abandon; négligent","t":"Abandoned (déréliction). Derelict in duty = négligent."},{"w":"duplicity","p":"n.","m":"Deceitfulness, double-dealing.","e":"Latin <i>duplicitas</i> (doubleness).","f":"duplicité","t":"Same as « duplicité »: double face."},{"w":"effrontery","p":"n.","m":"Insolent boldness.","e":"French <i>effronterie</i>, from <i>effronté</i> (without a forehead to blush).","f":"effronterie, culot","t":"« Effronterie »."},{"w":"enjoin","p":"v.","m":"To instruct or urge; to prohibit (legal).","e":"Old French <i>enjoindre</i>, Latin <i>iniungere</i>.","f":"enjoindre","t":"Same as « enjoindre »."},{"w":"enthrall","p":"v.","m":"To captivate.","e":"<i>en-</i> + thrall (slave, Old Norse <i>þræll</i>).","f":"captiver, subjuguer","t":"Make a slave of: totally captivated."},{"w":"epiphany","p":"n.","m":"A sudden realisation.","e":"Greek <i>epiphaneia</i> (manifestation). Also the Christian feast (Épiphanie).","f":"révélation, illumination","t":"La galette des rois: Épiphanie. A sudden revelation."},{"w":"flummox","p":"v.","m":"To bewilder completely.","e":"19th-century English dialect, origin unknown.","f":"déconcerter, laisser perplexe","t":"A funny word for a funny feeling."},{"w":"gaffe","p":"n.","m":"An embarrassing blunder.","e":"French <i>gaffe</i> (boat hook; blunder).","f":"gaffe","t":"Straight from French."},{"w":"grandiloquent","p":"adj.","m":"Pompous or extravagant in language.","e":"Latin <i>grandiloquus</i>: <i>grandis</i> + <i>loqui</i>.","f":"grandiloquent","t":"Same as « grandiloquent »."},{"w":"hagiographic","p":"adj.","m":"Excessively flattering in describing someone.","e":"Greek <i>hagios</i> (holy) + <i>graphein</i>: writing saints’ lives.","f":"hagiographique","t":"Writing about someone as if they were a saint."},{"w":"hail","p":"v.","m":"To acclaim enthusiastically; to come from.","e":"Old Norse <i>heill</i> (healthy): a greeting.","f":"acclamer, saluer; être originaire de","x":"2nd meaning","t":"Hailed as a genius; she hails from Paris."},{"w":"illustrious","p":"adj.","m":"Famous and admired.","e":"Latin <i>illustris</i> (bright, distinguished).","f":"illustre","t":"Same as « illustre »."},{"w":"importune","p":"v.","m":"To harass with persistent requests.","e":"Latin <i>importunus</i> (unfit, troublesome).","f":"importuner","t":"Same as « importuner »."},{"w":"impute","p":"v.","m":"To attribute (a fault) to someone.","e":"Latin <i>imputare</i> (to reckon in).","f":"imputer","t":"Same as « imputer »."},{"w":"insouciance","p":"n.","m":"Casual lack of concern.","e":"French <i>insouciance</i>.","f":"insouciance","t":"Straight from French."},{"w":"lampoon","p":"v. / n.","m":"To ridicule publicly; a satire.","e":"French <i>lampon</i>, from <i>lampons</i> (let’s drink), a refrain in drinking songs.","f":"tourner en dérision; satire","t":"Mocking drinking songs: « lampons! »"},{"w":"litany","p":"n.","m":"A tedious recital or long list.","e":"Greek <i>litaneia</i> (prayer).","f":"litanie","t":"« Une litanie de plaintes »."},{"w":"lugubrious","p":"adj.","m":"Looking or sounding sad and dismal.","e":"Latin <i>lugubris</i>, from <i>lugere</i> (to mourn).","f":"lugubre","t":"Same as « lugubre »."},{"w":"maunder","p":"v.","m":"To talk or wander in a rambling way.","e":"Perhaps from obsolete <i>maund</i> (to beg).","f":"divaguer, radoter","t":"Meander + wander while talking."},{"w":"mordant","p":"adj.","m":"Sharply sarcastic.","e":"French <i>mordant</i> (biting), from <i>mordre</i>.","f":"mordant","t":"Same as « mordant »."},{"w":"moribund","p":"adj.","m":"At the point of death; in decline.","e":"Latin <i>moribundus</i>, from <i>mori</i> (to die).","f":"moribond","t":"Same as « moribond »."},{"w":"pecuniary","p":"adj.","m":"Relating to money.","e":"Latin <i>pecuniarius</i>, from <i>pecunia</i>.","f":"pécuniaire","t":"Same as « pécuniaire »."},{"w":"perspicacious","p":"adj.","m":"Having keen insight.","e":"Latin <i>perspicax</i> (sharp-sighted), from <i>perspicere</i> (to see through).","f":"perspicace","t":"Same as « perspicace »."},{"w":"plucky","p":"adj.","m":"Brave and determined.","e":"From <i>pluck</i> (courage), originally the heart and lungs of an animal.","f":"courageux, qui a du cran","t":"Pluck = courage: the plucky underdog who keeps fighting. « Qui a du cran »."},{"w":"portentous","p":"adj.","m":"Ominous; also pompously solemn.","e":"Latin <i>portentum</i> (omen).","f":"de mauvais augure; pompeux","t":"A portent is an omen: portentous clouds before a storm; also pompously solemn."},{"w":"primacy","p":"n.","m":"The state of being most important.","e":"Medieval Latin <i>primatia</i>, from <i>primus</i>.","f":"primauté","t":"« Primauté »."},{"w":"probity","p":"n.","m":"Strong moral principles; honesty.","e":"Latin <i>probitas</i>, from <i>probus</i> (upright).","f":"probité","t":"Same as « probité »."},{"w":"prognostication","p":"n.","m":"A prediction.","e":"Greek <i>prognōsis</i> (foreknowledge).","f":"pronostic, prédiction","t":"« Pronostic »."},{"w":"prolixity","p":"n.","m":"Tedious wordiness.","e":"Latin <i>prolixus</i> (extended, long).","f":"prolixité","t":"Same as « prolixe »."},{"w":"provident","p":"adj.","m":"Making provision for the future.","e":"Latin <i>providens</i> (foreseeing).","f":"prévoyant","t":"« Prévoyant », not providential."},{"w":"punctilio","p":"n.","m":"A fine point of etiquette.","e":"Italian <i>puntiglio</i>, Spanish <i>puntillo</i> (small point), from Latin <i>punctum</i>.","f":"point d’étiquette","t":"A tiny point of protocol."},{"w":"punctilious","p":"adj.","m":"Very attentive to correct behaviour and detail.","e":"From punctilio.","f":"pointilleux, scrupuleux","t":"Obsessed with tiny points."},{"w":"quail","p":"v.","m":"To feel or show fear.","e":"Middle English <i>quailen</i> (to fail, give way), perhaps from Latin <i>coagulare</i>.","f":"trembler, flancher","x":"2nd meaning","t":"Not the bird: quailing at the sight of the boss."},{"w":"raconteur","p":"n.","m":"A skilled storyteller.","e":"French <i>raconteur</i>.","f":"conteur","t":"Straight from « raconter »."},{"w":"recapitulation","p":"n.","m":"A summary.","e":"Latin <i>recapitulare</i> (to go over the headings, <i>capitulum</i>).","f":"récapitulation","t":"Same as « récapitulation »."},{"w":"redoubtable","p":"adj.","m":"Formidable; worthy of respect.","e":"Old French <i>redoutable</i>, from <i>redouter</i>.","f":"redoutable","t":"Same as « redoutable »."},{"w":"sagacious","p":"adj.","m":"Wise; showing good judgment.","e":"Latin <i>sagax</i> (keen-scented, shrewd).","f":"sagace","t":"Same as « sagace »."},{"w":"semblance","p":"n.","m":"Outward appearance, often deceptive.","e":"Old French <i>semblance</i>, from <i>sembler</i>.","f":"semblant, apparence","t":"« Un semblant d’ordre »."},{"w":"sinecure","p":"n.","m":"A paid position requiring little work.","e":"Latin <i>sine cura</i> (without care).","f":"sinécure","t":"Same as « sinécure »."},{"w":"solecism","p":"n.","m":"A grammatical mistake; a breach of etiquette.","e":"Greek <i>soloikismos</i>, from Soloi, a colony whose dialect Athenians mocked.","f":"solécisme","t":"Same as « solécisme »."},{"w":"temerity","p":"n.","m":"Excessive boldness; audacity.","e":"Latin <i>temeritas</i> (rashness).","f":"témérité, culot","t":"« Témérité »."},{"w":"umbrage","p":"n.","m":"Offence or annoyance.","e":"Latin <i>umbra</i> (shadow): something that overshadows you.","f":"ombrage","t":"« Prendre ombrage »."},{"w":"unforthcoming","p":"adj.","m":"Not willing to give information.","e":"<i>un-</i> + forthcoming.","f":"peu loquace, réticent","t":"Not forthcoming with information: a tight-lipped witness."},{"w":"vitriolic","p":"adj.","m":"Filled with bitter criticism.","e":"Medieval Latin <i>vitriolum</i> (sulphuric acid), from <i>vitrum</i> (glass).","f":"au vitriol, virulent","t":"« Une critique au vitriol »."}]},{"name":"Advanced IV","slug":"advanced-iv","series":"Advanced","words":[{"w":"apposite","p":"adj.","m":"Apt; highly appropriate.","e":"Latin <i>appositus</i> (placed near), from <i>apponere</i>.","f":"à propos, pertinent","t":"Placed right next to the point: an apposite remark is « à propos »."},{"w":"asperity","p":"n.","m":"Harshness of tone or manner.","e":"Latin <i>asperitas</i>, from <i>asper</i> (rough).","f":"aspérité, rudesse","t":"Rough surface: « aspérité »."},{"w":"celerity","p":"n.","m":"Swiftness.","e":"Latin <i>celeritas</i>, from <i>celer</i> (swift).","f":"célérité","t":"Same as « célérité »."},{"w":"corollary","p":"n.","m":"A proposition that follows from one already proved; a consequence.","e":"Latin <i>corollarium</i> (gift of a garland, gratuity), from <i>corolla</i> (little crown).","f":"corollaire","t":"Same as « corollaire »."},{"w":"cosset","p":"v.","m":"To pamper.","e":"From <i>cosset</i>, a pet lamb raised by hand.","f":"dorloter, choyer","t":"A cosset was a lamb raised by hand: to cosset = « dorloter »."},{"w":"crestfallen","p":"adj.","m":"Sad and disappointed.","e":"<i>crest</i> + <i>fallen</i>: a fighting cock with a drooping crest.","f":"dépité, abattu","t":"A fighting cock’s crest falls when he loses: « dépité »."},{"w":"crystallize","p":"v.","m":"To make or become definite and clear.","e":"Greek <i>krystallos</i> (ice, crystal).","f":"se cristalliser, se préciser","t":"Ideas taking solid, clear form, like crystals forming."},{"w":"decry","p":"v.","m":"To publicly denounce.","e":"French <i>décrier</i>.","f":"décrier, dénoncer","t":"Same as « décrier »."},{"w":"denouement","p":"n.","m":"The final resolution of a plot.","e":"French <i>dénouement</i> (untying), from <i>dénouer</i>.","f":"dénouement","t":"Straight from French."},{"w":"dispensation","p":"n.","m":"Exemption from a rule; a system of order.","e":"Latin <i>dispensatio</i> (management, distribution).","f":"dispense; régime","t":"« Dispense »."},{"w":"dovetail","p":"v.","m":"To fit together harmoniously.","e":"From the dovetail joint in carpentry, shaped like a dove’s tail.","f":"concorder, s’emboîter","t":"Interlocking wood joints: « queue d’aronde »."},{"w":"encumber","p":"v.","m":"To burden or impede.","e":"Old French <i>encombrer</i>.","f":"encombrer, entraver","t":"Same as « encombrer »."},{"w":"equitable","p":"adj.","m":"Fair and impartial.","e":"French <i>équitable</i>, Latin <i>aequitas</i>.","f":"équitable","t":"Same as « équitable »."},{"w":"firebrand","p":"n.","m":"A person who passionately stirs up trouble.","e":"<i>fire</i> + <i>brand</i> (burning piece of wood).","f":"agitateur, boutefeu","t":"A brand is a burning stick: the firebrand activist sets crowds alight."},{"w":"flippant","p":"adj.","m":"Not showing proper seriousness.","e":"From <i>flip</i> (to flick).","f":"désinvolte, cavalier","t":"Flip = flick away: treating a serious subject too lightly. « Désinvolte »."},{"w":"hobble","p":"v.","m":"To walk awkwardly; to hamper.","e":"Middle English <i>hobelen</i>, probably Low German.","f":"entraver; boitiller","t":"A hobble ties a horse’s legs so it can’t run: hobbled by debt = « entravé »."},{"w":"hubris","p":"n.","m":"Excessive pride.","e":"Greek <i>hybris</i> (outrage, arrogance punished by the gods).","f":"démesure, orgueil","t":"Hybris in Greek tragedy: the pride the gods punish, like Icarus flying too close to the sun."},{"w":"immure","p":"v.","m":"To confine or imprison.","e":"Medieval Latin <i>immurare</i>, from <i>murus</i> (wall).","f":"emmurer","t":"« Emmurer »."},{"w":"imperious","p":"adj.","m":"Arrogant and domineering.","e":"Latin <i>imperiosus</i>, from <i>imperium</i> (command).","f":"impérieux","t":"Same as « impérieux »."},{"w":"impetuous","p":"adj.","m":"Acting without thought.","e":"Latin <i>impetuosus</i>, from <i>impetus</i> (attack).","f":"impétueux","t":"Same as « impétueux »."},{"w":"improvident","p":"adj.","m":"Not providing for the future.","e":"<i>in-</i> + provident (foreseeing).","f":"imprévoyant","t":"« Imprévoyant »."},{"w":"incontrovertible","p":"adj.","m":"Not able to be denied.","e":"<i>in-</i> + controvert, Latin <i>contra</i> + <i>vertere</i>.","f":"incontestable, irréfutable","t":"Can’t be controverted (turned against): « incontestable »."},{"w":"inimitable","p":"adj.","m":"So good as to be impossible to copy.","e":"Latin <i>inimitabilis</i>.","f":"inimitable","t":"Same as « inimitable »."},{"w":"intimation","p":"n.","m":"An indication or hint.","e":"Late Latin <i>intimare</i> (to make known).","f":"indice, allusion","t":"From intimate (to hint): an intimation is a hint, « un signe avant-coureur »."},{"w":"inure","p":"v.","m":"To accustom to something unpleasant.","e":"Anglo-French <i>en ure</i> (in use, in practice).","f":"endurcir, aguerrir","t":"Inured to criticism = « aguerri »."},{"w":"invidious","p":"adj.","m":"Likely to arouse resentment; unfair.","e":"Latin <i>invidiosus</i>, from <i>invidia</i> (envy).","f":"injuste, odieux","t":"Envie: an invidious comparison."},{"w":"inviolate","p":"adj.","m":"Free from injury or violation.","e":"Latin <i>inviolatus</i>.","f":"inviolé, intact","t":"In + violate: never violated, still intact. « Inviolé »."},{"w":"irrefutable","p":"adj.","m":"Impossible to deny.","e":"Late Latin <i>irrefutabilis</i>.","f":"irréfutable","t":"Same as « irréfutable »."},{"w":"lacerate","p":"v.","m":"To tear; to wound deeply.","e":"Latin <i>lacerare</i> (to tear).","f":"lacérer","t":"Same as « lacérer »."},{"w":"machinate","p":"v.","m":"To plot.","e":"Latin <i>machinari</i> (to devise).","f":"machiner, comploter","t":"« Machination »."},{"w":"magisterial","p":"adj.","m":"Having authority; masterful; domineering.","e":"Latin <i>magister</i> (master).","f":"magistral","t":"« Magistral »."},{"w":"nonchalant","p":"adj.","m":"Calm and casual.","e":"French <i>nonchalant</i>: <i>non</i> + <i>chaloir</i> (to matter).","f":"nonchalant","t":"Straight from French."},{"w":"obstreperous","p":"adj.","m":"Noisy and difficult to control.","e":"Latin <i>obstreperus</i>, from <i>obstrepere</i> (to make a noise against).","f":"tapageur, turbulent","t":"Ob + strepere (to make a noise): the noisy, unruly child at the restaurant."},{"w":"ossify","p":"v.","m":"To become rigid and unchanging.","e":"Latin <i>os, ossis</i> (bone).","f":"se scléroser, s’ossifier","t":"Os = bone: an ossified institution has turned rigid like bone."},{"w":"patent","p":"adj.","m":"Obvious.","e":"Latin <i>patentem</i> (lying open), from <i>patere</i>.","f":"patent, manifeste","x":"2nd meaning","t":"« Patent »: a patent lie."},{"w":"peripatetic","p":"adj.","m":"Travelling from place to place.","e":"Greek <i>peripatētikos</i>; Aristotle taught while walking.","f":"itinérant","t":"Aristotle taught while walking around (peripatein): a peripatetic consultant always travelling."},{"w":"presentiment","p":"n.","m":"A feeling that something will happen.","e":"French <i>pressentiment</i>.","f":"pressentiment","t":"Straight from French."},{"w":"puerile","p":"adj.","m":"Childishly silly.","e":"Latin <i>puerilis</i>, from <i>puer</i> (boy).","f":"puéril","t":"Same as « puéril »."},{"w":"puissant","p":"adj.","m":"Powerful.","e":"French <i>puissant</i>.","f":"puissant","t":"Straight from French."},{"w":"rarefied","p":"adj.","m":"Esoteric; distant from ordinary life.","e":"Latin <i>rarefacere</i>.","f":"raffiné, élitiste; raréfié","t":"Thin air at the top: the rarefied world of haute couture."},{"w":"recrimination","p":"n.","m":"An accusation in response to one.","e":"Medieval Latin <i>recriminari</i>.","f":"récrimination","t":"Same as « récriminations »."},{"w":"ribald","p":"adj.","m":"Referring to sex in an amusingly rude way.","e":"Old French <i>ribaut</i> (rascal, debauchee).","f":"paillard, grivois","t":"« Chansons paillardes »."},{"w":"spartan","p":"adj.","m":"Showing austerity; lacking comfort.","e":"From Sparta.","f":"spartiate","t":"« Spartiate »."},{"w":"stalwart","p":"adj. / n.","m":"Loyal, reliable, hard-working; a loyal supporter.","e":"Old English <i>stǣlwierthe</i> (serviceable).","f":"fidèle, inébranlable","t":"Stalwart = solid and loyal: the party stalwart who has voted the same way for 40 years."},{"w":"subterfuge","p":"n.","m":"Deceit used to achieve a goal.","e":"Latin <i>subterfugere</i> (to escape secretly).","f":"subterfuge","t":"Same as « subterfuge »."},{"w":"surreptitious","p":"adj.","m":"Kept secret because it would not be approved.","e":"Latin <i>surrepticius</i> (stolen, secret).","f":"subreptice","t":"« Subreptice »."},{"w":"tempestuous","p":"adj.","m":"Characterised by strong, turbulent emotion.","e":"Latin <i>tempestas</i> (storm).","f":"tumultueux, orageux","t":"« Tempête »."},{"w":"unflappable","p":"adj.","m":"Calm in a crisis.","e":"<i>un-</i> + flap (state of agitation).","f":"imperturbable","t":"Never in a flap (panic): the unflappable pilot."},{"w":"unpropitious","p":"adj.","m":"Not favourable.","e":"<i>un-</i> + propitious.","f":"peu propice, défavorable","t":"« Peu propice »."},{"w":"untenable","p":"adj.","m":"Not able to be defended.","e":"<i>un-</i> + French <i>tenable</i>, from <i>tenir</i>.","f":"intenable, indéfendable","t":"« Intenable »."},{"w":"unviable","p":"adj.","m":"Not capable of working successfully.","e":"<i>un-</i> + viable.","f":"non viable","t":"Un-viable = can’t live (vie) on its own: an unviable business model needs constant cash."}]},{"name":"Advanced V","slug":"advanced-v","series":"Advanced","words":[{"w":"anachronism","p":"n.","m":"Something out of its proper time.","e":"Greek <i>anakhronismos</i>: <i>ana</i> (against) + <i>khronos</i> (time).","f":"anachronisme","t":"Same as « anachronisme »: a wristwatch in a Roman film."},{"w":"antic","p":"adj. / n.","m":"Grotesque or bizarre; (pl.) foolish behaviour.","e":"Italian <i>antico</i> (ancient), used of grotesque Roman decorations.","f":"loufoque; pitreries","t":"Antics = « pitreries »."},{"w":"apothegm","p":"n.","m":"A concise saying or maxim.","e":"Greek <i>apophthegma</i>, from <i>apophthengesthai</i> (to speak out).","f":"apophtegme, maxime","t":"Same as « apophtegme »."},{"w":"appurtenant","p":"adj.","m":"Belonging; pertinent.","e":"Anglo-French <i>apurtenant</i>, from Latin <i>pertinere</i>.","f":"rattaché à, afférent","t":"« Appartenant »."},{"w":"arrogate","p":"v.","m":"To take without justification.","e":"Latin <i>arrogare</i> (to claim for oneself).","f":"s’arroger","t":"« S’arroger un droit »."},{"w":"artifice","p":"n.","m":"Clever trickery.","e":"Latin <i>artificium</i> (craft), from <i>ars</i> + <i>facere</i>.","f":"artifice, ruse","t":"Same as « artifice »."},{"w":"atavism","p":"n.","m":"Reversion to something ancestral.","e":"Latin <i>atavus</i> (great-great-great-grandfather).","f":"atavisme","t":"Same as « atavisme »."},{"w":"baleful","p":"adj.","m":"Threatening harm; menacing.","e":"Old English <i>bealu</i> (evil) + <i>-ful</i>.","f":"menaçant, funeste","t":"Bale = evil: a baleful glare that wishes you harm. « Menaçant »."},{"w":"bemoan","p":"v.","m":"To express discontent about.","e":"<i>be-</i> + moan.","f":"se lamenter sur, déplorer","t":"Be + moan: moaning about something, « se lamenter sur »."},{"w":"besotted","p":"adj.","m":"Strongly infatuated.","e":"<i>be-</i> + sot (fool, Old French <i>sot</i>).","f":"entiché, fou de","t":"Made a « sot » by love."},{"w":"bristle","p":"v.","m":"To react angrily; to be thickly covered.","e":"Old English <i>byrst</i> (bristle).","f":"se hérisser","t":"Hair standing up: bristling at criticism."},{"w":"broadside","p":"n.","m":"A fierce verbal attack.","e":"Naval term: firing all guns on one side of a ship.","f":"attaque en règle, bordée","t":"A warship firing every cannon on one side at once: a broadside against the government."},{"w":"brook","p":"v.","m":"To tolerate (usually negative: brook no dissent).","e":"Old English <i>brūcan</i> (to use, enjoy).","f":"tolérer, souffrir","x":"2nd meaning","t":"To brook = to tolerate; she brooks no dissent. Not the stream!"},{"w":"browbeat","p":"v.","m":"To intimidate.","e":"<i>brow</i> + <i>beat</i>: bearing down with a frown.","f":"intimider, rudoyer","t":"Brow + beat: intimidating someone with a heavy frown, « rudoyer »."},{"w":"chagrin","p":"n.","m":"Annoyance or humiliation.","e":"French <i>chagrin</i> (sorrow).","f":"dépit, contrariété","x":"Faux ami","t":"English chagrin = vexation at failing, more « dépit » than sadness."},{"w":"chimera","p":"n.","m":"An illusion or fabrication.","e":"Greek <i>khimaira</i>, a fire-breathing monster (lion, goat, serpent).","f":"chimère","t":"Same as « chimère »."},{"w":"debonair","p":"adj.","m":"Confident, stylish and charming (of a man).","e":"Old French <i>de bon aire</i> (of good disposition).","f":"élégant, charmant","t":"« De bon air »."},{"w":"deign","p":"v.","m":"To do something one considers beneath one.","e":"Old French <i>deignier</i>, Latin <i>dignari</i>.","f":"daigner","t":"Same as « daigner »."},{"w":"disingenuous","p":"adj.","m":"Not candid; pretending to know less.","e":"<i>dis-</i> + ingenuous.","f":"de mauvaise foi, hypocrite","t":"Dis + ingenuous (ingénu): fake innocence, « de mauvaise foi »."},{"w":"doleful","p":"adj.","m":"Expressing sorrow.","e":"Old French <i>doel</i> (grief), Latin <i>dolere</i>.","f":"dolent, plaintif","t":"« Douleur »."},{"w":"effervescent","p":"adj.","m":"Vivacious and enthusiastic.","e":"Latin <i>effervescere</i> (to boil up).","f":"pétillant","t":"Bubbling like champagne: an effervescent personality."},{"w":"embryonic","p":"adj.","m":"In a rudimentary stage.","e":"Greek <i>embryon</i>.","f":"embryonnaire","t":"Same as « embryonnaire »."},{"w":"empiricism","p":"n.","m":"The theory that knowledge comes from experience.","e":"Greek <i>empeiria</i> (experience).","f":"empirisme","t":"Same as « empirisme »."},{"w":"epigram","p":"n.","m":"A short, witty saying.","e":"Greek <i>epigramma</i> (inscription).","f":"épigramme","t":"Same as « épigramme »."},{"w":"ersatz","p":"adj.","m":"Artificial and inferior substitute.","e":"German <i>Ersatz</i> (replacement), used for wartime substitutes like acorn coffee.","f":"ersatz, de substitution","t":"Same as « ersatz »."},{"w":"exemplar","p":"n.","m":"A model or pattern.","e":"Latin <i>exemplum</i>.","f":"modèle, exemple","t":"« Exemplaire »."},{"w":"gambit","p":"n.","m":"An opening move to gain an advantage.","e":"Italian <i>gambetto</i> (tripping up), chess opening sacrificing a pawn.","f":"stratagème, manœuvre","t":"In chess, a gambit sacrifices a pawn to gain position: an opening move with a plan."},{"w":"hoary","p":"adj.","m":"Grey with age; old and trite.","e":"Old English <i>hār</i> (grey).","f":"chenu; éculé","t":"Hoar = grey-white (hoarfrost = « givre »): a hoary joke is old and grey."},{"w":"inanity","p":"n.","m":"Silliness, emptiness.","e":"Latin <i>inanis</i> (empty).","f":"inanité, ineptie","t":"« Inanité »."},{"w":"inchoate","p":"adj.","m":"Just begun; not fully formed.","e":"Latin <i>inchoare</i> (to begin).","f":"embryonnaire, informe","t":"Inchoate ideas = « balbutiantes »."},{"w":"ineffable","p":"adj.","m":"Too great to be expressed in words.","e":"Latin <i>ineffabilis</i>: <i>in-</i> + <i>effari</i> (to speak out).","f":"ineffable","t":"Same as « ineffable »."},{"w":"languish","p":"v.","m":"To grow weak; suffer neglect.","e":"Old French <i>languir</i>.","f":"languir, dépérir","t":"Same as « languir »."},{"w":"meteoric","p":"adj.","m":"Very rapid (of success).","e":"Greek <i>meteōros</i> (lofty).","f":"fulgurant","t":"Like a meteor streaking across the sky: a meteoric rise is fast and spectacular."},{"w":"nettlesome","p":"adj.","m":"Causing annoyance.","e":"From <i>nettle</i>, the stinging plant.","f":"irritant, agaçant","t":"Stinging like nettles (« orties »): a nettlesome problem."},{"w":"objurgate","p":"v.","m":"To rebuke severely.","e":"Latin <i>obiurgare</i> (to scold).","f":"réprimander, admonester","t":"Ob + iurgare (to quarrel): scolding someone harshly."},{"w":"paragon","p":"n.","m":"A model of excellence.","e":"Italian <i>paragone</i> (touchstone).","f":"parangon, modèle","t":"« Parangon de vertu »."},{"w":"percipient","p":"adj.","m":"Perceptive.","e":"Latin <i>percipere</i> (to perceive).","f":"perspicace","t":"Percipient ≈ perceptive: someone who perceives what others miss. « Perspicace »."},{"w":"philistine","p":"n.","m":"A person hostile to culture and the arts.","e":"From the Philistines of the Bible; German students’ slang for townspeople.","f":"béotien, philistin","t":"« Béotien »."},{"w":"phlegmatic","p":"adj.","m":"Calm, unemotional.","e":"Greek <i>phlegmatikos</i>, from phlegm, the humour of calm.","f":"flegmatique","t":"Same as « flegmatique »."},{"w":"pith","p":"n.","m":"The essence; forcefulness.","e":"Old English <i>pitha</i> (core).","f":"essence, substance","t":"The pith is the core of a plant: the pith of an argument is its essence."},{"w":"rapprochement","p":"n.","m":"Re-establishment of harmonious relations.","e":"French <i>rapprochement</i>.","f":"rapprochement","t":"Straight from French « rapprochement »: two countries drawing closer again."},{"w":"recrudesce","p":"v.","m":"To break out again after a dormant period.","e":"Latin <i>recrudescere</i> (to become raw again): <i>crudus</i> (raw).","f":"connaître une recrudescence","t":"« Recrudescence »."},{"w":"reprisal","p":"n.","m":"An act of retaliation.","e":"Old French <i>reprisaille</i>.","f":"représailles","t":"« Représailles »."},{"w":"solicitude","p":"n.","m":"Care or concern.","e":"Latin <i>sollicitudo</i>.","f":"sollicitude","t":"Same as « sollicitude »."},{"w":"squelch","p":"v.","m":"To suppress forcefully.","e":"Imitative of a squishing sound.","f":"étouffer, écraser","t":"Squelch = the sound of a boot stamping on mud: crushing a rumour or protest flat."},{"w":"truculence","p":"n.","m":"Aggressive defiance.","e":"Latin <i>truculentus</i>, from <i>trux</i> (savage).","f":"agressivité","x":"Faux ami","t":"English truculence = aggressive defiance; French truculence = colourfulness."},{"w":"unprepossessing","p":"adj.","m":"Not attractive or appealing.","e":"<i>un-</i> + prepossess (to impress favourably).","f":"peu engageant","t":"Prepossessing = making a good first impression. Unprepossessing = « peu engageant »."},{"w":"unstinting","p":"adj.","m":"Given without restraint.","e":"<i>un-</i> + stint.","f":"généreux, sans réserve","t":"Stint = to hold back. Unstinting praise holds nothing back."},{"w":"untrammeled","p":"adj.","m":"Not restricted.","e":"<i>un-</i> + trammel (a net), Old French <i>tramail</i>.","f":"sans entraves","t":"A trammel was a net (« tramail »). Untrammeled = not caught in any net: free."},{"w":"vitriol","p":"n.","m":"Cruel and bitter criticism.","e":"Medieval Latin <i>vitriolum</i> (sulphuric acid).","f":"vitriol, venin","t":"Vitriol is sulphuric acid: « une critique au vitriol » burns."}]},{"name":"Advanced VI","slug":"advanced-vi","series":"Advanced","words":[{"w":"abjure","p":"v.","m":"To solemnly renounce.","e":"Latin <i>abiurare</i> (to deny on oath): <i>ab</i> + <i>iurare</i> (to swear).","f":"abjurer, renier","t":"Same as « abjurer »: swearing away."},{"w":"afford","p":"v.","m":"To provide or offer.","e":"Old English <i>geforthian</i> (to further, accomplish).","f":"offrir, fournir","x":"2nd meaning","t":"The view affords a panorama = « offre »."},{"w":"aplomb","p":"n.","m":"Self-confidence in a difficult situation.","e":"French <i>aplomb</i> (perpendicularity), from <i>à plomb</i> (plumb line).","f":"aplomb, assurance","t":"Straight from French."},{"w":"appropriate","p":"v.","m":"To take for one’s own use, often without permission.","e":"Late Latin <i>appropriare</i>, from <i>proprius</i> (own).","f":"s’approprier","x":"2nd meaning","t":"« S’approprier », not “suitable”."},{"w":"assiduously","p":"adv.","m":"With great care and perseverance.","e":"Latin <i>assiduus</i> (constant), from <i>assidere</i> (to sit by).","f":"assidûment","t":"Sitting at your desk: « assidu »."},{"w":"autocratic","p":"adj.","m":"Taking no account of others; tyrannical.","e":"Greek <i>autokratēs</i> (ruling by oneself).","f":"autocratique, autoritaire","t":"Auto + kratos (power): power held by one person alone. « Autocratique »."},{"w":"bridle","p":"v.","m":"To show resentment; to restrain.","e":"Old English <i>brīdel</i>; a horse throwing back its head against the bridle.","f":"se cabrer, se rebiffer; brider","x":"2nd meaning","t":"A horse rearing against its bridle (« bride »)."},{"w":"bromide","p":"n.","m":"A trite, unoriginal remark.","e":"Potassium bromide was used as a sedative; dull remarks were as soothing.","f":"banalité, platitude","t":"Bromide was a sedative: a bromide is a remark so dull it puts you to sleep."},{"w":"callow","p":"adj.","m":"Inexperienced and immature.","e":"Old English <i>calu</i> (bald): a featherless young bird.","f":"inexpérimenté, blanc-bec","t":"Callow once meant bald: a featherless chick, young and inexperienced."},{"w":"complaisant","p":"adj.","m":"Willing to please others.","e":"French <i>complaisant</i>.","f":"complaisant","t":"Same as French complaisant. Not complacent."},{"w":"complicit","p":"adj.","m":"Involved with others in wrongdoing.","e":"From complicity, French <i>complicité</i>.","f":"complice","t":"« Complice »."},{"w":"conflagration","p":"n.","m":"A large, destructive fire; a conflict.","e":"Latin <i>conflagrare</i> (to burn up).","f":"incendie, conflagration","t":"« Conflagration »."},{"w":"conflate","p":"v.","m":"To combine two things into one (often wrongly).","e":"Latin <i>conflare</i> (to blow together, fuse).","f":"amalgamer, confondre","t":"« Faire l’amalgame »."},{"w":"coterminous","p":"adj.","m":"Having the same boundaries or extent.","e":"Latin <i>conterminus</i>: <i>com-</i> + <i>terminus</i>.","f":"limitrophe, coextensif","t":"Co + terminus: two things ending at the same boundary, « limitrophe »."},{"w":"desiccated","p":"adj.","m":"Dried out; lacking vitality.","e":"Latin <i>desiccare</i>.","f":"desséché","t":"« Desséché »."},{"w":"desideratum","p":"n.","m":"Something needed or wanted.","e":"Latin <i>desideratum</i> (thing desired).","f":"desiderata","t":"« Desiderata »."},{"w":"discursive","p":"adj.","m":"Digressing from subject to subject.","e":"Medieval Latin <i>discursivus</i>, from <i>discurrere</i> (to run about).","f":"décousu, digressif","t":"Running about from topic to topic (discourir): a discursive essay."},{"w":"dolorous","p":"adj.","m":"Feeling great sorrow.","e":"Latin <i>dolor</i> (pain).","f":"douloureux","t":"« Douleur »."},{"w":"doughty","p":"adj.","m":"Brave and persistent.","e":"Old English <i>dohtig</i> (able, worthy).","f":"vaillant","t":"Doughty sounds sturdy: a doughty old fighter who never gives up, « vaillant »."},{"w":"elegiac","p":"adj.","m":"Mournful; relating to an elegy.","e":"Greek <i>elegeia</i> (lament).","f":"élégiaque","t":"Same as « élégiaque »."},{"w":"enormity","p":"n.","m":"The great wickedness of something; (loosely) great size.","e":"Latin <i>enormitas</i> (irregularity): <i>e</i> + <i>norma</i> (rule).","f":"atrocité, monstruosité","x":"2nd meaning","t":"Out of the norm: the enormity of the crime."},{"w":"ethereal","p":"adj.","m":"Extremely delicate and light.","e":"Greek <i>aithēr</i> (upper air).","f":"éthéré","t":"Same as « éthéré »."},{"w":"facile","p":"adj.","m":"Superficial; too simple.","e":"Latin <i>facilis</i> (easy).","f":"simpliste, superficiel (≠ facile)","x":"Faux ami","t":"In English it’s a criticism: too easy, shallow."},{"w":"fecund","p":"adj.","m":"Fertile; productive.","e":"Latin <i>fecundus</i>.","f":"fécond","t":"Same as « fécond »."},{"w":"gumption","p":"n.","m":"Shrewd resourcefulness; initiative.","e":"Scots (18th c.), origin unknown.","f":"jugeote, cran","t":"Gumption = common sense + guts: the initiative to just get it done."},{"w":"hauteur","p":"n.","m":"Haughtiness.","e":"French <i>hauteur</i> (height).","f":"hauteur, morgue","t":"Straight from French « hauteur »: looking down from on high."},{"w":"impervious","p":"adj.","m":"Unable to be affected; impenetrable.","e":"Latin <i>impervius</i>: <i>in-</i> + <i>pervius</i> (passable).","f":"imperméable, insensible","t":"Impervious = nothing gets through, like a waterproof jacket: impervious to criticism."},{"w":"impugn","p":"v.","m":"To dispute the truth or honesty of.","e":"Latin <i>impugnare</i> (to attack).","f":"contester, attaquer","t":"Pugnare = fight: « impugner »."},{"w":"inequity","p":"n.","m":"Lack of fairness.","e":"<i>in-</i> + equity.","f":"iniquité, injustice","t":"In + equity: « iniquité », not inequality of numbers but unfairness."},{"w":"internecine","p":"adj.","m":"Destructive to both sides within a group.","e":"Latin <i>internecinus</i> (deadly), from <i>necare</i> (to kill).","f":"fratricide","t":"« Une lutte fratricide »."},{"w":"inviolable","p":"adj.","m":"Never to be broken or dishonoured.","e":"Latin <i>inviolabilis</i>.","f":"inviolable","t":"Same as « inviolable »."},{"w":"malingerer","p":"n.","m":"Someone who fakes illness to avoid work.","e":"French <i>malingre</i> (sickly).","f":"tire-au-flanc, simulateur","t":"« Malingre »: pretending to be sickly."},{"w":"mendicant","p":"n. / adj.","m":"A beggar; begging.","e":"Latin <i>mendicare</i> (to beg).","f":"mendiant","t":"« Mendiant », ordres mendiants."},{"w":"noisome","p":"adj.","m":"Offensive, disgusting (often smell).","e":"Middle English <i>noy</i> (annoyance) + <i>-some</i>.","f":"nauséabond, fétide","t":"Not noisy! Smelly."},{"w":"obtuse","p":"adj.","m":"Slow to understand.","e":"Latin <i>obtusus</i> (blunted).","f":"obtus","t":"Same as « obtus »."},{"w":"palatable","p":"adj.","m":"Acceptable; pleasant to taste.","e":"From palate, Latin <i>palatum</i>.","f":"acceptable, agréable","t":"Pleasing to the palate (palais): a palatable compromise."},{"w":"panegyric","p":"n.","m":"A public speech of high praise.","e":"Greek <i>panēgyrikos</i> (for a public assembly).","f":"panégyrique","t":"Same as « panégyrique »."},{"w":"pellucid","p":"adj.","m":"Translucently clear; easy to understand.","e":"Latin <i>pellucidus</i>: <i>per</i> + <i>lucidus</i>.","f":"limpide, transparent","t":"Per + lucidus: light passes straight through it: pellucid water, pellucid prose."},{"w":"pontificate","p":"v.","m":"To express opinions pompously.","e":"From pontiff, Latin <i>pontifex</i> (bridge-maker, high priest).","f":"pontifier","t":"« Pontifier »."},{"w":"proscribe","p":"v.","m":"To forbid.","e":"Latin <i>proscribere</i> (to publish as outlawed).","f":"proscrire","t":"Same as « proscrire ». Prescribe = order."},{"w":"proselytize","p":"v.","m":"To try to convert.","e":"Greek <i>prosēlytos</i> (newcomer, convert).","f":"faire du prosélytisme","t":"« Prosélytisme »."},{"w":"self-effacing","p":"adj.","m":"Modest.","e":"self + efface, French <i>effacer</i>.","f":"effacé, modeste","t":"« S’effacer »: erasing yourself to let others shine."},{"w":"solicitous","p":"adj.","m":"Showing interest or concern.","e":"Latin <i>sollicitus</i> (anxious).","f":"plein de sollicitude, attentionné","t":"« Sollicitude »."},{"w":"stultify","p":"v.","m":"To cause to lose enthusiasm through routine.","e":"Late Latin <i>stultificare</i>, from <i>stultus</i> (foolish).","f":"abrutir, étouffer","t":"Stultus = stupid: a stultifying job makes you numb and dull."},{"w":"transmute","p":"v.","m":"To change in form or nature.","e":"Latin <i>transmutare</i>.","f":"transmuer","t":"Trans + mutare: the alchemist transmuting lead into gold."},{"w":"turgid","p":"adj.","m":"Pompous, swollen (style).","e":"Latin <i>turgidus</i> (swollen).","f":"ampoulé, boursouflé","t":"Turgid = swollen: turgid prose is bloated with big words."},{"w":"tyro","p":"n.","m":"A beginner, novice.","e":"Latin <i>tiro</i> (recruit).","f":"novice, débutant","t":"Tiro = a Roman recruit: a tyro is a beginner. « Novice »."},{"w":"unassailable","p":"adj.","m":"Unable to be attacked or questioned.","e":"<i>un-</i> + assail.","f":"inattaquable","t":"« Inattaquable »."},{"w":"unimpeachable","p":"adj.","m":"Beyond reproach.","e":"<i>un-</i> + impeach (to accuse), Old French <i>empechier</i>.","f":"irréprochable","t":"Impeach = accuse (as with a president). Unimpeachable = beyond accusation: « irréprochable »."},{"w":"vaunted","p":"adj.","m":"Praised or boasted about.","e":"Old French <i>vanter</i>.","f":"vanté","t":"Same as « vanté »."}]},{"name":"Advanced VII","slug":"advanced-vii","series":"Advanced","words":[{"w":"abrogate","p":"v.","m":"To repeal or abolish a law.","e":"Latin <i>abrogare</i>: <i>ab</i> + <i>rogare</i> (to propose a law).","f":"abroger","t":"Same as « abroger »."},{"w":"adjudicate","p":"v.","m":"To make a formal judgment.","e":"Latin <i>adiudicare</i>, from <i>iudex</i> (judge).","f":"juger, arbitrer","t":"Ad + iudex (juge): the referee who adjudicates a dispute and hands down the decision."},{"w":"bastardization","p":"n.","m":"Corruption of something to a worse form.","e":"From bastard, Old French <i>bastard</i>.","f":"abâtardissement, dénaturation","t":"« Abâtardir »."},{"w":"bereft","p":"adj.","m":"Deprived of; sad from loss.","e":"Old English <i>berēafian</i> (to rob).","f":"privé de, dépourvu","t":"Bereft = robbed (same root as bereaved): bereft of hope."},{"w":"canard","p":"n.","m":"An unfounded rumour.","e":"French <i>canard</i> (duck; hoax), from <i>vendre un canard à moitié</i> (to half-sell a duck, i.e. cheat).","f":"canard, bobard","t":"« Le Canard enchaîné »."},{"w":"capitulate","p":"v.","m":"To surrender.","e":"Medieval Latin <i>capitulare</i> (to draw up terms under headings).","f":"capituler","t":"Same as « capituler »."},{"w":"cataclysm","p":"n.","m":"A violent upheaval.","e":"Greek <i>kataklysmos</i> (deluge).","f":"cataclysme","t":"Same as « cataclysme »."},{"w":"chauvinism","p":"n.","m":"Excessive or prejudiced support for one’s group.","e":"French <i>chauvinisme</i>, from Nicolas Chauvin.","f":"chauvinisme","t":"Nicolas Chauvin, the fanatically loyal (possibly legendary) Napoleonic soldier."},{"w":"concomitant","p":"adj.","m":"Naturally accompanying.","e":"Latin <i>concomitari</i> (to accompany), from <i>comes</i> (companion).","f":"concomitant","t":"Same as « concomitant »."},{"w":"countermand","p":"v.","m":"To revoke an order.","e":"Old French <i>contremander</i>.","f":"annuler, révoquer","t":"Counter + mandate: cancelling an order you gave, « contre-ordre »."},{"w":"demonstrative","p":"adj.","m":"Openly showing feelings.","e":"Latin <i>demonstrare</i>.","f":"démonstratif, expansif","t":"« Démonstratif »."},{"w":"despot","p":"n.","m":"A tyrant.","e":"Greek <i>despotēs</i> (master).","f":"despote","t":"Same as « despote »."},{"w":"diminutive","p":"adj.","m":"Extremely small.","e":"Latin <i>diminutivus</i>.","f":"minuscule","t":"Diminutive = diminished, tiny: think of the diminutive -ette in « fillette », « maisonnette »."},{"w":"dissemble","p":"v.","m":"To conceal one’s true motives.","e":"Latin <i>dissimulare</i>.","f":"dissimuler","t":"« Dissimuler »."},{"w":"dissipate","p":"v.","m":"To disperse; to squander.","e":"Latin <i>dissipare</i>.","f":"dissiper, gaspiller","t":"Same as « dissiper »."},{"w":"dissolution","p":"n.","m":"Closing down; debauchery.","e":"Latin <i>dissolutio</i>.","f":"dissolution; débauche","t":"« Dissolution »."},{"w":"ebullient","p":"adj.","m":"Cheerful and full of energy.","e":"Latin <i>ebullire</i> (to boil over).","f":"exubérant, débordant d’enthousiasme","t":"Bubbling over (ébullition)."},{"w":"enamored","p":"adj.","m":"Filled with love for.","e":"Old French <i>enamourer</i>.","f":"épris, amoureux","t":"« Énamouré »."},{"w":"eponym","p":"n.","m":"A person after whom something is named.","e":"Greek <i>epōnymos</i> (named after).","f":"éponyme","t":"Eponym = the name-giver: Galvani for galvanize, Mesmer for mesmerize."},{"w":"estimable","p":"adj.","m":"Worthy of great respect.","e":"Latin <i>aestimabilis</i>.","f":"estimable","t":"Same as « estimable »."},{"w":"evanescent","p":"adj.","m":"Quickly fading.","e":"Latin <i>evanescere</i> (to vanish).","f":"évanescent","t":"Same as « évanescent »."},{"w":"exiguity","p":"n.","m":"Scantiness.","e":"Latin <i>exiguitas</i>.","f":"exiguïté","t":"Your 26 m²: « l’exiguïté »."},{"w":"exorbitant","p":"adj.","m":"Unreasonably high (price).","e":"Latin <i>exorbitare</i> (to go out of the track).","f":"exorbitant","t":"Ex + orbita = out of its orbit: an exorbitant price is off the charts."},{"w":"extrapolate","p":"v.","m":"To extend known trends to unknown situations.","e":"<i>extra</i> + (inter)polate.","f":"extrapoler","t":"Same as « extrapoler »."},{"w":"flag","p":"v.","m":"To become tired or weaker.","e":"Perhaps from obsolete <i>flag</i> (drooping).","f":"faiblir, fléchir","x":"2nd meaning","t":"To flag = to droop like a flag without wind: energy flags at 3 p.m."},{"w":"graft","p":"n.","m":"Corruption; bribery.","e":"Probably from <i>graft</i> (digging), US slang for dishonest gain.","f":"corruption, pots-de-vin","x":"2nd meaning","t":"Political graft = « pots-de-vin »."},{"w":"halcyon","p":"adj.","m":"Idyllically happy and peaceful (past).","e":"Greek <i>alkyōn</i> (kingfisher), said to calm the sea while nesting.","f":"paisible, heureux","t":"The halcyon (kingfisher) was said to calm the seas: halcyon days = peaceful, happy times."},{"w":"hoodwink","p":"v.","m":"To deceive.","e":"<i>hood</i> + <i>wink</i> (close the eyes): blindfolding.","f":"duper, berner","t":"Hood over someone’s eyes: blindfolded and tricked, « berner »."},{"w":"ineluctable","p":"adj.","m":"Unable to be avoided.","e":"Latin <i>ineluctabilis</i>: <i>in-</i> + <i>eluctari</i> (to struggle out).","f":"inéluctable","t":"Same as « inéluctable »."},{"w":"infelicitous","p":"adj.","m":"Unfortunate; inappropriate.","e":"<i>in-</i> + felicitous, Latin <i>felix</i>.","f":"malheureux, malvenu","t":"Felix = happy (félicité). An infelicitous remark is an unhappy choice of words: « malvenu »."},{"w":"lachrymose","p":"adj.","m":"Tearful; given to weeping.","e":"Latin <i>lacrima</i> (tear).","f":"larmoyant","t":"« Larme »."},{"w":"loath","p":"adj.","m":"Reluctant.","e":"Old English <i>lāth</i> (hateful).","f":"peu enclin à, réticent","t":"Loath (adjective) = reluctant: « peu enclin à ». Loathe (verb) = to hate."},{"w":"misattribute","p":"v.","m":"To wrongly attribute.","e":"<i>mis-</i> + attribute.","f":"attribuer à tort","t":"Mis + attribute: the famous quote you hear at every conference that the person never actually said."},{"w":"modicum","p":"n.","m":"A small quantity.","e":"Latin <i>modicus</i> (moderate).","f":"minimum, brin","t":"« Modique »."},{"w":"oblique","p":"adj.","m":"Indirect.","e":"Latin <i>obliquus</i> (slanting).","f":"indirect, oblique","t":"Same as « oblique »."},{"w":"obtain","p":"v.","m":"To be prevalent or in effect.","e":"Latin <i>obtinere</i> (to hold).","f":"prévaloir, être en vigueur","x":"2nd meaning","t":"Obtain (intransitive) = to be in force: the rules that obtain here = « en vigueur »."},{"w":"officious","p":"adj.","m":"Assertive of authority in an annoying way.","e":"Latin <i>officiosus</i> (dutiful).","f":"trop zélé, importun (≠ officieux)","x":"Faux ami","t":"Not « officieux » (unofficial)!"},{"w":"palaver","p":"n.","m":"Prolonged, idle discussion; fuss.","e":"Portuguese <i>palavra</i> (word).","f":"palabres","t":"« Palabres »."},{"w":"panacea","p":"n.","m":"A cure-all.","e":"Greek <i>panakeia</i>: <i>pan</i> + <i>akos</i> (cure).","f":"panacée","t":"Same as « panacée »."},{"w":"pillory","p":"v.","m":"To attack or ridicule publicly.","e":"Old French <i>pilori</i>, a wooden frame for public punishment.","f":"clouer au pilori","t":"« Clouer au pilori »."},{"w":"promulgate","p":"v.","m":"To make widely known; to put a law into effect.","e":"Latin <i>promulgare</i>.","f":"promulguer","t":"Same as « promulguer »."},{"w":"raillery","p":"n.","m":"Good-humoured teasing.","e":"French <i>raillerie</i>.","f":"raillerie","t":"Same as « raillerie »."},{"w":"row","p":"n.","m":"A noisy quarrel (rhymes with cow).","e":"18th-century slang, origin uncertain.","f":"dispute, querelle","x":"2nd meaning","t":"A row (rhymes with cow) is a noisy quarrel: « une engueulade »."},{"w":"sardonic","p":"adj.","m":"Grimly mocking.","e":"Greek <i>sardonios</i>; a Sardinian plant was said to make you grimace and die.","f":"sardonique","t":"« Rire sardonique »."},{"w":"simulacrum","p":"n.","m":"An imitation or representation.","e":"Latin <i>simulacrum</i> (likeness).","f":"simulacre","t":"« Simulacre »."},{"w":"splenetic","p":"adj.","m":"Bad-tempered.","e":"Latin <i>spleneticus</i>; the spleen was the seat of melancholy and anger.","f":"atrabilaire, irritable","t":"The spleen was the seat of bad temper: Baudelaire’s « spleen », but angry."},{"w":"surfeit","p":"n.","m":"An excess.","e":"Old French <i>surfait</i>.","f":"surabondance, excès","t":"« Surfait »."},{"w":"trenchant","p":"adj.","m":"Vigorous and incisive.","e":"Old French <i>trenchant</i> (cutting).","f":"tranchant, incisif","t":"Same as « tranchant »."},{"w":"verisimilitude","p":"n.","m":"The appearance of being true.","e":"Latin <i>verisimilitudo</i>: <i>verus</i> + <i>similis</i>.","f":"vraisemblance","t":"« Vraisemblance »."},{"w":"veritable","p":"adj.","m":"Real, genuine (for emphasis).","e":"French <i>véritable</i>.","f":"véritable","t":"Straight from French."}]},{"name":"Advanced VIII","slug":"advanced-viii","series":"Advanced","words":[{"w":"abeyance","p":"n.","m":"Temporary suspension.","e":"Old French <i>abeance</i> (expectation), from <i>baer</i> (to gape).","f":"suspens","t":"« En suspens »: held in abeyance."},{"w":"abscission","p":"n.","m":"The act of cutting off.","e":"Latin <i>abscindere</i> (to cut off).","f":"abscission, ablation","t":"Ab + scindere (scinder): cutting off, like a leaf detaching from its branch in autumn."},{"w":"attenuated","p":"adj.","m":"Weakened; thin.","e":"Latin <i>attenuare</i>.","f":"atténué","t":"« Atténué »."},{"w":"august","p":"adj.","m":"Respected and impressive.","e":"Latin <i>augustus</i> (venerable), title of the first emperor.","f":"auguste","t":"August = majestic, like the Emperor Augustus: an august institution."},{"w":"captious","p":"adj.","m":"Fault-finding.","e":"Latin <i>captiosus</i> (deceptive).","f":"pointilleux","t":"Captious = trying to capture you on a technicality, « pointilleux »."},{"w":"contumacious","p":"adj.","m":"Stubbornly disobedient.","e":"Latin <i>contumax</i> (insolent).","f":"rebelle, insoumis","t":"« Contumace »."},{"w":"descry","p":"v.","m":"To catch sight of.","e":"Old French <i>descrier</i> (to proclaim).","f":"apercevoir","t":"Descry = « discerner » from far away: the sailor descrying land on the horizon."},{"w":"dichotomy","p":"n.","m":"A division into two contrasting things.","e":"Greek <i>dikhotomia</i> (cutting in two).","f":"dichotomie","t":"Same as « dichotomie »."},{"w":"droll","p":"adj.","m":"Curious or unusual in a way that provokes amusement.","e":"French <i>drôle</i>.","f":"drôle, cocasse","t":"Straight from « drôle »."},{"w":"effigy","p":"n.","m":"A sculpture or model of a person.","e":"Latin <i>effigies</i>.","f":"effigie","t":"An effigy is a figure of a person, often burned in protest: « brûlé en effigie »."},{"w":"elegy","p":"n.","m":"A mournful poem.","e":"Greek <i>elegeia</i>.","f":"élégie","t":"« Élégie »."},{"w":"encomium","p":"n.","m":"A speech of high praise.","e":"Greek <i>enkōmion</i> (eulogy).","f":"éloge, panégyrique","t":"An encomium is a whole speech of « éloges »: think of the eulogy at a retirement dinner, but for someone still alive."},{"w":"equanimity","p":"n.","m":"Calmness under stress.","e":"Latin <i>aequanimitas</i>: <i>aequus</i> + <i>animus</i>.","f":"équanimité, sérénité","t":"Aequus + animus = an even mind: staying calm when the deck breaks at 2 a.m."},{"w":"exculpate","p":"v.","m":"To clear from blame.","e":"Latin <i>ex</i> + <i>culpa</i>.","f":"disculper","t":"Ex + culpa (mea culpa): exculpate = taking the culpa away, « disculper »."},{"w":"exigent","p":"adj.","m":"Pressing; demanding.","e":"Latin <i>exigere</i>.","f":"urgent, exigeant","t":"« Exigence »."},{"w":"expiate","p":"v.","m":"To atone for.","e":"Latin <i>expiare</i>.","f":"expier","t":"Same as « expier »."},{"w":"extraneous","p":"adj.","m":"Irrelevant.","e":"Latin <i>extraneus</i> (external).","f":"étranger, superflu","t":"Extraneous = « étranger » to the topic: extraneous slides in the appendix."},{"w":"fulminate","p":"v.","m":"To express vehement protest.","e":"Latin <i>fulminare</i> (to strike with lightning).","f":"fulminer","t":"Same as « fulminer »."},{"w":"hapless","p":"adj.","m":"Unfortunate.","e":"<i>hap</i> (luck) + <i>-less</i>.","f":"infortuné","t":"Hap = luck (as in happen, perhaps). Hapless = without luck: the hapless tourist who loses his passport twice."},{"w":"incipient","p":"adj.","m":"In an initial stage.","e":"Latin <i>incipere</i> (to begin).","f":"naissant","t":"Incipit = the first words of a text. Incipient = just starting: an incipient cold, an incipient crisis."},{"w":"inculcate","p":"v.","m":"To instil by persistent instruction.","e":"Latin <i>inculcare</i> (to tread in, press with the heel).","f":"inculquer","t":"« Inculquer »."},{"w":"indefatigable","p":"adj.","m":"Tireless.","e":"Latin <i>indefatigabilis</i>.","f":"infatigable","t":"« Infatigable »."},{"w":"ingrained","p":"adj.","m":"Firmly established.","e":"<i>in</i> + grain.","f":"enraciné, ancré","t":"Dye that has soaked into the grain of the wood can’t be scrubbed off: ingrained habits."},{"w":"insouciant","p":"adj.","m":"Casually unconcerned.","e":"French <i>insouciant</i>.","f":"insouciant","t":"Straight from French."},{"w":"intrinsic","p":"adj.","m":"Essential, belonging naturally.","e":"Latin <i>intrinsecus</i> (inwardly).","f":"intrinsèque","t":"Same as « intrinsèque »."},{"w":"jettison","p":"v.","m":"To throw away; abandon.","e":"Old French <i>getaison</i> (throwing).","f":"larguer, abandonner","t":"« Jeter » overboard."},{"w":"makeshift","p":"adj.","m":"Temporary and improvised.","e":"<i>make</i> + <i>shift</i> (to manage).","f":"de fortune","t":"« Un abri de fortune »."},{"w":"mendacious","p":"adj.","m":"Untruthful.","e":"Latin <i>mendax</i>.","f":"mensonger","t":"Mendacious sounds like « mensonger », and means exactly that: a mendacious report is full of lies."},{"w":"milieu","p":"n.","m":"Social environment.","e":"French <i>milieu</i>.","f":"milieu","t":"Straight from French."},{"w":"obfuscate","p":"v.","m":"To make unclear.","e":"Latin <i>obfuscare</i> (to darken), from <i>fuscus</i> (dark).","f":"obscurcir, embrouiller","t":"Fuscus = dark (as in « offusquer », which once meant to darken). Obfuscate = cloud the issue on purpose."},{"w":"obviate","p":"v.","m":"To remove a need or difficulty.","e":"Latin <i>obviare</i> (to meet in the way).","f":"éviter, rendre superflu","t":"« Obvier à »."},{"w":"outstrip","p":"v.","m":"To surpass.","e":"<i>out</i> + <i>strip</i> (to move fast).","f":"dépasser","t":"Out + strip (to move fast): running so fast you leave the others behind."},{"w":"palliate","p":"v.","m":"To alleviate without curing.","e":"Latin <i>palliare</i> (to cloak).","f":"pallier","t":"« Soins palliatifs »."},{"w":"pedant","p":"n.","m":"Someone overly concerned with rules.","e":"Italian <i>pedante</i>.","f":"pédant","t":"« Pédant »."},{"w":"penury","p":"n.","m":"Extreme poverty.","e":"Latin <i>penuria</i>.","f":"pénurie, misère","t":"« Pénurie »."},{"w":"perfidious","p":"adj.","m":"Deceitful, untrustworthy.","e":"Latin <i>perfidia</i>.","f":"perfide","t":"La perfide Albion."},{"w":"politic","p":"adj.","m":"Wise and prudent.","e":"Greek <i>politikos</i>.","f":"avisé, judicieux","x":"2nd meaning","t":"Politic = wise in a political way: it would be politic to stay quiet."},{"w":"prattle","p":"v.","m":"To talk foolishly.","e":"Low German <i>pratelen</i>.","f":"babiller, jacasser","t":"Prattle = childish chatter, « babiller »: a toddler prattling on about dinosaurs."},{"w":"prescient","p":"adj.","m":"Having foreknowledge.","e":"Latin <i>praescire</i>.","f":"prescient, clairvoyant","t":"Pre + scire (savoir): knowing before. A prescient analyst saw the crash coming."},{"w":"proclivity","p":"n.","m":"A tendency.","e":"Latin <i>proclivis</i> (sloping).","f":"penchant, propension","t":"Clivus = slope: a proclivity is a natural slope your behaviour slides down."},{"w":"propagate","p":"v.","m":"To spread.","e":"Latin <i>propagare</i>.","f":"propager","t":"Same as « propager »."},{"w":"prurient","p":"adj.","m":"Having excessive interest in sexual matters.","e":"Latin <i>prurire</i> (to itch).","f":"lubrique, malsain","t":"Itching: « prurit »."},{"w":"recalcitrant","p":"adj.","m":"Stubbornly uncooperative.","e":"Latin <i>recalcitrare</i> (to kick back), from <i>calx</i> (heel).","f":"récalcitrant","t":"Same as « récalcitrant »."},{"w":"salacious","p":"adj.","m":"Having undue interest in sex.","e":"Latin <i>salax</i> (lustful).","f":"salace","t":"Same as « salace »."},{"w":"scintilla","p":"n.","m":"A tiny trace.","e":"Latin <i>scintilla</i> (spark).","f":"once, soupçon","t":"Scintilla = spark (scintiller): not a scintilla of evidence = not one spark."},{"w":"stratagem","p":"n.","m":"A plan to deceive.","e":"Greek <i>stratēgēma</i>.","f":"stratagème","t":"Same as « stratagème »."},{"w":"supplicate","p":"v.","m":"To beg humbly.","e":"Latin <i>supplicare</i>.","f":"supplier","t":"« Supplier »."},{"w":"tumid","p":"adj.","m":"Swollen; pompous.","e":"Latin <i>tumidus</i>.","f":"enflé, boursouflé","t":"« Tuméfié »."},{"w":"unfeigned","p":"adj.","m":"Genuine, sincere.","e":"<i>un-</i> + feign (Old French <i>feindre</i>).","f":"sincère, non feint","t":"Feign = « feindre ». Unfeigned = not faked: unfeigned joy, genuine and spontaneous."},{"w":"voluble","p":"adj.","m":"Talking fluently and at length.","e":"Latin <i>volubilis</i>.","f":"volubile","t":"Same as « volubile »."}]},{"name":"Advanced IX","slug":"advanced-ix","series":"Advanced","words":[{"w":"abstemious","p":"adj.","m":"Indulging only very moderately.","e":"Latin <i>abstemius</i>: <i>abs</i> + <i>temetum</i> (strong drink).","f":"sobre, frugal","t":"Abs + temetum (strong drink): staying away from wine. « Sobre »."},{"w":"adventitious","p":"adj.","m":"Happening by chance; external.","e":"Latin <i>adventicius</i> (coming from outside).","f":"fortuit, accessoire","t":"Ad + venire: something that arrives from outside, by chance. « Fortuit »."},{"w":"affectation","p":"n.","m":"Behaviour designed to impress.","e":"Latin <i>affectatio</i>.","f":"affectation","t":"Same as « affectation »."},{"w":"aggrandize","p":"v.","m":"To increase power or status.","e":"French <i>agrandir</i>.","f":"agrandir, accroître","t":"Aggrandize = « agrandir » your own power or image: a self-aggrandizing CEO memoir."},{"w":"amalgamate","p":"v.","m":"To combine.","e":"From amalgam.","f":"fusionner","t":"Amalgamate = « fusionner », from amalgam: two companies amalgamated into one group."},{"w":"assiduous","p":"adj.","m":"Showing great care and perseverance.","e":"Latin <i>assiduus</i>.","f":"assidu","t":"Same as « assidu »."},{"w":"bilk","p":"v.","m":"To cheat out of money.","e":"Perhaps from <i>balk</i>, a cribbage term.","f":"escroquer","t":"Bilk = cheat someone of money owed: the Ponzi scheme that bilked thousands of investors."},{"w":"blithe","p":"adj.","m":"Casually indifferent; carefree.","e":"Old English <i>blīthe</i> (joyous).","f":"insouciant, joyeux","t":"Blithe = carefree to the point of not caring: blithely ignoring warnings."},{"w":"cadge","p":"v.","m":"To ask for something without paying.","e":"Origin uncertain (17th c.).","f":"taxer, quémander","t":"Picture a student cadging a cigarette, a coffee and a lift home, never paying for any of them: « taxer »."},{"w":"cogitate","p":"v.","m":"To think deeply.","e":"Latin <i>cogitare</i>.","f":"cogiter","t":"Cogitare, as in Descartes’ cogito: « cogiter », thinking hard."},{"w":"desultory","p":"adj.","m":"Lacking purpose or enthusiasm.","e":"Latin <i>desultorius</i> (of a circus rider leaping from horse to horse).","f":"décousu, sans conviction","t":"A desultor was a circus rider jumping from horse to horse: desultory = aimless, jumping around."},{"w":"diaphanous","p":"adj.","m":"Light, delicate and translucent.","e":"Greek <i>diaphanēs</i> (see-through).","f":"diaphane","t":"Same as « diaphane »."},{"w":"dissonance","p":"n.","m":"Lack of harmony.","e":"Latin <i>dissonantia</i>.","f":"dissonance","t":"Dis + sonare: sounds that clash. Cognitive dissonance = ideas that clash."},{"w":"distend","p":"v.","m":"To swell outward.","e":"Latin <i>distendere</i>.","f":"distendre","t":"Dis + tendre: stretched out in every direction, like a stomach distended after Christmas dinner."},{"w":"emollient","p":"adj.","m":"Soothing; calming.","e":"Latin <i>emollire</i> (to soften).","f":"émollient, apaisant","t":"Emollient creams soften (mollis = mou) your skin; an emollient tone softens an angry client."},{"w":"empirical","p":"adj.","m":"Based on observation.","e":"Greek <i>empeirikos</i>.","f":"empirique","t":"Same as « empirique »."},{"w":"execrable","p":"adj.","m":"Extremely bad.","e":"Latin <i>exsecrabilis</i>.","f":"exécrable","t":"Same as « exécrable »."},{"w":"expedient","p":"adj.","m":"Convenient but possibly improper.","e":"Latin <i>expedire</i>.","f":"opportun, commode","t":"« Un expédient »."},{"w":"fatuous","p":"adj.","m":"Silly and pointless.","e":"Latin <i>fatuus</i> (foolish).","f":"sot, inepte","t":"« Fat » in old French meant conceited fool."},{"w":"forestall","p":"v.","m":"To prevent by acting ahead.","e":"Old English <i>foresteall</i> (ambush).","f":"devancer, prévenir","t":"Fore + stall: getting in front of a problem to block it, « prendre les devants »."},{"w":"frenetic","p":"adj.","m":"Fast and energetic in an uncontrolled way.","e":"Greek <i>phrenitikos</i> (delirious).","f":"frénétique","t":"Same as « frénétique »."},{"w":"gambol","p":"v.","m":"To run or jump playfully.","e":"Italian <i>gambata</i> (a kick), <i>gamba</i> (leg).","f":"gambader","t":"« Gambader »."},{"w":"gustatory","p":"adj.","m":"Concerned with taste.","e":"Latin <i>gustare</i>.","f":"gustatif","t":"« Gustatif »."},{"w":"imminent","p":"adj.","m":"About to happen.","e":"Latin <i>imminere</i>.","f":"imminent","t":"Same as « imminent »."},{"w":"imperturbable","p":"adj.","m":"Unable to be upset.","e":"Latin <i>imperturbabilis</i>.","f":"imperturbable","t":"Same as « imperturbable »."},{"w":"inefficacious","p":"adj.","m":"Not producing the desired effect.","e":"<i>in-</i> + efficacious.","f":"inefficace","t":"« Inefficace »."},{"w":"insuperable","p":"adj.","m":"Impossible to overcome.","e":"Latin <i>insuperabilis</i>.","f":"insurmontable","t":"« Insurmontable »."},{"w":"inveigle","p":"v.","m":"To persuade by flattery.","e":"French <i>aveugler</i> (to blind).","f":"enjôler","t":"From French « aveugler »: blinding someone with flattery to get them to agree."},{"w":"legerdemain","p":"n.","m":"Skilful trickery; sleight of hand.","e":"French <i>léger de main</i>.","f":"tour de passe-passe","t":"« Léger de main »."},{"w":"machination","p":"n.","m":"A plot.","e":"Latin <i>machinatio</i>.","f":"machination","t":"Same as « machination »."},{"w":"malediction","p":"n.","m":"A curse.","e":"Latin <i>maledictio</i>.","f":"malédiction","t":"Same as « malédiction »."},{"w":"malinger","p":"v.","m":"To fake illness to avoid work.","e":"French <i>malingre</i>.","f":"tirer au flanc","t":"« Malingre »."},{"w":"modish","p":"adj.","m":"Fashionable.","e":"From mode, French <i>mode</i>.","f":"à la mode","t":"« À la mode »."},{"w":"occlude","p":"v.","m":"To block.","e":"Latin <i>occludere</i>.","f":"obstruer","t":"Ob + claudere (clore): an occluded artery is closed off. Same root as preclude and exclude."},{"w":"pallid","p":"adj.","m":"Pale; lacking intensity.","e":"Latin <i>pallidus</i>.","f":"pâle, blafard","t":"Pallid = « pâle » (and « blafard »): a pallid face, or pallid, lifeless prose."},{"w":"pastiche","p":"n.","m":"An imitation of another style.","e":"French <i>pastiche</i>, Italian <i>pasticcio</i> (pie).","f":"pastiche","t":"Same as « pastiche »."},{"w":"providential","p":"adj.","m":"Occurring at a favourable time; lucky.","e":"Latin <i>providentia</i>.","f":"providentiel","t":"« Providentiel »."},{"w":"quiescent","p":"adj.","m":"Inactive, dormant.","e":"Latin <i>quiescere</i> (to rest).","f":"latent, en sommeil","t":"Quiescent = quiet, like a volcano « en sommeil » that could wake up any time."},{"w":"recalcitrance","p":"n.","m":"Stubborn resistance.","e":"Latin <i>recalcitrare</i> (to kick back).","f":"résistance, refus d’obéir","t":"Re + calx (heel): kicking back with your heels like a mule. « Récalcitrant »."},{"w":"recrudescent","p":"adj.","m":"Breaking out again.","e":"Latin <i>recrudescere</i>.","f":"en recrudescence","t":"« Recrudescence »."},{"w":"requite","p":"v.","m":"To repay.","e":"<i>re-</i> + quite (quit).","f":"rendre, payer de retour","t":"Requite = repay. Unrequited love is love that is never paid back."},{"w":"ruminate","p":"v.","m":"To think deeply.","e":"Latin <i>ruminare</i> (to chew the cud).","f":"ruminer","t":"Same as « ruminer »."},{"w":"salubrious","p":"adj.","m":"Health-giving; pleasant.","e":"Latin <i>salubris</i>.","f":"salubre","t":"Same as « salubre »."},{"w":"slake","p":"v.","m":"To quench (thirst).","e":"Old English <i>slacian</i> (to slacken).","f":"étancher","t":"Slake ≈ slacken: your thirst slackens when you drink. « Étancher sa soif »."},{"w":"transgression","p":"n.","m":"Act that goes against a law.","e":"Latin <i>transgressio</i>.","f":"transgression","t":"Same as « transgression »."},{"w":"trifling","p":"adj.","m":"Unimportant, trivial.","e":"Old French <i>trufle</i> (mockery).","f":"insignifiant","t":"A trifle is also an English dessert of leftovers: a trifling sum is a crumb, not worth worrying about."},{"w":"vagary","p":"n.","m":"An unpredictable change.","e":"Latin <i>vagari</i> (to wander).","f":"caprice, aléa","t":"« Les aléas »."},{"w":"vitiate","p":"v.","m":"To spoil or impair.","e":"Latin <i>vitiare</i>, from <i>vitium</i> (fault).","f":"vicier","t":"« Vicier »."},{"w":"welter","p":"n.","m":"A large disorderly mass.","e":"Middle Dutch <i>welteren</i> (to roll).","f":"fatras, fouillis","t":"Welter = something rolling around in a heap: a welter of data with no structure, « un fatras »."},{"w":"wizened","p":"adj.","m":"Shrivelled with age.","e":"Old English <i>wisnian</i> (to wither).","f":"ratatiné, desséché","t":"Wizened = withered and wrinkled, like an old apple. Nothing to do with wise."}]},{"name":"GregMat I","slug":"gregmat-i","series":"GregMat","words":[{"w":"abound","p":"v.","m":"To exist in large numbers or amounts.","e":"Latin <i>abundare</i> (to overflow): <i>ab-</i> + <i>unda</i> (wave).","f":"abonder","t":"Same as « abonder »: waves (unda) overflowing."},{"w":"accentuate","p":"v.","m":"To make more noticeable; to emphasize.","e":"Latin <i>accentus</i> (accent, tone): <i>ad-</i> + <i>cantus</i> (song).","f":"accentuer, souligner","t":"Same as « accentuer »."},{"w":"aloof","p":"adj.","m":"Not friendly; distant and cool.","e":"From Dutch sailing term <i>a</i> + <i>luff</i>: keeping the ship to windward, away from the lee shore.","f":"distant, froid, réservé","t":"Keeping your boat away from everyone else. An aloof manager stays apart."},{"w":"anachronistic","p":"adj.","m":"Belonging to a period other than the one in which it exists.","e":"Greek <i>anachronismos</i>: <i>ana-</i> (against) + <i>khronos</i> (time).","f":"anachronique","t":"Against time: a smartphone in a Molière play is an « anachronisme »."},{"w":"cacophonous","p":"adj.","m":"Harsh-sounding; a mix of loud, unpleasant sounds.","e":"Greek <i>kakophōnia</i>: <i>kakos</i> (bad) + <i>phōnē</i> (sound).","f":"cacophonique","t":"Kakos (caca!) + phone: bad sound. The cacophony of a Paris traffic jam."},{"w":"canonize","p":"v.","m":"To declare a person officially a saint; to regard as great.","e":"Medieval Latin <i>canonizare</i>, from <i>canon</i> (rule, list), Greek <i>kanōn</i>.","f":"canoniser","t":"Same as « canoniser »: added to the list of saints."},{"w":"chauvinistic","p":"adj.","m":"Excessively or aggressively patriotic; prejudiced in favour of one's own group.","e":"French <i>chauvin</i>, from Nicolas Chauvin, a legendary Napoleonic soldier of fanatical loyalty.","f":"chauvin","t":"A French word! Chauvin, the fanatical soldier of Napoleon. Same as « chauvin »."},{"w":"cherish","p":"v.","m":"To protect and care for lovingly; to hold dear.","e":"Old French <i>cherir</i>, from <i>cher</i> (dear), Latin <i>carus</i>.","f":"chérir","t":"Same as « chérir »: mon cher."},{"w":"clamorous","p":"adj.","m":"Making a loud and confused noise.","e":"Latin <i>clamare</i> (to cry out).","f":"bruyant, tapageur","t":"A clamour (clameur): a clamorous crowd shouts together."},{"w":"clangor","p":"n.","m":"A continuous loud banging or ringing noise.","e":"Latin <i>clangor</i> (sound of a trumpet), imitative of the sound.","f":"fracas, vacarme","t":"Hear the clang of metal: « clangor » is a loud ringing din. Cousin of « clameur »."},{"w":"comity","p":"n.","m":"Courteous and considerate behaviour; mutual respect between states.","e":"Latin <i>comitas</i> (courtesy), from <i>comis</i> (friendly).","f":"courtoisie, bienveillance","t":"From « comité »? No: comity = friendly civility. « Comity of nations »: states respecting each other’s laws."},{"w":"compelling","p":"adj.","m":"Evoking interest or admiration in a powerfully irresistible way; convincing.","e":"Latin <i>compellere</i> (to drive together): <i>com-</i> + <i>pellere</i> (to drive).","f":"convaincant, irrésistible","t":"A compelling argument drives you to agree (compel = contraindre)."},{"w":"congenial","p":"adj.","m":"Pleasant because of shared qualities or interests.","e":"Latin <i>con-</i> (together) + <i>genialis</i> (of one's guiding spirit, <i>genius</i>).","f":"sympathique, agréable","x":"Look-alike","t":"Not « congénital ». Congenial = « sympathique »: a congenial colleague is easy company."},{"w":"conjectural","p":"adj.","m":"Based on guesswork rather than proof.","e":"Latin <i>coniectura</i> (inference), from <i>conicere</i> (to throw together).","f":"conjectural, hypothétique","t":"Same as « conjecture » (une conjecture): a guess."},{"w":"contend","p":"v.","m":"To struggle to overcome; to assert.","e":"Latin <i>contendere</i> (to stretch, strive): <i>con-</i> + <i>tendere</i> (to stretch).","f":"lutter; soutenir, prétendre","x":"2nd meaning","t":"Two meanings: compete (contender) and claim. « Il soutient que… » = he contends that…"},{"w":"conventional","p":"adj.","m":"Based on what is generally done; traditional.","e":"Latin <i>conventio</i> (agreement), from <i>convenire</i> (to come together).","f":"conventionnel, classique","t":"Same as « conventionnel »: following the usual agreement."},{"w":"covet","p":"v.","m":"To desire what belongs to someone else.","e":"Old French <i>coveitier</i>, from Latin <i>cupiditas</i> (desire).","f":"convoiter","t":"Same as « convoiter »."},{"w":"cursory","p":"adj.","m":"Hasty and not thorough.","e":"Latin <i>cursorius</i> (of running), from <i>currere</i> (to run).","f":"superficiel, rapide","t":"Same root as « cursus » and « courir »: you run through it without stopping."},{"w":"daunting","p":"adj.","m":"Seeming difficult to deal with; intimidating.","e":"Old French <i>danter</i>, from Latin <i>domitare</i> (to tame), <i>domare</i>.","f":"intimidant, décourageant","t":"Danter = dompter: a task so big it tames you. A daunting pile of work."},{"w":"decadent","p":"adj.","m":"In a state of moral or cultural decline; luxuriously self-indulgent.","e":"French <i>décadent</i>, Latin <i>de-</i> + <i>cadere</i> (to fall).","f":"décadent","t":"Same as « décadent »: Rome in decline. A decadent chocolate cake."},{"w":"deft","p":"adj.","m":"Neatly skilful and quick in movement.","e":"Middle English <i>defte</i>, variant of <i>daft</i> (gentle, fitting). Germanic.","f":"habile, adroit","t":"Think « déft »: dexterous fingers. A deft pickpocket, a deft negotiator."},{"w":"deify","p":"v.","m":"To treat as a god; to worship.","e":"Latin <i>deificare</i>: <i>deus</i> (god) + <i>facere</i> (to make).","f":"déifier, diviniser","t":"Same as « déifier »: make (fier) into a deus."},{"w":"discernible","p":"adj.","m":"Able to be seen or noticed.","e":"Latin <i>discernere</i> (to separate): <i>dis-</i> + <i>cernere</i> (to sift).","f":"discernable, perceptible","t":"Same root as « discerner »: you can tell it apart."},{"w":"dogged","p":"adj.","m":"Persistent and determined.","e":"From <i>dog</i>: with the stubborn grip of a dog. Germanic.","f":"tenace, obstiné","t":"Dogged like a dog on a bone: dogged determination = « une ténacité de bouledogue »."},{"w":"enigmatic","p":"adj.","m":"Mysterious and difficult to understand.","e":"Greek <i>ainigma</i> (riddle).","f":"énigmatique","t":"Same as « énigmatique »: the Mona Lisa’s smile."},{"w":"entitled","p":"adj.","m":"Believing oneself inherently deserving of privileges; having a right to.","e":"From <i>entitle</i>, Old French <i>entiteler</i>, Latin <i>titulus</i> (title).","f":"qui se croit tout permis; ayant droit","x":"2nd meaning","t":"Two senses: having a right (entitled to a refund) or arrogant (an entitled brat)."},{"w":"estranged","p":"adj.","m":"No longer close or affectionate; alienated.","e":"Old French <i>estranger</i>, from Latin <i>extraneus</i> (foreign).","f":"séparé, brouillé, éloigné","t":"Made « étranger » to someone: an estranged husband is a stranger now."},{"w":"explicable","p":"adj.","m":"Able to be explained.","e":"Latin <i>explicare</i> (to unfold, explain): <i>ex-</i> + <i>plicare</i> (to fold).","f":"explicable","t":"Same as « explicable ». Opposite: inexplicable."},{"w":"extravagant","p":"adj.","m":"Lacking restraint in spending or in behaviour.","e":"Medieval Latin <i>extravagari</i> (to wander outside): <i>extra</i> + <i>vagari</i>.","f":"extravagant, dépensier","t":"Same as « extravagant »: wandering outside the limits."},{"w":"fanciful","p":"adj.","m":"Overly imaginative and unrealistic.","e":"From <i>fancy</i>, shortened from <i>fantasy</i>, Greek <i>phantasia</i>.","f":"fantaisiste, imaginaire","t":"Fancy = fantaisie. A fanciful plan lives only in the imagination."},{"w":"feasible","p":"adj.","m":"Possible and practical to do.","e":"Old French <i>faisable</i>, from <i>faire</i> (to do), Latin <i>facere</i>.","f":"faisable, réalisable","t":"Feasible = « faisable ». A feasibility study is an étude de faisabilité."},{"w":"flamboyant","p":"adj.","m":"Tending to attract attention because of exuberance or confidence.","e":"French <i>flamboyant</i> (flaming), from <i>flamber</i>.","f":"flamboyant, extravagant","t":"Straight from French: flaming. Le style gothique flamboyant."},{"w":"incendiary","p":"adj.","m":"Designed to start fires; tending to stir up conflict.","e":"Latin <i>incendiarius</i>, from <i>incendium</i> (fire), <i>incendere</i> (to set on fire).","f":"incendiaire","t":"Same as « incendiaire »: an incendiary remark sets the room on fire."},{"w":"incredulous","p":"adj.","m":"Unwilling or unable to believe something.","e":"Latin <i>incredulus</i>: <i>in-</i> (not) + <i>credere</i> (to believe).","f":"incrédule","t":"Same as « incrédule »."},{"w":"indiscriminate","p":"adj.","m":"Done at random or without careful judgement.","e":"<i>in-</i> (not) + Latin <i>discriminare</i> (to distinguish).","f":"sans discernement, aveugle","t":"Not « discrimé »: no distinguishing. Indiscriminate bombing hits everything."},{"w":"invasive","p":"adj.","m":"Tending to intrude; spreading harmfully.","e":"Latin <i>invadere</i> (to go in): <i>in-</i> + <i>vadere</i> (to go).","f":"invasif, envahissant","t":"Same as « invasif »: invasive species, invasive surgery."},{"w":"invigorate","p":"v.","m":"To give strength or energy to.","e":"Latin <i>in-</i> + <i>vigor</i> (strength), from <i>vigere</i> (to be lively).","f":"revigorer, donner de la vigueur","t":"In + vigueur: put vigour into someone. An invigorating morning run."},{"w":"irreverent","p":"adj.","m":"Showing a lack of respect for people or things usually taken seriously.","e":"Latin <i>irreverens</i>: <i>in-</i> (not) + <i>reverens</i> (respectful).","f":"irrévérencieux","t":"Same as « irrévérencieux »: no révérence."},{"w":"lax","p":"adj.","m":"Not strict or careful enough.","e":"Latin <i>laxus</i> (loose).","f":"relâché, laxiste","t":"Same as « laxiste »: loose rules, lax security."},{"w":"loathe","p":"v.","m":"To feel intense dislike or disgust for.","e":"Old English <i>lāthian</i> (to be hateful), from <i>lāth</i> (hostile). Germanic.","f":"détester, avoir en horreur","t":"Loathe, hate. Not to be confused with « loath » (reluctant, no e)."},{"w":"malign","p":"v.","m":"To speak harmful untruths about; (adj.) evil in nature.","e":"Latin <i>malignus</i> (ill-natured): <i>malus</i> (bad) + <i>gignere</i> (to beget).","f":"calomnier, dénigrer; malin","t":"Same as « malin » (as in tumeur maligne): malign = speak ill of."},{"w":"marginalize","p":"v.","m":"To treat as insignificant or peripheral.","e":"Latin <i>margo</i> (edge).","f":"marginaliser","t":"Same as « marginaliser »: push to the margin of the page."},{"w":"misanthropic","p":"adj.","m":"Disliking other people and avoiding society.","e":"Greek <i>misanthrōpos</i>: <i>misein</i> (to hate) + <i>anthrōpos</i> (human).","f":"misanthrope","t":"Molière’s « Le Misanthrope »: a man who hates mankind."},{"w":"misnomer","p":"n.","m":"A wrong or inaccurate name or term.","e":"Old French <i>mesnommer</i> (to misname): <i>mes-</i> (wrongly) + <i>nommer</i> (to name).","f":"terme impropre, erreur de nom","t":"Mis + nom: a wrong name. « Un abus de langage »."},{"w":"momentary","p":"adj.","m":"Lasting for a very short time.","e":"Latin <i>momentarius</i>, from <i>momentum</i> (movement, moment).","f":"momentané, passager","t":"Same as « momentané »."},{"w":"negligent","p":"adj.","m":"Failing to take proper care.","e":"Latin <i>negligens</i>, from <i>neglegere</i> (to disregard): <i>nec</i> + <i>legere</i>.","f":"négligent","t":"Same as « négligent »."},{"w":"nullify","p":"v.","m":"To make legally void; to cancel out the effect of.","e":"Latin <i>nullus</i> (none) + <i>facere</i> (to make).","f":"annuler, rendre nul","t":"Make nul: « rendre nul et non avenu »."},{"w":"obsolete","p":"adj.","m":"No longer produced or used; out of date.","e":"Latin <i>obsolescere</i> (to fall into disuse).","f":"obsolète, désuet","t":"Same as « obsolète »."},{"w":"omnipresent","p":"adj.","m":"Present everywhere at the same time.","e":"Latin <i>omni-</i> (all) + <i>praesens</i> (present).","f":"omniprésent","t":"Same as « omniprésent »."},{"w":"oust","p":"v.","m":"To drive out or expel from a position.","e":"Anglo-French <i>ouster</i>, Old French <i>oster</i> (to remove), Latin <i>obstare</i> (to stand in the way).","f":"évincer, chasser","t":"French « ôter »: to remove. A CEO ousted by the board."},{"w":"palpable","p":"adj.","m":"So intense it seems almost touchable; easily perceived.","e":"Latin <i>palpabilis</i>, from <i>palpare</i> (to touch gently).","f":"palpable, tangible","t":"Same as « palpable »: you could touch it. Palpable tension."},{"w":"paradigmatic","p":"adj.","m":"Serving as a typical example or model.","e":"Greek <i>paradeigma</i> (pattern, example): <i>para-</i> (beside) + <i>deiknynai</i> (to show).","f":"paradigmatique, exemplaire","t":"From « paradigme »: the perfect pattern. A paradigmatic case."},{"w":"pertinacious","p":"adj.","m":"Holding firmly to an opinion or course of action; stubborn.","e":"Latin <i>pertinax</i> (very tenacious): <i>per-</i> (very) + <i>tenax</i> (holding).","f":"tenace, entêté, opiniâtre","t":"Per + tenace: very tenacious. Not « pertinent »."},{"w":"polarize","p":"v.","m":"To divide into two sharply contrasting groups.","e":"French <i>polariser</i>, from Latin <i>polus</i> (pole), Greek <i>polos</i>.","f":"polariser","t":"Same as « polariser »: a polarizing debate splits into two poles."},{"w":"polemical","p":"adj.","m":"Relating to strongly critical or controversial argument.","e":"Greek <i>polemikos</i> (of war), from <i>polemos</i> (war).","f":"polémique","t":"Same as « polémique »: a war of words."},{"w":"profundity","p":"n.","m":"Great depth of insight or knowledge.","e":"Latin <i>profunditas</i>, from <i>profundus</i> (deep): <i>pro-</i> + <i>fundus</i> (bottom).","f":"profondeur","t":"Profondeur: a deep thought, with a deep bottom (fundus)."},{"w":"prophetic","p":"adj.","m":"Accurately predicting what will happen.","e":"Greek <i>prophētēs</i> (one who speaks before): <i>pro-</i> + <i>phēmi</i> (to speak).","f":"prophétique","t":"Same as « prophétique »."},{"w":"remedial","p":"adj.","m":"Intended to correct or improve something deficient.","e":"Latin <i>remedium</i> (cure): <i>re-</i> + <i>mederi</i> (to heal).","f":"de rattrapage, correctif","t":"A remedy: remedial classes are « cours de rattrapage »."},{"w":"skullduggery","p":"n.","m":"Underhand or unscrupulous behaviour.","e":"17th-century Scottish <i>sculduddery</i> (obscene behaviour), origin unknown.","f":"magouilles, manœuvres louches","t":"A skull and dagger! Shady skullduggery in the boardroom = « des magouilles »."},{"w":"stern","p":"adj.","m":"Serious and strict, especially in manner.","e":"Old English <i>styrne</i> (severe). Germanic.","f":"sévère, austère","x":"2nd meaning","t":"A stern teacher is strict. (Also the back of a ship: another meaning.)"},{"w":"stigmatize","p":"v.","m":"To describe or regard as worthy of disgrace.","e":"Greek <i>stigma</i> (mark, brand burned on the skin).","f":"stigmatiser","t":"Same as « stigmatiser »: to brand someone."},{"w":"subjective","p":"adj.","m":"Based on personal feelings rather than facts.","e":"Latin <i>subjectivus</i>, from <i>subjectus</i> (placed under).","f":"subjectif","t":"Same as « subjectif »: opinion, not fact."},{"w":"subvert","p":"v.","m":"To undermine the power of an established system.","e":"Latin <i>subvertere</i> (to overturn): <i>sub-</i> + <i>vertere</i> (to turn).","f":"subvertir, renverser","t":"Same as « subversif »: turn it upside down from below."},{"w":"tranquil","p":"adj.","m":"Free from disturbance; calm.","e":"Latin <i>tranquillus</i> (calm, still).","f":"tranquille","t":"Same as « tranquille »."},{"w":"trivial","p":"adj.","m":"Of little value or importance.","e":"Latin <i>trivialis</i> (of the crossroads, common): <i>tri-</i> (three) + <i>via</i> (road).","f":"insignifiant, banal","x":"Faux ami","t":"French « trivial » means vulgar. English trivial = unimportant: « sans importance »."},{"w":"utterly","p":"adv.","m":"Completely and absolutely.","e":"From <i>utter</i> (outer, extreme), Old English <i>ūtera</i>, from <i>ūt</i> (out). Germanic.","f":"complètement, tout à fait","t":"To the outermost limit: utterly ridiculous = tout à fait ridicule."},{"w":"vapid","p":"adj.","m":"Offering nothing that is stimulating or challenging; dull.","e":"Latin <i>vapidus</i> (flat, flavourless, like wine that has lost its spirit).","f":"insipide, fade","t":"Flat like a wine gone off: « fade ». A vapid conversation."},{"w":"venal","p":"adj.","m":"Willing to do dishonest things for money; corrupt.","e":"Latin <i>venalis</i> (for sale), from <i>venum</i> (sale).","f":"vénal, corrompu","t":"Same as « vénal »: someone whose loyalty is for sale."},{"w":"weary","p":"adj.","m":"Tired; also, cautious about something because of past experience.","e":"Old English <i>wērig</i> (tired). Germanic.","f":"las, fatigué","x":"Look-alike","t":"Not « wary » (prudent). Weary = las: weary of the job market."}]},{"name":"GregMat II","slug":"gregmat-ii","series":"GregMat","words":[{"w":"acquiesce","p":"v.","m":"To accept something reluctantly but without protest.","e":"Latin <i>acquiescere</i> (to rest): <i>ad-</i> + <i>quies</i> (rest).","f":"acquiescer, consentir","t":"Same as « acquiescer »: you rest your objections."},{"w":"acrimonious","p":"adj.","m":"Angry and bitter.","e":"Latin <i>acrimonia</i>, from <i>acer</i> (sharp).","f":"acrimonieux, acerbe","t":"Same as « acrimonieux »: sharp (acre) words."},{"w":"adroit","p":"adj.","m":"Clever or skilful, especially in handling difficult situations.","e":"French <i>à droit</i> (rightly), from <i>droit</i> (right).","f":"adroit","t":"Same as « adroit » — even the opposite is French: « maladroit » = inept."},{"w":"affinity","p":"n.","m":"A natural liking or attraction; similarity.","e":"Latin <i>affinitas</i> (relationship by marriage), from <i>affinis</i> (bordering).","f":"affinité","t":"Same as « affinité »: « avoir des affinités »."},{"w":"altruistic","p":"adj.","m":"Showing selfless concern for others.","e":"French <i>altruisme</i>, from Latin <i>alter</i> (other).","f":"altruiste","t":"Same as « altruiste »."},{"w":"amend","p":"v.","m":"To make minor changes to improve; to correct.","e":"Latin <i>emendare</i> (to free from fault), <i>e-</i> + <i>menda</i> (fault).","f":"amender, modifier","t":"Same as « amender »: un amendement to a law. Not « emend » (to correct a text)."},{"w":"antithesis","p":"n.","m":"A direct opposite; a contrast of ideas.","e":"Greek <i>antithesis</i>: <i>anti-</i> (against) + <i>tithenai</i> (to place).","f":"antithèse, contraire","t":"Same as « antithèse »: placed against."},{"w":"baroque","p":"adj.","m":"Highly ornate and extravagant.","e":"French <i>baroque</i>, from Portuguese <i>barroco</i> (irregular pearl).","f":"baroque","t":"Same as « baroque »: complex and over-decorated."},{"w":"befuddled","p":"adj.","m":"Unable to think clearly; confused.","e":"From <i>be-</i> + <i>fuddle</i> (to confuse, probably drink-related), origin unclear.","f":"embrouillé, déboussolé","t":"Fuddled brain, as if drunk: « l'esprit brouillé »."},{"w":"beneficent","p":"adj.","m":"Doing good; generous.","e":"Latin <i>beneficus</i>: <i>bene</i> (well) + <i>facere</i> (to do).","f":"bienfaisant","t":"Bene + facere = « bienfaisant »."},{"w":"boisterous","p":"adj.","m":"Noisy, energetic and cheerful.","e":"Middle English <i>boistous</i> (rough, coarse), origin unknown.","f":"bruyant, turbulent","t":"Not « boisson ». A boisterous party is rowdy."},{"w":"canny","p":"adj.","m":"Shrewd, especially in money matters.","e":"From Scots <i>can</i> (to know), Old English <i>cunnan</i>.","f":"astucieux, avisé","t":"Knows how to: a canny investor. Cousin of « cunning »."},{"w":"clandestine","p":"adj.","m":"Kept secret, especially because illicit.","e":"Latin <i>clandestinus</i>, from <i>clam</i> (secretly).","f":"clandestin","t":"Same as « clandestin »."},{"w":"compromise","p":"v.","m":"To weaken or damage; to settle by mutual concession.","e":"Latin <i>compromissum</i> (mutual promise): <i>com-</i> + <i>promittere</i>.","f":"compromettre; faire un compromis","x":"2nd meaning","t":"Two uses: reach a compromise, OR « compromettre » (compromise safety = endanger it)."},{"w":"cordial","p":"adj.","m":"Warm and friendly.","e":"Medieval Latin <i>cordialis</i>, from Latin <i>cor, cordis</i> (heart).","f":"cordial, chaleureux","t":"Same as « cordial »: from the heart (cœur)."},{"w":"countenance","p":"v.","m":"To tolerate or approve; (n.) the face.","e":"Old French <i>contenance</i> (bearing), Latin <i>continere</i> (to hold together).","f":"tolérer, approuver; contenance, visage","x":"2nd meaning","t":"Contenance. As a verb: « ne pas cautionner ». I will not countenance such behaviour."},{"w":"credible","p":"adj.","m":"Able to be believed; convincing.","e":"Latin <i>credibilis</i>, from <i>credere</i> (to believe).","f":"crédible","t":"Same as « crédible »."},{"w":"debilitating","p":"adj.","m":"Making someone weak and infirm.","e":"Latin <i>debilitare</i>, from <i>debilis</i> (weak).","f":"débilitant, affaiblissant","t":"From « débile » (weak), not stupid: a debilitating illness drains strength."},{"w":"diffuse","p":"adj.","m":"Spread over a wide area; not concise. (v. diffuse = to spread)","e":"Latin <i>diffundere</i>: <i>dis-</i> + <i>fundere</i> (to pour).","f":"diffus, prolixe","t":"Same as « diffus »: a diffuse writing style never gets to the point."},{"w":"distressed","p":"adj.","m":"Suffering anxiety or pain; (of goods) sold at a low price; (of furniture) aged on purpose.","e":"Old French <i>destresse</i>, Latin <i>districtus</i> (restrained).","f":"affligé, en détresse","x":"2nd meaning","t":"Détresse. But distressed jeans are artificially worn."},{"w":"documentary","p":"adj.","m":"Consisting of documents; based on factual evidence.","e":"Latin <i>documentum</i> (lesson, proof), from <i>docere</i> (to teach).","f":"documentaire, sur documents","t":"Documentary evidence = « preuves documentaires »."},{"w":"dwindling","p":"adj.","m":"Diminishing gradually.","e":"From <i>dwindle</i>, Old English <i>dwīnan</i> (to shrink). Germanic.","f":"qui diminue, décroissant","t":"Dwindling supplies are slowly vanishing: « s'amenuiser »."},{"w":"eclipse","p":"v.","m":"To obscure or surpass in importance.","e":"Greek <i>ekleipsis</i>: <i>ek-</i> + <i>leipein</i> (to leave).","f":"éclipser","t":"Same as « éclipser »: a star outshines the others."},{"w":"edify","p":"v.","m":"To instruct or improve morally or intellectually.","e":"Latin <i>aedificare</i> (to build): <i>aedes</i> (building) + <i>facere</i>.","f":"édifier, instruire","t":"Same as « édifier »: build up the mind, like building an édifice."},{"w":"encyclopedic","p":"adj.","m":"Comprehensive in scope.","e":"Greek <i>enkyklios paideia</i> (general education).","f":"encyclopédique","t":"Same as « encyclopédique »: knowing everything."},{"w":"exasperated","p":"adj.","m":"Intensely irritated.","e":"Latin <i>exasperare</i>: <i>ex-</i> + <i>asper</i> (rough).","f":"exaspéré","t":"Same as « exaspéré »."},{"w":"exhaustive","p":"adj.","m":"Examining or including all elements; thorough.","e":"Latin <i>exhaurire</i> (to drain out).","f":"exhaustif","t":"Same as « exhaustif »: leave nothing out. Not « exhausting »."},{"w":"exhilarating","p":"adj.","m":"Making one feel very happy, animated or elated.","e":"Latin <i>exhilarare</i>: <i>ex-</i> + <i>hilaris</i> (cheerful).","f":"grisant, euphorisant","t":"Hilarious inside: hilaris. An exhilarating rollercoaster."},{"w":"expedite","p":"v.","m":"To make an action or process happen sooner or be accomplished more quickly.","e":"Latin <i>expedire</i> (to free the feet): <i>ex-</i> + <i>pes, pedis</i> (foot).","f":"accélérer, expédier","t":"Free the feet and go: « expédier » une affaire. Opposite of impede."},{"w":"feeble","p":"adj.","m":"Lacking physical strength; weak.","e":"Old French <i>feble</i>, Latin <i>flebilis</i> (lamentable).","f":"faible, débile","t":"Feeble = « faible » (feble → faible)."},{"w":"feign","p":"v.","m":"To pretend to be affected by (a feeling or state).","e":"Old French <i>feindre</i>, Latin <i>fingere</i> (to shape, invent).","f":"feindre, simuler","t":"Same as « feindre »."},{"w":"felicitous","p":"adj.","m":"Well chosen or apt; pleasing.","e":"Latin <i>felicitas</i> (happiness), from <i>felix</i> (happy).","f":"heureux, bien choisi","t":"Une formule heureuse: a felicitous phrase fits perfectly. Cousin of « félicité »."},{"w":"fervor","p":"n.","m":"Intense and passionate feeling.","e":"Latin <i>fervor</i> (boiling heat), from <i>fervere</i> (to boil).","f":"ferveur","t":"Same as « ferveur »."},{"w":"forbear","p":"v.","m":"To refrain from; to hold back.","e":"Old English <i>forberan</i>: <i>for-</i> (away) + <i>beran</i> (to bear).","f":"s'abstenir de, se retenir","x":"Look-alike","t":"Bear back your anger. Not to be confused with « forebear » (ancestor)."},{"w":"fungible","p":"adj.","m":"Replaceable by another identical item; interchangeable.","e":"Medieval Latin <i>fungibilis</i>, from <i>fungi vice</i> (to perform in place of).","f":"fongible, interchangeable","t":"Fongible: a euro is fungible, a painting is not."},{"w":"illusory","p":"adj.","m":"Based on illusion; not real.","e":"Latin <i>illusorius</i>, from <i>illudere</i> (to mock).","f":"illusoire","t":"Same as « illusoire »."},{"w":"indispensable","p":"adj.","m":"Absolutely necessary.","e":"<i>in-</i> + <i>dispensable</i>, Latin <i>dispensare</i> (to weigh out).","f":"indispensable","t":"Same as « indispensable »."},{"w":"interchangeable","p":"adj.","m":"Able to be exchanged with each other.","e":"<i>inter-</i> + <i>change</i>, Old French <i>changier</i>.","f":"interchangeable","t":"Same as « interchangeable »."},{"w":"lucrative","p":"adj.","m":"Producing a great deal of profit.","e":"Latin <i>lucrativus</i>, from <i>lucrum</i> (gain).","f":"lucratif","t":"Same as « lucratif »."},{"w":"mercenary","p":"adj.","m":"Motivated primarily by money.","e":"Latin <i>mercenarius</i> (hired), from <i>merces</i> (wages).","f":"mercenaire, intéressé","t":"Same as « mercenaire »: acting only for the pay."},{"w":"metaphorical","p":"adj.","m":"Used in a figurative sense, not literal.","e":"Greek <i>metaphora</i>: <i>meta-</i> (across) + <i>pherein</i> (to carry).","f":"métaphorique","t":"Same as « métaphorique »."},{"w":"mimic","p":"v.","m":"To imitate, especially to ridicule.","e":"Greek <i>mimos</i> (imitator).","f":"imiter, singer","t":"Mimic = « mime »: act like someone else."},{"w":"numinous","p":"adj.","m":"Having a strong religious or spiritual quality; awe-inspiring.","e":"Latin <i>numen</i> (divine power).","f":"numineux, sacré","t":"Numen = divinity. Sensing a god in a cathedral."},{"w":"obeisance","p":"n.","m":"Deferential respect; a gesture of submission.","e":"Old French <i>obeissance</i>, from <i>obeir</i> (to obey).","f":"révérence, soumission","t":"Obéissance + « révérence »: a deep bow."},{"w":"partial","p":"adj.","m":"Existing only in part; biased, or fond of something.","e":"Medieval Latin <i>partialis</i>, from <i>pars</i> (part).","f":"partiel; partial, favorable à","x":"2nd meaning","t":"Three senses: incomplete (partiel), biased (partial), and « partial to » = fond of."},{"w":"pensive","p":"adj.","m":"Engaged in deep or serious thought.","e":"Old French <i>pensif</i>, from <i>penser</i> (to think).","f":"pensif, songeur","t":"Same as « pensif »."},{"w":"perilous","p":"adj.","m":"Full of danger or risk.","e":"Latin <i>periculosus</i>, from <i>periculum</i> (danger).","f":"périlleux","t":"Same as « périlleux »."},{"w":"peripheral","p":"adj.","m":"Of secondary importance; on the edge.","e":"Greek <i>peripheria</i>: <i>peri-</i> (around) + <i>pherein</i> (to carry).","f":"périphérique, secondaire","t":"Périphérique (le boulevard!) = the ring around the middle."},{"w":"portend","p":"v.","m":"To be an omen or warning of.","e":"Latin <i>portendere</i> (to point out, foretell): <i>por-</i> + <i>tendere</i>.","f":"présager, annoncer","t":"Same family as « portent » (a bad sign): dark clouds portend a storm."},{"w":"provocative","p":"adj.","m":"Causing a strong reaction, especially anger or arousal.","e":"Latin <i>provocativus</i>, from <i>provocare</i> (to call forth).","f":"provocant, provocateur","t":"Same as « provocant »."},{"w":"quirky","p":"adj.","m":"Characterized by peculiar or unconventional traits.","e":"From <i>quirk</i> (odd twist), origin uncertain.","f":"excentrique, original","t":"A quirk is a petite manie: a quirky sense of humour."},{"w":"rapacious","p":"adj.","m":"Aggressively greedy or grasping.","e":"Latin <i>rapax</i>, from <i>rapere</i> (to seize).","f":"rapace, avide","t":"Same as « rapace »: a bird of prey. Rapacious landlords seize everything."},{"w":"rational","p":"adj.","m":"Based on reason or logic.","e":"Latin <i>rationalis</i>, from <i>ratio</i> (reckoning, reason).","f":"rationnel","t":"Same as « rationnel »."},{"w":"relish","p":"v.","m":"To enjoy greatly.","e":"Old French <i>relais</i> (something left behind, a savour), from <i>relaisser</i>.","f":"savourer, se délecter de","t":"Relish a meal = savourer. (Also n.: a condiment.)"},{"w":"renounce","p":"v.","m":"To formally give up or reject.","e":"Latin <i>renuntiare</i> (to announce against): <i>re-</i> + <i>nuntiare</i>.","f":"renoncer à","t":"Same as « renoncer »."},{"w":"salutary","p":"adj.","m":"Beneficial, especially when unpleasant.","e":"Latin <i>salutaris</i>, from <i>salus</i> (health).","f":"salutaire","t":"Same as « salutaire »: a salutary lesson."},{"w":"satirical","p":"adj.","m":"Using irony or mockery to expose folly.","e":"Latin <i>satira</i> (a medley, mixed dish).","f":"satirique","t":"Same as « satirique »: Charlie Hebdo."},{"w":"scathing","p":"adj.","m":"Witheringly scornful; severely critical.","e":"Old Norse <i>skaða</i> (to harm). Germanic.","f":"cinglant, acerbe","t":"A scathing review leaves scars: « cinglant »."},{"w":"sever","p":"v.","m":"To cut off; to end a connection.","e":"Old French <i>sevrer</i> (to separate), Latin <i>separare</i>.","f":"couper, rompre; sevrer","t":"Related to « sevrer » and « séparer »: sever ties."},{"w":"sham","p":"n.","m":"Something fake presented as genuine.","e":"17th-century slang, perhaps a variant of <i>shame</i>.","f":"imposture, faux-semblant","t":"A sham marriage: a « mariage blanc ». A fake."},{"w":"skirt","p":"v.","m":"To avoid dealing with; to go around the edge of.","e":"Old Norse <i>skyrta</i> (shirt). Germanic.","f":"contourner, éluder","t":"The skirt is the edge of the garment: you go around the edge. Skirt the issue = contourner."},{"w":"sluggish","p":"adj.","m":"Slow-moving; lacking energy.","e":"From <i>slug</i>, Scandinavian <i>slugga</i> (to be slow).","f":"lent, apathique","t":"Like a slug (limace): a sluggish economy."},{"w":"somnolent","p":"adj.","m":"Sleepy; inducing drowsiness.","e":"Latin <i>somnolentus</i>, from <i>somnus</i> (sleep).","f":"somnolent","t":"Same as « somnolent »: somnus = sleep."},{"w":"stoic","p":"adj.","m":"Enduring pain or hardship without showing feelings.","e":"Greek <i>Stoikos</i>, from <i>stoa</i> (porch where Zeno taught).","f":"stoïque","t":"Same as « stoïque »."},{"w":"subtle","p":"adj.","m":"So delicate as to be difficult to analyze; clever and indirect.","e":"Latin <i>subtilis</i> (finely woven): <i>sub-</i> + <i>tela</i> (web).","f":"subtil, délicat","t":"Same as « subtil »: finely woven."},{"w":"superficial","p":"adj.","m":"Existing only on the surface; lacking depth.","e":"Latin <i>superficies</i>: <i>super-</i> + <i>facies</i> (face).","f":"superficiel","t":"Same as « superficiel »."},{"w":"tenable","p":"adj.","m":"Able to be defended against attack or objection.","e":"Old French <i>tenir</i> (to hold), Latin <i>tenere</i>.","f":"défendable, soutenable","t":"Tenable = « tenable »: a position you can hold. Untenable = indéfendable."},{"w":"turbulent","p":"adj.","m":"Characterized by conflict, disorder or confusion.","e":"Latin <i>turbulentus</i>, from <i>turba</i> (crowd, disorder).","f":"turbulent, agité","t":"Same as « turbulent »."},{"w":"wane","p":"v.","m":"To decrease gradually in size, strength or power.","e":"Old English <i>wanian</i> (to lessen). Germanic.","f":"décliner, décroître","t":"The moon wanes (« décroît »). Opposite: wax."}]},{"name":"GregMat III","slug":"gregmat-iii","series":"GregMat","words":[{"w":"abet","p":"v.","m":"To encourage or assist, typically in wrongdoing.","e":"Old French <i>abeter</i> (to bait, incite).","f":"encourager, soutenir (un délit)","t":"Aid and abet = « être complice »."},{"w":"accessible","p":"adj.","m":"Able to be reached or understood.","e":"Latin <i>accessibilis</i>, from <i>accedere</i> (to approach).","f":"accessible","t":"Same as « accessible »."},{"w":"acclaim","p":"v.","m":"To praise enthusiastically and publicly.","e":"Latin <i>acclamare</i>: <i>ad-</i> + <i>clamare</i> (to shout).","f":"acclamer, saluer","t":"Same as « acclamer »."},{"w":"acquisitive","p":"adj.","m":"Excessively interested in acquiring money or material things.","e":"Latin <i>acquirere</i> (to get).","f":"cupide, avide de possession","t":"Same as « acquisitif »: always wanting to buy more."},{"w":"alienate","p":"v.","m":"To make someone feel isolated or estranged.","e":"Latin <i>alienare</i>, from <i>alienus</i> (of another).","f":"aliéner, s'aliéner","t":"Same as « aliéner »: s'aliéner ses collègues."},{"w":"animus","p":"n.","m":"Hostility or ill feeling; a motivating spirit.","e":"Latin <i>animus</i> (mind, spirit, anger).","f":"animosité, hostilité","t":"Cousin of « animosité »: feeling of hostility. Animus toward a rival."},{"w":"apologist","p":"n.","m":"A person who offers a formal defence of a controversial idea or institution.","e":"Greek <i>apologia</i> (a speech in defence): <i>apo-</i> + <i>logos</i>.","f":"apologiste, défenseur","x":"Look-alike","t":"Not someone who says sorry! A defender: « un apologiste » of a regime."},{"w":"apropos","p":"adj.","m":"Very appropriate to a particular situation.","e":"French <i>à propos</i> (to the purpose).","f":"à propos, pertinent","t":"Straight from French « à propos »."},{"w":"apt","p":"adj.","m":"Appropriate or suitable; having a tendency to.","e":"Latin <i>aptus</i> (fitted).","f":"approprié; enclin à","x":"2nd meaning","t":"Apte = suitable. Also apt to (+ verb) = tends to."},{"w":"ascertain","p":"v.","m":"To find out for certain.","e":"Old French <i>acertener</i>, from <i>certain</i>.","f":"s'assurer de, établir","t":"A + certain: make certain. « S'assurer »."},{"w":"assertive","p":"adj.","m":"Having or showing a confident and forceful personality.","e":"Latin <i>asserere</i> (to claim): <i>ad-</i> + <i>serere</i> (to join).","f":"affirmé, assuré","t":"« Assertif ». Cousin of « assertion »."},{"w":"astringent","p":"adj.","m":"Sharp or severe in manner or style; causing tissues to contract.","e":"Latin <i>astringere</i> (to bind tight): <i>ad-</i> + <i>stringere</i>.","f":"astringent, âpre, mordant","t":"Same as « astringent »: tightens the skin; astringent wit is dry and cutting."},{"w":"aversion","p":"n.","m":"A strong dislike.","e":"Latin <i>aversio</i>, from <i>avertere</i> (to turn away).","f":"aversion, répugnance","t":"Same as « aversion »."},{"w":"bogus","p":"adj.","m":"Not genuine; fake.","e":"19th-century American slang, origin uncertain.","f":"faux, bidon","t":"« Bidon »: a bogus claim."},{"w":"cataclysmic","p":"adj.","m":"Relating to a violent upheaval or disaster.","e":"Greek <i>kataklysmos</i> (flood): <i>kata-</i> + <i>klyzein</i> (to wash).","f":"cataclysmique, catastrophique","t":"Same as « cataclysme »: a flood."},{"w":"cloak","p":"v.","m":"To cover or hide.","e":"Old French <i>cloque</i> (bell-shaped cape), Latin <i>clocca</i> (bell).","f":"dissimuler, masquer","t":"Cloche: a cloak hangs like a bell. Cloaked in secrecy."},{"w":"collaborate","p":"v.","m":"To work jointly on an activity.","e":"Latin <i>collaborare</i>: <i>com-</i> + <i>laborare</i> (to work).","f":"collaborer","t":"Same as « collaborer »."},{"w":"competent","p":"adj.","m":"Having the necessary ability or skill.","e":"Latin <i>competere</i> (to be suitable).","f":"compétent","t":"Same as « compétent »."},{"w":"comply","p":"v.","m":"To act in accordance with a wish or command.","e":"Latin <i>complere</i> (to fulfil), via Italian <i>complire</i>.","f":"se conformer à, obtempérer","t":"Comply with rules = « se conformer »."},{"w":"consensus","p":"n.","m":"General agreement.","e":"Latin <i>consensus</i>, from <i>consentire</i> (to feel together).","f":"consensus","t":"Same as « consensus »."},{"w":"contempt","p":"n.","m":"The feeling that something is worthless.","e":"Latin <i>contemptus</i>, from <i>contemnere</i> (to despise).","f":"mépris","t":"Same as « contempt » root (contemptible). « Mépris »."},{"w":"correlate","p":"v.","m":"To have a mutual relationship or connection.","e":"Latin <i>com-</i> + <i>relatus</i> (related).","f":"être corrélé, mettre en corrélation","t":"Same as « corréler »."},{"w":"curtail","p":"v.","m":"To reduce in extent or quantity; to cut short.","e":"Old French <i>courtault</i> (docked), from <i>court</i> (short).","f":"réduire, écourter","t":"« Court »: make it short. Curtail spending."},{"w":"dictate","p":"v.","m":"To lay down authoritatively; to say aloud for writing down.","e":"Latin <i>dictare</i> (to say often), from <i>dicere</i> (to say).","f":"dicter, imposer","t":"Same as « dicter »: dictate terms = imposer ses conditions."},{"w":"distort","p":"v.","m":"To pull out of shape; to misrepresent.","e":"Latin <i>distorquere</i>: <i>dis-</i> + <i>torquere</i> (to twist).","f":"déformer, fausser","t":"Same as « distordre / distorsion »."},{"w":"divergent","p":"adj.","m":"Tending to be different or develop in different directions.","e":"Latin <i>divergere</i>: <i>dis-</i> + <i>vergere</i> (to incline).","f":"divergent","t":"Same as « divergent »."},{"w":"divorced","p":"adj.","m":"Separated from; no longer connected (to).","e":"Latin <i>divortium</i>, from <i>divertere</i> (to turn aside).","f":"divorcé; coupé de, détaché de","x":"2nd meaning","t":"Figuratively: divorced from reality = « coupé de la réalité »."},{"w":"elated","p":"adj.","m":"Extremely happy and excited.","e":"Latin <i>elatus</i> (lifted up), from <i>efferre</i>.","f":"enthousiaste, ravi","t":"Lifted up by joy: « exalté »."},{"w":"elitist","p":"adj.","m":"Believing a select group deserves influence or privilege.","e":"French <i>élite</i>, from Latin <i>eligere</i> (to choose out).","f":"élitiste","t":"Same as « élitiste »."},{"w":"enchant","p":"v.","m":"To fill with great delight; to put under a spell.","e":"Latin <i>incantare</i> (to sing a spell over): <i>in-</i> + <i>cantare</i>.","f":"enchanter","t":"Same as « enchanter »: sing a spell."},{"w":"evade","p":"v.","m":"To escape or avoid, especially by cleverness or trickery.","e":"Latin <i>evadere</i> (to go out): <i>e-</i> + <i>vadere</i> (to go).","f":"éluder, échapper à","t":"Cousin of « s'évader » (escape). Evade taxes = fraude fiscale."},{"w":"exotic","p":"adj.","m":"Originating in a distant foreign country; striking.","e":"Greek <i>exōtikos</i> (from outside), <i>exō</i>.","f":"exotique","t":"Same as « exotique »."},{"w":"exploitative","p":"adj.","m":"Making use of a situation or person unfairly for one's own advantage.","e":"French <i>exploiter</i>, Latin <i>explicare</i> (to unfold).","f":"abusif, d'exploitation","t":"Cognate « exploiter » in the negative sense (exploiter des travailleurs)."},{"w":"fester","p":"v.","m":"To become worse or more intense, especially through neglect.","e":"Old French <i>festre</i> (ulcer), Latin <i>fistula</i> (ulcer).","f":"suppurer, s'envenimer","t":"« S'envenimer »: a festering wound or dispute."},{"w":"flummoxed","p":"adj.","m":"Perplexed; bewildered.","e":"19th-century English slang, origin unknown.","f":"déconcerté, perplexe","t":"Sounds like a mess: a flummoxed student staring at a trick question."},{"w":"foreseeable","p":"adj.","m":"Able to be anticipated.","e":"<i>fore-</i> (before) + <i>see</i> + <i>-able</i>. Germanic.","f":"prévisible","t":"See before: « prévisible ». In the foreseeable future = dans un avenir prévisible."},{"w":"forsake","p":"v.","m":"To abandon; to give up.","e":"Old English <i>forsacan</i>: <i>for-</i> + <i>sacan</i> (to contend). Germanic.","f":"abandonner, délaisser","t":"For + sake: renounce. Forsaken = délaissé."},{"w":"fruitful","p":"adj.","m":"Producing good results; productive.","e":"<i>fruit</i> (Latin <i>fructus</i>) + <i>-ful</i>.","f":"fructueux, productif","t":"« Fructueux »: a fruitful meeting bears fruit."},{"w":"gratify","p":"v.","m":"To give pleasure or satisfaction to.","e":"Latin <i>gratificari</i>, from <i>gratus</i> (pleasing).","f":"satisfaire, gratifier","t":"Same as « gratifier »: gratify a desire."},{"w":"heed","p":"v.","m":"To pay attention to.","e":"Old English <i>hēdan</i>. Germanic.","f":"tenir compte de, écouter","t":"Heed a warning = tenir compte d'un avertissement."},{"w":"hinder","p":"v.","m":"To create difficulties for; to delay.","e":"Old English <i>hindrian</i> (to hold back). Germanic.","f":"entraver, gêner","t":"Stands behind you (hind): holds you back."},{"w":"impair","p":"v.","m":"To weaken or damage, especially a faculty.","e":"Old French <i>empeirer</i>, Latin <i>pejorare</i> (to make worse).","f":"affaiblir, altérer","t":"Cousin of « empirer » and « pire »: make worse. Impaired vision."},{"w":"improvise","p":"v.","m":"To create and perform spontaneously, without preparation.","e":"Latin <i>improvisus</i> (unforeseen): <i>in-</i> + <i>pro-</i> + <i>videre</i>.","f":"improviser","t":"Same as « improviser »."},{"w":"inborn","p":"adj.","m":"Existing from birth; natural.","e":"<i>in-</i> + <i>born</i>. Germanic.","f":"inné","t":"Born in: « inné », not learned."},{"w":"inclined","p":"adj.","m":"Having a tendency; willing.","e":"Latin <i>inclinare</i>: <i>in-</i> + <i>clinare</i> (to lean).","f":"enclin, porté à","t":"Same as « incliné »: leaning toward."},{"w":"inhibit","p":"v.","m":"To hinder, restrain or prevent.","e":"Latin <i>inhibere</i> (to hold in).","f":"inhiber, entraver","t":"Same as « inhiber »."},{"w":"miserly","p":"adj.","m":"Unwilling to spend; ungenerously small.","e":"Latin <i>miser</i> (wretched).","f":"avare, mesquin","t":"Not « misérable »! A miser: Harpagon in L'Avare."},{"w":"monotonous","p":"adj.","m":"Dull, tedious and repetitious.","e":"Greek <i>monotonos</i>: <i>mono-</i> (one) + <i>tonos</i> (tone).","f":"monotone","t":"Mono + tone: one tone. Same as « monotone »."},{"w":"peculiar","p":"adj.","m":"Strange or odd; characteristic of one.","e":"Latin <i>peculiaris</i> (of private property), from <i>pecu</i> (cattle).","f":"bizarre, particulier","t":"Cattle = private wealth: something belonging to you alone. « Particulier ». Peculiar to = propre à."},{"w":"pliant","p":"adj.","m":"Easily bent; easily influenced.","e":"Old French <i>plier</i> (to fold), Latin <i>plicare</i>.","f":"souple, docile","t":"Plier: foldable. A pliant mind obeys."},{"w":"polymath","p":"n.","m":"A person of wide knowledge or learning.","e":"Greek <i>polymathēs</i>: <i>poly-</i> (many) + <i>manthanein</i> (to learn).","f":"polymathe, esprit universel","t":"Poly (many) + math (learning): Leonardo da Vinci."},{"w":"premeditate","p":"v.","m":"To think out or plan beforehand.","e":"Latin <i>praemeditari</i>: <i>prae-</i> + <i>meditari</i>.","f":"préméditer","t":"Same as « préméditer »."},{"w":"refine","p":"v.","m":"To remove impurities; to improve by small changes.","e":"<i>re-</i> + <i>fine</i>, French <i>raffiner</i>.","f":"raffiner, affiner","t":"Same as « raffiner / affiner »."},{"w":"relinquish","p":"v.","m":"To voluntarily cease to keep or claim.","e":"Latin <i>relinquere</i> (to leave behind).","f":"abandonner, renoncer à","t":"Cousin of « relique »: what is left behind. Relinquish power."},{"w":"sensational","p":"adj.","m":"Causing great public interest; of outstanding quality.","e":"Latin <i>sensatio</i>, from <i>sensus</i> (feeling).","f":"sensationnel; à sensation","t":"Same as « sensationnel »: sensational journalism = journalisme à sensation."},{"w":"skittish","p":"adj.","m":"Nervous or excitable; easily scared.","e":"Middle English, probably Scandinavian <i>skyt-</i> (to shoot).","f":"nerveux, ombrageux, craintif","t":"A skittish horse jumps at shadows: « ombrageux »."},{"w":"sophisticated","p":"adj.","m":"Developed to a high degree of complexity; worldly and refined.","e":"Medieval Latin <i>sophisticare</i> (to adulterate), Greek <i>sophistēs</i>.","f":"sophistiqué, raffiné","t":"Same as « sophistiqué »."},{"w":"sound","p":"adj.","m":"In good condition; based on valid reasoning.","e":"Old English <i>gesund</i> (healthy). Germanic.","f":"sain, solide, valable","x":"2nd meaning","t":"« Sain »: a sound argument, sound judgement. Safe and sound."},{"w":"strife","p":"n.","m":"Angry or bitter disagreement over fundamental issues.","e":"Old French <i>estrif</i> (quarrel).","f":"conflit, discorde","t":"Cousin of « s'efforcer » via 'strive'. Conflict."},{"w":"subservient","p":"adj.","m":"Prepared to obey others unquestioningly.","e":"Latin <i>subservire</i>: <i>sub-</i> + <i>servire</i> (to serve).","f":"servile, soumis","t":"Sub + serve: serving from below. « Servile »."},{"w":"synoptic","p":"adj.","m":"Taking a comprehensive view; giving a general summary.","e":"Greek <i>synoptikos</i>: <i>syn-</i> (together) + <i>opsis</i> (view).","f":"synoptique","t":"Same as « synoptique »: seen together."},{"w":"tantalizing","p":"adj.","m":"Teasing with something desirable but out of reach.","e":"From <i>Tantalus</i>, Greek myth: punished with water and fruit just out of reach.","f":"tentant, aguichant","t":"Tantale in French! Le supplice de Tantale: see it, can't have it."},{"w":"tepid","p":"adj.","m":"Slightly warm; lacking enthusiasm.","e":"Latin <i>tepidus</i>, from <i>tepere</i> (to be warm).","f":"tiède","t":"Same as « tiède »: a tepid reception."},{"w":"thorough","p":"adj.","m":"Complete with regard to every detail.","e":"Old English <i>thuruh</i>, a form of <i>through</i>. Germanic.","f":"minutieux, approfondi","t":"Through-and-through: « minutieux »."},{"w":"understated","p":"adj.","m":"Presented in a subtle, restrained way.","e":"<i>under-</i> + <i>state</i>. Germanic.","f":"discret, sobre","t":"Stated under: « sobre ». An understated elegance."},{"w":"versatile","p":"adj.","m":"Able to adapt to many functions.","e":"Latin <i>versatilis</i>, from <i>versare</i> (to turn).","f":"polyvalent, souple","x":"Faux ami","t":"« Versatile » in French means fickle (changeable). English: flexible, many-skilled."},{"w":"vexation","p":"n.","m":"The state of being annoyed or worried.","e":"Latin <i>vexatio</i>, from <i>vexare</i> (to harass).","f":"contrariété, irritation","t":"Same as « vexation » (but milder than in French)."},{"w":"visionary","p":"adj.","m":"Thinking about the future with imagination.","e":"Latin <i>visio</i> (sight), from <i>videre</i>.","f":"visionnaire","t":"Same as « visionnaire »."},{"w":"wayward","p":"adj.","m":"Difficult to control because of unpredictable behaviour.","e":"Middle English, short for <i>awayward</i> (turned away).","f":"capricieux, rebelle","t":"Turned away from the way: a wayward teenager."}]},{"name":"GregMat IV","slug":"gregmat-iv","series":"GregMat","words":[{"w":"abject","p":"adj.","m":"Extremely bad; showing hopelessness or humiliation.","e":"Latin <i>abjectus</i> (cast away): <i>ab-</i> + <i>jacere</i>.","f":"abject, misérable","t":"Same as « abject ». Abject poverty."},{"w":"abreast","p":"adv.","m":"Up to date with; side by side.","e":"<i>a-</i> + <i>breast</i>. Germanic.","f":"au courant de; de front","t":"Keep abreast of the news = rester au courant."},{"w":"acolyte","p":"n.","m":"An assistant or follower.","e":"Greek <i>akolouthos</i> (follower), via Latin <i>acolythus</i>.","f":"acolyte","t":"Same as « acolyte » (in English with a mild negative tone)."},{"w":"amicable","p":"adj.","m":"Characterized by friendliness; without ill feeling.","e":"Latin <i>amicabilis</i>, from <i>amicus</i> (friend).","f":"amical, à l'amiable","t":"« Amical ». An amicable divorce = divorce à l'amiable."},{"w":"anoint","p":"v.","m":"To smear with oil, as a rite; to choose officially.","e":"Latin <i>inungere</i> (to smear on).","f":"oindre; désigner","t":"Same as « oindre ». An heir anointed as successor."},{"w":"arresting","p":"adj.","m":"Striking; capturing the attention.","e":"Old French <i>arester</i> (to stop), Latin <i>arrestare</i>.","f":"saisissant, frappant","t":"It stops you in your tracks: an arresting photograph."},{"w":"barrage","p":"n.","m":"A concentrated outpouring (of questions, criticism); heavy artillery fire.","e":"French <i>barrage</i> (barrier), from <i>barrer</i>.","f":"avalanche, déluge; tir de barrage","t":"Un barrage: like a dam bursting. A barrage of questions."},{"w":"coercion","p":"n.","m":"Persuasion by force or threats.","e":"Latin <i>coercere</i> (to restrain).","f":"coercition, contrainte","t":"Same as « coercition »."},{"w":"coin","p":"v.","m":"To invent a new word or phrase.","e":"Old French <i>coing</i> (wedge, stamp for minting money).","f":"inventer (un mot), forger","x":"Look-alike","t":"Not « coin » (corner)! Coin a term = forger. Money is struck with a coin die."},{"w":"cunning","p":"adj.","m":"Skilled in deceit; clever in achieving one's ends.","e":"Old English <i>cunnan</i> (to know). Germanic.","f":"rusé, malin","t":"Fox-like: « rusé »."},{"w":"dawdle","p":"v.","m":"To waste time; to move slowly.","e":"17th-century English, possibly related to <i>daddle</i> (to walk unsteadily).","f":"traîner, lambiner","t":"Don't dawdle: « ne traîne pas »."},{"w":"decipher","p":"v.","m":"To succeed in understanding or reading something unclear.","e":"<i>de-</i> + <i>cipher</i> (Arabic <i>ṣifr</i>, zero/code).","f":"déchiffrer","t":"Same as « déchiffrer »."},{"w":"deflect","p":"v.","m":"To cause to change direction; to turn aside.","e":"Latin <i>deflectere</i>: <i>de-</i> + <i>flectere</i> (to bend).","f":"dévier, détourner","t":"Same as « défléchir / déflexion ». Deflect criticism = détourner."},{"w":"delusion","p":"n.","m":"A false belief held despite contrary evidence.","e":"Latin <i>deludere</i> (to mock): <i>de-</i> + <i>ludere</i> (to play).","f":"illusion, délire","t":"« Délire ». Delusions of grandeur = folie des grandeurs."},{"w":"digression","p":"n.","m":"A temporary departure from the main subject.","e":"Latin <i>digredi</i> (to step aside).","f":"digression","t":"Same as « digression »."},{"w":"discomfit","p":"v.","m":"To make uneasy or confused.","e":"Old French <i>desconfit</i> (defeated), Latin <i>deficere</i>.","f":"décontenancer, déconcerter","t":"Related to « déconfit »: defeated and embarrassed. Discomfit ≠ discomfort."},{"w":"discount","p":"v.","m":"To regard as unlikely or unworthy of consideration; to reduce the price of.","e":"Old French <i>desconter</i>: <i>des-</i> + <i>conter</i> (to count).","f":"ne pas tenir compte de; escompter","x":"2nd meaning","t":"Discount a rumour = ignore it. Beyond price cuts: « ne pas tenir compte »."},{"w":"dispense","p":"v.","m":"To distribute; (dispense with) to do without.","e":"Latin <i>dispensare</i> (to weigh out).","f":"distribuer; se passer de","x":"2nd meaning","t":"Dispense with formalities = se passer des formalités. Dispenser = distributeur."},{"w":"dissident","p":"n.","m":"One who opposes official policy.","e":"Latin <i>dissidere</i> (to sit apart): <i>dis-</i> + <i>sedere</i>.","f":"dissident","t":"Same as « dissident »: sits apart."},{"w":"distill","p":"v.","m":"To purify a liquid; to extract the essential meaning of.","e":"Latin <i>destillare</i> (to drip down): <i>de-</i> + <i>stilla</i> (drop).","f":"distiller; extraire l'essentiel","t":"Same as « distiller »: drops. Distill a report into key points."},{"w":"duplicitous","p":"adj.","m":"Deceitful; double-dealing.","e":"Latin <i>duplicitas</i>, from <i>duplex</i> (twofold).","f":"fourbe, hypocrite","t":"Duplex = two-faced. Duplicité in French has the same sense."},{"w":"economy","p":"n.","m":"Careful management of resources; thrift.","e":"Greek <i>oikonomia</i>: <i>oikos</i> (house) + <i>nomos</i> (management).","f":"économie, parcimonie","x":"2nd meaning","t":"Beyond GDP: economy of words = brièveté, économie de moyens."},{"w":"elementary","p":"adj.","m":"Relating to the basic, simplest parts.","e":"Latin <i>elementarius</i>, from <i>elementum</i>.","f":"élémentaire","t":"Same as « élémentaire »: « Élémentaire, mon cher Watson »."},{"w":"euphoric","p":"adj.","m":"Characterized by intense excitement and happiness.","e":"Greek <i>euphoria</i>: <i>eu-</i> (well) + <i>pherein</i> (to bear).","f":"euphorique","t":"Same as « euphorique »."},{"w":"fabricate","p":"v.","m":"To invent (something false); to make or manufacture.","e":"Latin <i>fabricare</i>, from <i>fabrica</i> (workshop).","f":"fabriquer; inventer","x":"2nd meaning","t":"Fabriquer. A fabricated story is invented from scratch."},{"w":"fallible","p":"adj.","m":"Capable of making mistakes.","e":"Latin <i>fallere</i> (to deceive).","f":"faillible","t":"Same as « faillible »: capable of faillir."},{"w":"falter","p":"v.","m":"To start to lose strength; to speak hesitatingly.","e":"Middle English, possibly Scandinavian.","f":"faiblir, vaciller, hésiter","t":"Falter = vaciller. His voice faltered."},{"w":"fervent","p":"adj.","m":"Having or displaying passionate intensity.","e":"Latin <i>fervere</i> (to boil).","f":"fervent","t":"Same as « fervent »."},{"w":"fortitude","p":"n.","m":"Courage in pain or adversity.","e":"Latin <i>fortitudo</i>, from <i>fortis</i> (strong).","f":"courage, force d'âme","t":"Same family as « fort »."},{"w":"gawky","p":"adj.","m":"Nervously awkward and ungainly.","e":"17th-century English, from <i>gawk</i> (a fool), possibly Scandinavian.","f":"dégingandé, gauche","t":"Tall, gauche and clumsy: « dégingandé »."},{"w":"glum","p":"adj.","m":"Looking or feeling dejected.","e":"Probably from <i>gloom</i>. Germanic.","f":"morose, abattu","t":"Gloomy: « avoir le moral dans les chaussettes »."},{"w":"harbinger","p":"n.","m":"A person or thing that announces the approach of something.","e":"Old French <i>herberger</i> (to lodge), an advance officer arranging lodging.","f":"signe avant-coureur, précurseur","t":"Originally the scout who finds you a bed (auberge). Swallows are a harbinger of spring."},{"w":"heterodox","p":"adj.","m":"Not conforming to accepted standards or beliefs.","e":"Greek <i>heterodoxos</i>: <i>heteros</i> (other) + <i>doxa</i> (opinion).","f":"hétérodoxe","t":"Same as « hétérodoxe »; opposite: orthodox."},{"w":"inform","p":"v.","m":"(inform on/against) To betray; (inform) to give shape or character to.","e":"Latin <i>informare</i> (to shape, give form).","f":"dénoncer; informer; imprégner","x":"2nd meaning","t":"inform on someone = « dénoncer ». Also: a decision informed by data."},{"w":"irksome","p":"adj.","m":"Irritating; tedious.","e":"Middle English <i>irken</i> (to tire).","f":"agaçant, pénible","t":"It irks me: « ça m'agace ». An irksome chore."},{"w":"largesse","p":"n.","m":"Generosity in bestowing gifts or money.","e":"Old French <i>largesse</i>, from <i>large</i> (generous).","f":"largesse, générosité","t":"Same as « largesse »."},{"w":"liability","p":"n.","m":"A person or thing that causes problems; legal responsibility; a debt.","e":"From <i>liable</i>, French <i>lier</i> (to bind), Latin <i>ligare</i>.","f":"handicap, passif; responsabilité","x":"2nd meaning","t":"Opposite of an asset. Un handicap / « passif ». Product liability = responsabilité du fait des produits."},{"w":"libertine","p":"n.","m":"A person who behaves without moral restraint.","e":"Latin <i>libertinus</i> (freedman), from <i>liber</i> (free).","f":"libertin","t":"Same as « libertin »: Dom Juan."},{"w":"manacle","p":"n.","m":"A metal chain for the hands; (v.) to restrain.","e":"Latin <i>manicula</i> (little hand), from <i>manus</i>.","f":"menotte, entrave","t":"Latin manus (hand): « menotte »."},{"w":"manifest","p":"adj.","m":"Clear and obvious; (v.) to display.","e":"Latin <i>manifestus</i> (caught in the act, plain).","f":"manifeste, évident","t":"Same as « manifeste ». Manifest destiny."},{"w":"meritorious","p":"adj.","m":"Deserving reward or praise.","e":"Latin <i>meritorius</i>, from <i>merere</i> (to earn).","f":"méritoire","t":"Same as « méritoire »."},{"w":"minute","p":"adj.","m":"Extremely small; very precise (pronounced my-NYOOT).","e":"Latin <i>minutus</i> (made small).","f":"minuscule, minutieux","x":"2nd meaning","t":"Not the time unit: mi-NUTE = tiny, « minutieux ». Minute details."},{"w":"modest","p":"adj.","m":"Unassuming; moderate or limited in size.","e":"Latin <i>modestus</i> (moderate), from <i>modus</i> (measure).","f":"modeste","t":"Same as « modeste »: a modest salary is of limited size."},{"w":"mutiny","p":"n.","m":"An open rebellion against authority, especially by sailors.","e":"Old French <i>mutin</i> (rebellious), Latin <i>movere</i> (to move).","f":"mutinerie","t":"Same as « mutinerie »."},{"w":"noble","p":"adj.","m":"Having fine personal qualities or high social rank.","e":"Latin <i>nobilis</i> (well known, of high birth).","f":"noble","t":"Same as « noble »."},{"w":"noxious","p":"adj.","m":"Harmful, poisonous or very unpleasant.","e":"Latin <i>noxius</i>, from <i>noxa</i> (harm).","f":"nocif, nuisible","t":"Same family as « nocif ». Noxious fumes."},{"w":"perseverance","p":"n.","m":"Persistence in doing something despite difficulty.","e":"Latin <i>perseverare</i>: <i>per-</i> + <i>severus</i> (strict).","f":"persévérance","t":"Same as « persévérance »."},{"w":"predicament","p":"n.","m":"A difficult, unpleasant situation.","e":"Late Latin <i>praedicamentum</i> (category), from <i>praedicare</i>.","f":"situation difficile, dilemme","t":"« Prédicament » is not French. Think « pétrin »: in a predicament."},{"w":"prime","p":"adj.","m":"Of first importance; main.","e":"Latin <i>primus</i> (first).","f":"principal, premier","t":"Prime minister: « Premier ministre »."},{"w":"proficient","p":"adj.","m":"Competent or skilled.","e":"Latin <i>proficere</i> (to make progress): <i>pro-</i> + <i>facere</i>.","f":"compétent, doué","t":"Pro + facere: progress as a pro. Proficient in French."},{"w":"prolix","p":"adj.","m":"Using too many words; tediously lengthy.","e":"Latin <i>prolixus</i> (extended).","f":"prolixe, verbeux","t":"Same as « prolixe »: a verbose essay."},{"w":"prowess","p":"n.","m":"Skill or expertise; bravery in battle.","e":"Old French <i>proesce</i>, from <i>prou</i> (valiant).","f":"prouesse, talent","t":"Same as « prouesse »."},{"w":"radical","p":"adj.","m":"Fundamental; far-reaching; extreme.","e":"Latin <i>radicalis</i>, from <i>radix</i> (root).","f":"radical, fondamental","t":"Same as « radical »: from the root. Radical reform."},{"w":"render","p":"v.","m":"To cause to be or become; to provide or give.","e":"Old French <i>rendre</i>, Latin <i>reddere</i>.","f":"rendre, rendre (un jugement)","t":"Same as « rendre »: render someone speechless."},{"w":"repertoire","p":"n.","m":"The stock of skills or pieces a person is prepared to perform.","e":"Latin <i>repertorium</i> (inventory).","f":"répertoire","t":"Same as « répertoire »."},{"w":"resilient","p":"adj.","m":"Able to recover quickly; flexible.","e":"Latin <i>resilire</i> (to leap back): <i>re-</i> + <i>salire</i>.","f":"résilient, qui a du ressort","t":"Same as « résilient »: bounces back."},{"w":"resolute","p":"adj.","m":"Admirably purposeful and determined.","e":"Latin <i>resolutus</i> (loosened, settled), from <i>resolvere</i>.","f":"résolu, déterminé","t":"Same as « résolu »."},{"w":"schism","p":"n.","m":"A split between strongly opposed groups.","e":"Greek <i>skhisma</i> (cleft), from <i>skhizein</i> (to split).","f":"schisme","t":"Same as « schisme »: schizo = split."},{"w":"scorn","p":"n.","m":"Contempt or disdain.","e":"Old French <i>escarn</i>, Germanic origin.","f":"mépris, dédain","t":"Cousin of « escarnir »: to treat with scorn. « Mépriser » = to scorn."},{"w":"slander","p":"n.","m":"The making of a false spoken statement damaging to a person's reputation.","e":"Old French <i>esclandre</i>, Latin <i>scandalum</i> (scandal).","f":"calomnie, diffamation","t":"« Esclandre »: scandal → slander."},{"w":"stinting","p":"adj.","m":"Restricting an allowance; frugal.","e":"Old English <i>styntan</i> (to blunt). Germanic.","f":"parcimonieux, chiche","t":"Not stinging! Stinting = skimping. Opposite of lavish: « sans lésiner » = unstinting."},{"w":"subordinate","p":"adj.","m":"Lower in rank or importance.","e":"Latin <i>sub-</i> + <i>ordinare</i> (to order).","f":"subordonné","t":"Same as « subordonné »."},{"w":"supple","p":"adj.","m":"Bending and moving easily and gracefully.","e":"Old French <i>souple</i>, Latin <i>supplex</i> (bending).","f":"souple","t":"« Souple » → supple."},{"w":"temper","p":"v.","m":"To moderate or mitigate; (n.) disposition or anger.","e":"Latin <i>temperare</i> (to mix in due proportion).","f":"tempérer, modérer","x":"2nd meaning","t":"Same as « tempérer ». Temper enthusiasm with caution. Also a bad temper."},{"w":"temporal","p":"adj.","m":"Relating to time; worldly, not spiritual.","e":"Latin <i>temporalis</i>, from <i>tempus</i> (time).","f":"temporel","t":"Same as « temporel »: temporal power opposes spiritual power."},{"w":"tentative","p":"adj.","m":"Not certain or fixed; hesitant.","e":"Latin <i>tentare</i> (to try).","f":"provisoire, hésitant","x":"Faux ami","t":"Not « tentative » (an attempt, a try). Tentative plans = provisoire, sous réserve."},{"w":"universal","p":"adj.","m":"Applicable to all cases; relating to everyone.","e":"Latin <i>universalis</i>, from <i>universus</i> (whole).","f":"universel","t":"Same as « universel »."},{"w":"valor","p":"n.","m":"Great courage in the face of danger.","e":"Latin <i>valor</i>, from <i>valere</i> (to be strong).","f":"bravoure, vaillance","t":"Same as « valeur » (in the old sense). « Valeureux »."},{"w":"woeful","p":"adj.","m":"Very sad; deplorably bad.","e":"<i>woe</i> (Old English <i>wā</i>) + <i>-ful</i>.","f":"lamentable, déplorable","t":"Full of woe (malheur). Woeful performance = pitoyable."}]},{"name":"GregMat V","slug":"gregmat-v","series":"GregMat","words":[{"w":"adept","p":"adj.","m":"Very skilled; proficient.","e":"Latin <i>adeptus</i> (having attained).","f":"expert, habile","x":"Faux ami","t":"« Adepte » = follower. English: an adept = someone skilled at something."},{"w":"adverse","p":"adj.","m":"Harmful or unfavourable.","e":"Latin <i>adversus</i> (turned against).","f":"défavorable, néfaste","x":"Look-alike","t":"Not « adverse » (opponent). Adverse effects, adverse weather = conditions défavorables. Not 'averse'."},{"w":"allusive","p":"adj.","m":"Making indirect reference to something.","e":"Latin <i>alludere</i> (to play with): <i>ad-</i> + <i>ludere</i>.","f":"allusif","t":"Same as « allusif / allusion »."},{"w":"archetype","p":"n.","m":"A very typical example; an original model.","e":"Greek <i>arkhetypon</i>: <i>arkhe-</i> (first) + <i>typos</i> (model).","f":"archétype","t":"Same as « archétype »."},{"w":"ardent","p":"adj.","m":"Enthusiastic or passionate.","e":"Latin <i>ardere</i> (to burn).","f":"ardent","t":"Same as « ardent »."},{"w":"astute","p":"adj.","m":"Having the ability to assess situations accurately; shrewd.","e":"Latin <i>astutus</i>, from <i>astus</i> (cunning).","f":"astucieux, perspicace","t":"Cousin of « astucieux »: an astute investor."},{"w":"axiomatic","p":"adj.","m":"Self-evident or unquestionable.","e":"Greek <i>axiōma</i> (that which is thought worthy).","f":"axiomatique, évident","t":"Same as « axiome »: no proof needed."},{"w":"benevolent","p":"adj.","m":"Well meaning and kindly.","e":"Latin <i>bene</i> (well) + <i>velle</i> (to wish).","f":"bienveillant","t":"Bene + volent = « bienveillant »: wishing well."},{"w":"berate","p":"v.","m":"To scold or criticize angrily.","e":"<i>be-</i> + <i>rate</i> (to scold), perhaps Scandinavian.","f":"réprimander sévèrement, rabrouer","t":"Be-rate: dressing someone down. Not related to « rate » (tax)."},{"w":"buoyant","p":"adj.","m":"Able to float; cheerful and optimistic.","e":"Spanish <i>boyante</i>, from <i>boya</i> (buoy).","f":"flottant; optimiste, allègre","x":"2nd meaning","t":"Une bouée floats: buoyant mood. Also a buoyant market is rising."},{"w":"cease","p":"v.","m":"To come or bring to an end.","e":"Old French <i>cesser</i>, Latin <i>cessare</i>.","f":"cesser","t":"Same as « cesser »."},{"w":"commence","p":"v.","m":"To begin.","e":"Old French <i>comencier</i>, Latin <i>cum-</i> + <i>initiare</i>.","f":"commencer","t":"Same as « commencer »."},{"w":"conclusive","p":"adj.","m":"Decisive; ending all doubt.","e":"Latin <i>concludere</i> (to close).","f":"concluant, probant","t":"Un résultat concluant."},{"w":"condone","p":"v.","m":"To accept or allow behaviour that is wrong.","e":"Latin <i>condonare</i> (to give away): <i>con-</i> + <i>donare</i>.","f":"cautionner, excuser, fermer les yeux sur","x":"Look-alike","t":"Donner: you give it a pass. Not 'approve': condone = tolerate wrong."},{"w":"conspire","p":"v.","m":"To make secret plans jointly for an unlawful act.","e":"Latin <i>conspirare</i> (to breathe together).","f":"conspirer, comploter","t":"Same as « conspirer »: breathe together."},{"w":"contravene","p":"v.","m":"To violate a law or rule.","e":"Latin <i>contravenire</i> (to come against): <i>contra</i> + <i>venire</i>.","f":"enfreindre, contrevenir à","t":"Same as « contrevenir »: contravene a law."},{"w":"convalescent","p":"adj.","m":"Recovering from illness.","e":"Latin <i>convalescere</i> (to grow strong).","f":"convalescent","t":"Same as « convalescent »."},{"w":"corporeal","p":"adj.","m":"Relating to a person's body; tangible.","e":"Latin <i>corporeus</i>, from <i>corpus</i> (body).","f":"corporel","t":"Same as « corporel »."},{"w":"curb","p":"v.","m":"To restrain or keep in check.","e":"Old French <i>courber</i> (to bend), Latin <i>curvus</i>.","f":"freiner, juguler","t":"Same family as « courber »: a curb on a horse is a strap. Curb inflation."},{"w":"denounce","p":"v.","m":"To publicly declare to be wrong or evil.","e":"Latin <i>denuntiare</i> (to announce).","f":"dénoncer","t":"Same as « dénoncer »."},{"w":"despotic","p":"adj.","m":"Exercising absolute power in a cruel way.","e":"Greek <i>despotēs</i> (master).","f":"despotique","t":"Same as « despotique »."},{"w":"deviate","p":"v.","m":"To depart from an established course.","e":"Latin <i>deviare</i>: <i>de-</i> + <i>via</i> (road).","f":"dévier, s'écarter","t":"Same as « dévier »: off the road."},{"w":"disentangle","p":"v.","m":"To free from entanglement; to untangle.","e":"<i>dis-</i> + <i>entangle</i>.","f":"démêler","t":"« Démêler ». Disentangle fact from fiction."},{"w":"doctrinaire","p":"adj.","m":"Seeking to impose a doctrine without regard to practical considerations.","e":"French <i>doctrinaire</i>, from <i>doctrine</i>.","f":"doctrinaire, dogmatique","t":"Same as « doctrinaire »."},{"w":"escalate","p":"v.","m":"To increase rapidly; to become more intense.","e":"From <i>escalator</i>, Latin <i>scala</i> (ladder).","f":"s'intensifier, monter en puissance","t":"Escalier: step up. A conflict escalates = « s'envenime »."},{"w":"evoke","p":"v.","m":"To bring a feeling or memory to mind.","e":"Latin <i>evocare</i> (to call out): <i>e-</i> + <i>vocare</i>.","f":"évoquer","t":"Same as « évoquer »."},{"w":"exorcise","p":"v.","m":"To drive out an evil spirit; to get rid of a painful memory.","e":"Greek <i>exorkizein</i> (to bind by oath).","f":"exorciser","t":"Same as « exorciser »."},{"w":"figurative","p":"adj.","m":"Departing from literal meaning; metaphorical.","e":"Latin <i>figurativus</i>, from <i>figura</i> (shape).","f":"figuré","t":"Au sens figuré. Opposite: literal."},{"w":"finicky","p":"adj.","m":"Fussy about details; hard to please.","e":"From <i>finical</i>, probably from <i>fine</i>.","f":"tatillon, pointilleux, difficile","t":"Finicky about food: « difficile »; about details: « tatillon »."},{"w":"flustered","p":"adj.","m":"Agitated and confused.","e":"Scandinavian origin (cf. Icelandic <i>flaustr</i>, hurry).","f":"troublé, déboussolé","t":"A flustered speaker loses the thread: « décontenancé »."},{"w":"foil","p":"v.","m":"To prevent from succeeding.","e":"Old French <i>fouler</i> (to trample), Latin <i>fullo</i> (fuller).","f":"déjouer, faire échouer","t":"Foil a plot = déjouer un complot. (Also n.: a contrasting character.)"},{"w":"frailty","p":"n.","m":"Weakness; vulnerability.","e":"Old French <i>fraileté</i>, Latin <i>fragilis</i> (breakable).","f":"fragilité, faiblesse","t":"Frail = « frêle » = fragile."},{"w":"fret","p":"v.","m":"To be constantly or visibly anxious.","e":"Old English <i>fretan</i> (to devour). Germanic.","f":"se tracasser, s'inquiéter","t":"Worry eats at you. Don't fret = ne t'en fais pas."},{"w":"grievance","p":"n.","m":"A real or imagined cause for complaint.","e":"Old French <i>grever</i> (to burden), Latin <i>gravare</i>.","f":"doléance, grief","t":"« Grief » (also in French legal speak): a heavy burden. Cousin of « grave »."},{"w":"headstrong","p":"adj.","m":"Wilful and obstinate.","e":"<i>head</i> + <i>strong</i>. Germanic.","f":"têtu, entêté","t":"Strong in the head: « têtu »."},{"w":"idiosyncratic","p":"adj.","m":"Peculiar or individual to one person.","e":"Greek <i>idiosunkrasia</i>: <i>idios</i> (own) + <i>sunkrasis</i> (mixture).","f":"idiosyncrasique, particulier","t":"Same as « idiosyncrasie »: your own mix."},{"w":"incidental","p":"adj.","m":"Happening as a minor accompaniment; secondary.","e":"Latin <i>incidens</i> (falling upon).","f":"accessoire, secondaire","t":"Related to « incident ». Incidental expenses = frais accessoires."},{"w":"intertwined","p":"adj.","m":"Twisted together; closely connected.","e":"<i>inter-</i> + <i>twine</i>. Germanic.","f":"entrelacé, étroitement lié","t":"Entrelacés."},{"w":"ire","p":"n.","m":"Anger.","e":"Latin <i>ira</i> (anger).","f":"colère, courroux","t":"Cousin of « irascible »: ira = anger."},{"w":"ironclad","p":"adj.","m":"Impossible to break or change.","e":"<i>iron</i> + <i>clad</i> (clothed). Germanic.","f":"inattaquable, en béton","t":"Clad in iron: an ironclad contract is airtight. « Blindé »."},{"w":"jeopardize","p":"v.","m":"To put at risk of harm or failure.","e":"Old French <i>jeu parti</i> (divided game, even chances).","f":"mettre en danger, compromettre","t":"« Jeu parti »: a gamble with even odds. Jeopardy = péril."},{"w":"lull","p":"v.","m":"To calm or send to sleep; (n.) a pause.","e":"Imitative of lullaby sounds (<i>lulla</i>).","f":"bercer, apaiser; accalmie","t":"Lullaby: lull a baby; a lull in the storm = « accalmie »."},{"w":"neutralize","p":"v.","m":"To render ineffective by countering.","e":"French <i>neutraliser</i>, Latin <i>neuter</i> (neither).","f":"neutraliser","t":"Same as « neutraliser »."},{"w":"oblivious","p":"adj.","m":"Not aware of or concerned about what is happening around.","e":"Latin <i>obliviosus</i>, from <i>oblivio</i> (forgetfulness).","f":"inconscient de, indifférent","t":"Same family as « oubli / oblivion »."},{"w":"perpetrate","p":"v.","m":"To carry out a harmful or illegal act.","e":"Latin <i>perpetrare</i> (to accomplish).","f":"perpétrer, commettre","t":"Same as « perpétrer ». The perpetrator = auteur du crime."},{"w":"plaintive","p":"adj.","m":"Sounding sad and mournful.","e":"Old French <i>plaintif</i>, from <i>plaindre</i>.","f":"plaintif","t":"Same as « plaintif »."},{"w":"poise","p":"n.","m":"Graceful, self-assured balance in manner.","e":"Old French <i>peser</i> (to weigh), Latin <i>pensare</i>.","f":"aplomb, assurance","t":"Poids → balance: « avoir de l'aplomb »."},{"w":"pomposity","p":"n.","m":"Self-importance; ostentatious speech.","e":"Latin <i>pomposus</i>, from <i>pompa</i> (procession).","f":"emphase, grandiloquence","t":"Same as « pompeux / pompe ». Pompous."},{"w":"pretentious","p":"adj.","m":"Attempting to impress by affecting greater importance than is possessed.","e":"Latin <i>praetendere</i> (to put forward).","f":"prétentieux","t":"Same as « prétentieux »."},{"w":"profound","p":"adj.","m":"Very great or intense; having great depth.","e":"Latin <i>profundus</i> (deep): <i>pro-</i> + <i>fundus</i> (bottom).","f":"profond","t":"Same as « profond »."},{"w":"proxy","p":"n.","m":"The authority to represent someone else; a stand-in.","e":"Contraction of <i>procuracy</i>, Latin <i>procurare</i> (to take care of).","f":"procuration, mandataire","t":"Proxy = « procuration ». Use as a proxy for."},{"w":"ramification","p":"n.","m":"A consequence of an action; a branching out.","e":"Latin <i>ramus</i> (branch).","f":"ramification, conséquence","t":"Same as « ramification »: ramus = branch. Ramifications are consequences that branch out."},{"w":"recourse","p":"n.","m":"A source of help in a difficult situation; resort.","e":"Latin <i>recursus</i> (a running back): <i>re-</i> + <i>currere</i>.","f":"recours","t":"Same as « recours »: avoir recours à. Without recourse = sans recours."},{"w":"regress","p":"v.","m":"To return to a former, less developed state.","e":"Latin <i>regredi</i> (to step back): <i>re-</i> + <i>gradi</i>.","f":"régresser, rétrograder","t":"Opposite of progress: « régresser »."},{"w":"reiterate","p":"v.","m":"To say again for emphasis.","e":"Latin <i>reiterare</i>: <i>re-</i> + <i>iterum</i> (again).","f":"réitérer","t":"Same as « réitérer »."},{"w":"relent","p":"v.","m":"To yield after initially refusing.","e":"Latin <i>re-</i> + <i>lentus</i> (slow, soft).","f":"fléchir, se radoucir","t":"Cousin of « ralentir ». Soften your stance: « céder »."},{"w":"repercussion","p":"n.","m":"An unintended consequence.","e":"Latin <i>repercussio</i> (rebound): <i>re-</i> + <i>percutere</i> (to strike).","f":"répercussion, conséquence","t":"Same as « répercussion ». Usually plural: repercussions."},{"w":"replenish","p":"v.","m":"To fill up again.","e":"Old French <i>replenir</i>, Latin <i>plenus</i> (full).","f":"réapprovisionner, remplir à nouveau","t":"Re + plein: fill again. Cousin of « plénitude »."},{"w":"rigor","p":"n.","m":"The quality of being extremely thorough and strict.","e":"Latin <i>rigor</i> (stiffness).","f":"rigueur","t":"Same as « rigueur »."},{"w":"sparse","p":"adj.","m":"Thinly dispersed or scattered.","e":"Latin <i>sparsus</i> (scattered), from <i>spargere</i>.","f":"clairsemé, épars","t":"Same as « épars »: sparse vegetation."},{"w":"surmount","p":"v.","m":"To overcome (a difficulty); to be on top of.","e":"Old French <i>surmonter</i>: <i>sur-</i> + <i>monter</i>.","f":"surmonter","t":"Same as « surmonter »."},{"w":"suspect","p":"adj.","m":"Open to doubt; possibly dishonest.","e":"Latin <i>suspectus</i>, from <i>suspicere</i> (to look up at).","f":"suspect, douteux","t":"Same as « suspect »."},{"w":"tedious","p":"adj.","m":"Too long, slow or dull.","e":"Latin <i>taedium</i> (weariness).","f":"fastidieux, ennuyeux","t":"Same as « fastidieux »; not « tédieux »."},{"w":"transcend","p":"v.","m":"To go beyond the range or limits of.","e":"Latin <i>transcendere</i> (to climb over).","f":"transcender, dépasser","t":"Same as « transcender »."},{"w":"treatise","p":"n.","m":"A formal written work dealing systematically with a subject.","e":"Old French <i>tretiz</i>, from Latin <i>tractare</i> (to handle).","f":"traité","t":"« Un traité » de philosophie."},{"w":"vigilant","p":"adj.","m":"Keeping careful watch for danger.","e":"Latin <i>vigilare</i> (to stay awake).","f":"vigilant","t":"Same as « vigilant »."},{"w":"vitality","p":"n.","m":"The state of being strong and active.","e":"Latin <i>vita</i> (life).","f":"vitalité","t":"Same as « vitalité »."},{"w":"vivacious","p":"adj.","m":"Attractively lively and animated.","e":"Latin <i>vivax</i> (lively), from <i>vivere</i> (to live).","f":"vif, plein d'entrain","t":"Same family as « vivace / vivacité »."},{"w":"yield","p":"v.","m":"To produce; to give way.","e":"Old English <i>gieldan</i> (to pay). Germanic.","f":"produire, rapporter; céder","x":"2nd meaning","t":"Rendement (n.). Yield to pressure = céder. Yield returns = rapporter."}]},{"name":"GregMat VI","slug":"gregmat-vi","series":"GregMat","words":[{"w":"abide","p":"v.","m":"To tolerate; to accept or follow (rules).","e":"Old English <i>ābīdan</i> (to wait). Germanic.","f":"supporter, tolérer; respecter","x":"2nd meaning","t":"Can't abide = ne supporte pas. Abide by the rules = respecter."},{"w":"abstract","p":"adj.","m":"Existing in thought rather than as a concrete thing.","e":"Latin <i>abstractus</i> (drawn away): <i>abs-</i> + <i>trahere</i>.","f":"abstrait","t":"Same as « abstrait »."},{"w":"affront","p":"n.","m":"An action that causes offence.","e":"Old French <i>afronter</i> (to slap in the face), Latin <i>ad frontem</i>.","f":"affront, offense","t":"Same as « affront »: a slap in the front/face."},{"w":"aghast","p":"adj.","m":"Filled with horror or shock.","e":"Middle English <i>agasten</i> (to terrify), related to <i>ghost</i>.","f":"consterné, horrifié","t":"As if you've seen a ghost: « sidéré »."},{"w":"agitate","p":"v.","m":"To disturb or excite; to campaign.","e":"Latin <i>agitare</i> (to drive), from <i>agere</i>.","f":"agiter; faire campagne","t":"Same as « agiter »."},{"w":"antagonize","p":"v.","m":"To provoke hostility in someone.","e":"Greek <i>antagōnizesthai</i>: <i>anti-</i> + <i>agōnizesthai</i> (to struggle).","f":"s'aliéner, provoquer l'hostilité de","t":"Cousin of « antagoniste ». Don't antagonize the client."},{"w":"apprise","p":"v.","m":"To inform or tell someone of something.","e":"French <i>apprendre</i> (to learn, to teach), past participle <i>appris</i>.","f":"informer, mettre au courant","x":"Look-alike","t":"Not « apprécier »! Apprise = « mettre au courant ». Apprise him of the facts."},{"w":"aspersion","p":"n.","m":"An attack on someone's reputation (usually: cast aspersions).","e":"Latin <i>aspergere</i> (to sprinkle).","f":"calomnie, insinuation","t":"Sprinkle mud on someone's name: cast aspersions on."},{"w":"barren","p":"adj.","m":"Too poor to produce much or any vegetation; unproductive.","e":"Old French <i>baraigne</i> (sterile, of land or women).","f":"stérile, aride","t":"Think « bréhaigne » (old: sterile). Barren desert = désert aride."},{"w":"bawdy","p":"adj.","m":"Humorously indecent.","e":"From <i>bawd</i> (brothel keeper), Old French <i>baud</i> (merry).","f":"grivois, salé","t":"Rabelais! A bawdy tale = histoire grivoise."},{"w":"beguile","p":"v.","m":"To charm or enchant; to deceive.","e":"<i>be-</i> + Old French <i>guile</i> (deceit).","f":"séduire, charmer; tromper","x":"2nd meaning","t":"Guile: ruse. Beguiled by a smile = séduit. Also beguile into = tromper."},{"w":"bravado","p":"n.","m":"A bold manner intended to impress; false courage.","e":"Spanish <i>bravada</i>, from <i>bravo</i>.","f":"bravade, fanfaronnade","t":"Same as « bravade »."},{"w":"burnish","p":"v.","m":"To polish by rubbing.","e":"Old French <i>burnir</i> (to make brown, polish), from <i>brun</i>.","f":"polir, brunir","t":"« Brunir »: to polish metal until it shines. Burnish an image."},{"w":"cajole","p":"v.","m":"To persuade by sustained coaxing or flattery.","e":"French <i>cajoler</i> (to chatter like a jay), from <i>gaiole</i> (cage).","f":"cajoler, enjôler","t":"Same as « cajoler »: coax with sweet words."},{"w":"callous","p":"adj.","m":"Showing insensitive disregard for others.","e":"Latin <i>callosus</i> (thick-skinned), from <i>callum</i> (hard skin).","f":"insensible, cruel","t":"Un cal(lus) on the heart: thick skin."},{"w":"collude","p":"v.","m":"To cooperate secretly for illegal ends.","e":"Latin <i>colludere</i> (to play together).","f":"être de connivence, s'entendre","t":"Same as « collusion »."},{"w":"commiserate","p":"v.","m":"To express sympathy or pity.","e":"Latin <i>commiserari</i>: <i>com-</i> + <i>miser</i> (wretched).","f":"compatir, plaindre","t":"Commisérer. Share someone's misery."},{"w":"contretemps","p":"n.","m":"An unexpected and awkward occurrence.","e":"French <i>contretemps</i> (against the time).","f":"contretemps","t":"Straight from French « contretemps »."},{"w":"conviction","p":"n.","m":"A firmly held belief; a formal declaration of guilt.","e":"Latin <i>convictio</i>, from <i>convincere</i> (to overcome).","f":"conviction; condamnation","x":"2nd meaning","t":"« Conviction » = belief. Also a criminal conviction = condamnation."},{"w":"coy","p":"adj.","m":"Making a pretence of shyness; reluctant to give details.","e":"Old French <i>coi</i> (quiet), Latin <i>quietus</i>.","f":"faussement timide, évasif","t":"« Coi » (se tenir coi). Coy about the salary = évasif."},{"w":"croon","p":"v.","m":"To sing softly in a low voice.","e":"Middle Dutch <i>kronen</i> (to lament).","f":"fredonner, chanter doucement","t":"Frank Sinatra, the crooner."},{"w":"deportment","p":"n.","m":"Behaviour or manners; bearing.","e":"French <i>déportement</i>, Latin <i>deportare</i>.","f":"maintien, tenue","t":"Not « déportation »! Deportment = bearing, comportement."},{"w":"depose","p":"v.","m":"To remove from office; to testify under oath.","e":"Old French <i>deposer</i>, <i>de-</i> + <i>poser</i>.","f":"destituer; déposer","t":"Same as « déposer »: put down the ruler."},{"w":"deprecate","p":"v.","m":"To express disapproval of; to belittle (self-deprecating).","e":"Latin <i>deprecari</i> (to pray against).","f":"désapprouver, minimiser","x":"Look-alike","t":"Not depreciate (lose value). Self-deprecating humour belittles oneself: « autodérision »."},{"w":"detente","p":"n.","m":"The easing of strained relations.","e":"French <i>détente</i> (relaxation).","f":"détente","t":"Straight from French « détente »."},{"w":"dirge","p":"n.","m":"A lament for the dead; a mournful song.","e":"Latin <i>dirige</i> (direct!), the first word of the Office of the Dead.","f":"chant funèbre, complainte","t":"Latin dirige (“guide”): opening of a funeral prayer. A dirge = funeral song."},{"w":"disdain","p":"n.","m":"The feeling that someone is unworthy of respect.","e":"Old French <i>desdeignier</i>, Latin <i>dedignari</i> (to reject as unworthy).","f":"dédain","t":"Same as « dédain »."},{"w":"disperse","p":"v.","m":"To go in different directions.","e":"Latin <i>dispergere</i>: <i>dis-</i> + <i>spargere</i> (to scatter).","f":"disperser, se disperser","t":"Same as « disperser »."},{"w":"dowdy","p":"adj.","m":"Unfashionable and drab.","e":"Middle English <i>doude</i> (slut/drab woman), origin unknown.","f":"sans élégance, mal fagoté","t":"Dull dress: « mal fagoté »."},{"w":"echelon","p":"n.","m":"A level or rank in an organization.","e":"French <i>échelon</i> (rung of a ladder), from <i>échelle</i>.","f":"échelon, niveau","t":"Same as « échelon »: upper echelons of management."},{"w":"ennui","p":"n.","m":"Listlessness arising from boredom.","e":"French <i>ennui</i>, Latin <i>in odio</i> (in hatred).","f":"ennui, lassitude","t":"Straight from French: « l'ennui » (stronger in English)."},{"w":"expatiate","p":"v.","m":"To speak or write at length on a subject.","e":"Latin <i>exspatiari</i> (to wander): <i>ex-</i> + <i>spatium</i>.","f":"s'étendre sur, développer longuement","x":"Look-alike","t":"Not « expatriate » (live abroad). Expatiate = « s'étendre » on a subject."},{"w":"extemporize","p":"v.","m":"To speak or perform without preparation.","e":"Latin <i>ex tempore</i> (out of the moment).","f":"improviser","t":"Ex tempore: out of the moment."},{"w":"fallow","p":"adj.","m":"(Of land) ploughed but left unplanted; inactive.","e":"Old English <i>fealh</i> (ploughed land).","f":"en jachère, inactif","t":"Jachère. A fallow period for the mind."},{"w":"feint","p":"n.","m":"A deceptive movement intended to distract.","e":"Old French <i>feinte</i>, from <i>feindre</i>.","f":"feinte","t":"Same as « feinte » in boxing and fencing."},{"w":"flagrant","p":"adj.","m":"Conspicuously offensive; blatant.","e":"Latin <i>flagrare</i> (to blaze).","f":"flagrant","t":"« Flagrant délit »: caught in the act."},{"w":"fraught","p":"adj.","m":"Filled with (something undesirable); causing anxiety.","e":"Middle Dutch <i>vracht</i> (freight). Germanic.","f":"chargé de, tendu","t":"Freight: loaded with. A fraught meeting is « chargé de tension »."},{"w":"fulcrum","p":"n.","m":"The point on which a lever rests; the pivot of an activity.","e":"Latin <i>fulcrum</i> (bedpost), from <i>fulcire</i> (to support).","f":"point d'appui, pivot","t":"Archimède: the pivot of a lever."},{"w":"gratuitous","p":"adj.","m":"Uncalled for; lacking good reason.","e":"Latin <i>gratuitus</i> (free).","f":"gratuit, injustifié","x":"2nd meaning","t":"Not 'free of charge' here: gratuit = for no reason. Gratuitous violence = violence gratuite, injustifiée."},{"w":"heady","p":"adj.","m":"Intoxicating; exhilarating.","e":"From <i>head</i>. Germanic.","f":"grisant, enivrant","t":"Goes to your head: « grisant ». Heady perfume, heady days."},{"w":"hysterical","p":"adj.","m":"Exhibiting wildly uncontrolled emotion; extremely funny.","e":"Greek <i>hystera</i> (womb), from old medical theory.","f":"hystérique; à mourir de rire","x":"2nd meaning","t":"Hysterical laughter = fou rire. A hysterical comedy is hilarious."},{"w":"intrigue","p":"v.","m":"To arouse curiosity; to plot secretly.","e":"French <i>intriguer</i>, Latin <i>intricare</i> (to entangle).","f":"intriguer, comploter","t":"Same as « intriguer »."},{"w":"jocund","p":"adj.","m":"Cheerful and lighthearted.","e":"Latin <i>jocundus</i>, variant of <i>jucundus</i> (pleasant).","f":"jovial, enjoué","t":"Jocund = jovial; same joke (jocus) root as « jouer »."},{"w":"lambaste","p":"v.","m":"To criticize harshly.","e":"<i>lam</i> (to beat) + <i>baste</i> (to thrash). Germanic.","f":"éreinter, fustiger","t":"Beat + beat: verbally. « Éreinter » a film."},{"w":"nimble","p":"adj.","m":"Quick and light in movement.","e":"Old English <i>nǣmel</i> (quick to grasp). Germanic.","f":"agile, leste","t":"Nimble fingers: « agile »."},{"w":"nominal","p":"adj.","m":"Existing in name only; very small (of a fee).","e":"Latin <i>nominalis</i>, from <i>nomen</i> (name).","f":"nominal, symbolique","x":"2nd meaning","t":"For a nominal fee = une somme symbolique. Nominal leader: leader in name only."},{"w":"odious","p":"adj.","m":"Extremely unpleasant; repulsive.","e":"Latin <i>odiosus</i>, from <i>odium</i> (hatred).","f":"odieux","t":"Same as « odieux »."},{"w":"ominous","p":"adj.","m":"Giving the impression that something bad will happen.","e":"Latin <i>ominosus</i>, from <i>omen</i>.","f":"menaçant, de mauvais augure","t":"An omen: « de mauvais augure »."},{"w":"outlandish","p":"adj.","m":"Looking or sounding bizarre or unfamiliar.","e":"Old English <i>ūtlendisc</i> (foreign): <i>ūt</i> + <i>land</i>. Germanic.","f":"extravagant, bizarre","t":"From outside the land: weird."},{"w":"peccadillo","p":"n.","m":"A small, minor sin or fault.","e":"Spanish <i>pecadillo</i>, diminutive of <i>pecado</i> (sin), Latin <i>peccare</i>.","f":"peccadille, faute vénielle","t":"Same as « peccadille »: a little pécher."},{"w":"quarantine","p":"n.","m":"A period of isolation to prevent the spread of disease.","e":"Italian <i>quaranta giorni</i> (forty days).","f":"quarantaine","t":"Same as « quarantaine »: forty days (quarante)."},{"w":"quash","p":"v.","m":"To reject as invalid; to put an end to.","e":"Old French <i>quasser</i> (to annul), Latin <i>quassare</i>.","f":"annuler, étouffer, réprimer","t":"Casser! Quash a verdict = casser un jugement; quash a rebellion."},{"w":"quibble","p":"v.","m":"To argue about trivial matters.","e":"Probably from Latin <i>quibus</i> (to whom), legal jargon pun.","f":"chicaner, ergoter","t":"Quibble = ergoter. Don't quibble over details."},{"w":"ravage","p":"v.","m":"To cause severe damage to.","e":"Old French <i>ravir</i> (to seize).","f":"ravager, dévaster","t":"Same as « ravager »."},{"w":"remuneration","p":"n.","m":"Payment for work done.","e":"Latin <i>remunerari</i> (to reward).","f":"rémunération","t":"Same as « rémunération »."},{"w":"repugnant","p":"adj.","m":"Extremely distasteful; unacceptable.","e":"Latin <i>repugnare</i> (to fight against).","f":"répugnant, repoussant","t":"Same as « répugnant »."},{"w":"sadistic","p":"adj.","m":"Deriving pleasure from inflicting pain.","e":"From the Marquis de <i>Sade</i>.","f":"sadique","t":"Same as « sadique » — named for the French marquis."},{"w":"shrill","p":"adj.","m":"High-pitched and piercing.","e":"Middle English <i>shrille</i>, imitative.","f":"strident, perçant","t":"Hear the shriek: « strident »."},{"w":"slovenly","p":"adj.","m":"Untidy and dirty; careless.","e":"Possibly Flemish <i>sloef</i> (dirty).","f":"négligé, débraillé","t":"Un « souillon ». A slovenly appearance."},{"w":"soliloquy","p":"n.","m":"An act of speaking one's thoughts aloud when alone.","e":"Latin <i>solus</i> (alone) + <i>loqui</i> (to speak).","f":"monologue, soliloque","t":"Hamlet’s « To be or not to be »."},{"w":"sophistry","p":"n.","m":"The use of clever but misleading arguments.","e":"Greek <i>sophistēs</i> (a clever person).","f":"sophisme, argutie","t":"Same as « sophisme »: clever but misleading."},{"w":"swindle","p":"v.","m":"To use deception to deprive of money or possessions.","e":"German <i>schwindeln</i> (to be dizzy, to cheat).","f":"escroquer, arnaquer","t":"Swindler: « escroc »."},{"w":"tangible","p":"adj.","m":"Perceptible by touch; real and concrete.","e":"Latin <i>tangere</i> (to touch).","f":"tangible, palpable","t":"Same as « tangible »."},{"w":"unalloyed","p":"adj.","m":"Complete; not mixed with anything.","e":"<i>un-</i> + <i>alloy</i> (metal mix), Old French <i>aloyer</i>.","f":"pur, sans mélange","t":"« Alliage »: no alloy. Unalloyed joy = joie pure."},{"w":"undercut","p":"v.","m":"To weaken; to offer lower prices than a competitor.","e":"<i>under</i> + <i>cut</i>. Germanic.","f":"saper, mettre à mal; casser les prix","t":"Cut from beneath: it « sape » the argument."},{"w":"verve","p":"n.","m":"Vigour, spirit and style in writing or performance.","e":"French <i>verve</i> (enthusiasm).","f":"verve","t":"Same as « verve »."},{"w":"wheedle","p":"v.","m":"To persuade by flattery or coaxing.","e":"Possibly German <i>wedeln</i> (to wag the tail, fawn).","f":"enjôler, cajoler","t":"A dog wagging its tail: wheedle a treat out of you."},{"w":"wily","p":"adj.","m":"Skilled at gaining an advantage by deceit.","e":"From <i>wile</i> (trick), Old French <i>guile</i>.","f":"rusé, malicieux","t":"Wile E. Coyote. « Rusé »."},{"w":"xenophobic","p":"adj.","m":"Having a fear or dislike of strangers or foreigners.","e":"Greek <i>xenos</i> (stranger) + <i>phobos</i> (fear).","f":"xénophobe","t":"Same as « xénophobe »."}]},{"name":"GregMat VII","slug":"gregmat-vii","series":"GregMat","words":[{"w":"abrasive","p":"adj.","m":"Harsh and rough in manner; capable of scraping.","e":"Latin <i>abradere</i> (to scrape away).","f":"abrasif, rugueux, cassant","t":"Same as « abrasif »: an abrasive personality grates."},{"w":"allegorical","p":"adj.","m":"Having a hidden meaning, typically moral or political.","e":"Greek <i>allēgoria</i>: <i>allos</i> (other) + <i>agoreuein</i> (to speak).","f":"allégorique","t":"Same as « allégorique »: speaks of another thing."},{"w":"allude","p":"v.","m":"To suggest or call attention to indirectly.","e":"Latin <i>alludere</i> (to play with).","f":"faire allusion à","t":"Same as « faire allusion »."},{"w":"amplify","p":"v.","m":"To increase in volume or effect.","e":"Latin <i>amplificare</i>, from <i>amplus</i> (large).","f":"amplifier","t":"Same as « amplifier »."},{"w":"auxiliary","p":"adj.","m":"Providing supplementary support.","e":"Latin <i>auxiliarius</i>, from <i>auxilium</i> (help).","f":"auxiliaire","t":"Same as « auxiliaire »."},{"w":"brevity","p":"n.","m":"Concise and exact use of words.","e":"Latin <i>brevis</i> (short).","f":"brièveté","t":"Same as « brièveté »."},{"w":"caricature","p":"n.","m":"A grotesque exaggeration of a person's features.","e":"Italian <i>caricatura</i> (loading), from <i>caricare</i>.","f":"caricature","t":"Same as « caricature »."},{"w":"catastrophic","p":"adj.","m":"Involving sudden great damage or suffering.","e":"Greek <i>katastrophē</i> (overturning).","f":"catastrophique","t":"Same as « catastrophique »."},{"w":"circumstantial","p":"adj.","m":"Pointing indirectly to a conclusion; based on circumstances.","e":"Latin <i>circumstare</i> (to stand around).","f":"circonstanciel; indirect","t":"Circumstantial evidence = preuves indirectes."},{"w":"coddle","p":"v.","m":"To treat in an indulgent or overprotective way.","e":"Possibly from <i>caudle</i>, a warm drink for invalids; Latin <i>calidus</i> (warm).","f":"dorloter, chouchouter","t":"« Dorloter »: coddle a child."},{"w":"contemporary","p":"adj.","m":"Living or occurring at the same time; modern.","e":"Latin <i>con-</i> + <i>tempus</i> (time).","f":"contemporain; actuel","t":"Same as « contemporain »."},{"w":"counterfeit","p":"adj.","m":"Made in exact imitation to deceive; forged.","e":"Old French <i>contrefait</i>.","f":"contrefait, faux","t":"Same as « contrefaçon » / « contrefait »: counterfeit money = fausse monnaie."},{"w":"crescendo","p":"n.","m":"A gradual increase in loudness or intensity.","e":"Italian <i>crescendo</i>, from Latin <i>crescere</i> (to grow).","f":"crescendo","t":"Same as « crescendo »."},{"w":"defame","p":"v.","m":"To damage the good reputation of.","e":"Latin <i>diffamare</i> (to spread evil report): <i>dis-</i> + <i>fama</i>.","f":"diffamer","t":"Same as « diffamer »."},{"w":"depravity","p":"n.","m":"Moral corruption.","e":"Latin <i>depravare</i> (to make crooked).","f":"dépravation, perversion","t":"Same as « dépravation »."},{"w":"detract","p":"v.","m":"To diminish the value of.","e":"Latin <i>detrahere</i> (to draw away).","f":"enlever de la valeur, rabaisser","t":"Detractors drag you down. « Détracteur »."},{"w":"devious","p":"adj.","m":"Showing a skilful use of underhand tactics; roundabout.","e":"Latin <i>devius</i> (off the road): <i>de-</i> + <i>via</i>.","f":"retors, tortueux","t":"Off the road: a « chemin détourné »."},{"w":"disciple","p":"n.","m":"A follower of a teacher, leader or philosophy.","e":"Latin <i>discipulus</i> (learner), from <i>discere</i>.","f":"disciple","t":"Same as « disciple »."},{"w":"dormant","p":"adj.","m":"Temporarily inactive; asleep.","e":"Latin <i>dormire</i> (to sleep).","f":"en sommeil, dormant","t":"Same as « dormant » (volcan dormant)."},{"w":"draconian","p":"adj.","m":"Excessively harsh and severe (of laws).","e":"From <i>Draco</i>, Athenian lawgiver (7th c. BC).","f":"draconien","t":"Same as « draconien »."},{"w":"encroach","p":"v.","m":"To intrude on a territory or right.","e":"Old French <i>encrochier</i> (to seize), from <i>croc</i> (hook).","f":"empiéter sur","t":"« Empiéter »: use a hook to grab. Encroach on one's rights."},{"w":"endow","p":"v.","m":"To provide with a quality or a source of income.","e":"Old French <i>endouer</i>, Latin <i>dotare</i> (to give a dowry).","f":"doter","t":"Same as « doter »: un don, a dot. Endowed with talent = doté."},{"w":"entreat","p":"v.","m":"To ask earnestly or anxiously.","e":"Old French <i>entraiter</i> (to treat), from <i>traiter</i>.","f":"supplier, implorer","t":"« Supplier ». Entreat him to stay."},{"w":"erstwhile","p":"adj.","m":"Former.","e":"Old English <i>ǣrest</i> (earliest) + <i>while</i>. Germanic.","f":"ancien, d'autrefois","t":"« Jadis »: his erstwhile friend."},{"w":"extol","p":"v.","m":"To praise enthusiastically.","e":"Latin <i>extollere</i> (to raise up).","f":"louer, exalter","t":"Raise up with praise. Cousin of « exalter »."},{"w":"forebode","p":"v.","m":"To predict or have a presentiment of evil.","e":"<i>fore-</i> + <i>bode</i> (Old English <i>bodian</i>, announce). Germanic.","f":"présager, pressentir","t":"A bad omen: « pressentir » le pire. Foreboding."},{"w":"fringe","p":"n.","m":"The outer edge; a minority group beyond the mainstream.","e":"Old French <i>frenge</i>, Latin <i>fimbria</i> (fibre, fringe).","f":"frange, marge","t":"« Frange »: the fringe of society = en marge."},{"w":"gloat","p":"v.","m":"To dwell on one's own success or another's misfortune with smugness.","e":"Possibly Scandinavian <i>glotta</i> (to grin).","f":"jubiler, se réjouir mesquinement","t":"« Jubiler » méchamment. Don't gloat."},{"w":"harrowing","p":"adj.","m":"Acutely distressing.","e":"From <i>harrow</i> (a farm tool tearing up soil). Germanic.","f":"éprouvant, déchirant","t":"Like a rake tearing at the earth: « déchirant »."},{"w":"ideologue","p":"n.","m":"An adherent of an ideology, especially a dogmatic one.","e":"French <i>idéologue</i>, from Greek <i>idea</i> + <i>-logos</i>.","f":"idéologue","t":"Same as « idéologue »."},{"w":"immaculate","p":"adj.","m":"Perfectly clean, neat or tidy; free from flaws.","e":"Latin <i>immaculatus</i>: <i>in-</i> + <i>macula</i> (spot).","f":"immaculé, impeccable","t":"« L'Immaculée Conception »: no spot."},{"w":"impediment","p":"n.","m":"A hindrance or obstruction.","e":"Latin <i>impedimentum</i>, from <i>impedire</i> (to shackle the feet).","f":"obstacle, empêchement","t":"Feet bound (pes, pedis). Speech impediment = défaut d'élocution."},{"w":"imperative","p":"adj.","m":"Of vital importance; compulsory.","e":"Latin <i>imperativus</i>, from <i>imperare</i> (to command).","f":"impératif, indispensable","t":"Same as « impératif »."},{"w":"impulsive","p":"adj.","m":"Acting without forethought.","e":"Latin <i>impulsivus</i>, from <i>impellere</i> (to push).","f":"impulsif","t":"Same as « impulsif »."},{"w":"indefinite","p":"adj.","m":"Lasting for an unspecified time; vague.","e":"Latin <i>indefinitus</i>: <i>in-</i> + <i>definire</i>.","f":"indéfini, indéterminé","t":"Same as « indéfini »: an indefinite strike (grève illimitée)."},{"w":"indictment","p":"n.","m":"A formal charge; a sign that something is bad.","e":"Anglo-French <i>enditement</i>, Latin <i>indictare</i>.","f":"mise en accusation; réquisitoire","x":"2nd meaning","t":"Figurative: a damning indictment of the system = un réquisitoire."},{"w":"ingenious","p":"adj.","m":"Clever, original and inventive.","e":"Latin <i>ingeniosus</i>, from <i>ingenium</i> (talent).","f":"ingénieux","t":"Same as « ingénieux »; not ingenuous (naïve)."},{"w":"inquisitive","p":"adj.","m":"Curious, prying, asking too many questions.","e":"Latin <i>inquirere</i> (to seek into).","f":"curieux, indiscret","t":"« Inquisitif » is rare: use « curieux »."},{"w":"interminable","p":"adj.","m":"Endless (often tediously).","e":"Latin <i>interminabilis</i>: <i>in-</i> + <i>terminare</i>.","f":"interminable","t":"Same as « interminable »."},{"w":"intuitive","p":"adj.","m":"Using instinct rather than conscious reasoning.","e":"Latin <i>intueri</i> (to look at).","f":"intuitif","t":"Same as « intuitif »."},{"w":"keen","p":"adj.","m":"Eager; sharp (of senses or edges).","e":"Old English <i>cēne</i> (bold, brave). Germanic.","f":"enthousiaste, vif, aiguisé","t":"Keen on = passionné par. Keen eyesight = vue perçante."},{"w":"latitude","p":"n.","m":"Scope for freedom of action or thought.","e":"Latin <i>latitudo</i>, from <i>latus</i> (wide).","f":"latitude, liberté d'action","t":"Same as « latitude »: a wide berth. Latitude to decide."},{"w":"mediate","p":"v.","m":"To intervene between disputing parties.","e":"Latin <i>mediare</i> (to be in the middle).","f":"servir de médiateur, arbitrer","t":"Same as « médiation »."},{"w":"multifaceted","p":"adj.","m":"Having many aspects.","e":"<i>multi-</i> (many) + <i>facet</i>, French <i>facette</i>.","f":"à multiples facettes, complexe","t":"« Multi-facettes ». A multifaceted issue."},{"w":"omit","p":"v.","m":"To leave out or exclude.","e":"Latin <i>omittere</i> (to let go).","f":"omettre","t":"Same as « omettre »."},{"w":"omniscient","p":"adj.","m":"Knowing everything.","e":"Latin <i>omnis</i> (all) + <i>scire</i> (to know).","f":"omniscient","t":"Same as « omniscient »."},{"w":"pacify","p":"v.","m":"To quell the anger of; to bring peace to.","e":"Latin <i>pacificare</i>: <i>pax</i> (peace) + <i>facere</i>.","f":"apaiser, pacifier","t":"Same as « pacifier »."},{"w":"paltry","p":"adj.","m":"Ridiculously small or unimportant.","e":"Dialect <i>palt</i> (rubbish), Low German <i>paltrig</i> (ragged).","f":"dérisoire, piètre","t":"A paltry sum = une somme dérisoire."},{"w":"prefigure","p":"v.","m":"To be an early indication of.","e":"Latin <i>praefigurare</i>: <i>prae-</i> + <i>figurare</i>.","f":"préfigurer","t":"Same as « préfigurer »."},{"w":"presage","p":"v.","m":"To be a sign or warning of a future event.","e":"Latin <i>praesagium</i>, from <i>praesagire</i> (to perceive beforehand).","f":"présager, annoncer","t":"Same as « présage / présager »."},{"w":"prescribe","p":"v.","m":"To recommend with authority; to order a medicine.","e":"Latin <i>praescribere</i> (to write before).","f":"prescrire","t":"Same as « prescrire »."},{"w":"rampant","p":"adj.","m":"Flourishing or spreading unchecked.","e":"Old French <i>ramper</i> (to climb, rear up).","f":"endémique, déchaîné","t":"A lion rampant (heraldry) rears up. Rampant corruption spreads wildly."},{"w":"recluse","p":"n.","m":"A person who lives alone and avoids society.","e":"Latin <i>recludere</i> (to shut away).","f":"reclus, ermite","t":"Same as « reclus »."},{"w":"remarkable","p":"adj.","m":"Worthy of attention; extraordinary.","e":"French <i>remarquable</i>, from <i>remarquer</i>.","f":"remarquable","t":"Same as « remarquable »."},{"w":"remote","p":"adj.","m":"Far away; slight (of chances).","e":"Latin <i>remotus</i>, from <i>removere</i>.","f":"éloigné, lointain; faible","x":"2nd meaning","t":"Remote chance = faible chance. Distant too."},{"w":"retaliate","p":"v.","m":"To make an attack in return for a similar attack.","e":"Latin <i>retaliare</i>, from <i>talio</i> (like for like).","f":"riposter, user de représailles","t":"« Loi du talion » (an eye for an eye): talio."},{"w":"rhapsody","p":"n.","m":"An effusive expression of enthusiasm; a free musical work.","e":"Greek <i>rhapsōidia</i>: <i>rhaptein</i> (to stitch) + <i>ōidē</i> (song).","f":"rhapsodie","t":"Same as « rhapsodie »: Bohemian Rhapsody. Wax rhapsodic = s'extasier."},{"w":"serendipitous","p":"adj.","m":"Occurring by happy chance.","e":"Coined by Horace Walpole from <i>The Three Princes of Serendip</i> (Sri Lanka).","f":"dû à un heureux hasard","t":"« Heureux hasard ». Penicillin was serendipitous."},{"w":"shirk","p":"v.","m":"To avoid or neglect (a duty).","e":"Probably German <i>Schurke</i> (scoundrel).","f":"se dérober à, éviter","t":"« Se défiler ». Shirk responsibility."},{"w":"sinuous","p":"adj.","m":"Having many curves and turns.","e":"Latin <i>sinuosus</i>, from <i>sinus</i> (curve).","f":"sinueux","t":"Same as « sinueux »."},{"w":"sober","p":"adj.","m":"Not drunk; serious and sensible.","e":"Latin <i>sobrius</i> (not drunk).","f":"sobre; sérieux","t":"Same as « sobre »: a sober assessment = réaliste."},{"w":"stanch","p":"v.","m":"To stop or restrict a flow (especially of blood).","e":"Old French <i>estanchier</i> (to stop).","f":"étancher, arrêter","t":"Same as « étancher ». Stanch the bleeding."},{"w":"stem from","p":"phr.","m":"To originate in or be caused by.","e":"Old English <i>stefn</i> (stem, trunk). Germanic.","f":"découler de, provenir de","t":"A plant's stem: where it all comes from. Stem from = « découler de »."},{"w":"subdued","p":"adj.","m":"Quiet and rather reflective; reduced in intensity.","e":"Latin <i>subdere</i> (to place under).","f":"discret, atténué, réprimé","t":"Subdued light = lumière tamisée. A subdued crowd is quiet."},{"w":"token","p":"adj.","m":"Done for the sake of appearances; symbolic.","e":"Old English <i>tācen</i> (sign). Germanic.","f":"symbolique, de pure forme","x":"2nd meaning","t":"A token gesture = un geste symbolique, « pour la forme »."},{"w":"turbid","p":"adj.","m":"Cloudy, opaque or thick with suspended matter; confused.","e":"Latin <i>turbidus</i>, from <i>turba</i> (disturbance).","f":"trouble, boueux","t":"« Trouble » water: turbid. Turbid emotions."},{"w":"ulterior","p":"adj.","m":"Existing beyond what is obvious; hidden (of motives).","e":"Latin <i>ulterior</i> (farther), from <i>ultra</i>.","f":"ultérieur; caché","x":"Faux ami","t":"« Ultérieur » = later in time. English ulterior = hidden: an ulterior motive = arrière-pensée."},{"w":"unravel","p":"v.","m":"To undo twisted or knitted threads; to solve a mystery.","e":"<i>un-</i> + Dutch <i>ravelen</i> (to tangle).","f":"démêler, défaire, élucider","t":"Un-tangle: démêler. A plot unravels."},{"w":"withstand","p":"v.","m":"To remain undamaged or unaffected by.","e":"Old English <i>withstandan</i> (stand against). Germanic.","f":"résister à, supporter","t":"With = against: stand against. Withstand pressure = résister."}]},{"name":"GregMat VIII","slug":"gregmat-viii","series":"GregMat","words":[{"w":"accord","p":"v.","m":"To give or grant; to be consistent with.","e":"Old French <i>acorder</i>, Latin <i>ad cor</i> (to the heart).","f":"accorder; concorder","t":"Same as « accorder / être en accord »."},{"w":"ad hoc","p":"adj.","m":"Created for a particular purpose only.","e":"Latin <i>ad hoc</i> (for this).","f":"ad hoc, improvisé","t":"Same as « ad hoc »."},{"w":"all-ecompassing","p":"adj.","m":"Including everything; comprehensive. (Standard spelling: all-encompassing.)","e":"<i>all</i> + <i>encompass</i> (<i>en-</i> + <i>compass</i>, Latin <i>compassare</i>).","f":"global, exhaustif","x":"Spelling","t":"GregMat’s spelling has a typo: the correct form is all-encompassing. « Qui englobe tout »."},{"w":"attribute","p":"v.","m":"To regard something as belonging to or caused by.","e":"Latin <i>attribuere</i> (to assign).","f":"attribuer","t":"Same as « attribuer »."},{"w":"beholden","p":"adj.","m":"Owing thanks or having a duty to someone.","e":"Old English <i>behealdan</i> (to hold, observe); past participle of <i>behold</i>.","f":"redevable","t":"« Redevable » to someone. Beholden to donors."},{"w":"benchmark","p":"n.","m":"A standard against which things can be measured.","e":"From a surveyor’s <i>bench mark</i> cut in stone.","f":"référence, étalon","t":"Same in French business jargon: « un benchmark »."},{"w":"blighted","p":"adj.","m":"Spoiled or ruined; stricken by disease (plants).","e":"<i>blight</i> (plant disease), origin unknown.","f":"gâché, ravagé","t":"A blight: la rouille. Blighted hopes."},{"w":"calamitous","p":"adj.","m":"Causing great damage.","e":"Latin <i>calamitas</i> (disaster).","f":"désastreux, calamiteux","t":"Same as « calamiteux »."},{"w":"cluster","p":"n.","m":"A group of similar things close together.","e":"Old English <i>clyster</i>. Germanic.","f":"grappe, groupe","t":"Un « amas ». A cluster of stars."},{"w":"coherent","p":"adj.","m":"Logical and consistent; clear.","e":"Latin <i>cohaerere</i> (to stick together).","f":"cohérent","t":"Same as « cohérent »."},{"w":"contemplate","p":"v.","m":"To think deeply; to consider as a possibility.","e":"Latin <i>contemplari</i> (to observe), <i>templum</i> (a space for observing).","f":"contempler; envisager","x":"2nd meaning","t":"« Contempler » a view, but also envisager: contemplate resigning."},{"w":"content","p":"adj.","m":"In a state of peaceful happiness; satisfied. (Stress: conTENT.)","e":"Latin <i>contentus</i> (satisfied), from <i>continere</i>.","f":"content, satisfait","x":"2nd meaning","t":"Same as « content ». Two words: CONtent (the substance) vs conTENT (satisfied)."},{"w":"crafty","p":"adj.","m":"Clever at achieving aims by deceit.","e":"Old English <i>cræftig</i>, from <i>cræft</i> (skill).","f":"rusé, astucieux","t":"Craft = skill, and slyness. A crafty fox."},{"w":"dexterous","p":"adj.","m":"Showing skill with hands or mind.","e":"Latin <i>dexter</i> (right-handed, skilful).","f":"adroit, habile","t":"Dexter = right. Cousin of « dextérité »."},{"w":"dictum","p":"n.","m":"A formal pronouncement; a short statement of principle.","e":"Latin <i>dictum</i> (something said).","f":"maxime, sentence","t":"Same as « dicton ». Dictum = a said thing."},{"w":"disconcerting","p":"adj.","m":"Causing unease or confusion.","e":"French <i>disconcerter</i>.","f":"déconcertant","t":"Same as « déconcertant »."},{"w":"dismantle","p":"v.","m":"To take apart; to abolish gradually.","e":"Old French <i>desmanteler</i> (to strip off a cloak).","f":"démanteler, démonter","t":"Same as « démanteler »: take off the mantle."},{"w":"dutiful","p":"adj.","m":"Conscientiously obedient.","e":"<i>duty</i> + <i>-ful</i>.","f":"respectueux, obéissant","t":"Full of duty (devoir): a dutiful son."},{"w":"ensue","p":"v.","m":"To happen afterwards, as a result.","e":"Old French <i>ensuivre</i>: <i>en-</i> + <i>suivre</i> (to follow).","f":"s'ensuivre, résulter","t":"Same as « s'ensuivre »."},{"w":"facility","p":"n.","m":"A natural ease; a place or equipment for an activity.","e":"Latin <i>facilitas</i>, from <i>facilis</i> (easy).","f":"aisance, facilité; installation","x":"2nd meaning","t":"Facility for languages = facilité. But a research facility = une installation."},{"w":"fathom","p":"v.","m":"To understand after much thought.","e":"Old English <i>fæthm</i> (outstretched arms), a unit of depth.","f":"comprendre, sonder","t":"Sound the depth: « sonder ». I can’t fathom it."},{"w":"fitful","p":"adj.","m":"Active only in short bursts; irregular.","e":"<i>fit</i> (a sudden attack), Old English <i>fitt</i> + <i>-ful</i>.","f":"intermittent, irrégulier","t":"Fits and starts: fitful sleep = sommeil agité."},{"w":"forgo","p":"v.","m":"To go without; to give up.","e":"Old English <i>forgān</i> (to pass over). Germanic.","f":"renoncer à, se passer de","x":"Look-alike","t":"Not « forego » (to precede). Forgo dessert = renoncer au dessert."},{"w":"frank","p":"adj.","m":"Open, honest and direct.","e":"Old French <i>franc</i> (free), from Frankish.","f":"franc","t":"Same as « franc »: Franc de port."},{"w":"grumble","p":"v.","m":"To complain in a bad-tempered way.","e":"Dutch <i>grommelen</i>. Germanic.","f":"grogner, ronchonner","t":"Grommeler. Grumble about taxes."},{"w":"hidebound","p":"adj.","m":"Unwilling to accept new ideas; rigidly conventional.","e":"<i>hide</i> (skin) + <i>bound</i>: cattle with tight skin.","f":"étroit d'esprit, borné","t":"Skin too tight: un esprit « borné »."},{"w":"hypocrite","p":"n.","m":"A person who pretends to have virtues they do not possess.","e":"Greek <i>hypokritēs</i> (actor).","f":"hypocrite","t":"Same as « hypocrite »: an actor playing a role."},{"w":"impenetrable","p":"adj.","m":"Impossible to pass through or understand.","e":"Latin <i>impenetrabilis</i>.","f":"impénétrable","t":"Same as « impénétrable »."},{"w":"impolitic","p":"adj.","m":"Unwise; failing to take account of consequences.","e":"<i>im-</i> + <i>politic</i> (wise), Greek <i>politikos</i>.","f":"peu judicieux, malavisé","t":"Not rude: politic = prudent. An impolitic remark = une maladresse."},{"w":"inalienable","p":"adj.","m":"Unable to be taken away from or given away.","e":"<i>in-</i> + <i>alien</i>, Latin <i>alienare</i>.","f":"inaliénable","t":"Same as « inaliénable »: les droits inaliénables."},{"w":"incite","p":"v.","m":"To encourage or stir up (violence or hatred).","e":"Latin <i>incitare</i> (to urge on).","f":"inciter, provoquer","t":"Same as « inciter »."},{"w":"induce","p":"v.","m":"To persuade; to bring about.","e":"Latin <i>inducere</i> (to lead in).","f":"inciter, provoquer, induire","t":"Same as « induire » (en erreur). Induce sleep = provoquer le sommeil."},{"w":"inept","p":"adj.","m":"Having no skill; clumsy.","e":"Latin <i>ineptus</i>: <i>in-</i> + <i>aptus</i> (suitable).","f":"inapte, incompétent","t":"Opposite of apt. An inept manager = « incapable »."},{"w":"infelicity","p":"n.","m":"An inappropriate remark or expression; unhappiness.","e":"Latin <i>infelicitas</i>: <i>in-</i> + <i>felix</i> (happy).","f":"impropriété, maladresse","t":"Opposite of felicity. An infelicity of style = formule malheureuse."},{"w":"intelligible","p":"adj.","m":"Able to be understood.","e":"Latin <i>intelligibilis</i>, from <i>intellegere</i>.","f":"intelligible","t":"Same as « intelligible »."},{"w":"intermediary","p":"n.","m":"A person who acts as a link between parties.","e":"Latin <i>intermedius</i>.","f":"intermédiaire","t":"Same as « intermédiaire »."},{"w":"narcissism","p":"n.","m":"Excessive interest in oneself.","e":"Greek <i>Narkissos</i>, mythical youth in love with his reflection.","f":"narcissisme","t":"Same as « narcissisme »."},{"w":"objurgation","p":"n.","m":"A harsh rebuke.","e":"Latin <i>objurgare</i> (to scold): <i>ob-</i> + <i>jurgare</i> (to quarrel).","f":"réprimande, objurgation","t":"Cousin of « objurguer » (rare in French). Think « injure »: a severe scolding."},{"w":"onetime","p":"adj.","m":"Former.","e":"<i>one</i> + <i>time</i>. Germanic.","f":"ancien, d'autrefois","t":"A onetime champion = ancien champion."},{"w":"opportunistic","p":"adj.","m":"Exploiting circumstances for immediate advantage.","e":"Latin <i>opportunus</i> (favourable).","f":"opportuniste","t":"Same as « opportuniste »."},{"w":"passable","p":"adj.","m":"Acceptable but not outstanding; (of a road) able to be travelled.","e":"Old French <i>passer</i> (to pass).","f":"passable, acceptable","t":"Same as « passable » (just OK). A passable meal."},{"w":"passive","p":"adj.","m":"Accepting what happens without active response.","e":"Latin <i>passivus</i>, from <i>pati</i> (to suffer).","f":"passif","t":"Same as « passif »."},{"w":"penetrating","p":"adj.","m":"Able to pass through; showing keen insight.","e":"Latin <i>penetrare</i>.","f":"pénétrant, perspicace","t":"Same as « pénétrant »: a penetrating question."},{"w":"phony","p":"adj.","m":"Not genuine; fake.","e":"American slang, early 20th century, possibly from <i>fawney</i> (a gilt brass ring used in scams).","f":"faux, bidon","t":"Holden Caulfield: phoney. « Bidon »."},{"w":"picturesque","p":"adj.","m":"Visually attractive, as in a painting.","e":"French <i>pittoresque</i>, Italian <i>pittoresco</i>.","f":"pittoresque","t":"Same as « pittoresque »."},{"w":"plausible","p":"adj.","m":"Seeming reasonable or probable.","e":"Latin <i>plausibilis</i> (deserving applause).","f":"plausible, vraisemblable","t":"Same as « plausible »."},{"w":"posturing","p":"n.","m":"Behaviour intended to impress or mislead.","e":"Latin <i>positura</i> (position).","f":"pose, affectation, grands airs","t":"Une « posture » (not neutral): political posturing = jeu de rôle."},{"w":"potent","p":"adj.","m":"Having great power or strong effect.","e":"Latin <i>potens</i>, from <i>posse</i> (to be able).","f":"puissant, efficace","t":"Same as « potentiel / puissant ». A potent drug."},{"w":"ramble","p":"v.","m":"To walk for pleasure; to talk at length confusedly.","e":"Middle Dutch <i>rammelen</i> (to roam in sexual excitement).","f":"flâner; divaguer","x":"2nd meaning","t":"A rambling speech = discours décousu. Walkers ramble too."},{"w":"recapitulate","p":"v.","m":"To summarize and state again the main points.","e":"Latin <i>recapitulare</i>, from <i>capitulum</i> (little head, chapter).","f":"récapituler","t":"Same as « récapituler »."},{"w":"redundant","p":"adj.","m":"Not needed; superfluous.","e":"Latin <i>redundare</i> (to overflow).","f":"redondant, superflu","t":"Same as « redondant »; also “laid off” in British English."},{"w":"reflect","p":"v.","m":"To throw back light; to think carefully.","e":"Latin <i>reflectere</i> (to bend back).","f":"refléter; réfléchir","t":"Same as « réfléchir »: both meanings (mirror, thought)."},{"w":"resent","p":"v.","m":"To feel bitter indignation at.","e":"French <i>ressentir</i> (to feel again).","f":"en vouloir à, ne pas supporter","x":"Faux ami","t":"Ressentir ≠ resent: English = bitter. « Il m'en veut » = he resents me."},{"w":"residual","p":"adj.","m":"Remaining after the main part has gone.","e":"Latin <i>residuum</i>, from <i>residere</i> (to remain).","f":"résiduel","t":"Same as « résiduel »."},{"w":"resourceful","p":"adj.","m":"Having the ability to find quick and clever ways to overcome difficulties.","e":"<i>resource</i> (French <i>ressource</i>) + <i>-ful</i>.","f":"ingénieux, débrouillard","t":"« Débrouillard »."},{"w":"retrench","p":"v.","m":"To reduce costs or spending.","e":"Old French <i>retrenchier</i> (to cut back).","f":"réduire ses dépenses, se restreindre","t":"Cut back: « retrancher ». Retrenchment = austérité."},{"w":"sacrosanct","p":"adj.","m":"Too important to be changed.","e":"Latin <i>sacrosanctus</i>: <i>sacro</i> (by a sacred rite) + <i>sanctus</i> (made holy).","f":"sacro-saint","t":"Same as « sacro-saint »."},{"w":"self-indulgent","p":"adj.","m":"Allowing oneself to enjoy pleasures or luxuries.","e":"<i>self</i> + Latin <i>indulgere</i> (to be kind).","f":"complaisant envers soi-même","t":"Indulgence: you pardon yourself everything. « Laxiste envers soi »."},{"w":"shrewd","p":"adj.","m":"Having sharp judgement, especially in business.","e":"Middle English <i>shrewe</i> (wicked person), later 'sharp'.","f":"astucieux, perspicace","t":"A shrewd negotiator = fin négociateur."},{"w":"speculate","p":"v.","m":"To form a theory without firm evidence; to invest at risk.","e":"Latin <i>speculari</i> (to observe).","f":"spéculer, conjecturer","t":"Same as « spéculer »."},{"w":"suppress","p":"v.","m":"To forcibly put an end to; to prevent from being seen.","e":"Latin <i>supprimere</i>: <i>sub-</i> + <i>premere</i> (to press).","f":"réprimer, étouffer, supprimer","t":"Same as « supprimer / réprimer »."},{"w":"surrogate","p":"n.","m":"A substitute, especially a person acting for another.","e":"Latin <i>surrogare</i> (to substitute).","f":"substitut, remplaçant","t":"Same as « substitut »: surrogate mother = mère porteuse."},{"w":"unadorned","p":"adj.","m":"Plain; without decoration.","e":"<i>un-</i> + Latin <i>adornare</i>.","f":"sans fard, dépouillé","t":"« Sans fard »: the unadorned truth."},{"w":"valedictory","p":"adj.","m":"Serving as a farewell.","e":"Latin <i>vale dicere</i> (to say farewell).","f":"d'adieu","t":"Vale! Valedictorian gives the farewell speech."},{"w":"vestigial","p":"adj.","m":"Forming a remnant of something that once existed.","e":"Latin <i>vestigium</i> (footprint).","f":"vestigial, résiduel","t":"Same as « vestige »: a vestigial organ."},{"w":"warranted","p":"adj.","m":"Justified or necessary.","e":"Old French <i>warant</i>, Germanic. Cf. « garantir ».","f":"justifié, fondé","t":"Warrant ~ garantir: warranted = guaranteed to be justified."},{"w":"willful","p":"adj.","m":"Stubbornly determined; intentional.","e":"<i>will</i> + <i>-ful</i>. Germanic.","f":"entêté; délibéré","t":"Willful neglect = négligence volontaire; a willful child = têtu."},{"w":"wistful","p":"adj.","m":"Having a feeling of vague longing.","e":"Probably from <i>wistly</i> (intently), influenced by <i>wishful</i>.","f":"mélancolique, nostalgique","t":"Wishful, melancholy: « nostalgique »."}]}];
